// ── ROLE CONSTANTS ────────────────────────────────────────────
define('ROLE_OWNER',          1);
define('ROLE_BRANCH_MANAGER', 2);
define('ROLE_CASHIER',        3);
define('ROLE_STOREKEEPER',    4);
define('ROLE_SUPPLIER_CLERK', 5);
define('ROLE_HR', 12);
define('ROLE_SUPPORT',        11);

// ── HELPERS ───────────────────────────────────────────────────
function logged_in(): bool { return isset($_SESSION['staff_id']); }
function me(): array        { return $_SESSION['staff'] ?? []; }
function role(): int        { return (int)($_SESSION['staff']['role_id'] ?? 0); }
function branch(): int      { return (int)($_SESSION['staff']['branch_id'] ?? 0); }
// People-actions HR may perform. HR passes a "manager" check ONLY for these.
// Money actions (salary_request_otp, salary_disburse_otp, payout_schedule, ...) are deliberately absent.
define('HR_ACTIONS', [
    'staff_payroll_list', 'staff_payroll_save', 'salary_overview',
    'appointed_staff_list', 'appointed_staff_add', 'appointed_staff_remove', 'appointed_card_data', 'card_data',
    'payslip_preview', 'payslip_generate', 'payslip_list',
    'ai_staff_profile', 'ai_profiles_list', 'staff_cv_upload', 'staff_cv_view',
]);
function can(array $roles): bool {
    if (in_array(role(), $roles, true)) return true;
    return role() === ROLE_HR
        && in_array(ROLE_BRANCH_MANAGER, $roles, true)
        && in_array($GLOBALS['action'] ?? '', HR_ACTIONS, true);
}
function fmt(float $n): string   { return 'KSh ' . number_format($n, 2); }
function today(): string         { return date('Y-m-d'); }
function esc(mixed $v): string   { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }

function redirect(string $to): void { header('Location: ' . $to); exit; }
function json_out(mixed $data): void {
    if (session_status() === PHP_SESSION_ACTIVE) session_write_close();
    header('Content-Type: application/json');
    header('Cache-Control: no-store, no-cache, must-revalidate');
    header('Pragma: no-cache');
    echo json_encode($data); exit;
}

// ── CSRF ──────────────────────────────────────────────────────
function csrf(): string {
    if (empty($_SESSION['csrf'])) {
        $_SESSION['csrf'] = bin2hex(random_bytes(32));
    }
    return $_SESSION['csrf'];
}
function csrf_ok(): bool {
    $token = $_POST['csrf'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '';
    return !empty($token) && hash_equals($_SESSION['csrf'] ?? '', $token);
}
function csrf_check(): void {
    if (!csrf_ok()) {
        json_out(['ok' => false, 'msg' => 'Invalid or missing CSRF token.']);
    }
}

// ── LOGIN RATE LIMITER ────────────────────────────────────────
function login_rate_check(string $ip): bool {
    $key = 'login_attempts_' . md5($ip);
    if (!isset($_SESSION[$key])) {
        $_SESSION[$key] = ['count' => 0, 'first' => time()];
    }
    $att = &$_SESSION[$key];
    if ((time() - $att['first']) > 900) { // reset after 15 min
        $att = ['count' => 0, 'first' => time()];
    }
    return $att['count'] < 5;
}
function login_rate_increment(string $ip): void {
    $key = 'login_attempts_' . md5($ip);
    $_SESSION[$key]['count'] = ($_SESSION[$key]['count'] ?? 0) + 1;
}
function login_rate_reset(string $ip): void {
    unset($_SESSION['login_attempts_' . md5($ip)]);
}

// ── BRANCH SQL HELPER (parameterized-safe) ────────────────────
// Returns ['sql' => string, 'params' => array]
// Caller merges params into their own execute() array
function branch_filter(string $alias = ''): array {
    $col = $alias ? "$alias.branch_id" : 'branch_id';
    $client_id = (int)(me()['client_id'] ?? 0);
    if (role() === ROLE_OWNER && $client_id) {
        $br = $alias ? "$alias.branch_id" : 'branch_id';
        return ['sql' => "$br IN (SELECT id FROM branches WHERE client_id = ?)", 'params' => [$client_id]];
    }
    return ['sql' => "$col = ?", 'params' => [branch()]];
}

// ── RECEIPT / LPO GENERATORS ─────────────────────────────────
function gen_receipt(): string {
    return 'RCP-' . strtoupper(base_convert(time(), 10, 36)) . '-' . rand(100, 999);
}
function gen_sale_no(): string {
    return 'SL-' . date('Ymd') . '-' . strtoupper(substr(uniqid(), -5)) . rand(10, 99);
}
// ── NYMIX STAFF ID CARD ──────────────────────────────────────
// CHANGE THIS to a long random string and never share it. It signs every card's security code.
define('CARD_SECRET', 'CHANGE-ME-TO-A-LONG-RANDOM-STRING-2026');

function card_sig(string $no, int $uid): string {
    return strtoupper(substr(hash_hmac('sha256', $no . '|' . $uid, CARD_SECRET), 0, 12));
}
function card_code_fmt(string $sig): string { return implode('-', str_split($sig, 4)); }

// Generates a card number that exists nowhere in users OR appointed_staff
function gen_unique_card_no(PDO $pdo): string {
    $chk = $pdo->prepare("SELECT (SELECT COUNT(*) FROM users WHERE card_no = ?) + (SELECT COUNT(*) FROM appointed_staff WHERE card_no = ?)");
    do {
        $no = 'NX-' . strtoupper(bin2hex(random_bytes(4))) . '-' . str_pad((string)random_int(0, 9999), 4, '0', STR_PAD_LEFT);
        $chk->execute([$no, $no]);
    } while ((int)$chk->fetchColumn() > 0);
    return $no;
}

// Returns everything needed to draw a card. Reserves the card number the first time.
function card_payload(PDO $pdo, int $uid): ?array {
    $st = $pdo->prepare("
        SELECT u.id, u.full_name, u.photo_path, u.card_no,
               r.name AS role_name, b.branch_name, b.phone AS branch_phone, c.business_name
        FROM users u
        JOIN roles r ON r.id = u.role_id
        LEFT JOIN branches b ON b.id = u.branch_id
        LEFT JOIN clients c ON c.id = b.client_id
        WHERE u.id = ?
    ");
    $st->execute([$uid]);
    $u = $st->fetch();
    if (!$u) return null;
    $no = $u['card_no'];
    if (!$no) {
        $no = gen_unique_card_no($pdo);
        $pdo->prepare("UPDATE users SET card_no = ? WHERE id = ?")->execute([$no, $uid]);
    }
    return [
        'card_no'    => $no,
        'code'       => card_code_fmt(card_sig($no, $uid)),
        'name'       => $u['full_name'],
        'role'       => $u['role_name'],
        'business'   => $u['business_name'] ?: 'NYMIX TECH',
        'branch'     => $u['branch_name'] ?: 'All Branches',
        'phone'      => $u['branch_phone'] ?: '',
        'photo'      => $u['photo_path'] ?: '',
        'issued'     => date('d M Y'),
        'verify_url' => nx_email_absolute_url(ltrim(strtok($_SERVER['REQUEST_URI'] ?? 'staff_portal.php', '?'), '/')) . '?action=card_check&no=' . urlencode($no),
    ];
}

function gen_lpo(): string {
    return 'LPO-' . date('Ymd') . '-' . rand(1000, 9999);
}

// ── HTML EMAIL TEMPLATE (branded wrapper for all outgoing mail) ──
// $type controls the header color + icon so the inbox preview instantly
// signals urgency: alert=red, warning=orange, success=green, security=blue, info=amber (default)
function nx_email_theme(string $type): array {
    return match ($type) {
        'alert'    => ['grad' => 'linear-gradient(135deg,#ef4444,#dc2626)', 'icon' => '⚠️', 'fg' => '#ffffff', 'accent' => '#ef4444', 'soft' => '#fef2f2', 'label' => 'Alert'],
        'warning'  => ['grad' => 'linear-gradient(135deg,#f97316,#ea580c)', 'icon' => '🔔', 'fg' => '#ffffff', 'accent' => '#f97316', 'soft' => '#fff7ed', 'label' => 'Warning'],
        'success'  => ['grad' => 'linear-gradient(135deg,#22c55e,#16a34a)', 'icon' => '✅', 'fg' => '#ffffff', 'accent' => '#22c55e', 'soft' => '#f0fdf4', 'label' => 'Success'],
        'security' => ['grad' => 'linear-gradient(135deg,#3b82f6,#2563eb)', 'icon' => '🔒', 'fg' => '#ffffff', 'accent' => '#3b82f6', 'soft' => '#eff6ff', 'label' => 'Security'],
        default    => ['grad' => 'linear-gradient(135deg,#1E9E52,#17C548)', 'icon' => 'ℹ️', 'fg' => '#000000', 'accent' => '#d97706', 'soft' => '#fffbeb', 'label' => 'Notice'],
    };
}

// ── EMAIL BUILDING BLOCKS — reusable label/value table for structured content ──
function nx_email_row(string $label, string $value, bool $strong = false): string {
    $valStyle = $strong ? 'font-weight:700;color:#0f172a;' : 'font-weight:600;color:#334155;';
    return '<tr>
      <td style="padding:10px 14px;border-bottom:1px solid #eef1f5;font-size:11px;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap">' . $label . '</td>
      <td style="padding:10px 14px;border-bottom:1px solid #eef1f5;font-size:14px;text-align:right;' . $valStyle . '">' . $value . '</td>
    </tr>';
}
function nx_email_table(array $rowsHtml): string {
    $rowsHtml[count($rowsHtml)-1] = str_replace('border-bottom:1px solid #eef1f5;', '', end($rowsHtml));
    return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #eef1f5;border-radius:10px;overflow:hidden;margin:14px 0">' . implode('', $rowsHtml) . '</table>';
}
function nx_email_pill(string $text, string $color, string $bg): string {
    return '<span style="display:inline-block;background:' . $bg . ';color:' . $color . ';font-size:11px;font-weight:700;letter-spacing:.5px;padding:3px 10px;border-radius:20px">' . htmlspecialchars($text, ENT_QUOTES, 'UTF-8') . '</span>';
}
// Converts a possibly-relative uploaded image path into an absolute URL emails can load
function nx_email_absolute_url(string $path): string {
    if ($path === '' || preg_match('~^https?://~i', $path)) return $path;
    $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
    $host   = $_SERVER['HTTP_HOST'] ?? 'nymix-tech.top';
    return $scheme . '://' . $host . '/' . ltrim($path, '/');
}

function nx_email_template(string $subject, string $bodyContent, string $type = 'info', string $businessName = 'NYMIX BUSINESS'): string {
    $t      = nx_email_theme($type);
    $e      = fn($s) => htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
    $logo   = nx_email_absolute_url('logo.png');
    $portal = nx_email_absolute_url('staff_portal.php');
    $year   = date('Y');
    $pStyle = 'margin:0 0 14px;font-size:15px;line-height:1.7;color:#334155';
    $inner  = '';

    if (preg_match('/<[a-z][\s\S]*>/i', $bodyContent)) {
        $inner = $bodyContent;
    } else {
        $isCode = stripos($subject, 'code') !== false;
        foreach (preg_split('/\n\s*\n/', trim($bodyContent)) as $bi => $block) {
            $lines = array_values(array_filter(array_map('trim', explode("\n", $block)), 'strlen'));
            if (!$lines) continue;

            // "Label: value" blocks become a neat table
            $kv = [];
            foreach ($lines as $ln) {
                if (preg_match('/^([A-Za-z][A-Za-z0-9 \/&\.\-]{1,30}):\s+(.+)$/', $ln, $m)) { $kv[] = [$m[1], $m[2]]; }
                else { $kv = []; break; }
            }
            if (count($kv) >= 2 && count($kv) === count($lines)) {
                $rows = [];
                foreach ($kv as $p) $rows[] = nx_email_row($e($p[0]), $e($p[1]));
                $inner .= nx_email_table($rows);
                continue;
            }

            $txt = $e(implode("\n", $lines));
            if ($isCode) {
                $txt = preg_replace('/(?<![\d,.])(\d{6})(?![\d,.])/',
                    '<span style="display:inline-block;background:#0b1020;color:#fbbf24;font-family:Courier New,monospace;font-weight:700;font-size:30px;letter-spacing:8px;padding:14px 20px;border-radius:12px;margin:8px 0">$1</span>', $txt);
            }
            if ($bi === 0 && preg_match('/^Hi\b/i', $lines[0])) {
                $inner .= '<p style="margin:0 0 16px;font-size:17px;font-weight:700;color:#0f172a">' . nl2br($txt) . '</p>';
            } else {
                $inner .= '<p style="' . $pStyle . '">' . nl2br($txt) . '</p>';
            }
        }
    }

    return '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif">
<div style="display:none;max-height:0;overflow:hidden;opacity:0">' . $e($subject) . '</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:28px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:24px;overflow:hidden;box-shadow:0 10px 40px rgba(15,23,42,.10)">

  <tr><td style="background:#0b1020;padding:18px 28px">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
      <td width="44"><img src="' . $e($logo) . '" width="40" height="40" alt="NYMIX" style="display:block;border-radius:10px;background:#ffffff"></td>
      <td style="padding-left:12px;color:#ffffff;font-size:16px;font-weight:800;letter-spacing:1.5px">NYMIX TECH</td>
      <td align="right"><span style="display:inline-block;background:' . $t['accent'] . ';color:#ffffff;font-size:11px;font-weight:700;letter-spacing:1px;padding:5px 12px;border-radius:20px">' . strtoupper($t['label']) . '</span></td>
    </tr></table>
  </td></tr>

  <tr><td align="center" style="background:' . $t['accent'] . ';background-image:' . $t['grad'] . ';padding:38px 28px 34px">
    <div style="width:68px;height:68px;line-height:68px;border-radius:50%;background:rgba(255,255,255,.22);font-size:32px;margin:0 auto 16px">' . $t['icon'] . '</div>
    <div style="font-size:24px;font-weight:800;color:#ffffff;line-height:1.3">' . $e($subject) . '</div>
    <div style="font-size:12px;color:rgba(255,255,255,.85);margin-top:8px;letter-spacing:1px">' . $e(strtoupper($businessName)) . '</div>
  </td></tr>

  <tr><td style="padding:30px 32px 10px">' . $inner . '</td></tr>

  <tr><td align="center" style="padding:6px 32px 34px">
    <a href="' . $e($portal) . '" style="display:inline-block;background:' . $t['accent'] . ';color:#ffffff;text-decoration:none;font-weight:700;font-size:15px;padding:14px 34px;border-radius:14px">Open Staff Portal &rarr;</a>
    <div style="font-size:12px;color:#94a3b8;margin-top:14px">Need help? Contact your branch manager or NYMIX TECH support.</div>
  </td></tr>

  <tr><td style="background:#0b1020;padding:22px 28px;text-align:center">
    <div style="color:#ffffff;font-size:13px;font-weight:700;letter-spacing:1.5px">NYMIX TECH</div>
    <div style="color:#94a3b8;font-size:11px;margin-top:6px;line-height:1.6">This is an automated message from the NYMIX Staff Portal. Please do not reply directly.<br>&copy; ' . $year . ' NYMIX TECH &middot; Powered by NYMIX HMS</div>
  </td></tr>

</table></td></tr></table></body></html>';
}

