// ── GENERIC MAILER (Brevo HTTP API) ────────────────────────────
function nx_mail_send(string $toEmail, string $toName, string $subject, string $html, string $alt = '', string $attachmentPath = ''): bool {
    if (!$toEmail) return false;
    $payload = [
        'sender'      => ['name' => MAIL_FROM_NAME, 'email' => MAIL_FROM_EMAIL],
        'to'          => [['email' => $toEmail, 'name' => $toName ?: $toEmail]],
        'subject'     => $subject,
        'htmlContent' => $html,
    ];
    if ($alt !== '') $payload['textContent'] = $alt;
    if ($attachmentPath && file_exists($attachmentPath)) {
        $payload['attachment'] = [[
            'name'    => basename($attachmentPath),
            'content' => base64_encode(file_get_contents($attachmentPath)),
        ]];
    }
    $ch = curl_init('https://api.brevo.com/v3/smtp/email');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode($payload),
        CURLOPT_HTTPHEADER     => [
            'accept: application/json',
            'content-type: application/json',
            'api-key: ' . BREVO_API_KEY,
        ],
        CURLOPT_TIMEOUT        => 15,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $err  = curl_error($ch);
    curl_close($ch);
    if ($err || $code < 200 || $code >= 300) {
        error_log("[NYMIX MAIL] HTTP {$code} {$err} {$resp}");
        return false;
    }
    return true;
}

function nx_mail_alt(string $body): string {
    return preg_match('/<[a-z][\s\S]*>/i', $body)
        ? trim(preg_replace('/\n{3,}/', "\n\n", strip_tags(str_replace(['<tr>','</tr>','<br>','<br/>','<br />'], "\n", $body))))
        : $body;
}

function nx_staff_mail(string $toEmail, string $toName, string $subject, string $body, string $type = 'info', string $businessName = 'NYMIX BUSINESS'): bool {
    return nx_mail_send($toEmail, $toName, $subject, nx_email_template($subject, $body, $type, $businessName), nx_mail_alt($body));
}

function nx_staff_mail_attachment(string $toEmail, string $toName, string $subject, string $body, string $attachmentPath = '', string $type = 'info', string $businessName = 'NYMIX BUSINESS'): bool {
    return nx_mail_send($toEmail, $toName, $subject, nx_email_template($subject, $body, $type, $businessName), nx_mail_alt($body), $attachmentPath);
}

function nx_salary_owner_email(int $client_id): ?array {
    $pdo = db();
    $st = $pdo->prepare("
        SELECT cpu.id, c.email, c.business_name
        FROM client_portal_users cpu JOIN clients c ON c.id = cpu.client_id
        WHERE cpu.client_id = ? LIMIT 1
    ");
    $st->execute([$client_id]);
    $row = $st->fetch();
    return ($row && $row['email']) ? ['email'=>$row['email'],'name'=>$row['business_name']] : null;
}

// ── MINIMAL PDF WRITER (no external library needed) ────────────
// ── AI (Groq) ──
function ai_log_usage(PDO $pdo, int $client_id, string $feature, int $tokens): void {
    try { $pdo->prepare("INSERT INTO ai_usage (client_id, feature, tokens) VALUES (?,?,?)")->execute([$client_id, $feature, $tokens]); } catch (Throwable $e) {}
}

// Works for any OpenAI-compatible API (Gemini and OpenRouter both are)
function ai_chat_compat(PDO $pdo, int $client_id, string $feature, string $label, string $url, string $key, string $model,
                        string $system, string $user, bool $json, int $max_tokens, array $extra_headers = [], bool $json_mode = true): array {
    if ($key === '' || strpos($key, 'PASTE_') === 0) return ['ok' => false, 'msg' => $label . ' is not configured.'];
    $payload = [
        'model'       => $model,
        'messages'    => [['role' => 'system', 'content' => $system], ['role' => 'user', 'content' => $user]],
        'temperature' => 0.3,
        'max_tokens'  => max($max_tokens, 1500),
    ];
    if ($json && $json_mode) $payload['response_format'] = ['type' => 'json_object'];
if ($label === 'Gemini') $payload['reasoning_effort'] = 'low';
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode($payload),
        CURLOPT_HTTPHEADER     => array_merge(['Content-Type: application/json', 'Authorization: Bearer ' . $key], $extra_headers),
        CURLOPT_TIMEOUT        => 25,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $err  = curl_error($ch);
    curl_close($ch);
    if ($err || !$resp) { error_log("[NYMIX AI $label] curl: $err"); return ['ok' => false, 'msg' => $label . ' unreachable.']; }
    $data = json_decode($resp, true);
    $text = trim((string)($data['choices'][0]['message']['content'] ?? ''));
    if ($code < 200 || $code >= 300 || $text === '') {
        error_log("[NYMIX AI $label] HTTP $code " . substr($resp, 0, 300));
        return ['ok' => false, 'msg' => $label . ' could not answer right now.'];
    }
    if ($json) $text = trim(preg_replace('/^```(?:json)?\s*|\s*```$/m', '', $text));
    ai_log_usage($pdo, $client_id, $feature, (int)($data['usage']['total_tokens'] ?? 0));
    return ['ok' => true, 'text' => $text, 'provider' => $label];
}

// Tries Groq, then Gemini, then OpenRouter. Stops early on daily cap or DB setup errors.
function ai_chat(PDO $pdo, int $client_id, string $feature, string $system, string $user, bool $json = false, int $max_tokens = 500): array {
    $chain = [
        fn() => ai_chat_groq($pdo, $client_id, $feature, $system, $user, $json, $max_tokens),
        fn() => ai_chat_compat($pdo, $client_id, $feature, 'Gemini',
            'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
            defined('GEMINI_API_KEY') ? GEMINI_API_KEY : '',
            defined('GEMINI_MODEL') ? GEMINI_MODEL : 'gemini-2.5-flash',
            $system, $user, $json, $max_tokens),
        fn() => ai_chat_compat($pdo, $client_id, $feature, 'OpenRouter',
            'https://openrouter.ai/api/v1/chat/completions',
            defined('OPENROUTER_API_KEY') ? OPENROUTER_API_KEY : '',
            defined('OPENROUTER_MODEL') ? OPENROUTER_MODEL : 'meta-llama/llama-3.3-70b-instruct:free',
            $system, $user, $json, $max_tokens,
            ['HTTP-Referer: https://nymix-tech.top', 'X-Title: NYMIX Staff Portal'], false),
    ];
    foreach ($chain as $try) {
        $r = $try();
        if (!empty($r['ok'])) return $r;
        $m = (string)($r['msg'] ?? '');
        if (stripos($m, 'not set up yet') !== false) return $r;
        error_log('[NYMIX AI] provider failed, trying next: ' . $m);
    }
    return ['ok' => false, 'msg' => 'AI is busy right now. Try again in a minute.'];
}

function ai_chat_groq(PDO $pdo, int $client_id, string $feature, string $system, string $user, bool $json = false, int $max_tokens = 500): array {     if (!defined('GROQ_API_KEY') || GROQ_API_KEY === '' || GROQ_API_KEY === 'PASTE_YOUR_GROQ_KEY_HERE') {         return ['ok' => false, 'msg' => 'AI is not configured yet.'];     }     $cap = defined('AI_DAILY_CAP') ? (int)AI_DAILY_CAP : 500;     try {         $st = $pdo->prepare("SELECT COUNT(*) FROM ai_usage WHERE client_id = ? AND created_at >= CURDATE()");         $st->execute([$client_id]);         if ((int)$st->fetchColumn() >= $cap) return ['ok' => false, 'msg' => 'Daily AI limit reached. Try again tomorrow.'];     } catch (Throwable $e) {         error_log('[NYMIX AI] ' . $e->getMessage());         return ['ok' => false, 'msg' => 'AI is not set up yet (run the SQL).'];     }     $payload = [         'model'       => defined('GROQ_MODEL') ? GROQ_MODEL : 'llama-3.3-70b-versatile',         'messages'    => [['role' => 'system', 'content' => $system], ['role' => 'user', 'content' => $user]],         'temperature' => 0.3,         'max_tokens'  => max($max_tokens, 1500),      ];     if ($json) $payload['response_format'] = ['type' => 'json_object'];     if (strpos((string)$payload['model'], 'openai/gpt-oss') === 0) $payload['reasoning_effort'] = 'low';
if (strpos((string)$payload['model'], 'openai/gpt-oss') === 0) $payload['reasoning_effort'] = 'low';
$ch = curl_init('https://api.groq.com/openai/v1/chat/completions');     curl_setopt_array($ch, [         CURLOPT_RETURNTRANSFER => true,         CURLOPT_POST           => true,         CURLOPT_POSTFIELDS     => json_encode($payload),         CURLOPT_HTTPHEADER     => ['Content-Type: application/json', 'Authorization: Bearer ' . GROQ_API_KEY],         CURLOPT_TIMEOUT        => 20,         CURLOPT_SSL_VERIFYPEER => true,     ]);     $resp = curl_exec($ch);     $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);     $err  = curl_error($ch);     curl_close($ch);     if ($err || !$resp) { error_log('[NYMIX AI] curl: ' . $err); return ['ok' => false, 'msg' => 'AI service unreachable.']; }     if ($code === 429)  return ['ok' => false, 'msg' => 'AI is busy right now (free-tier limit). Try again in a minute.'];     $data = json_decode($resp, true);     $text = trim((string)($data['choices'][0]['message']['content'] ?? ''));     if ($code < 200 || $code >= 300 || $text === '') {         error_log('[NYMIX AI] HTTP ' . $code . ' ' . substr($resp, 0, 300));         return ['ok' => false, 'msg' => 'AI could not answer right now.' . (APP_ENV === 'development' ? ' [DEBUG HTTP ' . $code . ': ' . substr((string)$resp, 0, 300) . ']' : '')];     }     try {         $pdo->prepare("INSERT INTO ai_usage (client_id, feature, tokens) VALUES (?,?,?)")             ->execute([$client_id, $feature, (int)($data['usage']['total_tokens'] ?? 0)]);     } catch (Throwable $e) {}     return ['ok' => true, 'text' => $text]; }

// Deterministic SQL rules find the oddities; the AI only explains them.
function ai_anomaly_facts(PDO $pdo, int $client_id, int $bid): array {     $facts = [];     $bc = $bid ? ' AND s.branch_id = ?' : '';     $p  = $bid ? [$client_id, $bid] : [$client_id];      $st = $pdo->prepare("         SELECT u.full_name, COUNT(*) AS total, SUM(s.voided = 1) AS voids,                COALESCE(SUM(s.discount),0) AS disc, COALESCE(SUM(s.grand_total + s.discount),0) AS gross         FROM sales s JOIN users u ON u.id = s.served_by JOIN branches b ON b.id = s.branch_id         WHERE b.client_id = ? {$bc} AND s.sale_date >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)         GROUP BY u.id HAVING total >= 5");     $st->execute($p);     foreach ($st->fetchAll() as $r) {         $voids = (int)$r['voids']; $total = (int)$r['total'];         if ($voids >= 3 && $voids / $total >= 0.10) {             $facts[] = "{$r['full_name']} voided {$voids} of {$total} sales in the last 7 days (" . round($voids / $total * 100) . "%).";         }         $gross = (float)$r['gross'];         if ($gross > 0 && (float)$r['disc'] / $gross >= 0.08) {             $facts[] = "{$r['full_name']} gave discounts worth KSh " . number_format((float)$r['disc']) . " (" . round((float)$r['disc'] / $gross * 100) . "% of sales) in the last 7 days.";         }     }      $bc2 = $bid ? ' AND sm.branch_id = ?' : '';     $st = $pdo->prepare("         SELECT p.name, COUNT(*) AS n, SUM(-sm.quantity) AS qty, SUM(-sm.quantity * p.buying_price) AS val,                MAX(sm.note LIKE 'theft%') AS theft         FROM stock_movements sm JOIN products p ON p.id = sm.product_id JOIN branches b ON b.id = sm.branch_id         WHERE b.client_id = ? {$bc2} AND sm.type = 'adjustment' AND sm.quantity < 0           AND sm.created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY)           AND (sm.note LIKE 'damage%' OR sm.note LIKE 'theft%')         GROUP BY p.id HAVING n >= 3 OR theft = 1 ORDER BY val DESC LIMIT 5");     $st->execute($p);     foreach ($st->fetchAll() as $r) {         $facts[] = "Stock loss on {$r['name']}: {$r['n']} damage/theft write-offs, " . round((float)$r['qty'], 2) . " units, about KSh " . number_format((float)$r['val']) . " at cost" . ((int)$r['theft'] ? ' (includes a theft entry).' : '.');     }      $st = $pdo->prepare("SELECT COUNT(*) AS n, COALESCE(SUM(balance - credit_limit),0) AS over_amt FROM customers WHERE client_id = ? AND credit_limit > 0 AND balance > credit_limit");     $st->execute([$client_id]);     $c = $st->fetch();     if ((int)$c['n'] > 0) $facts[] = "{$c['n']} customer(s) are over their credit limit by a combined KSh " . number_format((float)$c['over_amt']) . ".";      return $facts; }  function ai_eod_summary(PDO $pdo, int $client_id, int $bid, string $date, array $totals): string {     try {         $prev = date('Y-m-d', strtotime($date . ' -7 days'));         $q = $pdo->prepare("SELECT COALESCE(SUM(grand_total),0) FROM sales WHERE branch_id = ? AND voided = 0 AND DATE(sale_date) = ?");         $q->execute([$bid, $prev]); $prevGross = (float)$q->fetchColumn();         $q = $pdo->prepare("SELECT COUNT(*) FROM sales WHERE branch_id = ? AND voided = 1 AND DATE(sale_date) = ?");         $q->execute([$bid, $date]); $voids = (int)$q->fetchColumn();         $q = $pdo->prepare("SELECT p.name, SUM(si.quantity * si.unit_price) AS rev FROM sale_items si             JOIN sales s ON s.id = si.sale_id JOIN products p ON p.id = si.product_id             WHERE s.branch_id = ? AND s.voided = 0 AND DATE(s.sale_date) = ? GROUP BY p.id ORDER BY rev DESC LIMIT 3");         $q->execute([$bid, $date]); $top = $q->fetchAll();         $q = $pdo->prepare("SELECT COUNT(*) FROM stock st JOIN products p ON p.id = st.product_id WHERE st.branch_id = ? AND p.reorder_level > 0 AND st.quantity <= p.reorder_level");         $q->execute([$bid]); $low = (int)$q->fetchColumn();          $gross = (float)($totals['gross'] ?? 0);         $facts = "Date: {$date}\nTransactions: " . (int)($totals['count'] ?? 0)             . "\nGross revenue: KSh " . number_format($gross)             . "\nSame weekday last week: KSh " . number_format($prevGross)             . "\nCash: KSh " . number_format((float)($totals['cash'] ?? 0))             . "\nM-Pesa: KSh " . number_format((float)($totals['mpesa'] ?? 0))             . "\nCredit given: KSh " . number_format((float)($totals['credit'] ?? 0))             . "\nVoided sales today: {$voids}\nItems at or below reorder level: {$low}\nTop products: "             . implode(', ', array_map(fn($t) => $t['name'] . ' (KSh ' . number_format((float)$t['rev']) . ')', $top));         $r = ai_chat($pdo, $client_id, 'eod_summary',             "You write a 3 to 4 sentence end-of-day summary for a Kenyan shop owner. Use ONLY the numbers given. Compare with last week's same day, and end with one thing to watch. Plain text, no markdown, no emojis, no greeting.",             $facts, false, 250);         return $r['ok'] ? $r['text'] : '';     } catch (Throwable $e) { error_log('[NYMIX AI EOD] ' . $e->getMessage()); return ''; } }  function nx_pdf_escape(string $s): string { return str_replace(['\\','(',')'], ['\\\\','\\(','\\)'], $s); }

function nx_generate_salary_pdf(string $title, array $rows, float $total, string $filepath): bool {
    $lines = [$title, str_repeat('-', 78),
        sprintf('%-22s %-14s %-14s %14s','STAFF NAME','ID NUMBER','PHONE','AMOUNT (KSh)'),
        str_repeat('-', 78)];
    foreach ($rows as $r) {
        $lines[] = sprintf('%-22s %-14s %-14s %14s',
            substr($r['name'],0,22), substr($r['id_number'] ?? '-',0,14), substr($r['phone'] ?? '-',0,14),
            number_format((float)$r['amount'],2));
    }
    $lines[] = str_repeat('-', 78);
    $lines[] = sprintf('%-52s %14s', 'TOTAL', number_format($total,2));

    $content = "BT /F1 10 Tf 36 800 Td\n";
    foreach ($lines as $i => $ln) {
        $prefix = $i === 0 ? '' : "0 -14 Td\n";
        $content .= $prefix . "(" . nx_pdf_escape($ln) . ") Tj\n";
    }
    $content .= "ET\n";
    $streamLen = strlen($content);

    $objs = [];
    $objs[1] = "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n";
    $objs[2] = "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n";
    $objs[3] = "3 0 obj\n<< /Type /Page /Parent 2 0 R /Resources << /Font << /F1 4 0 R >> >> /MediaBox [0 0 612 842] /Contents 5 0 R >>\nendobj\n";
    $objs[4] = "4 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>\nendobj\n";
    $objs[5] = "5 0 obj\n<< /Length {$streamLen} >>\nstream\n{$content}endstream\nendobj\n";

    $pdf = "%PDF-1.4\n";
    $offsets = [];
    foreach ($objs as $num => $obj) { $offsets[$num] = strlen($pdf); $pdf .= $obj; }
    $xrefStart = strlen($pdf);
    $count = count($objs) + 1;
    $xref = "xref\n0 {$count}\n0000000000 65535 f \n";
    for ($i = 1; $i <= count($objs); $i++) $xref .= sprintf("%010d 00000 n \n", $offsets[$i]);
    $pdf .= $xref . "trailer\n<< /Size {$count} /Root 1 0 R >>\nstartxref\n{$xrefStart}\n%%EOF";

    $dir = dirname($filepath);
    if (!is_dir($dir)) mkdir($dir, 0755, true);
    return (bool)file_put_contents($filepath, $pdf);
}

