// ── STAFF SELF-REGISTRATION: RATE LIMIT ────────────────────────
function reg_rate_check(string $ip): bool {
    $key = 'reg_attempts_' . md5($ip);
    if (!isset($_SESSION[$key])) $_SESSION[$key] = ['count' => 0, 'first' => time()];
    $att = &$_SESSION[$key];
    if ((time() - $att['first']) > 900) $att = ['count' => 0, 'first' => time()];
    return $att['count'] < 8;
}
function reg_rate_increment(string $ip): void {
    $key = 'reg_attempts_' . md5($ip);
    $_SESSION[$key]['count'] = ($_SESSION[$key]['count'] ?? 0) + 1;
}

