  <div class="alert alert-warning small text-start">📞 Contact <strong>NYMIX TECH</strong> to renew your subscription.</div>
  <a href="staff_portal.php?action=logout" class="btn btn-secondary w-100">Sign Out</a>
</div>
</body></html>';
    exit;
}

// ── CASCADE: deactivate branch users ─────────────────────────
function deactivate_branch_users(PDO $pdo, int $branch_id, int $client_id): void {
    $stmt = $pdo->prepare("
        UPDATE users SET is_active = 0
        WHERE branch_id = ?
          AND branch_id IN (SELECT id FROM branches WHERE client_id = ?)
    ");
    $stmt->execute([$branch_id, $client_id]);
}

// ── CASCADE: reactivate branch users ─────────────────────────
function reactivate_branch_users(PDO $pdo, int $branch_id, int $client_id): void {
    $stmt = $pdo->prepare("
        UPDATE users SET is_active = 1
        WHERE branch_id = ?
          AND branch_id IN (SELECT id FROM branches WHERE client_id = ?)
    ");
    $stmt->execute([$branch_id, $client_id]);
}

// ============================================================
//  LOGOUT
// ============================================================
$action = $_REQUEST['action'] ?? '';

// Speed/latency probe: no login needed, releases the session lock first
if ($action === 'ping') {
    session_write_close();
    while (ob_get_level() > 0) ob_end_clean();
    header('Cache-Control: no-store, no-cache, must-revalidate');
    $n = min(200000, max(0, (int)($_GET['size'] ?? 0)));
    if ($n > 0) { header('Content-Type: application/octet-stream'); echo random_bytes($n); }
    else { header('Content-Type: application/json'); echo '{"ok":true}'; }
    exit;
}

if ($action === 'logout') {
    session_unset();
    session_destroy();
    session_start();
    session_regenerate_id(true);
    setcookie(session_name(), '', time() - 3600, '/');
    redirect('staff_portal.php');
}

// ============================================================
//  LOGIN  (POST, before auth guard)
// ============================================================
if ($action === 'login' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $ip       = $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
    $username = trim($_POST['username'] ?? '');
    $password = $_POST['password'] ?? '';
    $is_reauth = logged_in(); // true when unlocking locked screen

    if (!login_rate_check($ip)) {
        json_out(['ok' => false, 'msg' => 'Too many failed attempts. Please wait 15 minutes.']);
    }

    if (!$username || !$password) {
        json_out(['ok' => false, 'msg' => 'Username and password are required.']);
    }

    $pdo  = db();
    $stmt = $pdo->prepare("
        SELECT u.*, r.name AS role_name,
               b.branch_name, b.address AS branch_address, b.phone AS branch_phone,
               b.client_id, b.is_active AS branch_active,
               c.status AS client_status, c.business_name, c.logo,
               c.phone AS client_phone, c.address AS client_address
        FROM users u
        JOIN roles r ON r.id = u.role_id
        LEFT JOIN branches b ON b.id = u.branch_id
        LEFT JOIN clients c ON c.id = b.client_id
        WHERE u.username = ? AND u.is_active = 1
        LIMIT 1
    ");
    $stmt->execute([$username]);
    $user = $stmt->fetch();

    if (!$user || !password_verify($password, $user['password_hash'])) {
        login_rate_increment($ip);

        // ── NEW: warn the owner after repeated failed attempts on a real account ──
        if ($user) {
            $key = 'login_attempts_' . md5($ip);
            $attemptCount = (int)($_SESSION[$key]['count'] ?? 0);
            if ($attemptCount === 3) {
                try {
                    $ownerInfo = nx_salary_owner_email((int)($user['client_id'] ?? 0));
                    if ($ownerInfo) {
                        $sub = "🔒 Repeated Failed Login — " . ($user['full_name'] ?? $username);
                        $bod = "Hi,\n\nThere have been multiple failed login attempts for the account below:\n\n"
                            . "Username: {$username}\n"
                            . "IP Address: {$ip}\n"
                            . "Time: " . date('Y-m-d H:i:s') . "\n\n"
                            . "If this wasn't the staff member, consider resetting their password.";
                        nx_staff_mail($ownerInfo['email'], $ownerInfo['name'], $sub, $bod, 'security');
                    }
                } catch (Throwable $e) { error_log('[NYMIX LOGIN ALERT] ' . $e->getMessage()); }
            }
        }

        // Timing-safe: always hash to prevent timing attacks
        json_out(['ok' => false, 'msg' => 'Invalid username or password.']);
    }

    // ── Block: branch inactive ────────────────────────────────
    if (isset($user['branch_active']) && !(int)$user['branch_active']) {
        json_out(['ok' => false, 'msg' => 'Your branch is currently inactive. Contact your administrator.']);
    }

    // ── Block: client account suspended ──────────────────────
    if (($user['client_status'] ?? '') === 'suspended') {
        json_out(['ok' => false, 'msg' => 'This system is not available. Contact your administrator.']);
    }

    // ── Block: subscription check ─────────────────────────────
    $client_id = (int)($user['client_id'] ?? 0);
    if ($client_id) {
        $sub = check_subscription($pdo, $client_id);
        if (in_array($sub['sub_status'], ['suspended', 'expired', 'no_sub'])) {
            json_out(['ok' => false, 'msg' => 'This system is not available. Contact your administrator.']);
        }
    }

    // ── Success ───────────────────────────────────────────────
    login_rate_reset($ip);
    session_regenerate_id(true); // session fixation protection
    $_SESSION['staff_id'] = $user['id'];
    $_SESSION['staff']    = $user;
    $pdo->prepare("UPDATE users SET last_login = NOW() WHERE id = ?")->execute([$user['id']]);
    $_SESSION['staff']['pwd_weak'] = pwd_is_weak($password, (string)$username) ? 1 : 0;
    json_out(['ok' => true]);
}

// ============================================================
//  FORGOT PASSWORD (staff — username based, OTP via email)
// ============================================================
function nx_staff_send_otp_email(string $toEmail, string $toName, string $otp): bool {
    $subject   = 'Your NYMIX Staff Portal Reset Code';
    $plainBody = "Hi {$toName},\n\nYour password reset code is: {$otp}\n\nThis code expires in 10 minutes. If you didn't request this, ignore this email.";
    return nx_mail_send($toEmail, $toName, $subject, nx_email_template($subject, $plainBody), $plainBody);
}

if ($action === 'staff_forgot_check' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim($_POST['username'] ?? '');
    if (!$username) json_out(['ok' => false, 'msg' => 'Enter your username.']);
    $pdo  = db();
    $stmt = $pdo->prepare("SELECT id, full_name, email FROM users WHERE username = ? AND is_active = 1 LIMIT 1");
    $stmt->execute([$username]);
    $u = $stmt->fetch();
    // Always same message to avoid leaking which usernames exist
    if (!$u) json_out(['ok' => false, 'msg' => 'Username not found or inactive. Contact your administrator.']);
    json_out(['ok' => true, 'has_email' => !empty($u['email']), 'masked_email' => $u['email'] ? substr($u['email'],0,2).'***@'.explode('@',$u['email'])[1] : null]);
}

if ($action === 'staff_forgot_send' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim($_POST['username'] ?? '');
    $email    = trim($_POST['email'] ?? '');
    if (!$username || !$email) json_out(['ok' => false, 'msg' => 'Username and email are required.']);
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) json_out(['ok' => false, 'msg' => 'Enter a valid email address.']);

    $pdo  = db();
    $stmt = $pdo->prepare("SELECT id, full_name FROM users WHERE username = ? AND is_active = 1 LIMIT 1");
    $stmt->execute([$username]);
    $u = $stmt->fetch();
    if (!$u) json_out(['ok' => false, 'msg' => 'Username not found.']);

    $otp     = (string)random_int(100000, 999999);
    $expires = date('Y-m-d H:i:s', strtotime('+10 minutes'));
    // Save/update email + OTP on the staff record
    $pdo->prepare("UPDATE users SET email = ?, otp_code = ?, otp_expires_at = ?, otp_attempts = 0 WHERE id = ?")
        ->execute([$email, $otp, $expires, $u['id']]);

    $sent = nx_staff_send_otp_email($email, $u['full_name'], $otp);
    if (!$sent) json_out(['ok' => false, 'msg' => 'Could not send email right now. Try again shortly.']);

    json_out(['ok' => true, 'msg' => 'Reset code sent to your email.']);
}

if ($action === 'staff_forgot_reset' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $username  = trim($_POST['username'] ?? '');
    $otp       = trim($_POST['otp'] ?? '');
    $password  = $_POST['password'] ?? '';
    $password2 = $_POST['password2'] ?? '';

    if (!$username || !$otp || !$password) json_out(['ok' => false, 'msg' => 'All fields are required.']);
    if (strlen($password) < 8) json_out(['ok' => false, 'msg' => 'Password must be at least 8 characters.']);
    if ($password !== $password2) json_out(['ok' => false, 'msg' => 'Passwords do not match.']);

    $pdo  = db();
    $stmt = $pdo->prepare("SELECT id, otp_code, otp_expires_at, otp_attempts FROM users WHERE username = ? AND is_active = 1 LIMIT 1");
    $stmt->execute([$username]);
    $u = $stmt->fetch();
    if (!$u) json_out(['ok' => false, 'msg' => 'Invalid request. Start over.']);
    if ((int)$u['otp_attempts'] >= 5) json_out(['ok' => false, 'msg' => 'Too many attempts. Request a new code.']);
    if (!$u['otp_code'] || $u['otp_code'] !== $otp || strtotime($u['otp_expires_at']) < time()) {
        $pdo->prepare("UPDATE users SET otp_attempts = otp_attempts + 1 WHERE id = ?")->execute([$u['id']]);
        json_out(['ok' => false, 'msg' => 'Invalid or expired code.']);
    }

    $hash = password_hash($password, PASSWORD_DEFAULT);
    $pdo->prepare("UPDATE users SET password_hash = ?, otp_code = NULL, otp_expires_at = NULL, otp_attempts = 0 WHERE id = ?")
        ->execute([$hash, $u['id']]);

    json_out(['ok' => true, 'msg' => 'Password reset! You can now sign in.']);
}

