if ($action === 'leave_add' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER])) json_out(['ok' => false, 'msg' => 'No permission.']);
    $pdo = db(); $uid = (int)($_POST['user_id'] ?? 0);
    $t = nx_payslip_target($pdo, $uid);
    if (!$t) json_out(['ok' => false, 'msg' => 'Staff member not found in your branch.']);
    $s = $_POST['start_date'] ?? ''; $e = $_POST['end_date'] ?? '';
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $s) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $e) || $e < $s) json_out(['ok' => false, 'msg' => 'Pick a valid start and end date.']);
    $type = in_array($_POST['leave_type'] ?? '', ['annual', 'sick', 'compassionate', 'maternity', 'paternity', 'unpaid', 'other'], true) ? $_POST['leave_type'] : 'annual';
    nx_q($pdo, "INSERT INTO staff_leave (client_id, branch_id, user_id, start_date, end_date, leave_type, reason, created_by) VALUES (?,?,?,?,?,?,?,?)",
        [(int)(me()['client_id'] ?? 0), (int)$t['branch_id'], $uid, $s, $e, $type, mb_substr(trim($_POST['reason'] ?? ''), 0, 250), (int)me()['id']]);
    nx_notify_user($pdo, $uid, 'Leave approved', ucfirst($type) . " leave from {$s} to {$e} was recorded for you.");
    json_out(['ok' => true]);
}

