if ($action === 'po_create' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER, ROLE_STOREKEEPER, ROLE_SUPPLIER_CLERK])) {
        json_out(['ok' => false, 'msg' => 'No permission.']);
    }
    $pdo       = db();
    $bid       = branch() ?: (int)($_POST['branch_id'] ?? 0);
    $sid       = (int)$_POST['supplier_id'];
    $date      = $_POST['expected_date'] ?? null;
    $note      = trim($_POST['note'] ?? '');
    $items     = json_decode($_POST['items'] ?? '[]', true);
    $client_id = (int)(me()['client_id'] ?? 0);
    if (empty($items)) json_out(['ok' => false, 'msg' => 'Add at least one item.']);
    // Verify branch and supplier belong to this client
    $bchk = $pdo->prepare("SELECT id FROM branches WHERE id = ? AND client_id = ?");
    $bchk->execute([$bid, $client_id]);
    if (!$bchk->fetch()) json_out(['ok' => false, 'msg' => 'Invalid branch.']);
    $schk = $pdo->prepare("SELECT id FROM suppliers WHERE id = ? AND client_id = ?");
    $schk->execute([$sid, $client_id]);
    if (!$schk->fetch()) json_out(['ok' => false, 'msg' => 'Invalid supplier.']);
    $total = array_reduce($items, fn($c, $i) => $c + $i['qty'] * $i['price'], 0);
    $lpo   = gen_lpo();
    $pdo->prepare("INSERT INTO purchase_orders (branch_id, supplier_id, created_by, lpo_number, total_amount, expected_date, note)
        VALUES (?,?,?,?,?,?,?)")
        ->execute([$bid, $sid, me()['id'], $lpo, $total, $date, $note]);
    $po_id = $pdo->lastInsertId();
    $pi = $pdo->prepare("INSERT INTO purchase_items (purchase_order_id, product_id, quantity_ordered, buying_price) VALUES (?,?,?,?)");
    foreach ($items as $it) {
        $pi->execute([$po_id, (int)$it['id'], (float)$it['qty'], (float)$it['price']]);
    }

    // ── NEW: notify supplier + owner that a new LPO was raised ──
    try {
        $supRow = $pdo->prepare("SELECT name, email FROM suppliers WHERE id = ?");
        $supRow->execute([$sid]);
        $supplier = $supRow->fetch();
        $bnm = $pdo->prepare("SELECT branch_name FROM branches WHERE id = ?");
        $bnm->execute([$bid]);
        $branch_name_po = $bnm->fetchColumn() ?: 'Branch';

        $itemLines = '';
        foreach ($items as $it) { $itemLines .= "  - " . ($it['name'] ?? 'Item') . " x" . $it['qty'] . " @ KSh " . number_format((float)$it['price'], 2) . "\n"; }

        $po_subject = "📦 New Purchase Order {$lpo} — {$branch_name_po}";
        $po_body = "Hi,\n\nA new Purchase Order has been raised:\n\n"
            . "LPO Number: {$lpo}\n"
            . "Branch: {$branch_name_po}\n"
            . "Supplier: " . ($supplier['name'] ?? 'Supplier') . "\n"
            . "Total: KSh " . number_format($total, 2) . "\n"
            . "Expected Date: " . ($date ?: 'Not specified') . "\n\n"
            . "Items:\n{$itemLines}";

        if ($supplier && !empty($supplier['email'])) {
            nx_staff_mail($supplier['email'], $supplier['name'], $po_subject, $po_body, 'info');
        }
        $ownerInfo = nx_salary_owner_email($client_id);
        if ($ownerInfo) nx_staff_mail($ownerInfo['email'], $ownerInfo['name'], $po_subject, $po_body, 'info');
    } catch (Throwable $e) {
        error_log('[NYMIX PO NOTIFY] ' . $e->getMessage());
    }

    json_out(['ok' => true, 'lpo' => $lpo, 'po_id' => $po_id]);
}

