if ($action === 'payout_schedule' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    if (!can([ROLE_BRANCH_MANAGER])) json_out(['ok' => false, 'msg' => 'Only the branch manager can schedule payouts.']);
    $pdo = db(); $bid = branch(); $client_id = (int)(me()['client_id'] ?? 0);
    $uid = (int)($_POST['staff_user_id'] ?? 0);
    $ts  = strtotime(trim($_POST['disburse_at'] ?? ''));
    if (!$ts || $ts <= time()) json_out(['ok' => false, 'msg' => 'Pick a future date and time.']);
    $sp = nx_q($pdo, "SELECT sp.hourly_rate, sp.pay_method, u.full_name, u.email FROM staff_payroll sp JOIN users u ON u.id = sp.user_id WHERE sp.user_id = ? AND sp.branch_id = ? AND sp.pay_type = 'hourly'", [$uid, $bid])->fetch();
    if (!$sp || (float)$sp['hourly_rate'] <= 0) json_out(['ok' => false, 'msg' => 'Staff is not on hourly pay or has no hourly rate.']);

    $pdo->beginTransaction();
    try {
        $agg = nx_q($pdo, "SELECT COALESCE(SUM(TIMESTAMPDIFF(SECOND, clock_in, clock_out)),0) AS secs, MIN(DATE(clock_in)) AS s, MAX(DATE(clock_in)) AS e FROM staff_time_logs WHERE user_id = ? AND clock_out IS NOT NULL AND payout_id IS NULL", [$uid])->fetch();
        $hours = round(((int)$agg['secs']) / 3600, 2);
        if ($hours <= 0) { $pdo->rollBack(); json_out(['ok' => false, 'msg' => 'No unpaid hours for this staff member.']); }
        $rate = (float)$sp['hourly_rate']; $amount = round($hours * $rate, 2);
        nx_q($pdo, "INSERT INTO hourly_payouts (client_id, branch_id, staff_user_id, hours, rate, amount, pay_method, disburse_at, created_by) VALUES (?,?,?,?,?,?,?,?,?)",
            [$client_id, $bid, $uid, $hours, $rate, $amount, $sp['pay_method'], date('Y-m-d H:i:s', $ts), me()['id']]);
        $pid = (int)$pdo->lastInsertId();
        nx_q($pdo, "UPDATE staff_time_logs SET payout_id = ? WHERE user_id = ? AND clock_out IS NOT NULL AND payout_id IS NULL", [$pid, $uid]);
        $pdo->commit();
    } catch (Throwable $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        json_out(['ok' => false, 'msg' => APP_ENV === 'development' ? $e->getMessage() : 'Could not schedule payout.']);
    }

    $when = date('D, j M Y \a\t g:i A', $ts);
    $msg  = "Your pay of KSh " . number_format($amount, 2) . " for " . number_format($hours, 2) . " hours will be released on {$when} via " . nx_method_label($sp['pay_method']) . ".";
    nx_notify_user($pdo, $uid, 'Pay scheduled: ' . $when, $msg);
    if (!empty($sp['email'])) {
        nx_staff_mail($sp['email'], $sp['full_name'], 'Your pay has been scheduled',
            "Hi {$sp['full_name']},\n\n{$msg}\n\nHours: " . number_format($hours, 2) . "\nRate: KSh " . number_format($rate, 2) . "/hr\n\nMake sure your payment details are up to date under My Finance.", 'success');
    }
    json_out(['ok' => true, 'msg' => 'Payout scheduled. Staff notified by email and on the portal.']);
}

