// ════════════ MESSAGES + PASSWORD SECURITY ════════════
function pwd_is_weak(string $p, string $user = ''): bool {
    if (strlen($p) < 8) return true;
    if (!preg_match('/[A-Z]/', $p) || !preg_match('/[a-z]/', $p) || !preg_match('/\d/', $p)) return true;
    if ($user !== '' && stripos($p, $user) !== false) return true;
    foreach (['password', '12345678', 'qwerty', 'admin', 'welcome', 'nymix', 'letmein'] as $c) {
        if (stripos($p, $c) !== false) return true;
    }
    return false;
}

function msg_scope_old(): array {
    $me = (int)(me()['id'] ?? 0);
    if (role() === ROLE_OWNER)          return ['t.client_id = ?', [(int)(me()['client_id'] ?? 0)]];
    if (role() === ROLE_BRANCH_MANAGER) return ['(t.branch_id = ? OR t.created_by = ?)', [branch(), $me]];
    return ['t.created_by = ?', [$me]];
}
function msg_thread_for(PDO $pdo, int $tid): ?array {
    [$sql, $p] = msg_scope();
    return nx_q($pdo, "SELECT t.*, u.full_name AS creator FROM msg_threads t JOIN users u ON u.id = t.created_by WHERE t.id = ? AND {$sql}",
        array_merge([$tid], $p))->fetch() ?: null;
}
function msg_recipients(PDO $pdo, array $t, int $senderId): array {
    if (!empty($t['to_user_id'])) {
        $other = ($senderId === (int)$t['created_by']) ? (int)$t['to_user_id'] : (int)$t['created_by'];
        return nx_q($pdo, "SELECT id, email, full_name FROM users WHERE id = ? AND is_active = 1", [$other])->fetchAll();
    }
    if ($senderId === (int)$t['created_by']) {
        $rows = nx_q($pdo, "SELECT id, email, full_name FROM users WHERE branch_id = ? AND role_id = ? AND is_active = 1 AND id <> ?",
            [$t['branch_id'], ROLE_BRANCH_MANAGER, $senderId])->fetchAll();
        $cr = nx_q($pdo, "SELECT role_id FROM users WHERE id = ?", [$senderId])->fetch();
        if (!$rows || (int)($cr['role_id'] ?? 0) === ROLE_BRANCH_MANAGER) {
            $own = nx_q($pdo, "SELECT u.id, u.email, u.full_name FROM users u JOIN branches b ON b.id = u.branch_id
                WHERE u.role_id = ? AND b.client_id = ? AND u.is_active = 1 AND u.id <> ?",
                [ROLE_OWNER, $t['client_id'], $senderId])->fetchAll();
            $rows = array_merge($rows, $own);
        }
        return $rows;
    }
    return nx_q($pdo, "SELECT id, email, full_name FROM users WHERE id = ? AND is_active = 1", [$t['created_by']])->fetchAll();
}

if ($action === 'msg_threads_old') {
    $pdo = db(); $me = (int)me()['id'];
    [$sql, $p] = msg_scope();
    $rows = nx_q($pdo, "
        SELECT t.id, t.subject, t.category, t.status, t.last_message_at, t.created_by, u.full_name AS creator,
          (SELECT body FROM msg_messages m WHERE m.thread_id = t.id ORDER BY m.id DESC LIMIT 1) AS last_body,
          (SELECT COUNT(*) FROM msg_messages m WHERE m.thread_id = t.id AND m.sender_id <> ?
             AND m.id > COALESCE((SELECT last_read_id FROM msg_reads WHERE thread_id = t.id AND user_id = ?),0)) AS unread
        FROM msg_threads t JOIN users u ON u.id = t.created_by
        WHERE {$sql} ORDER BY t.last_message_at DESC LIMIT 100", array_merge([$me, $me], $p))->fetchAll();
    json_out(['ok' => true, 'threads' => $rows]);
}

if ($action === 'msg_thread_old') {
    $pdo = db(); $me = (int)me()['id'];
    $tid = (int)($_GET['id'] ?? 0);
    $t = msg_thread_for($pdo, $tid);
    if (!$t) json_out(['ok' => false, 'msg' => 'Conversation not found.']);
    $msgs = nx_q($pdo, "SELECT m.id, m.sender_id, m.body, m.created_at, u.full_name, r.name AS role_name
        FROM msg_messages m JOIN users u ON u.id = m.sender_id JOIN roles r ON r.id = u.role_id
        WHERE m.thread_id = ? ORDER BY m.id ASC LIMIT 500", [$tid])->fetchAll();
    $last = $msgs ? (int)end($msgs)['id'] : 0;
    nx_q($pdo, "INSERT INTO msg_reads (thread_id, user_id, last_read_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE last_read_id = VALUES(last_read_id)", [$tid, $me, $last]);
    json_out(['ok' => true, 'thread' => $t, 'messages' => $msgs, 'me' => $me]);
}

if ($action === 'msg_send' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    $pdo = db(); $me = (int)me()['id'];
    $body = trim($_POST['body'] ?? '');
    if ($body === '' || mb_strlen($body) > 2000) json_out(['ok' => false, 'msg' => 'Message must be 1–2000 characters.']);
    $tid = (int)($_POST['thread_id'] ?? 0); $isNew = false;

    if ($tid) {
        $t = msg_thread_for($pdo, $tid);
        if (!$t) json_out(['ok' => false, 'msg' => 'Conversation not found.']);
        if ($t['status'] !== 'open') json_out(['ok' => false, 'msg' => 'This conversation is closed.']);
    } else {
        $subject = trim($_POST['subject'] ?? '');
        if ($subject === '' || mb_strlen($subject) > 160) json_out(['ok' => false, 'msg' => 'Enter a subject (max 160 characters).']);
        $cat = in_array($_POST['category'] ?? '', ['general','product','payout','other'], true) ? $_POST['category'] : 'general';
        $bid = branch(); $cid = (int)(me()['client_id'] ?? 0);
        if (!$bid || !$cid) json_out(['ok' => false, 'msg' => 'Your account is not linked to a branch.']);
        $to = (int)($_POST['to_user_id'] ?? 0);
        if ($to) {
            $tu = nx_q($pdo, "SELECT u.id FROM users u JOIN branches b ON b.id = u.branch_id WHERE u.id = ? AND b.client_id = ? AND u.is_active = 1 AND u.id <> ? AND (? = 1 OR u.branch_id = ? OR u.role_id = 1)", [$to, $cid, $me, role() === ROLE_OWNER ? 1 : 0, branch()])->fetch();
            if (!$tu) json_out(['ok' => false, 'msg' => 'That person cannot be messaged.']);
        }
        nx_q($pdo, "INSERT INTO msg_threads (client_id, branch_id, created_by, subject, category, to_user_id) VALUES (?,?,?,?,?,?)", [$cid, $bid, $me, $subject, $cat, $to ?: null]);
        $tid = (int)$pdo->lastInsertId();
        $t = nx_q($pdo, "SELECT * FROM msg_threads WHERE id = ?", [$tid])->fetch();
        $isNew = true;
    }

    nx_q($pdo, "INSERT INTO msg_messages (thread_id, sender_id, body) VALUES (?,?,?)", [$tid, $me, $body]);
    $mid = (int)$pdo->lastInsertId();
    nx_q($pdo, "UPDATE msg_threads SET last_message_at = NOW() WHERE id = ?", [$tid]);
    nx_q($pdo, "INSERT INTO msg_reads (thread_id, user_id, last_read_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE last_read_id = VALUES(last_read_id)", [$tid, $me, $mid]);

    try {
        $who = me()['full_name'] ?? 'Staff';
        foreach (msg_recipients($pdo, $t, $me) as $r) {
            nx_notify_user($pdo, (int)$r['id'], ($isNew ? 'New message: ' : 'Reply: ') . $t['subject'], $who . ': ' . mb_substr($body, 0, 140));
            if ($isNew && !empty($r['email'])) {
                nx_staff_mail($r['email'], $r['full_name'], "New message from {$who}: {$t['subject']}",
                    "Hi {$r['full_name']},\n\n{$who} sent you a message:\n\n{$body}\n\nOpen the Staff Portal → Messages to reply.", 'info');
            }
        }
    } catch (Throwable $e) { error_log('[NYMIX MSG NOTIFY] ' . $e->getMessage()); }

    json_out(['ok' => true, 'thread_id' => $tid]);
}

if ($action === 'msg_status' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER])) json_out(['ok' => false, 'msg' => 'No permission.']);
    $pdo = db();
    $t = msg_thread_for($pdo, (int)($_POST['id'] ?? 0));
    if (!$t) json_out(['ok' => false, 'msg' => 'Conversation not found.']);
    $st = ($_POST['status'] ?? '') === 'closed' ? 'closed' : 'open';
    nx_q($pdo, "UPDATE msg_threads SET status = ? WHERE id = ?", [$st, $t['id']]);
    if ($st === 'closed') nx_notify_user($pdo, (int)$t['created_by'], 'Conversation closed', '"' . $t['subject'] . '" was marked as resolved.');
    json_out(['ok' => true]);
}

if ($action === 'password_change' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    $pdo = db(); $uid = (int)me()['id'];
    $cur = $_POST['current'] ?? ''; $new = $_POST['new'] ?? ''; $new2 = $_POST['new2'] ?? '';
    if ($new !== $new2) json_out(['ok' => false, 'msg' => 'New passwords do not match.']);
    if (pwd_is_weak($new, (string)(me()['username'] ?? ''))) json_out(['ok' => false, 'msg' => 'Still weak. Use 8+ characters with upper and lower case letters and a number, and avoid common words.']);
    $row = nx_q($pdo, "SELECT password_hash FROM users WHERE id = ?", [$uid])->fetch();
    if (!$row || !password_verify($cur, $row['password_hash'])) json_out(['ok' => false, 'msg' => 'Current password is incorrect.']);
    nx_q($pdo, "UPDATE users SET password_hash = ? WHERE id = ?", [password_hash($new, PASSWORD_DEFAULT), $uid]);
    $_SESSION['staff']['pwd_weak'] = 0;
    json_out(['ok' => true]);
}

// ════════════ MESSAGING v2 ════════════
function msg_scope(): array {
    $me = (int)(me()['id'] ?? 0);
    if (role() === ROLE_OWNER)
        return ['(t.client_id = ? AND (t.to_user_id IS NULL OR t.to_user_id = ? OR t.created_by = ?))', [(int)(me()['client_id'] ?? 0), $me, $me]];
    if (role() === ROLE_BRANCH_MANAGER)
        return ['((t.to_user_id IS NULL AND (t.branch_id = ? OR t.created_by = ?)) OR t.to_user_id = ? OR t.created_by = ?)', [branch(), $me, $me, $me]];
    return ['(t.created_by = ? OR t.to_user_id = ?)', [$me, $me]];
}
function msg_touch(PDO $pdo): void {
    try { nx_q($pdo, "UPDATE users SET last_seen = NOW() WHERE id = ?", [(int)(me()['id'] ?? 0)]); } catch (Throwable $e) {}
}
function msg_settings_for(PDO $pdo, int $uid): array {
    $r = nx_q($pdo, "SELECT show_last_seen, show_online, read_receipts, enter_to_send, sound FROM msg_settings WHERE user_id = ?", [$uid])->fetch();
    return $r ?: ['show_last_seen' => 1, 'show_online' => 1, 'read_receipts' => 1, 'enter_to_send' => 1, 'sound' => 1];
}
function msg_people(PDO $pdo, array $ids): array {
    $ids = array_values(array_unique(array_filter(array_map('intval', $ids))));
    if (!$ids) return [];
    $in = implode(',', $ids);
    $rows = nx_q($pdo, "SELECT u.id, u.full_name, u.photo_path, u.id_verified, r.name AS role_name, b.branch_name,
            TIMESTAMPDIFF(SECOND, u.last_seen, NOW()) AS seen_ago,
            COALESCE(s.show_last_seen,1) AS show_last_seen, COALESCE(s.show_online,1) AS show_online
        FROM users u JOIN roles r ON r.id = u.role_id
        LEFT JOIN branches b ON b.id = u.branch_id
        LEFT JOIN msg_settings s ON s.user_id = u.id
        WHERE u.id IN ($in)")->fetchAll();
    $canSee = (int)msg_settings_for($pdo, (int)me()['id'])['show_last_seen'] === 1; // hide yours = can't see theirs
    $out = [];
    foreach ($rows as $r) {
        $ago = $r['seen_ago'] === null ? null : (int)$r['seen_ago'];
        $out[(int)$r['id']] = [
            'id' => (int)$r['id'], 'name' => $r['full_name'], 'photo' => $r['photo_path'] ?: '',
            'verified' => (int)$r['id_verified'], 'role' => $r['role_name'], 'branch' => $r['branch_name'] ?: '',
            'online'   => ($canSee && (int)$r['show_online'] && $ago !== null) ? ($ago < 120) : null,
            'seen_ago' => ($canSee && (int)$r['show_last_seen'] && $ago !== null) ? $ago : null,
        ];
    }
    return $out;
}

if ($action === 'msg_contacts') {
    $pdo = db(); $me = (int)me()['id']; $cid = (int)(me()['client_id'] ?? 0);
    msg_touch($pdo);
    $extra = ''; $p = [$cid, $me];
    if (role() === ROLE_BRANCH_MANAGER)   { $extra = ' AND (u.branch_id = ? OR u.role_id = 1)'; $p[] = branch(); }
    elseif (role() !== ROLE_OWNER)        { $extra = ' AND (u.branch_id = ? OR u.role_id = 1)';      $p[] = branch(); }
    $ids = nx_q($pdo, "SELECT u.id FROM users u JOIN branches b ON b.id = u.branch_id
        WHERE b.client_id = ? AND u.is_active = 1 AND u.id <> ?{$extra} ORDER BY u.full_name", $p)->fetchAll(PDO::FETCH_COLUMN);
    $people = msg_people($pdo, $ids);
    $list = [];
    foreach ($ids as $i) if (isset($people[(int)$i])) $list[] = $people[(int)$i];
    json_out(['ok' => true, 'contacts' => $list]);
}

if ($action === 'msg_threads') {
    $pdo = db(); $me = (int)me()['id'];
    msg_touch($pdo);
    [$sql, $p] = msg_scope();
    $rows = nx_q($pdo, "
        SELECT t.id, t.subject, t.category, t.status, t.last_message_at, t.created_by, t.to_user_id, u.full_name AS creator,
          (SELECT body FROM msg_messages m WHERE m.thread_id = t.id ORDER BY m.id DESC LIMIT 1) AS last_body,
          (SELECT COUNT(*) FROM msg_messages m WHERE m.thread_id = t.id AND m.sender_id <> ?
             AND m.id > COALESCE((SELECT last_read_id FROM msg_reads WHERE thread_id = t.id AND user_id = ?),0)) AS unread
        FROM msg_threads t JOIN users u ON u.id = t.created_by
        WHERE {$sql} ORDER BY t.last_message_at DESC LIMIT 100", array_merge([$me, $me], $p))->fetchAll();
    $ids = [];
    foreach ($rows as &$r) {
        $cb = (int)$r['created_by'];
        $peer = $r['to_user_id'] ? ($cb === $me ? (int)$r['to_user_id'] : $cb) : ($cb === $me ? 0 : $cb);
        $r['peer_id'] = $peer; if ($peer) $ids[] = $peer;
    } unset($r);
    json_out(['ok' => true, 'threads' => $rows, 'people' => msg_people($pdo, $ids)]);
}

if ($action === 'msg_thread') {
    $pdo = db(); $me = (int)me()['id'];
    msg_touch($pdo);
    $tid = (int)($_GET['id'] ?? 0);
    $t = msg_thread_for($pdo, $tid);
    if (!$t) json_out(['ok' => false, 'msg' => 'Conversation not found.']);
    $msgs = nx_q($pdo, "SELECT m.id, m.sender_id, m.body, m.created_at, u.full_name, u.photo_path, u.id_verified, r.name AS role_name
        FROM msg_messages m JOIN users u ON u.id = m.sender_id JOIN roles r ON r.id = u.role_id
        WHERE m.thread_id = ? ORDER BY m.id ASC LIMIT 500", [$tid])->fetchAll();
    $last = $msgs ? (int)end($msgs)['id'] : 0;
    nx_q($pdo, "INSERT INTO msg_reads (thread_id, user_id, last_read_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE last_read_id = VALUES(last_read_id)", [$tid, $me, $last]);

    $mine   = msg_settings_for($pdo, $me);
    $recips = array_map(fn($r) => (int)$r['id'], msg_recipients($pdo, $t, $me));
    $readUpto = 0; $delivUpto = 0;
    if ($recips) {
        $in = implode(',', $recips);
        if ((int)$mine['read_receipts'] === 1) {
            $readUpto = (int)nx_q($pdo, "SELECT COALESCE(MAX(r.last_read_id),0) FROM msg_reads r
                LEFT JOIN msg_settings s ON s.user_id = r.user_id
                WHERE r.thread_id = ? AND r.user_id IN ($in) AND COALESCE(s.read_receipts,1) = 1", [$tid])->fetchColumn();
        }
        $delivUpto = (int)nx_q($pdo, "SELECT COALESCE(MAX(m.id),0) FROM msg_messages m
            WHERE m.thread_id = ? AND EXISTS (SELECT 1 FROM users u WHERE u.id IN ($in) AND u.last_seen >= m.created_at)", [$tid])->fetchColumn();
    }
    json_out(['ok' => true, 'thread' => $t, 'messages' => $msgs, 'me' => $me,
              'read_upto' => $readUpto, 'deliv_upto' => max($readUpto, $delivUpto),
              'people' => msg_people($pdo, $recips), 'settings' => $mine]);
}

if ($action === 'msg_settings') {
    json_out(['ok' => true, 'settings' => msg_settings_for(db(), (int)me()['id'])]);
}
if ($action === 'msg_settings_save' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    $b = fn($k) => !empty($_POST[$k]) ? 1 : 0;
    nx_q(db(), "INSERT INTO msg_settings (user_id, show_last_seen, show_online, read_receipts, enter_to_send, sound) VALUES (?,?,?,?,?,?)
        ON DUPLICATE KEY UPDATE show_last_seen=VALUES(show_last_seen), show_online=VALUES(show_online),
        read_receipts=VALUES(read_receipts), enter_to_send=VALUES(enter_to_send), sound=VALUES(sound)",
        [(int)me()['id'], $b('show_last_seen'), $b('show_online'), $b('read_receipts'), $b('enter_to_send'), $b('sound')]);
    json_out(['ok' => true]);
}

// ── PESAPAL HELPERS ───────────────────────────────────────────
function pesapal_get_token(): array {
    $body = json_encode([
        'consumer_key'    => trim(PESAPAL_CONSUMER_KEY),
        'consumer_secret' => trim(PESAPAL_CONSUMER_SECRET),
    ]);
    $ch = curl_init(PESAPAL_BASE_URL . '/api/Auth/RequestToken');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => $body,
        CURLOPT_HTTPHEADER     => [
            'Content-Type: application/json',
            'Accept: application/json',
            'Content-Length: ' . strlen($body),
        ],
        CURLOPT_TIMEOUT        => 15,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $err  = curl_error($ch);
    curl_close($ch);
    if ($err || !$resp) return ['ok' => false, 'msg' => 'Token fetch failed: ' . $err];
    $data = json_decode($resp, true);
    if (empty($data['token'])) return ['ok' => false, 'msg' => 'No token returned: ' . json_encode($data), 'raw' => $data];
    return ['ok' => true, 'token' => $data['token']];
}

function pesapal_register_ipn(string $token): array {
    $ch = curl_init(PESAPAL_BASE_URL . '/api/URLSetup/RegisterIPN');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode([
            'url'              => PESAPAL_IPN_URL,
            'ipn_notification_type' => 'GET',
        ]),
        CURLOPT_HTTPHEADER     => [
            'Content-Type: application/json',
            'Accept: application/json',
            'Authorization: Bearer ' . $token,
        ],
        CURLOPT_TIMEOUT        => 15,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    curl_close($ch);
    $data = json_decode($resp ?: '{}', true);
    if (empty($data['ipn_id'])) return ['ok' => false, 'msg' => 'IPN registration failed', 'raw' => $data];
    return ['ok' => true, 'ipn_id' => $data['ipn_id']];
}

// ── DARAJA (M-PESA) SANDBOX HELPERS — SYMPOSIUM DEMO ──────────
function daraja_get_token(): array {
    $cacheFile = __DIR__ . '/uploads/cache/daraja_token.json';
    $cacheDir  = dirname($cacheFile);
    if (!is_dir($cacheDir)) @mkdir($cacheDir, 0755, true);

    // Serve from cache if still valid — tokens last ~1hr, refresh 5 min early
    if (file_exists($cacheFile)) {
        $cached = json_decode(@file_get_contents($cacheFile), true);
        if ($cached && !empty($cached['token']) && ($cached['expires_at'] ?? 0) > time() + 300) {
            return ['ok' => true, 'token' => $cached['token']];
        }
    }

    // Lock so multiple tills refreshing at the same second don't all hit
    // Safaricom together — only one till does the real fetch, the rest wait
    // a moment then read the freshly-cached token.
    $lockFile   = $cacheFile . '.lock';
    $lockHandle = @fopen($lockFile, 'c');
    if ($lockHandle && flock($lockHandle, LOCK_EX)) {
        // Re-check cache after acquiring the lock — another till may have
        // already refreshed it while we were waiting.
        if (file_exists($cacheFile)) {
            $cached = json_decode(@file_get_contents($cacheFile), true);
            if ($cached && !empty($cached['token']) && ($cached['expires_at'] ?? 0) > time() + 300) {
                flock($lockHandle, LOCK_UN); fclose($lockHandle);
                return ['ok' => true, 'token' => $cached['token']];
            }
        }

        $creds = base64_encode(DARAJA_CONSUMER_KEY . ':' . DARAJA_CONSUMER_SECRET);
        $ch = curl_init(DARAJA_BASE_URL . '/oauth/v1/generate?grant_type=client_credentials');
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER     => ['Authorization: Basic ' . $creds],
            CURLOPT_TIMEOUT        => 15,
            CURLOPT_SSL_VERIFYPEER => true,
        ]);
        $resp = curl_exec($ch);
        $err  = curl_error($ch);
        $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        error_log('[DARAJA TOKEN] HTTP=' . $code . ' resp=' . $resp . ' curl_err=' . $err);

        if ($err || !$resp) {
            flock($lockHandle, LOCK_UN); fclose($lockHandle);
            return ['ok' => false, 'msg' => 'Daraja token fetch failed: ' . $err];
        }
        $data = json_decode($resp, true);
        if (empty($data['access_token'])) {
            flock($lockHandle, LOCK_UN); fclose($lockHandle);
            return ['ok' => false, 'msg' => 'No access token returned (HTTP ' . $code . '): ' . $resp];
        }

        $expiresIn = (int)($data['expires_in'] ?? 3599);
        @file_put_contents($cacheFile, json_encode([
            'token'      => $data['access_token'],
            'expires_at' => time() + $expiresIn,
        ]));

        flock($lockHandle, LOCK_UN); fclose($lockHandle);
        return ['ok' => true, 'token' => $data['access_token']];
    }

    // Couldn't get the lock for some reason — fall back to a direct fetch
    // so the sale isn't blocked entirely.
    $creds = base64_encode(DARAJA_CONSUMER_KEY . ':' . DARAJA_CONSUMER_SECRET);
    $ch = curl_init(DARAJA_BASE_URL . '/oauth/v1/generate?grant_type=client_credentials');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER     => ['Authorization: Basic ' . $creds],
        CURLOPT_TIMEOUT        => 15,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $err  = curl_error($ch);
    curl_close($ch);
    if ($err || !$resp) return ['ok' => false, 'msg' => 'Daraja token fetch failed: ' . $err];
    $data = json_decode($resp, true);
    if (empty($data['access_token'])) return ['ok' => false, 'msg' => 'No access token returned: ' . $resp];
    return ['ok' => true, 'token' => $data['access_token']];
}

function daraja_stk_push(string $phone, float $amount, string $account_ref, string $desc): array {
    $tok = daraja_get_token();
    if (!$tok['ok']) return $tok;

    $timestamp = date('YmdHis');
    $password  = base64_encode(DARAJA_SHORTCODE . DARAJA_PASSKEY . $timestamp);

    $payload = [
        'BusinessShortCode' => DARAJA_SHORTCODE,
        'Password'          => $password,
        'Timestamp'         => $timestamp,
        'TransactionType'   => 'CustomerPayBillOnline',
        'Amount'            => max(1, round($amount)), // sandbox wants whole numbers
        'PartyA'            => $phone,
        'PartyB'            => DARAJA_SHORTCODE,
        'PhoneNumber'       => $phone,
        'CallBackURL'       => DARAJA_CALLBACK_URL,
        'AccountReference'  => substr($account_ref, 0, 12) ?: 'NYMIXDEMO',
        'TransactionDesc'   => substr($desc, 0, 13) ?: 'POS Demo Sale',
    ];

    $ch = curl_init(DARAJA_BASE_URL . '/mpesa/stkpush/v1/processrequest');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode($payload),
        CURLOPT_HTTPHEADER     => [
            'Content-Type: application/json',
            'Authorization: Bearer ' . $tok['token'],
        ],
        CURLOPT_TIMEOUT        => 20,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $err  = curl_error($ch);
    curl_close($ch);

    if ($err || !$resp) return ['ok' => false, 'msg' => 'STK push request failed: ' . $err];
    $data = json_decode($resp, true);

    if (($data['ResponseCode'] ?? '') === '0') {
        return [
            'ok' => true,
            'checkout_request_id' => $data['CheckoutRequestID'],
            'merchant_request_id' => $data['MerchantRequestID'],
        ];
    }
    return ['ok' => false, 'msg' => $data['errorMessage'] ?? ($data['CustomerMessage'] ?? 'STK push rejected by Safaricom.'), 'raw' => $data];
}

function daraja_stk_query(string $checkout_request_id): array {
    $tok = daraja_get_token();
    if (!$tok['ok']) return $tok;

    $timestamp = date('YmdHis');
    $password  = base64_encode(DARAJA_SHORTCODE . DARAJA_PASSKEY . $timestamp);

    $payload = [
        'BusinessShortCode' => DARAJA_SHORTCODE,
        'Password'          => $password,
        'Timestamp'         => $timestamp,
        'CheckoutRequestID' => $checkout_request_id,
    ];

    $ch = curl_init(DARAJA_BASE_URL . '/mpesa/stkpushquery/v1/query');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode($payload),
        CURLOPT_HTTPHEADER     => [
            'Content-Type: application/json',
            'Authorization: Bearer ' . $tok['token'],
        ],
        CURLOPT_TIMEOUT        => 15,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp = curl_exec($ch);
    $err  = curl_error($ch);
    curl_close($ch);

    if ($err || !$resp) return ['ok' => false, 'msg' => 'Query failed: ' . $err, 'pending' => true];
    $data = json_decode($resp, true);

    // ResultCode 0 = paid. Only specific codes are a genuine, final cancel/failure.
    // Anything else (including transient "still processing" error bodies) just
    // means keep waiting — don't bail the customer out early.
    $result_code = $data['ResultCode'] ?? null;

    if ($result_code === '0' || $result_code === 0) {
        return ['ok' => true, 'paid' => true, 'raw' => $data];
    }

    // Real terminal failures from Safaricom:
    // 1032 = cancelled by user, 1037 = timeout/no response, 2001 = wrong PIN, 1 = insufficient balance
    $final_fail_codes = ['1032', '1037', '2001', '1'];
    if ($result_code !== null && in_array((string)$result_code, $final_fail_codes, true)) {
        return ['ok' => true, 'paid' => false, 'cancelled' => true, 'msg' => $data['ResultDesc'] ?? 'Payment not completed.', 'raw' => $data];
    }

    // No ResultCode yet, or an unrecognized/transient code — still processing.
    return ['ok' => true, 'paid' => false, 'pending' => true, 'raw' => $data];
}

// ── PESAPAL CHECKOUT ──────────────────────────────────────────
if ($action === 'pesapal_checkout' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    // CSRF skipped — action is auth-gated; session may regenerate across Pesapal redirect
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER, ROLE_CASHIER])) {
        json_out(['ok' => false, 'msg' => 'No permission.']);
    }

    $amount      = (float)($_POST['amount'] ?? 0);
    $phone       = trim($_POST['phone'] ?? '');
    $customer_name = trim($_POST['customer_name'] ?? 'Customer');
    $sale_ref    = 'POS-' . date('Ymd') . '-' . strtoupper(substr(uniqid(), -5));

    if ($amount <= 0) json_out(['ok' => false, 'msg' => 'Invalid amount.']);

    // Normalise phone to 254XXXXXXXXX
    $phone = preg_replace('/\D/', '', $phone);
    if (str_starts_with($phone, '0'))    $phone = '254' . substr($phone, 1);
    if (str_starts_with($phone, '+'))    $phone = substr($phone, 1);
    if (!str_starts_with($phone, '254')) $phone = '254' . $phone;

    // Step 1: Get token
    $tok = pesapal_get_token();
    if (!$tok['ok']) json_out(['ok' => false, 'msg' => $tok['msg']]);
    $token = $tok['token'];

    // Step 2: Register IPN (safe to call every time — Pesapal deduplicates)
    $ipn = pesapal_register_ipn($token);
    $ipn_id = $ipn['ipn_id'] ?? '';

    // Step 3: Submit order
    $order_payload = [
        'id'                      => $sale_ref,
        'currency'                => 'KES',
        'amount'                  => $amount,
        'description'             => 'POS Sale at ' . (me()['branch_name'] ?? 'Branch'),
        'callback_url'            => PESAPAL_CALLBACK_URL,
        'notification_id'         => $ipn_id,
        'billing_address'         => [
            'phone_number'        => $phone,
            'first_name'          => $customer_name,
            'last_name'           => '',
            'email_address'       => '',
        ],
    ];

    $ch = curl_init(PESAPAL_BASE_URL . '/api/Transactions/SubmitOrderRequest');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => json_encode($order_payload),
        CURLOPT_HTTPHEADER     => [
            'Content-Type: application/json',
            'Accept: application/json',
            'Authorization: Bearer ' . $token,
        ],
        CURLOPT_TIMEOUT        => 20,
        CURLOPT_SSL_VERIFYPEER => true,
    ]);
    $resp      = curl_exec($ch);
    $curl_err  = curl_error($ch);
    curl_close($ch);

    if ($curl_err || !$resp) {
        json_out(['ok' => false, 'msg' => 'Pesapal request failed: ' . $curl_err]);
    }

    $result = json_decode($resp, true);

    if (empty($result['redirect_url'])) {
        json_out(['ok' => false, 'msg' => $result['error']['message'] ?? 'No redirect URL returned.', 'raw' => $result]);
    }

    // Store tracking details in session so pesapal_return can reconcile
    $_SESSION['pesapal_pending'] = [
        'order_tracking_id' => $result['order_tracking_id'],
        'merchant_reference'=> $sale_ref,
        'amount'            => $amount,
        'phone'             => $phone,
    ];

    json_out([
        'ok'               => true,
        'redirect_url'     => $result['redirect_url'],
        'order_tracking_id'=> $result['order_tracking_id'],
        'merchant_reference'=> $sale_ref,
    ]);
}

// ── DARAJA STK PUSH (sandbox demo) ────────────────────────────
if ($action === 'daraja_stk_push' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER, ROLE_CASHIER])) {
        json_out(['ok' => false, 'msg' => 'No permission.']);
    }
    $amount = (float)($_POST['amount'] ?? 0);
    if ($amount <= 0) json_out(['ok' => false, 'msg' => 'Invalid amount.']);

    // Use the phone number typed in by the user; fall back to Safaricom's
    // public sandbox test number only if nothing was provided.
    $phone = trim($_POST['phone'] ?? '');
    if ($phone) {
        $phone = preg_replace('/\D/', '', $phone);
        if (str_starts_with($phone, '0'))    $phone = '254' . substr($phone, 1);
        if (!str_starts_with($phone, '254')) $phone = '254' . $phone;
    } else {
        $phone = DARAJA_TEST_PHONE;
    }

    $result = daraja_stk_push($phone, $amount, 'NYMIXDEMO', 'POS Demo Sale');
    json_out($result);
}

// ── DARAJA STK QUERY (poll for result — sandbox demo) ─────────
if ($action === 'daraja_stk_query') {
    $checkout_id = trim($_GET['checkout_request_id'] ?? $_POST['checkout_request_id'] ?? '');
    if (!$checkout_id) json_out(['ok' => false, 'msg' => 'Missing checkout_request_id.']);
    $result = daraja_stk_query($checkout_id);
    json_out($result);
}

// ── DARAJA CALLBACK (server-to-server, Safaricom hits this) ───
if ($action === 'daraja_callback') {
    http_response_code(200);
    header('Content-Type: application/json');
    $raw = file_get_contents('php://input');
    error_log('[DARAJA CALLBACK] ' . $raw);
    echo json_encode(['ResultCode' => 0, 'ResultDesc' => 'Accepted']);
    exit;
}

    
    
    

// ── PESAPAL IPN CALLBACK (server-to-server GET) ───────────────
if ($action === 'pesapal_ipn') {
    http_response_code(200);
    header('Content-Type: application/json');

    $tracking_id  = $_GET['OrderTrackingId']  ?? '';
    $merchant_ref = $_GET['OrderMerchantReference'] ?? '';
    $notification = $_GET['OrderNotificationType'] ?? '';

    if (!$tracking_id) { echo json_encode(['orderNotificationType' => $notification, 'orderTrackingId' => $tracking_id, 'orderMerchantReference' => $merchant_ref, 'status' => '200']); exit; }

    // Get token and fetch transaction status
    $tok = pesapal_get_token();
    if ($tok['ok']) {
        $ch = curl_init(PESAPAL_BASE_URL . '/api/Transactions/GetTransactionStatus?orderTrackingId=' . urlencode($tracking_id));
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER     => [
                'Accept: application/json',
                'Authorization: Bearer ' . $tok['token'],
            ],
            CURLOPT_TIMEOUT        => 10,
            CURLOPT_SSL_VERIFYPEER => true,
        ]);
        $status_resp = curl_exec($ch);
        curl_close($ch);
        $status = json_decode($status_resp ?: '{}', true);

        // payment_status_description: "Completed" = paid
        if (($status['payment_status_description'] ?? '') === 'Completed') {
            error_log("Pesapal IPN PAID: tracking=$tracking_id ref=$merchant_ref code=" . ($status['confirmation_code'] ?? ''));
            // You can update a pending_payments table here if needed
        }
    }

    echo json_encode(['orderNotificationType' => $notification, 'orderTrackingId' => $tracking_id, 'orderMerchantReference' => $merchant_ref, 'status' => '200']);
    exit;
}

// ── PESAPAL RETURN (customer redirect back after payment) ─────
if ($action === 'pesapal_return') {
    $tracking_id  = $_GET['OrderTrackingId']  ?? '';
    $merchant_ref = $_GET['OrderMerchantReference'] ?? '';

    if (!$tracking_id) { redirect('staff_portal.php'); }

    // Verify status
    $tok    = pesapal_get_token();
    $status = [];
    if ($tok['ok']) {
        $ch = curl_init(PESAPAL_BASE_URL . '/api/Transactions/GetTransactionStatus?orderTrackingId=' . urlencode($tracking_id));
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_HTTPHEADER     => ['Accept: application/json', 'Authorization: Bearer ' . $tok['token']],
            CURLOPT_TIMEOUT        => 10,
            CURLOPT_SSL_VERIFYPEER => true,
        ]);
        $status = json_decode(curl_exec($ch) ?: '{}', true);
        curl_close($ch);
    }

    $paid        = ($status['payment_status_description'] ?? '') === 'Completed';
    $mpesa_code  = $status['confirmation_code'] ?? '';
    $amount      = $status['amount'] ?? ($_SESSION['pesapal_pending']['amount'] ?? 0);

    // Store result in session for JS to pick up
    $_SESSION['pesapal_result'] = [
        'paid'       => $paid,
        'mpesa_code' => $mpesa_code,
        'amount'     => $amount,
        'tracking_id'=> $tracking_id,
        'merchant_ref'=> $merchant_ref,
    ];

    // Redirect back to POS with result flag
    redirect('staff_portal.php?pesapal_result=1');
}

// ── PESAPAL RESULT SESSION READER ────────────────────────────
if ($action === 'pesapal_result_session') {
