    if ($result) {
        json_out(['ok' => true, ...$result]);
    } else {
        json_out(['ok' => false, 'paid' => false]);
    }
}



// ── STEP 1: confirm identity against appointed_staff list ──────
// ── STEP 1 (new): scan the NYMIX card → identify the appointment ──
if ($action === 'staff_register_card' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $ip = $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
    if (!reg_rate_check($ip)) json_out(['ok' => false, 'msg' => 'Too many attempts. Please wait 15 minutes and try again.']);
    $no   = strtoupper(trim((string)($_POST['card_no'] ?? '')));
    $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($_POST['code'] ?? '')));
    $bad  = ['ok' => false, 'msg' => 'That card number and security code do not match any pending appointment.'];
    if (!preg_match('/^NX-[0-9A-F]{8}-[0-9]{4}$/', $no) || strlen($code) !== 12) { reg_rate_increment($ip); json_out($bad); }

    $pdo = db();
    $st = $pdo->prepare("
        SELECT a.*, b.branch_name, b.address AS branch_address, c.business_name, c.id AS client_id, r.name AS role_name
        FROM appointed_staff a
        JOIN branches b ON b.id = a.branch_id
        JOIN clients c ON c.id = a.client_id
        JOIN roles r ON r.id = a.expected_role_id
        WHERE a.card_no = ? LIMIT 1
    ");
    $st->execute([$no]);
    $match = $st->fetch();
    if (!$match || !hash_equals(card_sig($no, 0), $code)) { reg_rate_increment($ip); json_out($bad); }
    if ($match['status'] === 'registered') json_out(['ok' => false, 'msg' => 'already_registered']);

    unset($_SESSION['reg_pending'], $_SESSION['reg_email_ok'], $_SESSION['reg_idv_ok'], $_SESSION['idv'], $_SESSION['idv_fail']);
    $_SESSION['reg_match'] = [
        'appointed_id'   => $match['id'],
        'full_name'      => $match['full_name'],
        'national_id'    => $match['national_id'],
        'role_id'        => (int)$match['expected_role_id'],
        'branch_id'      => (int)$match['branch_id'],
        'branch_name'    => $match['branch_name'],
        'branch_address' => $match['branch_address'],
        'business_name'  => $match['business_name'],
        'client_id'      => (int)$match['client_id'],
        'card_no'        => $match['card_no'] ?? null,
        'photo_path'     => $match['photo_path'] ?? null,
        'pay_type'       => $match['pay_type'] ?? 'fixed',
        'hourly_rate'    => $match['hourly_rate'] ?? null,
        'fixed_salary'   => $match['fixed_salary'] ?? null,
        'pay_method'     => $match['pay_method'] ?? 'bank',
    ];
    $_SESSION['reg_card_ok'] = 1;
    $nid = (string)$match['national_id'];
    json_out(['ok' => true, 'name' => $match['full_name'], 'role' => $match['role_name'],
              'business' => $match['business_name'], 'branch' => $match['branch_name'],
              'id_hint' => str_repeat('•', max(0, strlen($nid) - 3)) . substr($nid, -3)]);
}

