// (old name + ID check, disabled. Safe to delete this whole block.)
if ($action === 'staff_register_send_otp' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $match = $_SESSION['reg_match'] ?? null;
    if (!$match || empty($_SESSION['reg_card_ok'])) json_out(['ok' => false, 'msg' => 'Session expired. Start over.']);

    $username = trim($_POST['username'] ?? '');
    $email    = trim($_POST['email'] ?? '');
    $password = $_POST['password'] ?? '';
    $phone    = trim($_POST['phone'] ?? '');
    $age      = (int)($_POST['age'] ?? 0);
    $insurance_provider = trim($_POST['insurance_provider'] ?? '');
    $insurance_number   = trim($_POST['insurance_number'] ?? '');
    $gender   = in_array($_POST['gender'] ?? '', ['Male','Female','Other']) ? $_POST['gender'] : null;
    $date_of_birth = trim($_POST['date_of_birth'] ?? '') ?: null;
    $address  = trim($_POST['address'] ?? '');
    $emergency_contact_name  = trim($_POST['emergency_contact_name'] ?? '');
    $emergency_contact_phone = trim($_POST['emergency_contact_phone'] ?? '');
    $next_of_kin_relationship = trim($_POST['next_of_kin_relationship'] ?? '');

    if (!$username || !$email || !$password || !$phone) json_out(['ok' => false, 'msg' => 'Please complete all required fields.']);
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) json_out(['ok' => false, 'msg' => 'Enter a valid email address.']);
    if (strlen($password) < 8) json_out(['ok' => false, 'msg' => 'Password must be at least 8 characters.']);

    $pdo = db();
    $dupe = $pdo->prepare("SELECT id FROM users WHERE username = ?");
    $dupe->execute([$username]);
    if ($dupe->fetch()) json_out(['ok' => false, 'msg' => 'That username is taken. Choose another.']);

    // The CV is required: PDF / DOC / DOCX / TXT, max 4MB, real file signature
    $cvf = $_FILES['cv'] ?? null;
    if (!$cvf || $cvf['error'] !== UPLOAD_ERR_OK) json_out(['ok' => false, 'msg' => 'Please upload your CV to continue.']);
    if ($cvf['size'] > 4 * 1024 * 1024) json_out(['ok' => false, 'msg' => 'CV too large (max 4MB).']);
    $cvExt  = strtolower(pathinfo($cvf['name'], PATHINFO_EXTENSION));
    if (!in_array($cvExt, ['pdf', 'txt', 'doc', 'docx'], true)) json_out(['ok' => false, 'msg' => 'Use a PDF, DOCX, DOC or TXT file.']);
    $cvHead = (string)file_get_contents($cvf['tmp_name'], false, null, 0, 8);
    if (($cvExt === 'pdf'  && substr($cvHead, 0, 4) !== '%PDF')
     || ($cvExt === 'docx' && substr($cvHead, 0, 2) !== 'PK')
     || ($cvExt === 'doc'  && substr($cvHead, 0, 4) !== "\xD0\xCF\x11\xE0" && substr($cvHead, 0, 5) !== '{\rtf')) {
        json_out(['ok' => false, 'msg' => 'That file does not look like a real ' . strtoupper($cvExt) . '.']);
    }
    require_once __DIR__ . '/includes/nx_malware.php';
    $nxChk = nx_mal_check_upload($cvf['tmp_name'], $cvf['name'], 'sign-up CV');
    if (!$nxChk['ok']) json_out(['ok' => false, 'msg' => $nxChk['msg']]);
    // Save the CV into a temp folder
    $tmpToken = bin2hex(random_bytes(8));
    $tmpDir = __DIR__ . '/uploads/staff_docs/tmp/' . $tmpToken;
    $paths = ['photo' => null, 'cv' => null, 'id_doc' => null];
    foreach (['cv'] as $field) {
        if (!empty($_FILES[$field]) && $_FILES[$field]['error'] === UPLOAD_ERR_OK) {
            if (!is_dir($tmpDir)) mkdir($tmpDir, 0755, true);
            $ext = pathinfo($_FILES[$field]['name'], PATHINFO_EXTENSION);
            $safe = $field . '_' . uniqid() . ($ext ? '.' . preg_replace('/[^a-zA-Z0-9]/','',$ext) : '');
            if (move_uploaded_file($_FILES[$field]['tmp_name'], $tmpDir . '/' . $safe)) $paths[$field] = 'uploads/staff_docs/tmp/' . $tmpToken . '/' . $safe;
        }
    }

    $otp = (string)random_int(100000, 999999);
    $_SESSION['reg_pending'] = [
        'username' => $username, 'email' => $email, 'password' => $password, 'phone' => $phone,
        'age' => $age, 'insurance_provider' => $insurance_provider, 'insurance_number' => $insurance_number,
        'gender' => $gender, 'date_of_birth' => $date_of_birth, 'address' => $address,
        'emergency_contact_name' => $emergency_contact_name, 'emergency_contact_phone' => $emergency_contact_phone,
        'next_of_kin_relationship' => $next_of_kin_relationship,
        'files' => $paths, 'otp' => $otp, 'expires' => time() + 600, 'attempts' => 0,
    ];

    $sent = nx_staff_mail($email, $match['full_name'], 'Your NYMIX Staff Registration Code',
        "Hi " . $match['full_name'] . ",\n\nYour verification code to complete your staff registration is: {$otp}\n\nExpires in 10 minutes.");
    if (!$sent) json_out(['ok' => false, 'msg' => 'Could not send verification email right now.']);

    json_out(['ok' => true, 'msg' => 'Verification code sent to your email.']);
}

// ── STEP 3: confirm OTP, create account, generate letter, notify ─
if ($action === 'staff_register_confirm_otp' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $match   = $_SESSION['reg_match']   ?? null;
    $pending = $_SESSION['reg_pending'] ?? null;
    if (!$match || !$pending || empty($_SESSION['reg_card_ok'])) json_out(['ok' => false, 'msg' => 'Session expired. Start over.']);
    if ((int)$pending['attempts'] >= 5) { json_out(['ok' => false, 'msg' => 'Too many attempts. Start over.']); }
    $code = trim($_POST['otp'] ?? '');
    if ($code === '' || !hash_equals((string)$pending['otp'], $code) || time() > $pending['expires']) {
        $_SESSION['reg_pending']['attempts']++;
        json_out(['ok' => false, 'msg' => 'Invalid or expired code.']);
    }
    $_SESSION['reg_email_ok'] = 1;
    json_out(['ok' => true, 'msg' => 'Email verified.']);
}

// ── STEP 3b: identity check failed 3 times → send ID photo + selfie to the manager for manual review ──
if ($action === 'staff_register_review_submit' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $match   = $_SESSION['reg_match']   ?? null;
    $pending = $_SESSION['reg_pending'] ?? null;
    if (!$match || !$pending || empty($_SESSION['reg_card_ok']) || empty($_SESSION['reg_email_ok'])) {
        json_out(['ok' => false, 'msg' => 'Your session expired. Please start registration again.']);
    }
    if ((int)($_SESSION['idv_fail'] ?? 0) < 1) {
        json_out(['ok' => false, 'msg' => 'Manual review is only available after a failed identity check.']);
    }

    $pdo = db();
    $pdo->exec("CREATE TABLE IF NOT EXISTS registration_reviews (
        id INT AUTO_INCREMENT PRIMARY KEY,
        client_id INT NOT NULL,
        branch_id INT NOT NULL,
        appointed_id INT NOT NULL,
        full_name VARCHAR(160) NOT NULL,
        national_id VARCHAR(40) NULL,
        role_id INT NOT NULL,
        email VARCHAR(160) NULL,
        phone VARCHAR(40) NULL,
        password_hash VARCHAR(255) NOT NULL,
        pending_json MEDIUMTEXT NULL,
        cv_path VARCHAR(255) NULL,
        id_photo_path VARCHAR(255) NULL,
        selfie_path VARCHAR(255) NULL,
        ai_result TEXT NULL,
        status VARCHAR(20) NOT NULL DEFAULT 'pending',
        decided_by INT NULL,
        decided_at DATETIME NULL,
        reject_note VARCHAR(500) NULL,
        created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
        KEY idx_client (client_id), KEY idx_branch (branch_id), KEY idx_status (status)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

    // make sure every column we use exists (table may have been created earlier with another layout)
    try {
        $have = array_column($pdo->query("SHOW COLUMNS FROM registration_reviews")->fetchAll(PDO::FETCH_ASSOC), 'Field');
        foreach ([
            'client_id'     => 'INT NOT NULL DEFAULT 0',
            'branch_id'     => 'INT NOT NULL DEFAULT 0',
            'appointed_id'  => 'INT NOT NULL DEFAULT 0',
            'full_name'     => 'VARCHAR(160) NULL',
            'national_id'   => 'VARCHAR(40) NULL',
            'role_id'       => 'INT NOT NULL DEFAULT 0',
            'email'         => 'VARCHAR(160) NULL',
            'phone'         => 'VARCHAR(40) NULL',
            'password_hash' => 'VARCHAR(255) NULL',
            'pending_json'  => 'MEDIUMTEXT NULL',
            'cv_path'       => 'VARCHAR(255) NULL',
            'id_photo_path' => 'VARCHAR(255) NULL',
            'selfie_path'   => 'VARCHAR(255) NULL',
            'ai_result'     => 'TEXT NULL',
            'status'        => "VARCHAR(20) NOT NULL DEFAULT 'pending'",
            'decided_by'    => 'INT NULL',
            'decided_at'    => 'DATETIME NULL',
            'reject_note'   => 'VARCHAR(500) NULL',
            'created_at'    => 'TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP',
        ] as $col => $def) {
            if (!in_array($col, $have, true)) $pdo->exec("ALTER TABLE registration_reviews ADD COLUMN `$col` $def");
        }
    } catch (Throwable $e) { error_log('[NYMIX REG REVIEW SCHEMA] ' . $e->getMessage()); }

    // one open submission per appointment
    $dupe = nx_q($pdo, "SELECT id FROM registration_reviews WHERE appointed_id = ? AND status = 'pending'", [(int)$match['appointed_id']])->fetch();
    if ($dupe) json_out(['ok' => false, 'msg' => 'You already submitted this for review. Please wait for your manager.']);

    $allowed = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'];
    $saved = [];
    $token = bin2hex(random_bytes(8));
    $dir = __DIR__ . '/uploads/staff_docs/review/' . $token;
    foreach (['id_photo', 'selfie'] as $f) {
        $file = $_FILES[$f] ?? null;
        if (!$file || $file['error'] !== UPLOAD_ERR_OK) json_out(['ok' => false, 'msg' => 'Please add both photos.']);
        if ($file['size'] > 6 * 1024 * 1024) json_out(['ok' => false, 'msg' => 'A photo is too large (max 6MB).']);
        $mime = mime_content_type($file['tmp_name']);
        if (!isset($allowed[$mime])) json_out(['ok' => false, 'msg' => 'Photos must be JPG, PNG or WEBP.']);
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $name = $f . '_' . bin2hex(random_bytes(4)) . '.' . $allowed[$mime];
        if (!move_uploaded_file($file['tmp_name'], $dir . '/' . $name)) json_out(['ok' => false, 'msg' => 'Could not save a photo. Try again.']);
        $saved[$f] = 'uploads/staff_docs/review/' . $token . '/' . $name;
    }

    // keep everything needed to create the account later, but never the plain password / OTP
    $keep = $pending;
    unset($keep['password'], $keep['otp'], $keep['files'], $keep['expires'], $keep['attempts']);

    try {
        nx_q($pdo, "INSERT INTO registration_reviews
            (client_id, branch_id, appointed_id, full_name, national_id, role_id, email, phone, password_hash, pending_json, cv_path, id_photo_path, selfie_path)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
            [(int)$match['client_id'], (int)$match['branch_id'], (int)$match['appointed_id'], $match['full_name'], $match['national_id'],
             (int)$match['role_id'], $pending['email'], $pending['phone'], password_hash($pending['password'], PASSWORD_DEFAULT),
             json_encode($keep, JSON_UNESCAPED_UNICODE), $pending['files']['cv'] ?? null, $saved['id_photo'], $saved['selfie']]);
    } catch (Throwable $e) {
        error_log('[NYMIX REG REVIEW] ' . $e->getMessage());
        json_out(['ok' => false, 'msg' => 'Could not submit for review. Please try again. [' . mb_substr($e->getMessage(), 0, 200) . ']']);
    }

    // tell the branch manager + owner
    try {
        foreach (nx_health_recipients($pdo, (int)$match['client_id'], (int)$match['branch_id']) as $m) {
            nx_notify_user($pdo, (int)$m['id'], 'Registration needs approval: ' . $match['full_name'],
                'Identity check failed. Open Accounts Under Review to compare their ID and selfie.');
            if (!empty($m['email'])) {
                nx_staff_mail($m['email'], $m['full_name'], 'Registration needs your approval: ' . $match['full_name'],
                    "Hi {$m['full_name']},\n\n{$match['full_name']} could not pass the automatic identity check during registration and has sent their ID photo and a selfie for your review.\n\nOpen the Staff Portal, then Accounts Under Review, to compare the photos and approve or reject.", 'warning');
            }
        }
    } catch (Throwable $e) { error_log('[NYMIX REG REVIEW NOTIFY] ' . $e->getMessage()); }

    nx_mail_send($pending['email'], $match['full_name'], 'Your registration is under review',
        nx_email_template('Registration under review',
            "Hi {$match['full_name']},\n\nWe could not verify your identity automatically, so your photos were sent to your manager for a quick manual check. You do not need to do anything else. We will email you once it is decided."),
        '');

    unset($_SESSION['reg_pending'], $_SESSION['reg_email_ok'], $_SESSION['reg_card_ok'], $_SESSION['reg_idv_ok'], $_SESSION['idv'], $_SESSION['idv_fail'], $_SESSION['reg_match']);
    json_out(['ok' => true]);
}

// ── STEP 4: card + email + identity all passed → create the account ──
if ($action === 'staff_register_finish' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    $match   = $_SESSION['reg_match']   ?? null;
    $pending = $_SESSION['reg_pending'] ?? null;
    if (!$match || !$pending) json_out(['ok' => false, 'msg' => 'Session expired. Start over.']);

    $otp = trim($_POST['otp'] ?? '');
    if (empty($_SESSION['reg_card_ok']) || empty($_SESSION['reg_email_ok'])) json_out(['ok' => false, 'msg' => 'Please finish the earlier steps first.']);
    $idvAt = (int)($_SESSION['reg_idv_ok'] ?? 0);
    if (!$idvAt || (time() - $idvAt) > 900) json_out(['ok' => false, 'need_idv' => true, 'msg' => 'Identity verification expired. Please verify again.']);
    // AI writes the appointment-letter wording now, BEFORE the database transaction opens
    $letterExtra = nx_letter_extra(db(), $match);
    if (false) { // the email code is now checked in staff_register_confirm_otp
        $_SESSION['reg_pending']['attempts']++;
        json_out(['ok' => false, 'msg' => 'Invalid or expired code.']);
    }

    $pdo = db();
    $pdo->beginTransaction();
    try {
        $pdo->prepare("
            INSERT INTO users (full_name, username, phone, email, role_id, branch_id, password_hash, is_active,
                age, national_id, insurance_provider, insurance_number, registration_status,
                gender, date_of_birth, address, emergency_contact_name, emergency_contact_phone, next_of_kin_relationship)
            VALUES (?,?,?,?,?,?,?,1,?,?,?,?, 'verified', ?,?,?,?,?,?)
        ")->execute([
            $match['full_name'], $pending['username'], $pending['phone'], $pending['email'],
            $match['role_id'], $match['branch_id'], password_hash($pending['password'], PASSWORD_DEFAULT),
            $pending['age'], $match['national_id'], $pending['insurance_provider'], $pending['insurance_number'],
            $pending['gender'], $pending['date_of_birth'], $pending['address'],
            $pending['emergency_contact_name'], $pending['emergency_contact_phone'], $pending['next_of_kin_relationship'],
        ]);
        $user_id = (int)$pdo->lastInsertId();

        // Card: new staff must verify with their physical NYMIX card
        $pdo->prepare("UPDATE users SET card_required = 1, id_verified = 1, id_verified_at = NOW(), id_verify_country = 'KE' WHERE id = ?")->execute([$user_id]);
        if (!empty($match['card_no'])) {
            $pdo->prepare("UPDATE users SET card_no = ? WHERE id = ?")->execute([$match['card_no'], $user_id]);
        }
        card_payload($pdo, $user_id); // only generates a number if none was pre-assigned

        // ── NEW: register in staff_payroll so this staff member appears in the Salary section ──
        $pdo->prepare("
            INSERT INTO staff_payroll (user_id, branch_id, id_number, phone, bank_name, bank_account)
            VALUES (?,?,?,?,NULL,NULL)
            ON DUPLICATE KEY UPDATE branch_id = VALUES(branch_id), id_number = VALUES(id_number), phone = VALUES(phone)
        ")->execute([$user_id, $match['branch_id'], $match['national_id'], $pending['phone']]);
        $pdo->prepare("UPDATE staff_payroll SET pay_type=?, hourly_rate=?, pay_method=?, fixed_salary=COALESCE(?, fixed_salary) WHERE user_id=?")
            ->execute([$match['pay_type'] ?? 'fixed', $match['hourly_rate'] ?? null, $match['pay_method'] ?? 'bank', $match['fixed_salary'] ?? null, $user_id]);

        // Move any uploaded docs from tmp to a permanent per-user folder
        $finalDir = __DIR__ . '/uploads/staff_docs/' . $user_id;
        $finalRel = [];
        foreach ($pending['files'] as $field => $rel) {
            if (!$rel) continue;
            $src = __DIR__ . '/' . $rel;
            if (file_exists($src)) {
                if (!is_dir($finalDir)) mkdir($finalDir, 0755, true);
                $dest = $finalDir . '/' . basename($rel);
                if (rename($src, $dest)) $finalRel[$field] = 'uploads/staff_docs/' . $user_id . '/' . basename($rel);
            }
        }
        $pdo->prepare("UPDATE users SET photo_path=?, cv_path=?, id_doc_path=? WHERE id=?")
            ->execute([$match['photo_path'] ?? ($finalRel['photo'] ?? null), $finalRel['cv'] ?? null, $finalRel['id_doc'] ?? null, $user_id]);

        $pdo->prepare("UPDATE appointed_staff SET status='registered', registered_user_id=? WHERE id=?")
            ->execute([$user_id, $match['appointed_id']]);

        // Generate branded appointment letter
        $roleRow = $pdo->prepare("SELECT name FROM roles WHERE id = ?");
        $roleRow->execute([$match['role_id']]);
        $role_name = $roleRow->fetchColumn() ?: 'Staff';
        $letterName = 'appointment_' . $user_id . '_' . time() . '.pdf';
        $letterPath = __DIR__ . '/uploads/staff_docs/' . $user_id . '/' . $letterName;
        nx_generate_appointment_letter_pdf($match['business_name'], $match['branch_name'], $match['branch_address'] ?? '',
            $match['full_name'], $role_name, date('jS F Y'), $letterPath,
            $match['pay_type'] ?? 'fixed', isset($match['hourly_rate']) ? (float)$match['hourly_rate'] : null, $match['pay_method'] ?? 'bank', $letterExtra);
        $letterRel = 'uploads/staff_docs/' . $user_id . '/' . $letterName;
        $pdo->prepare("UPDATE users SET appointment_letter_path = ? WHERE id = ?")->execute([$letterRel, $user_id]);

        $pdo->commit();

        // Notify manager/owner
        nx_notify_manager_new_registration($pdo, $match['branch_id'], $match['client_id'], $match['full_name'], $role_name);

        // Send welcome email with appointment letter attached
        $portals = ['Dashboard'];
        if (in_array($match['role_id'], [ROLE_OWNER, ROLE_BRANCH_MANAGER, ROLE_CASHIER])) $portals[] = 'Point of Sale';
        $portals[] = 'Stock Levels';
        if (in_array($match['role_id'], [ROLE_OWNER, ROLE_BRANCH_MANAGER, ROLE_CASHIER])) $portals[] = 'Customers';
        $portalList = implode(', ', $portals);
        nx_staff_mail_attachment($pending['email'], $match['full_name'], 'Welcome to ' . $match['business_name'],
            "Hi " . $match['full_name'] . ",\n\nWe are happy to inform you that your registration is confirmed and you now have access to the following portals: {$portalList}.\n\nYour appointment letter is attached. Welcome aboard!",
            $letterPath);

        unset($_SESSION['reg_match'], $_SESSION['reg_pending'], $_SESSION['reg_card_ok'], $_SESSION['reg_email_ok'], $_SESSION['reg_idv_ok'], $_SESSION['idv'], $_SESSION['idv_fail']);
        json_out(['ok' => true, 'msg' => 'Confirmed! We are happy to inform you that you now have access to the following portals: ' . $portalList . '.']);
    } catch (Exception $e) {
        $pdo->rollBack();
        json_out(['ok' => false, 'msg' => APP_ENV === 'development' ? $e->getMessage() : 'Registration failed. Please try again.']);
    }
}

// ── APPOINTED STAFF LIST (manager/owner add names before they self-register) ─
if ($action === 'appointed_staff_list') {
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER])) json_out(['ok' => false, 'msg' => 'No permission.']);
    $pdo = db();
    $client_id = (int)(me()['client_id'] ?? 0);
    if (role() === ROLE_OWNER) {
        $st = $pdo->prepare("SELECT a.*, b.branch_name, r.name AS role_name FROM appointed_staff a
            JOIN branches b ON b.id=a.branch_id JOIN roles r ON r.id=a.expected_role_id
            WHERE a.client_id = ? ORDER BY a.created_at DESC");
