if ($action === 'appointed_staff_add' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    if (!can([ROLE_OWNER, ROLE_BRANCH_MANAGER])) json_out(['ok' => false, 'msg' => 'No permission.']);
    $pdo = db();
    $bid = branch() ?: (int)($_POST['branch_id'] ?? 0);
    $client_id = (int)(me()['client_id'] ?? 0);
    $full_name = trim($_POST['full_name'] ?? '');
    $national_id = trim($_POST['national_id'] ?? '');
    $role_id = (int)($_POST['role_id'] ?? ROLE_CASHIER);
    if (!$full_name || !$national_id) json_out(['ok' => false, 'msg' => 'Full name and ID number are required.']);
    $pay_type    = ($_POST['pay_type'] ?? '') === 'hourly' ? 'hourly' : 'fixed';
    $hourly_rate = ($_POST['hourly_rate'] ?? '') !== '' ? (float)$_POST['hourly_rate'] : null;
    $fixed_apt   = ($_POST['fixed_salary'] ?? '') !== '' ? (float)$_POST['fixed_salary'] : null;
    $pay_method  = in_array($_POST['pay_method'] ?? '', ['mpesa','bank','paypal','cash'], true) ? $_POST['pay_method'] : 'bank';
    if ($pay_type === 'hourly' && (!$hourly_rate || $hourly_rate <= 0)) json_out(['ok' => false, 'msg' => 'Enter the hourly rate.']);
    $allowedRoles = [ROLE_CASHIER, ROLE_STOREKEEPER, ROLE_SUPPLIER_CLERK, ROLE_SUPPORT];
if (role() === ROLE_OWNER) { $allowedRoles[] = ROLE_BRANCH_MANAGER; $allowedRoles[] = ROLE_HR; }
if (!in_array($role_id, $allowedRoles, true)) $role_id = ROLE_CASHIER;
    // Photo (required for the ID card)
    $photo_rel = null;
    if (!empty($_FILES['photo']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK) {
        $f = $_FILES['photo'];
        if ($f['size'] > 3 * 1024 * 1024) json_out(['ok' => false, 'msg' => 'Photo too large (max 3MB).']);
        $allowed = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'];
        $mime = mime_content_type($f['tmp_name']);
        if (!isset($allowed[$mime])) json_out(['ok' => false, 'msg' => 'Use a JPG, PNG or WEBP photo.']);
        $dir = __DIR__ . '/uploads/staff_docs/appointed';
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $pname = 'appt_' . bin2hex(random_bytes(6)) . '.' . $allowed[$mime];
        if (!move_uploaded_file($f['tmp_name'], $dir . '/' . $pname)) json_out(['ok' => false, 'msg' => 'Could not save the photo.']);
        $photo_rel = 'uploads/staff_docs/appointed/' . $pname;
    }
    if (!$photo_rel) json_out(['ok' => false, 'msg' => 'A staff photo is required for the ID card.']);

    $card_no = gen_unique_card_no($pdo);
    try {
        $pdo->prepare("INSERT INTO appointed_staff (client_id, branch_id, full_name, national_id, expected_role_id, added_by, card_no, photo_path, pay_type, hourly_rate, fixed_salary, pay_method) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)")
            ->execute([$client_id, $bid, $full_name, $national_id, $role_id, me()['id'], $card_no, $photo_rel, $pay_type, $hourly_rate, $fixed_apt, $pay_method]);
        $newId = (int)$pdo->lastInsertId();
    } catch (Exception $e) {
        @unlink(__DIR__ . '/' . $photo_rel);
        json_out(['ok' => false, 'msg' => 'That ID number is already on the appointed list.']);
    }
    json_out(['ok' => true, 'id' => $newId, 'card_no' => $card_no]);
}

if ($action === 'appointed_staff_remove' && $_SERVER['REQUEST_METHOD'] === 'POST') {
