// ── PROFILE: UPDATE PHOTO / PHONE ─────────────────────────────
if ($action === 'profile_save' && $_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_check();
    $pdo   = db();
    $uid   = (int)(me()['id'] ?? 0);
    $phone = trim($_POST['phone'] ?? '');
    if ($phone !== '' && !preg_match('/^[0-9+\s\-]{7,20}$/', $phone)) {
        json_out(['ok' => false, 'msg' => 'Enter a valid phone number.']);
    }
    $photoRel = null;
    if (!empty($_FILES['photo']) && $_FILES['photo']['error'] === UPLOAD_ERR_OK) {
        $f = $_FILES['photo'];
        if ($f['size'] > 3 * 1024 * 1024) json_out(['ok' => false, 'msg' => 'Photo too large (max 3MB).']);
        $allowed = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'];
        $mime = mime_content_type($f['tmp_name']);
        if (!isset($allowed[$mime])) json_out(['ok' => false, 'msg' => 'Use a JPG, PNG or WEBP photo.']);
        $dir = __DIR__ . '/uploads/staff_docs/' . $uid;
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        $name = 'photo_' . uniqid() . '.' . $allowed[$mime];
        if (!move_uploaded_file($f['tmp_name'], $dir . '/' . $name)) {
            json_out(['ok' => false, 'msg' => 'Could not save the photo.']);
        }
        $photoRel = 'uploads/staff_docs/' . $uid . '/' . $name;
    }
    $sql = 'UPDATE users SET phone = ?' . ($photoRel ? ', photo_path = ?' : '') . ' WHERE id = ?';
    $params = $photoRel ? [$phone, $photoRel, $uid] : [$phone, $uid];
    $pdo->prepare($sql)->execute($params);
    $_SESSION['staff']['phone'] = $phone;
    if ($photoRel) $_SESSION['staff']['photo_path'] = $photoRel;
    json_out(['ok' => true, 'phone' => $phone, 'photo' => $_SESSION['staff']['photo_path'] ?? '']);
}

// ── TEMP DEBUG: list Groq models (owner only) — DELETE WHEN DONE ──
if ($action === 'groq_models') {
    if (!can([ROLE_OWNER])) { http_response_code(403); exit('No permission.'); }
    $ch = curl_init('https://api.groq.com/openai/v1/models');
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER     => ['Authorization: Bearer ' . GROQ_API_KEY],
        CURLOPT_TIMEOUT        => 15,
    ]);
    $r = curl_exec($ch);
