  color: #0f172a;
}
[data-theme="light"] .table { color: #0f172a; }
[data-theme="light"] .table > :not(caption) > * > * { border-bottom-color: #e2e8f0; }
[data-theme="light"] .table thead th { background: #f1f5f9; color: #64748b; border-bottom-color: #e2e8f0; }
[data-theme="light"] .table tbody tr:hover > td { background: rgba(0,0,0,.02); }
[data-theme="light"] .dropdown-menu { background: #ffffff; border-color: #e2e8f0; }
[data-theme="light"] .dropdown-item { color: #0f172a; }
[data-theme="light"] .dropdown-item:hover { background: #f1f5f9; }
[data-theme="light"] .modal-content { background: #ffffff; border-color: #e2e8f0; color: #0f172a; }
[data-theme="light"] .modal-header { background: #f8fafc; border-bottom-color: #e2e8f0; }
[data-theme="light"] .modal-footer { background: #f8fafc; border-top-color: #e2e8f0; }
[data-theme="light"] .btn-close { filter: none; }
[data-theme="light"] .receipt { background: #fff; color: #111; }
[data-theme="light"] #login-screen { background: radial-gradient(ellipse at 20% 50%, #dbeafe, #f0f2f5 60%); }
[data-theme="light"] .nx-toast { background: #ffffff; border-color: #e2e8f0; color: #0f172a; }

/* ── BOOTSTRAP OVERRIDES ───────────────────────────────────── */
body {
  font-family: var(--font-body);
  background: var(--nx-bg);
  color: var(--nx-text);
  min-height: 100vh;
}
.card {
  background: var(--nx-card);
  border: 1px solid var(--nx-border);
  border-radius: 12px;
}
.card-header {
  background: var(--nx-surface);
  border-bottom: 1px solid var(--nx-border);
  font-family: var(--font-head);
  font-weight: 600;
}
.modal-content {
  background: var(--nx-card);
  border: 1px solid var(--nx-border);
  border-radius: 14px;
  color: var(--nx-text);
}
.modal-header {
  background: var(--nx-surface);
  border-bottom: 1px solid var(--nx-border);
}
.modal-footer {
  background: var(--nx-surface);
  border-top: 1px solid var(--nx-border);
}
.btn-close { filter: invert(1); }
.form-control, .form-select {
  background: var(--nx-surface);
  border: 1px solid var(--nx-border);
  color: var(--nx-text);
  font-family: var(--font-body);
}
.form-control:focus, .form-select:focus {
  background: var(--nx-surface);
  border-color: var(--nx-accent);
  color: var(--nx-text);
  box-shadow: 0 0 0 3px rgba(30,158,82,.15);
}
.form-control::placeholder { color: var(--nx-muted); }
.form-select option { background: var(--nx-surface); }
.form-label { color: var(--nx-muted); font-size: .78rem; font-weight: 600; text-transform: uppercase; letter-spacing: .6px; }
.table { color: var(--nx-text); }
.table > :not(caption) > * > * { background: transparent; border-bottom-color: var(--nx-border); padding: 10px 14px; }
.table thead th { background: var(--nx-surface); color: var(--nx-muted); font-size: .72rem; text-transform: uppercase; letter-spacing: .7px; font-weight: 600; border-bottom: 1px solid var(--nx-border); }
.table tbody tr:hover > td { background: rgba(255,255,255,.02); }
.dropdown-menu { background: var(--nx-card); border: 1px solid var(--nx-border); }
.dropdown-item { color: var(--nx-text); }
.dropdown-item:hover { background: var(--nx-surface); color: var(--nx-accent); }
.nav-tabs { border-bottom: 1px solid var(--nx-border); }
.nav-tabs .nav-link { color: var(--nx-muted); border: none; padding: 10px 18px; font-weight: 500; }
.nav-tabs .nav-link:hover { color: var(--nx-text); }
.nav-tabs .nav-link.active { color: var(--nx-accent); border-bottom: 2px solid var(--nx-accent); background: transparent; }
.tab-content { padding-top: 20px; }
.badge { font-weight: 600; }
.alert { border: none; border-radius: 10px; }
::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: var(--nx-bg); }
::-webkit-scrollbar-thumb { background: var(--nx-border); border-radius: 4px; }

/* ── SIDEBAR ────────────────────────────────────────────────── */
.nx-sidebar {
  position: fixed; top: 0; left: 0; bottom: 0;
  width: var(--nx-sidebar);
  background: var(--nx-surface);
  border-right: 1px solid var(--nx-border);
  display: flex; flex-direction: column;
  z-index: 1040;
  overflow-y: auto;
  transition: transform .25s cubic-bezier(.4,0,.2,1);
}
.nx-sidebar .brand {
  font-family: var(--font-head);
  font-size: 1.15rem; font-weight: 700;
  background: linear-gradient(135deg, var(--nx-accent), #17C548);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.nx-sidebar .branch-badge {
  font-size: .7rem; color: var(--nx-muted);
  display: flex; align-items: center; gap: 4px;
}
.nx-nav-link {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 14px; border-radius: 8px;
  color: var(--nx-muted); font-size: .875rem; font-weight: 500;
  cursor: pointer; border: none; background: none;
  width: 100%; text-align: left;
  transition: all .15s ease;
  text-decoration: none;
}
.nx-nav-link:hover { background: var(--nx-card); color: var(--nx-text); }
.nx-nav-link.active { background: rgba(30,158,82,.12); color: var(--nx-accent); }
.nx-nav-link i { width: 16px; text-align: center; font-size: .9rem; }
.nav-section-label {
  font-size: .65rem; font-weight: 700; letter-spacing: 1.2px;
  text-transform: uppercase; color: var(--nx-muted);
  padding: 6px 14px 4px; margin-top: 8px;
}
.user-chip {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; background: var(--nx-card);
  border-radius: 10px; border: 1px solid var(--nx-border);
}
.user-avatar {
  width: 34px; height: 34px; border-radius: 50%;
  background: linear-gradient(135deg, var(--nx-accent), #17C548);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; color: #000; font-size: .85rem; flex-shrink: 0;
}

/* ── TOPBAR ─────────────────────────────────────────────────── */
.nx-topbar {
  position: fixed; top: 0; right: 0; left: var(--nx-sidebar);
  height: var(--nx-topbar);
  background: var(--nx-surface);
  border-bottom: 1px solid var(--nx-border);
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 20px; z-index: 1030;
  transition: left .25s cubic-bezier(.4,0,.2,1);
}
.nx-page-title { font-family: var(--font-head); font-size: 1.05rem; font-weight: 700; }

/* ── MAIN CONTENT ───────────────────────────────────────────── */
#nx-main {
  margin-left: var(--nx-sidebar);
  padding-top: var(--nx-topbar);
  min-height: 100vh;
  transition: margin-left .25s cubic-bezier(.4,0,.2,1);
}
#nx-content { padding: 24px; }
.cashier-mode #nx-content { padding: 0; }

/* ── STAT CARDS ─────────────────────────────────────────────── */
.stat-card {
  background: var(--nx-card);
  border: 1px solid var(--nx-border);
  border-radius: 12px; padding: 20px;
  position: relative; overflow: hidden;
  transition: transform .2s, border-color .2s;
}
.stat-card:hover { transform: translateY(-2px); border-color: rgba(30,158,82,.3); }
.stat-card::before {
  content: ''; position: absolute; top: 0; right: 0;
  width: 3px; height: 100%;
  background: var(--card-accent, var(--nx-accent));
}
.stat-label { font-size: .7rem; color: var(--nx-muted); text-transform: uppercase; letter-spacing: .8px; font-weight: 600; }
.stat-value { font-family: var(--font-head); font-size: 1.8rem; font-weight: 700; line-height: 1.1; margin: 6px 0 2px; }
.stat-sub   { font-size: .72rem; color: var(--nx-muted); }
.stat-icon  { position: absolute; top: 16px; right: 14px; font-size: 1.4rem; opacity: .12; }

/* ── POS LAYOUT ─────────────────────────────────────────────── */
.pos-wrap { display: grid; grid-template-columns: 1fr 320px; gap: 16px; height: calc(100vh - var(--nx-topbar) - 48px); }
.pos-wrap.fullscreen { height: calc(100vh - 16px); }
.pos-products { overflow-y: auto; }
.pos-cart { display: flex; flex-direction: column; background: var(--nx-card); border: 1px solid var(--nx-border); border-radius: 12px; overflow: hidden; }
.cart-items { flex: 1; overflow-y: auto; padding: 10px; }
.cart-item { background: var(--nx-surface); border: 1px solid var(--nx-border); border-radius: 8px; padding: 9px 11px; margin-bottom: 7px; }
.cart-qty-btn { width: 26px; height: 26px; border-radius: 6px; border: none; background: var(--nx-border); color: var(--nx-text); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: background .15s; }
.cart-qty-btn:hover { background: var(--nx-accent); color: #000; }
.cart-qty-input { width: 46px; text-align: center; background: var(--nx-bg); border: 1px solid var(--nx-border); border-radius: 6px; color: var(--nx-text); font-size: .85rem; padding: 2px 4px; }
.cart-summary { padding: 12px 14px; border-top: 1px solid var(--nx-border); background: var(--nx-surface); }
.cart-row { display: flex; justify-content: space-between; font-size: .83rem; margin-bottom: 5px; color: var(--nx-muted); }
.cart-row.total { font-size: 1.05rem; font-weight: 700; color: var(--nx-text); border-top: 1px solid var(--nx-border); padding-top: 7px; margin-top: 3px; }
.product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 16px; }
.prod-card { background: var(--nx-card); border: 1px solid var(--nx-border); border-radius: 10px; padding: 10px; cursor: pointer; transition: border-color .15s, transform .15s; display: flex; flex-direction: column; align-items: center; text-align: center; }
.prod-card:hover { border-color: var(--nx-accent); transform: translateY(-1px); }
.prod-card.out-of-stock { opacity: .45; pointer-events: none; }
.prod-img-wrap { width: 100%; aspect-ratio: 1/1; border-radius: 8px; overflow: hidden; background: var(--nx-surface); margin-bottom: 8px; display: flex; align-items: center; justify-content: center; }
.prod-img-wrap img { width: 100%; height: 100%; object-fit: cover; }
.prod-img-fallback { font-size: 1.6rem; font-weight: 700; color: var(--nx-muted); }
.prod-name { font-size: .83rem; font-weight: 600; margin-bottom: 3px; line-height: 1.3; }
.prod-sku  { font-size: .7rem; color: var(--nx-muted); margin-bottom: 6px; }
.prod-price { font-size: 1rem; font-weight: 700; color: var(--nx-accent); }
.prod-stock { font-size: .7rem; margin-top: 3px; }
.change-box { background: rgba(34,197,94,.1); border: 1px solid rgba(34,197,94,.25); border-radius: 8px; padding: 8px 12px; text-align: center; }

/* ── BAR CHART ──────────────────────────────────────────────── */
.bar-chart { display: flex; align-items: flex-end; gap: 8px; height: 110px; padding: 4px 0; }
.bar-wrap { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 3px; }
.bar { width: 100%; background: var(--nx-accent); border-radius: 4px 4px 0 0; min-height: 4px; opacity: .85; transition: opacity .2s; }
.bar:hover { opacity: 1; }
.bar-label { font-size: .65rem; color: var(--nx-muted); white-space: nowrap; }
.bar-val   { font-size: .65rem; color: var(--nx-accent); font-weight: 600; }

/* ── NEW POS LAYOUT ─────────────────────────────────────────── */
.pos-topbar { display:flex;align-items:center;justify-content:space-between;padding:0 16px;height:52px;background:var(--nx-surface);border-bottom:1px solid var(--nx-border);gap:12px }
.pos-topbar-brand { display:flex;align-items:center;gap:10px }
.pos-topbar-logo { width:32px;height:32px;border-radius:8px;background:linear-gradient(135deg,var(--nx-accent),#17C548);display:flex;align-items:center;justify-content:center;font-weight:700;color:#000;font-size:.85rem;flex-shrink:0 }
.pos-search-wrap { flex:1;max-width:440px;position:relative }
.pos-search-wrap input { width:100%;padding:8px 36px 8px 36px;border-radius:8px;border:1px solid var(--nx-border);background:var(--nx-bg);color:var(--nx-text);font-size:.85rem }
.pos-search-wrap .si { position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--nx-muted);font-size:.85rem }
.pos-search-wrap .sk { position:absolute;right:10px;top:50%;transform:translateY(-50%);font-size:.65rem;color:var(--nx-muted);background:var(--nx-border);border-radius:4px;padding:1px 5px }
.pos-layout { display:grid;grid-template-columns:1fr 340px;height:calc(100vh - 52px);overflow:hidden }
.pos-left { display:flex;flex-direction:column;overflow:hidden }
.pos-cats { display:flex;gap:8px;padding:12px 16px;border-bottom:1px solid var(--nx-border);overflow-x:auto;flex-shrink:0;scrollbar-width:none }
.pos-cats::-webkit-scrollbar { display:none }
.pos-cat-btn { display:flex;flex-direction:column;align-items:center;gap:6px;padding:10px 14px;border-radius:10px;border:1px solid var(--nx-border);background:var(--nx-surface);cursor:pointer;white-space:nowrap;flex-shrink:0;transition:all .15s;min-width:80px }
.pos-cat-btn.active { background:var(--nx-accent);border-color:var(--nx-accent);color:#000 }
.pos-cat-btn.active .pci { color:#000 }
.pos-cat-btn:hover:not(.active) { border-color:var(--nx-accent) }
.pci { font-size:1.3rem;color:var(--nx-muted) }
.pos-cat-label { font-size:.72rem;font-weight:600 }
.pos-products-wrap { flex:1;overflow-y:auto;padding:16px }
.pos-grid { display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px }
.pos-item { background:var(--nx-card);border:1px solid var(--nx-border);border-radius:10px;overflow:hidden;cursor:pointer;transition:border-color .15s,transform .12s }
.pos-item:hover { border-color:var(--nx-accent);transform:translateY(-1px) }
.pos-item.oos { opacity:.4;pointer-events:none }
.pos-item-img { width:100%;aspect-ratio:4/3;object-fit:cover;background:var(--nx-surface);display:flex;align-items:center;justify-content:center;font-size:2rem;color:var(--nx-muted) }
.pos-item-img img { width:100%;height:100%;object-fit:cover }
.pos-item-body { padding:10px 10px 12px }
.pos-item-name { font-size:.82rem;font-weight:600;margin-bottom:2px;line-height:1.3 }
.pos-item-price { font-size:.9rem;font-weight:700;color:var(--nx-accent) }
.pos-item-stock { font-size:.68rem;color:var(--nx-muted);margin-top:2px }
/* right panel */
.pos-right { display:flex;flex-direction:column;border-left:1px solid var(--nx-border);background:var(--nx-surface);overflow-y:auto;min-height:0 }
.pos-right-head { padding:12px 16px;border-bottom:1px solid var(--nx-border);display:flex;align-items:center;justify-content:space-between;flex-shrink:0 }
.pos-right-title { font-family:var(--font-head);font-weight:700;font-size:.95rem }
.pos-cart-list { flex:1;overflow-y:auto;padding:10px 12px;display:flex;flex-direction:column;gap:8px;min-height:60px }
.pos-cart-item { background:var(--nx-card);border:1px solid var(--nx-border);border-radius:10px;padding:10px 12px }
.pos-cart-name { font-size:.82rem;font-weight:600;margin-bottom:6px }
.pos-cart-row { display:flex;align-items:center;justify-content:space-between }
.pos-qbtn { width:28px;height:28px;border-radius:7px;border:1px solid var(--nx-border);background:var(--nx-surface);color:var(--nx-text);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:.9rem;transition:background .12s }
.pos-qbtn:hover { background:var(--nx-accent);border-color:var(--nx-accent);color:#000 }
.pos-qty-inp { width:40px;text-align:center;background:transparent;border:none;color:var(--nx-text);font-size:.88rem;font-weight:600 }
.pos-cart-price { font-size:.88rem;font-weight:700;color:var(--nx-accent) }
.pos-remove { background:none;border:none;color:var(--nx-muted);cursor:pointer;font-size:.9rem;padding:0 2px;line-height:1 }
.pos-remove:hover { color:var(--nx-red) }
.pos-divider { height:1px;background:var(--nx-border);margin:0 }
.pos-totals { padding:12px 16px;flex-shrink:0 }
.pos-total-row { display:flex;justify-content:space-between;font-size:.82rem;margin-bottom:6px;color:var(--nx-muted) }
.pos-total-row.big { font-size:1.1rem;font-weight:700;color:var(--nx-text);border-top:1px solid var(--nx-border);padding-top:8px;margin-top:4px }
.pos-pay-methods { display:flex;gap:8px;margin-bottom:12px }
.pos-pay-btn { flex:1;padding:9px 6px;border-radius:8px;border:1px solid var(--nx-border);background:var(--nx-card);color:var(--nx-text);font-size:.72rem;font-weight:600;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:3px;transition:all .15s }
.pos-pay-btn i { font-size:1.1rem }
.pos-pay-btn.active { border-color:var(--nx-accent);background:rgba(30,158,82,.12);color:var(--nx-accent) }
.pos-charge-btn { width:100%;padding:14px;border-radius:10px;border:none;background:var(--nx-accent);color:#fff;font-size:1rem;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:opacity .15s;margin-bottom:8px }
.pos-charge-btn:hover { opacity:.9 }
.pos-charge-btn:disabled { opacity:.5;cursor:not-allowed }
.pos-secondary-btns { display:flex;gap:8px }
.pos-secondary-btns button { flex:1;padding:9px;border-radius:8px;border:1px solid var(--nx-border);background:transparent;color:var(--nx-muted);font-size:.75rem;cursor:pointer;transition:background .12s }
.pos-secondary-btns button:hover { background:var(--nx-card);color:var(--nx-text) }
.pos-field-row { display:flex;align-items:center;justify-content:space-between;margin-bottom:8px }
.pos-field-row label { font-size:.75rem;color:var(--nx-muted) }
.pos-field-row input,.pos-field-row select { background:var(--nx-card);border:1px solid var(--nx-border);border-radius:7px;color:var(--nx-text);font-size:.8rem;padding:5px 8px;max-width:150px }
.pos-empty-cart { flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--nx-muted);gap:8px;padding:24px }
.pos-empty-cart i { font-size:2.5rem;opacity:.3 }
.pos-empty-cart span { font-size:.82rem }
.pos-cashier-bar { background:var(--nx-surface);border-bottom:1px solid var(--nx-border) }
@media (max-width:991.98px) { .pos-layout { grid-template-columns:1fr } .pos-right { max-height:420px;overflow-y:auto } }

/* ── RECEIPT ────────────────────────────────────────────────── */
.receipt { background: #fff; color: #111; padding: 20px; border-radius: 8px; font-family: 'Courier New', monospace; font-size: .75rem; max-width: 300px; margin: 0 auto; }
.receipt h5 { text-align: center; font-size: .9rem; }
.receipt hr { border-top: 1px dashed #aaa; }
.receipt-row { display: flex; justify-content: space-between; margin-bottom: 2px; }
.receipt-total { font-weight: 700; border-top: 2px solid #111; padding-top: 5px; margin-top: 5px; }

/* ── MOVEMENT TYPES ─────────────────────────────────────────── */
.mov-type { display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: .7rem; font-weight: 600; }
.mov-sale         { background: rgba(59,130,246,.15); color: var(--nx-blue); }
.mov-purchase     { background: rgba(34,197,94,.15);  color: var(--nx-green); }
.mov-adjustment   { background: rgba(30,158,82,.15); color: var(--nx-accent); }
.mov-transfer_in  { background: rgba(34,197,94,.12);  color: var(--nx-green); }
.mov-transfer_out { background: rgba(239,68,68,.12);  color: var(--nx-red); }
.mov-void_return  { background: rgba(107,114,128,.15);color: var(--nx-muted); }

/* ── TOAST ──────────────────────────────────────────────────── */
#toast-wrap { position: fixed; bottom: 20px; right: 20px; z-index: 9999; display: flex; flex-direction: column; gap: 8px; pointer-events: none; }
.nx-toast { background: var(--nx-card); border: 1px solid var(--nx-border); border-radius: 10px; padding: 11px 16px; font-size: .85rem; box-shadow: 0 4px 20px rgba(0,0,0,.4); display: flex; align-items: center; gap: 10px; min-width: 220px; animation: toastIn .25s ease; pointer-events: all; }
.nx-toast.success { border-left: 3px solid var(--nx-green); }
.nx-toast.error   { border-left: 3px solid var(--nx-red); }
.nx-toast.info    { border-left: 3px solid var(--nx-blue); }
@keyframes toastIn { from { transform: translateX(100%); opacity: 0; } to { transform: none; opacity: 1; } }

/* ── LOGIN ──────────────────────────────────────────────────── */
#login-screen { min-height: 100vh; position: relative; overflow: hidden; background: #0f1117; }
.login-split { display: flex; min-height: 100vh; width: 100%; }
.login-visual {
  flex: 1.1; position: relative; display: flex; align-items: center; justify-content: center;
  background: url('https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1600&q=80') center/cover no-repeat;
  padding: 60px;
}
.login-visual-overlay { position: absolute; inset: 0; background: linear-gradient(160deg, rgba(15,17,23,.92), rgba(15,17,23,.8) 55%, rgba(15,17,23,.95)); }
.login-visual-content { position: relative; z-index: 2; max-width: 440px; }
.login-tagline { font-size: .92rem; color: var(--nx-muted); line-height: 1.6; margin-top: 14px; margin-bottom: 0; }
.login-feature-list { margin-top: 32px; display: flex; flex-direction: column; gap: 18px; }
.login-feature-item { display: flex; align-items: flex-start; gap: 14px; }
.login-feature-item i { width: 38px; height: 38px; flex-shrink: 0; border-radius: 10px; background: rgba(30,158,82,.12); color: var(--nx-accent); display: flex; align-items: center; justify-content: center; font-size: 1rem; }
.login-feature-item strong { display: block; font-size: .88rem; color: var(--nx-text); }
.login-feature-item span { display: block; font-size: .75rem; color: var(--nx-muted); margin-top: 1px; }
.login-trust { margin-top: 36px; font-size: .72rem; color: var(--nx-muted); padding-top: 18px; border-top: 1px solid rgba(255,255,255,.08); }
.login-trust i { color: var(--nx-accent); margin-right: 6px; }
.login-form-panel { flex: 0.9; min-width: 420px; display: flex; align-items: center; justify-content: center; background: var(--nx-bg); padding: 40px; position: relative; z-index: 2; }
.login-box { background: transparent; border: none; border-radius: 0; padding: 0; width: 100%; max-width: 360px; box-shadow: none; }
.login-brand { font-family: var(--font-head); font-size: 1.6rem; font-weight: 700; background: linear-gradient(135deg, var(--nx-accent), #17C548); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }

@keyframes loginShake {
  0%,100% { transform: translateX(0); }
  20%     { transform: translateX(-8px); }
  40%     { transform: translateX(8px); }
  60%     { transform: translateX(-6px); }
  80%     { transform: translateX(6px); }
}
.login-shake { animation: loginShake .4s ease; }

/* ── REGISTRATION WIZARD (full screen) ─────────────────────── */
#reg-wizard-overlay { position:fixed; inset:0; z-index:99998; display:flex; align-items:flex-start; justify-content:center; overflow-y:auto; padding:40px 20px; }
.reg-wizard-bg { position:fixed; inset:0; background:url('https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1600&q=80') center/cover no-repeat; }
.reg-wizard-bg::after { content:''; position:absolute; inset:0; background:linear-gradient(160deg, rgba(15,17,23,.94), rgba(15,17,23,.88) 60%, rgba(15,17,23,.96)); }
.reg-wizard-close { position:fixed; top:20px; right:20px; z-index:100000; width:40px; height:40px; border-radius:50%; border:1px solid var(--nx-border); background:var(--nx-card); color:var(--nx-text); font-size:1.1rem; }
.reg-wizard-inner { position:relative; z-index:1; width:100%; max-width:560px; background:var(--nx-card); border:1px solid var(--nx-border); border-radius:20px; padding:40px 36px; box-shadow:0 20px 60px rgba(0,0,0,.6); }
.reg-wizard-header { text-align:center; margin-bottom:24px; }
.reg-wizard-brand { font-family:var(--font-head); font-weight:700; background:linear-gradient(135deg,var(--nx-accent),#17C548); -webkit-background-clip:text; -webkit-text-fill-color:transparent; font-size:1.1rem; }
.reg-wizard-header h2 { font-family:var(--font-head); font-weight:700; font-size:1.5rem; margin:8px 0 4px; color:var(--nx-text); }
.reg-wizard-progress { display:flex; align-items:flex-start; justify-content:center; margin-bottom:28px; }
.reg-w-step-dot { display:flex; flex-direction:column; align-items:center; gap:4px; }
.reg-w-step-dot span { width:32px; height:32px; border-radius:50%; background:var(--nx-surface); border:2px solid var(--nx-border); display:flex; align-items:center; justify-content:center; font-weight:700; font-size:.85rem; color:var(--nx-muted); transition:all .2s; }
.reg-w-step-dot label { font-size:.65rem; color:var(--nx-muted); }
.reg-w-step-dot.active span { background:var(--nx-accent); border-color:var(--nx-accent); color:#000; }
.reg-w-step-dot.active label { color:var(--nx-accent); font-weight:600; }
.reg-w-step-dot.done span { background:var(--nx-green); border-color:var(--nx-green); color:#fff; }
.reg-w-step-line { flex:1; max-width:50px; height:2px; background:var(--nx-border); margin:16px 6px 0; }
.reg-upload-status { font-size:.72rem; margin-top:4px; min-height:16px; }
.reg-upload-status.ok { color:var(--nx-green); }
.reg-upload-status.err { color:var(--nx-red); }
@media (max-width:575.98px) { .reg-wizard-inner { padding:28px 20px; } }

@media (max-width: 991.98px) {
  .login-visual { display: none; }
  .login-form-panel { min-width: 0; flex: 1; }
  #login-screen { background: radial-gradient(ellipse at 20% 50%, #1a1f35, #0f1117 60%); }
  .login-box { background: var(--nx-card); border: 1px solid var(--nx-border); border-radius: 16px; padding: 36px 28px; box-shadow: 0 8px 40px rgba(0,0,0,.5); }
}

/* ── IDLE OVERLAY ───────────────────────────────────────────── */
#idle-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.75); z-index: 9998; align-items: center; justify-content: center; backdrop-filter: blur(4px); }
#idle-overlay.show { display: flex; }
.idle-card { background: var(--nx-card); border: 1px solid var(--nx-border); border-radius: 16px; padding: 40px 36px; max-width: 360px; width: 90%; text-align: center; box-shadow: 0 8px 40px rgba(0,0,0,.6); }
#idle-seconds { font-family: var(--font-head); font-size: 3.5rem; font-weight: 700; color: var(--nx-accent); }

/* ── UTILITIES ──────────────────────────────────────────────── */
.text-accent { color: var(--nx-accent) !important; }
.text-nx-muted { color: var(--nx-muted) !important; }
.fw-head { font-family: var(--font-head); }
.low-stock-row td:first-child { border-left: 3px solid var(--nx-red); }
.surface { background: var(--nx-surface); }
.hr-pills .nav-link { color: var(--nx-muted); border-radius: 8px; font-weight: 600; font-size: .85rem; }
.hr-pills .nav-link.active { background: rgba(30,158,82,.15); color: var(--nx-accent); }
.bank-tile { cursor: pointer; border: 1px solid var(--nx-border); border-radius: 12px; padding: 14px 10px; text-align: center; background: var(--nx-card); transition: transform .12s, border-color .12s; }
.bank-tile:hover { transform: translateY(-2px); border-color: var(--nx-accent); }
.bank-logo { width: 46px; height: 46px; border-radius: 12px; margin: 0 auto 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 700; font-size: .95rem; overflow: hidden; }
.bank-logo img { width: 100%; height: 100%; object-fit: contain; background: #fff; }

/* ── RESPONSIVE ─────────────────────────────────────────────── */
@media (max-width: 991.98px) {
  .nx-sidebar { transform: translateX(-100%); }
  .nx-sidebar.show { transform: translateX(0); box-shadow: 8px 0 32px rgba(0,0,0,.6); }
  .nx-topbar { left: 0 !important; }
  #nx-main { margin-left: 0 !important; }
  .pos-wrap { grid-template-columns: 1fr; height: auto; }
  .pos-cart { margin-top: 16px; max-height: 500px; }
}
@media (max-width: 575.98px) {
  .login-box { padding: 32px 22px; }
  #nx-content { padding: 14px; }
  .stat-value { font-size: 1.4rem; }
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
}
/* ══ LOADER (bouncing logo) ══ */
#nx-loader{position:fixed;inset:0;z-index:100010;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(circle at 50% 40%,#1a2140,#0a0d16 70%);color:#fff;text-align:center;padding:24px}
.nt-doll{position:relative;width:140px;height:160px;display:flex;align-items:flex-end;justify-content:center}
.nt-doll .nt-body:not(.nt-logo-wrap){display:none}
.nt-logo-wrap{position:absolute;bottom:16px;width:96px;height:96px;border-radius:26px;background:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 14px 40px rgba(30,158,82,.45);animation:ntBounce .9s ease-in-out infinite}
.nt-logo{width:72px;height:72px;object-fit:contain}
.nt-logo-fb{width:72px;height:72px;align-items:center;justify-content:center;font-weight:800;font-size:1.8rem;color:#000}
/* BBG loader */.bbg-wrap{display:flex;flex-direction:column;align-items:center;gap:18px;margin-bottom:6px}.bbg-logo{position:relative;width:150px;height:150px;display:grid;place-items:center}.bbg-ring{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,#17C548,#E87800,#FBFAF4,#1E9E52,#17C548);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 5px),#000 calc(100% - 4px));mask:radial-gradient(farthest-side,transparent calc(100% - 5px),#000 calc(100% - 4px));animation:bbgSpin 1.1s linear infinite;filter:drop-shadow(0 0 12px rgba(23,197,72,.55))}.bbg-ring.r2{inset:12px;animation-duration:1.8s;animation-direction:reverse;opacity:.6}@keyframes bbgSpin{to{transform:rotate(360deg)}}.bbg-core{position:relative;width:96px;height:96px;border-radius:26px;background:linear-gradient(135deg,#1E9E52,#17C548);display:flex;align-items:center;justify-content:center;gap:1px;font-family:var(--font-head);font-weight:700;font-size:44px;color:#fff;box-shadow:0 0 0 6px rgba(255,255,255,.06),0 18px 40px rgba(0,0,0,.35);animation:bbgPulse 1.4s ease-in-out infinite}@keyframes bbgPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}.bbg-n{display:inline-block;animation:bbgN .7s cubic-bezier(.34,1.56,.64,1) both}.bbg-t{display:inline-block;color:#14351F;animation:bbgT .7s cubic-bezier(.34,1.56,.64,1) .15s both}@keyframes bbgN{from{opacity:0;transform:translateX(-30px)}to{opacity:1;transform:none}}@keyframes bbgT{from{opacity:0;transform:translateX(30px)}to{opacity:1;transform:none}}.bbg-word{font-family:var(--font-head);font-weight:600;font-size:22px;letter-spacing:6px;margin-top:6px}.bbg-motto{display:flex;gap:14px;align-items:center}.bbg-motto span{font-family:var(--font-mono),monospace;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:rgba(255,255,255,.75);opacity:0;animation:bbgWord .5s ease forwards}.bbg-motto span+span::before{content:'\00b7';margin-right:14px;color:#17C548}.bbg-motto span:nth-child(1){animation-delay:.3s}.bbg-motto span:nth-child(2){animation-delay:.75s}.bbg-motto span:nth-child(3){animation-delay:1.15s}@keyframes bbgWord{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
/* BBG loader */.bbg-wrap{display:flex;flex-direction:column;align-items:center;gap:18px;margin-bottom:6px}.bbg-logo{position:relative;width:150px;height:150px;display:grid;place-items:center}.bbg-ring{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,#17C548,#E87800,#FBFAF4,#1E9E52,#17C548);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 5px),#000 calc(100% - 4px));mask:radial-gradient(farthest-side,transparent calc(100% - 5px),#000 calc(100% - 4px));animation:bbgSpin 1.1s linear infinite;filter:drop-shadow(0 0 12px rgba(23,197,72,.55))}.bbg-ring.r2{inset:12px;animation-duration:1.8s;animation-direction:reverse;opacity:.6}@keyframes bbgSpin{to{transform:rotate(360deg)}}.bbg-core{position:relative;width:96px;height:96px;border-radius:26px;background:linear-gradient(135deg,#1E9E52,#17C548);display:flex;align-items:center;justify-content:center;gap:1px;font-family:var(--font-head);font-weight:700;font-size:44px;color:#fff;box-shadow:0 0 0 6px rgba(255,255,255,.06),0 18px 40px rgba(0,0,0,.35);animation:bbgPulse 1.4s ease-in-out infinite}@keyframes bbgPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}.bbg-n{display:inline-block;animation:bbgN .7s cubic-bezier(.34,1.56,.64,1) both}.bbg-t{display:inline-block;color:#14351F;animation:bbgT .7s cubic-bezier(.34,1.56,.64,1) .15s both}@keyframes bbgN{from{opacity:0;transform:translateX(-30px)}to{opacity:1;transform:none}}@keyframes bbgT{from{opacity:0;transform:translateX(30px)}to{opacity:1;transform:none}}.bbg-word{font-family:var(--font-head);font-weight:600;font-size:22px;letter-spacing:6px;margin-top:6px}.bbg-motto{display:flex;gap:14px;align-items:center}.bbg-motto span{font-family:var(--font-mono),monospace;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:rgba(255,255,255,.75);opacity:0;animation:bbgWord .5s ease forwards}.bbg-motto span+span::before{content:'\00b7';margin-right:14px;color:#17C548}.bbg-motto span:nth-child(1){animation-delay:.3s}.bbg-motto span:nth-child(2){animation-delay:.75s}.bbg-motto span:nth-child(3){animation-delay:1.15s}@keyframes bbgWord{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}.nt-shadow{position:absolute;bottom:0;width:70px;height:12px;border-radius:50%;background:rgba(0,0,0,.55);filter:blur(4px);animation:ntShadow .9s ease-in-out infinite}
.nt-title{font-family:var(--font-head);font-weight:700;font-size:1.3rem;margin-top:18px}
#nx-loader.d-none{display:none!important}
         .nt-status{font-size:.82rem;color:#94a3b8;margin-top:4px;min-height:20px}
.nt-bar{width:200px;height:5px;border-radius:5px;background:rgba(255,255,255,.12);margin-top:22px;overflow:hidden}
.nt-bar span{display:block;height:100%;width:40%;border-radius:5px;background:linear-gradient(90deg,#1E9E52,#17C548);animation:ntBar 1.2s ease-in-out infinite}
@keyframes ntBounce{0%,100%{transform:translateY(0) scale(1.06,.9)}50%{transform:translateY(-52px) scale(1,1)}}
@keyframes ntShadow{0%,100%{transform:scale(1);opacity:.6}50%{transform:scale(.55);opacity:.25}}
@keyframes ntBar{0%{transform:translateX(-100%)}100%{transform:translateX(350%)}}

/* ══ HOME (app style) ══ */
.hm{max-width:1200px;margin:0 auto;padding:0 16px 100px;animation:hmIn .5s ease}
@keyframes hmIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.hm-hero{position:relative;margin:0 -16px;padding:20px 20px 74px;border-radius:0 0 32px 32px;background-size:cover;background-position:center;color:#fff}
@media(min-width:992px){.hm-hero{margin:16px 0 0;border-radius:28px;padding:28px 34px 88px}}
.hm-top{display:flex;align-items:center;justify-content:space-between;gap:12px}
.hm-brand{display:flex;align-items:center;gap:12px;min-width:0}
.hm-brand img,.hm-brand .fb{width:46px;height:46px;border-radius:14px;object-fit:cover;flex-shrink:0}
.hm-brand .fb{background:linear-gradient(135deg,#1E9E52,#17C548);color:#000;font-weight:800;font-size:1.2rem;display:flex;align-items:center;justify-content:center}
.hm-brand .t{font-family:var(--font-head);font-weight:700;font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hm-brand .s{font-size:.72rem;opacity:.8}
.hm-acts{display:flex;gap:8px}
.hm-acts button{width:38px;height:38px;border-radius:12px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.14);backdrop-filter:blur(8px);color:#fff;cursor:pointer;transition:background .15s}
.hm-acts button:hover{background:rgba(255,255,255,.28)}
.hm-greet{margin-top:26px}
.hm-greet h1{font-family:var(--font-head);font-weight:700;font-size:1.7rem;margin:0}
.hm-greet p{margin:2px 0 0;opacity:.8;font-size:.85rem}
@media(min-width:992px){.hm-greet h1{font-size:2.4rem}}
.hm-search{position:relative;margin-top:18px;max-width:460px}
.hm-search i{position:absolute;left:16px;top:50%;transform:translateY(-50%);opacity:.7}
.hm-search input{width:100%;padding:12px 16px 12px 42px;border-radius:16px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.16);backdrop-filter:blur(8px);color:#fff;outline:none}
.hm-search input::placeholder{color:rgba(255,255,255,.7)}
.hm-rew{position:relative;z-index:2;margin-top:-54px;background:var(--nx-card);border:1px solid var(--nx-border);border-radius:24px;padding:18px;box-shadow:0 14px 40px rgba(0,0,0,.28)}
.hm-rew-top{display:flex;align-items:center;gap:14px}
.hm-rew-l{font-size:.68rem;letter-spacing:1.2px;color:var(--nx-muted);font-weight:700}
.hm-rew-n{font-family:var(--font-head);font-weight:700;font-size:1.3rem;line-height:1.1}
.hm-rew-xp{font-size:.8rem;color:var(--nx-accent);font-weight:700}
.hm-bar{height:10px;border-radius:10px;background:var(--nx-border);margin:14px 0 8px;overflow:hidden}
.hm-bar span{display:block;height:100%;border-radius:10px;background:linear-gradient(90deg,#1E9E52,#17C548);transition:width 1s ease}
.hm-aim{font-size:.8rem;color:var(--nx-muted);background:rgba(30,158,82,.08);border:1px dashed rgba(30,158,82,.4);border-radius:12px;padding:9px 12px}
.hm-aim b{color:var(--nx-text)}
.hm-lv{display:flex;gap:10px;overflow-x:auto;padding:14px 2px 2px;scrollbar-width:none}
.hm-lv::-webkit-scrollbar{display:none}
.hm-lv-i{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:66px;font-size:.62rem;font-weight:600;color:var(--nx-muted);text-align:center}
.hm-lv-i.lock{filter:grayscale(1);opacity:.35}
.hm-stats{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
.hm-stats div{flex:1;min-width:90px;background:var(--nx-surface);border-radius:12px;padding:8px 10px;text-align:center}
.hm-stats b{display:block;font-family:var(--font-head);font-size:1.05rem}
.hm-stats span{font-size:.62rem;color:var(--nx-muted);text-transform:uppercase;letter-spacing:.6px}
.hm-gh{height:84px;border-radius:20px;background-size:cover;background-position:center;background-color:#1e2333;display:flex;align-items:flex-end;padding:14px 18px;color:#fff;font-family:var(--font-head);font-weight:700;font-size:1.05rem;margin:26px 0 12px}
.hm .home-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
@media(min-width:640px){.hm .home-grid{grid-template-columns:repeat(3,1fr)}}
@media(min-width:992px){.hm .home-grid{grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:16px}}
.hm .home-card{position:relative;text-align:left;border:1px solid var(--nx-border);background:var(--nx-card);color:var(--nx-text);border-radius:22px;padding:16px;display:flex;flex-direction:column;gap:3px;cursor:pointer;transition:transform .15s,box-shadow .15s,border-color .15s}
.hm .home-card:hover{transform:translateY(-3px);box-shadow:0 12px 30px rgba(0,0,0,.25);border-color:rgba(30,158,82,.5)}
.hm .home-card:active{transform:scale(.97)}
.hm .home-ico{width:48px;height:48px;border-radius:16px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;margin-bottom:8px}
.hm .home-card b{font-size:.92rem;font-family:var(--font-head)}
.hm .home-card .d{font-size:.72rem;color:var(--nx-muted)}
.hm-nav{position:fixed;left:12px;right:12px;bottom:12px;z-index:1050;display:none;justify-content:space-around;background:var(--nx-card);border:1px solid var(--nx-border);border-radius:22px;padding:8px;box-shadow:0 10px 30px rgba(0,0,0,.4)}
.hm-nav button{flex:1;border:none;background:none;color:var(--nx-muted);font-size:.62rem;font-weight:600;display:flex;flex-direction:column;align-items:center;gap:3px;padding:6px 0;border-radius:14px}
.hm-nav button i{font-size:1.1rem}
.hm-nav button.on{color:var(--nx-accent);background:rgba(30,158,82,.12)}
@media(max-width:767.98px){.hm-nav{display:flex}}

/* ══ PAYOUT CELEBRATION ══ */
.pay-cel{position:fixed;inset:0;z-index:100020;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0a0d16,#0f3a22);padding:20px;overflow:hidden}
.pc-conf{position:absolute;inset:0;pointer-events:none}
.pc-conf i{position:absolute;top:-20px;width:10px;height:14px;border-radius:2px;animation:pcFall linear forwards}
@keyframes pcFall{to{transform:translateY(110vh) rotate(720deg)}}
.pc-card{position:relative;text-align:center;color:#fff;max-width:420px;width:100%;animation:pcPop .6s cubic-bezier(.2,1.4,.4,1)}
@keyframes pcPop{from{transform:scale(.6);opacity:0}to{transform:none;opacity:1}}
.pc-ring{width:110px;height:110px;margin:0 auto 18px}
.pc-ring svg{width:100%;height:100%}
.pc-ring circle{fill:rgba(34,197,94,.15);stroke:#22c55e;stroke-width:2.5;stroke-dasharray:151;stroke-dashoffset:151;animation:pcDraw .8s .1s forwards}
.pc-ring path{fill:none;stroke:#22c55e;stroke-width:3.5;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:40;stroke-dashoffset:40;animation:pcDraw .5s .8s forwards}
@keyframes pcDraw{to{stroke-dashoffset:0}}
.pc-h{font-family:var(--font-head);font-weight:700;font-size:1.5rem}
.pc-amt{font-family:var(--font-head);font-weight:800;font-size:2.8rem;color:#4ade80;margin:10px 0 2px}
.pc-sub{opacity:.8;margin-bottom:26px}
.pc-btn{width:100%;padding:14px;border:none;border-radius:14px;background:#22c55e;color:#fff;font-weight:700;font-size:1rem}
.pc-later{margin-top:10px;background:none;border:none;color:rgba(255,255,255,.6);font-size:.85rem}

/* ══ BANK "NOT AVAILABLE" CARD ══ */
.wd-ov{position:fixed;inset:0;z-index:100015;background:rgba(5,8,15,.7);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:20px;animation:hmIn .25s ease}
.wd-box{background:var(--nx-card);border:1px solid var(--nx-border);border-radius:24px;padding:28px 24px;max-width:360px;width:100%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.5)}
.wd-logo{position:relative;width:64px;height:64px;border-radius:18px;margin:0 auto 10px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;overflow:hidden}
.wd-logo img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#fff;padding:8px}
.wd-ic{font-size:2rem;margin-bottom:6px}
.wd-box h5{font-family:var(--font-head);font-weight:700}
.wd-box p{color:var(--nx-muted);font-size:.85rem}
.wd-box button{width:100%;padding:11px;border:none;border-radius:12px;background:var(--nx-accent);color:#fff;font-weight:700}

/* ══ CSS your file referenced but never defined ══ */
.msg-b{padding:8px 12px;border-radius:14px;font-size:.85rem;white-space:pre-wrap;word-break:break-word}
.msg-b.me{background:#fde68a;color:#1c1917;border-bottom-right-radius:4px}
.msg-b.them{background:var(--nx-card);border:1px solid var(--nx-border);border-bottom-left-radius:4px}
.msg-who{font-size:.68rem;color:var(--nx-muted);margin-bottom:2px}
#nx-net{position:fixed;left:12px;bottom:12px;z-index:1045;display:flex;align-items:center;gap:6px;background:var(--nx-card);border:1px solid var(--nx-border);border-radius:20px;padding:4px 10px;font-size:.68rem;cursor:pointer}
#nx-net .dot{width:8px;height:8px;border-radius:50%}
#nx-offline{position:fixed;top:0;left:0;right:0;z-index:100030;background:#ef4444;color:#fff;text-align:center;padding:8px;font-size:.82rem}
.pwd-banner{position:fixed;top:12px;left:50%;transform:translateX(-50%);z-index:100025;display:flex;align-items:center;gap:12px;background:#f97316;color:#fff;padding:10px 16px;border-radius:14px;max-width:94vw;font-size:.82rem;box-shadow:0 8px 30px rgba(0,0,0,.4)}
.pwd-banner .go{background:#fff;color:#c2410c;border:none;border-radius:8px;padding:5px 10px;font-weight:700}
.pwd-banner .x{background:none;border:none;color:#fff;font-size:1.2rem}

/* ══ APP SHELL: bottom nav, page transitions, table→cards on phones ══ */
.hm-nav{display:none!important}
.nx-bnav{position:fixed;left:12px;right:12px;bottom:calc(12px + env(safe-area-inset-bottom));z-index:1050;display:none;justify-content:space-around;background:var(--nx-card);border:1px solid var(--nx-border);border-radius:24px;padding:8px;box-shadow:0 12px 34px rgba(0,0,0,.45);backdrop-filter:blur(14px)}
.nx-bnav button{flex:1;border:none;background:none;color:var(--nx-muted);font-size:.62rem;font-weight:600;display:flex;flex-direction:column;align-items:center;gap:3px;padding:7px 0;border-radius:16px;transition:all .2s}
.nx-bnav button i{font-size:1.15rem;transition:transform .2s}
.nx-bnav button.on{color:var(--nx-accent);background:rgba(30,158,82,.14)}
.nx-bnav button.on i{transform:translateY(-2px) scale(1.15)}
@media(max-width:991.98px){
  .nx-bnav{display:flex}
  #nx-content{padding-bottom:100px!important}
  #nx-net{bottom:88px}
  #toast-wrap{bottom:92px;right:12px;left:12px}
  .nx-toast{min-width:0}
}
.pg-in{animation:pgIn .35s cubic-bezier(.2,.8,.2,1)}
@keyframes pgIn{from{opacity:0;transform:translateX(18px)}to{opacity:1;transform:none}}
@media(max-width:767.98px){
  #nx-content table.nx-stack,#nx-content table.nx-stack tbody{display:block;width:100%}
  #nx-content table.nx-stack thead{display:none}
  #nx-content table.nx-stack tr{display:block;margin:10px;padding:8px 14px;border:1px solid var(--nx-border);border-radius:18px;background:var(--nx-surface)}
  #nx-content table.nx-stack td{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:7px 0!important;border:none!important;text-align:right}
  #nx-content table.nx-stack td::before{content:attr(data-label);font-size:.66rem;text-transform:uppercase;letter-spacing:.6px;color:var(--nx-muted);font-weight:700;text-align:left;flex-shrink:0}
  #nx-content table.nx-stack td[data-label=""]::before{display:none}
  #nx-content table.nx-stack td[data-label=""]{justify-content:center}
}

/* ══ WALLET CARD (Finance) ══ */
.wc-wrap{display:flex;justify-content:center;margin-bottom:22px}
.wc{width:100%;max-width:390px;aspect-ratio:1.586;perspective:1400px;animation:wcIn .8s cubic-bezier(.2,1,.3,1)}
@keyframes wcIn{from{opacity:0;transform:translateY(30px) rotateX(20deg) scale(.9)}to{opacity:1;transform:none}}
.wc-in{position:relative;width:100%;height:100%;transition:transform .9s cubic-bezier(.2,.8,.2,1);transform-style:preserve-3d}
.wc.flip .wc-in{transform:rotateY(180deg)}
.wc-face{position:absolute;inset:0;border-radius:24px;padding:18px 22px;backface-visibility:hidden;-webkit-backface-visibility:hidden;overflow:hidden;color:#fff;box-shadow:0 22px 50px rgba(0,0,0,.45)}
.wc-front{background:linear-gradient(135deg,#0b1020 0%,#1d2547 55%,#3a2508 100%);cursor:pointer;display:flex;flex-direction:column;justify-content:space-between}
.wc-front::before{content:'';position:absolute;right:-60px;top:-60px;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,rgba(30,158,82,.55),transparent 65%)}
.wc-front::after{content:'';position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.14),transparent);transform:skewX(-20deg);animation:wcShine 4s ease-in-out infinite}
@keyframes wcShine{0%,60%{left:-60%}100%{left:140%}}
.wc-back{transform:rotateY(180deg);background:linear-gradient(135deg,#111827,#1f2937 60%,#2a1c08);display:flex;flex-direction:column;justify-content:center;text-align:center}
.wc-top{display:flex;justify-content:space-between;align-items:center;position:relative;z-index:1}
.wc-brand{display:flex;align-items:center;gap:8px}
.wc-brand img{width:28px;height:28px;border-radius:8px;background:#fff;object-fit:contain}
.wc-brand b{font-family:var(--font-head);letter-spacing:1.5px}
.wc-brand em{font-style:normal;font-size:.6rem;letter-spacing:2px;opacity:.7}
.wc-nfc{transform:rotate(90deg);opacity:.8}
.wc-chip{width:48px;height:36px;position:relative;z-index:1}
.wc-num{font-family:'Courier New',monospace;font-size:1.15rem;letter-spacing:3px;position:relative;z-index:1;text-shadow:0 2px 6px rgba(0,0,0,.5)}
.wc-bot{display:flex;justify-content:space-between;gap:10px;position:relative;z-index:1}
.wc-bot small{display:block;font-size:.55rem;letter-spacing:1.4px;opacity:.6}
.wc-bot div{font-size:.8rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}
.wc-hint{position:absolute;right:16px;bottom:44px;font-size:.6rem;opacity:.75;animation:wcPulse 1.6s infinite;z-index:1}
@keyframes wcPulse{50%{opacity:.25}}
.wc-qi{font-size:1.6rem}
.wc-back h6{font-family:var(--font-head);font-weight:700;margin:2px 0;font-size:.95rem}
.wc-back p{font-size:.68rem;opacity:.7;margin:0 0 10px}
.wc-btns{display:flex;gap:8px;justify-content:center}
.wc-btns button{border:none;border-radius:12px;padding:8px 14px;font-size:.75rem;font-weight:700}
.wc-btns .yes{background:linear-gradient(135deg,#1E9E52,#17C548);color:#000}
.wc-btns .no{background:rgba(255,255,255,.12);color:#fff}
.wc-bal small{font-size:.6rem;letter-spacing:2px;opacity:.7}
.wc-amt{font-family:var(--font-head);font-weight:800;font-size:1.9rem;color:#4ade80;line-height:1.1;margin:2px 0 8px}
.wc-mini{display:flex;gap:8px;justify-content:center;margin-bottom:10px}
.wc-mini div{background:rgba(255,255,255,.08);border-radius:10px;padding:5px 12px;font-size:.62rem}
.wc-mini span{display:block;opacity:.65;letter-spacing:.6px}
.wc-mini b{display:block;font-size:.8rem;color:#fff}
/* ── rules that were lost in the cut-off ── */
.qc-row{display:flex;gap:6px;margin-top:8px}
.qc-row button{flex:1;padding:6px 0;border-radius:8px;border:1px solid var(--nx-border);background:var(--nx-card);color:var(--nx-text);font-size:.72rem;font-weight:600}
.qc-row button:hover{border-color:var(--nx-accent);color:var(--nx-accent)}
.sale-burst{position:fixed;inset:0;z-index:100050;display:flex;align-items:center;justify-content:center;pointer-events:none;background:rgba(34,197,94,.12);animation:sbFade 1.1s ease forwards}
.sale-burst svg{width:140px;height:140px;filter:drop-shadow(0 10px 30px rgba(34,197,94,.5))}
.sale-burst circle{fill:rgba(34,197,94,.2);stroke:#22c55e;stroke-width:2.5;stroke-dasharray:151;stroke-dashoffset:151;animation:pcDraw .5s forwards}
.sale-burst path{fill:none;stroke:#22c55e;stroke-width:3.5;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:40;stroke-dashoffset:40;animation:pcDraw .4s .4s forwards}
@keyframes sbFade{0%{opacity:0}15%{opacity:1}80%{opacity:1}100%{opacity:0}}
.dash-strip{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}
.dash-strip>div{flex:1;min-width:180px;display:grid;grid-template-columns:auto 1fr;column-gap:10px;align-items:center;background:var(--nx-card);border:1px solid var(--nx-border);border-radius:14px;padding:10px 14px}
.dash-strip i{font-style:normal;font-size:1.4rem;grid-row:1/3}
.dash-strip span{font-size:.62rem;color:var(--nx-muted);text-transform:uppercase;letter-spacing:.6px}
.dash-strip b{font-size:.9rem}
.rc-brand{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:6px}
.rc-brand img{width:28px;height:28px;border-radius:6px;object-fit:cover}
.rc-qr{text-align:center;margin-top:10px;font-size:.62rem}.rc-qr img{width:90px}
.lock-shake{animation:lockShake .5s ease}

/* ── HR page: background, hero, centered profile cards ── */
body.hr-bg::before{content:'';position:fixed;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(10,13,22,.86),rgba(10,13,22,.95)),url('https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1800&q=70') center/cover no-repeat}
[data-theme="light"] body.hr-bg::before{background:linear-gradient(180deg,rgba(240,242,245,.9),rgba(240,242,245,.97)),url('https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1800&q=70') center/cover no-repeat}
body.hr-bg .hr-shell>div:first-child{background:color-mix(in srgb,var(--nx-bg) 78%,transparent)!important;backdrop-filter:blur(10px)}
.hr-shell{margin:0 auto}
.hr-pills{overflow-x:auto;flex-wrap:nowrap!important;white-space:nowrap;scrollbar-width:none}
.hr-pills::-webkit-scrollbar{display:none}
.hr-hero{position:relative;border-radius:26px;overflow:hidden;margin:10px 0 22px;padding:34px 20px;text-align:center;color:#fff;border:1px solid rgba(255,255,255,.12);background:linear-gradient(135deg,rgba(10,13,22,.78),	rgba(30,158,82,.45) 60%,rgba(30,158,82,.4)),url('https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1600&q=70') center/cover}
.hr-hero h2{font-family:var(--font-head);font-weight:700;font-size:1.7rem;margin:0 0 6px}
.hr-hero p{margin:0 auto 18px;max-width:520px;opacity:.88;font-size:.88rem}
.hr-stats{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-bottom:18px}
.hr-stat{min-width:120px;flex:1 1 120px;max-width:190px;background:rgba(10,13,22,.55);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.15);border-radius:16px;padding:10px 14px}
.hr-stat b{display:block;font-family:var(--font-head);font-size:1.2rem}
.hr-stat span{font-size:.62rem;letter-spacing:.7px;text-transform:uppercase;opacity:.75}
.hr-hero-btns{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}
.hr-hero-btns button{border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.14);backdrop-filter:blur(8px);color:#fff;border-radius:12px;padding:9px 16px;font-weight:600;font-size:.82rem}
.hr-hero-btns button.main{background:linear-gradient(135deg,#1E9E52,#17C548);border:none}
.hr3-wrap{max-width:1240px;margin:0 auto}
.hr3-bar{display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap;margin:6px 0 16px}
.hr3-bar .t{font-family:var(--font-head);font-weight:700;font-size:1.05rem;display:flex;align-items:center;gap:8px}
.hr3-bar .t .n{background:var(--nx-border);border-radius:20px;font-size:.7rem;padding:2px 9px}
.hr3-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,310px),360px));gap:18px;justify-content:center;margin-bottom:30px}
.hr3-card{background:var(--nx-card);border:1px solid var(--nx-border);border-radius:24px;overflow:hidden;text-align:center;display:flex;flex-direction:column;box-shadow:0 10px 30px rgba(0,0,0,.2);transition:transform .15s,border-color .15s}
.hr3-card:hover{transform:translateY(-4px);border-color:rgba(30,158,82,.55)}
.hr3-cover{height:74px;background:linear-gradient(135deg,#7c3aed,#3b82f6 55%,#1E9E52)}
.hr3-av{width:92px;height:92px;border-radius:50%;margin:-46px auto 8px;border:4px solid var(--nx-card);background:linear-gradient(135deg,#1E9E52,#17C548) center/cover no-repeat;display:flex;align-items:center;justify-content:center;font-size:2rem;font-weight:700;color:#000;position:relative;cursor:pointer;flex-shrink:0}
.hr3-name{font-family:var(--font-head);font-weight:700;font-size:1.05rem;display:flex;align-items:center;justify-content:center;padding:0 14px;text-align:center}
.hr3-role{font-size:.76rem;color:var(--nx-muted);margin-bottom:8px;padding:0 12px}
.hr3-chips{display:flex;gap:6px;justify-content:center;flex-wrap:wrap;padding:0 12px;margin-bottom:12px}
.hr-chip2.r{background:rgba(239,68,68,.15);color:#f87171}
.hr3-pay{margin:0 14px 12px;background:var(--nx-surface);border-radius:16px;padding:12px}
.hr3-pay small{display:block;font-size:.62rem;text-transform:uppercase;letter-spacing:.8px;color:var(--nx-muted)}
.hr3-pay .amt{font-family:var(--font-head);font-weight:700;font-size:1.5rem;background:linear-gradient(135deg,#1E9E52,#17C548);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.hr3-info{margin:0 14px 12px;display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:left}
.hr3-info div,.hr3-tile{background:var(--nx-surface);border-radius:12px;padding:8px 10px;min-width:0}
.hr3-info span,.hr3-tile span{display:block;font-size:.58rem;text-transform:uppercase;letter-spacing:.7px;color:var(--nx-muted)}
.hr3-info b,.hr3-tile b{display:block;font-size:.78rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hr3-ai{margin:0 14px 12px;font-size:.74rem;color:var(--nx-muted);line-height:1.5;border:1px dashed 	rgba(30,158,82,.45);border-radius:14px;padding:9px 12px;background:	rgba(30,158,82,.06)}
.hr3-ai b{color:var(--nx-text)}
.hr3-acts{margin-top:auto;display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:0 12px 14px}
.hr3-acts.three{grid-template-columns:repeat(3,1fr)}
.hr3-acts button{border:1px solid var(--nx-border);background:var(--nx-surface);color:var(--nx-text);border-radius:12px;padding:8px 2px;font-size:.62rem;font-weight:600;display:flex;flex-direction:column;align-items:center;gap:4px;transition:all .15s}
.hr3-acts button i{font-size:.95rem}
.hr3-acts button:hover:not(:disabled){border-color:var(--nx-accent);color:var(--nx-accent)}
.hr3-acts button:disabled{opacity:.35}
.hr3-acts button.ai{background:linear-gradient(135deg,	rgba(30,158,82,.18),rgba(59,130,246,.18));border-color:	rgba(30,158,82,.4)}
.hr3-pm-cover{height:90px;background:linear-gradient(135deg,#7c3aed,#3b82f6 55%,#1E9E52);margin:-1rem -1rem 0}
.hr3-pm-grid,.hr3-me-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
.hr3-sec{font-size:.68rem;text-transform:uppercase;letter-spacing:1px;color:var(--nx-muted);margin:18px 0 8px;font-weight:700}
@media(max-width:575.98px){.hr-hero{padding:26px 14px;border-radius:20px}.hr-hero h2{font-size:1.35rem}.hr3-grid{grid-template-columns:1fr}.hr3-card{max-width:420px;width:100%;margin:0 auto}}
.tb-av{width:28px;height:28px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;vertical-align:middle;font-size:.75rem;font-weight:700;color:#fff;background:linear-gradient(135deg,#1E9E52,#17C548) center/cover no-repeat;border:2px solid var(--nx-border);flex-shrink:0}
#nx-backdrop { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 1039; backdrop-filter: blur(2px); }
#nx-backdrop.show { display: block; }

/* Lock screen shake */
@keyframes lockShake {
  0%,100% { transform: translateX(0); }
  15%     { transform: translateX(-10px); }
  30%     { transform: translateX(10px); }
  45%     { transform: translateX(-8px); }
  60%     { transform: translateX(8px); }
  75%     { transform: translateX(-4px); }
  90%     { transform: translateX(4px); }
}
/* ── NYMIX AI + HR v3 ── */
.ico-tile{width:38px;height:38px;border-radius:12px;display:inline-flex;align-items:center;justify-content:center;margin-right:10px;color:#000;background:linear-gradient(135deg,#1E9E52,#17C548);box-shadow:0 6px 16px rgba(30,158,82,.35)}
.nx-ai-tag{font-size:.62rem;font-weight:700;letter-spacing:.6px;padding:3px 9px;border-radius:20px;background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff;white-space:nowrap}
.ai-fab{position:fixed;right:18px;bottom:22px;z-index:1046;border:none;border-radius:30px;padding:12px 18px;display:flex;align-items:center;gap:8px;font-weight:700;font-size:.82rem;color:#fff;background:linear-gradient(135deg,#1E9E52,#17C548);box-shadow:0 10px 30px rgba(99,60,237,.45);transition:transform .15s}
.ai-fab:hover{transform:translateY(-2px)}
.ai-panel{position:fixed;right:18px;bottom:78px;z-index:1047;width:350px;max-width:calc(100vw - 24px);height:460px;max-height:70vh;background:var(--nx-card);border:1px solid var(--nx-border);border-radius:20px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.5);animation:hmIn .25s ease}
.ai-ph{background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff;padding:14px 16px;display:flex;justify-content:space-between;align-items:flex-start}
.ai-ph button{background:none;border:none;color:#fff;font-size:1.3rem;line-height:1}.ai-ps{font-size:.68rem;opacity:.8}
.ai-msgs{flex:1;overflow-y:auto;padding:12px;display:flex;flex-direction:column;gap:8px}
.ai-b{max-width:86%;padding:8px 12px;border-radius:14px;font-size:.82rem;white-space:pre-wrap;word-break:break-word}
.ai-b.bot{background:var(--nx-surface);border:1px solid var(--nx-border);align-self:flex-start;border-bottom-left-radius:4px}
.ai-b.me{background:#ddd6fe;color:#1e1b4b;align-self:flex-end;border-bottom-right-radius:4px}
.ai-chips{display:flex;gap:6px;flex-wrap:wrap;padding:0 12px 8px}
.ai-chips button{border:1px solid var(--nx-border);background:var(--nx-surface);color:var(--nx-text);border-radius:20px;padding:4px 10px;font-size:.68rem}
.ai-chips button:hover{border-color:#7c3aed;color:#a78bfa}
.ai-in{display:flex;gap:8px;padding:10px;border-top:1px solid var(--nx-border)}
.ai-in input{flex:1;background:var(--nx-surface);border:1px solid var(--nx-border);border-radius:12px;padding:8px 12px;color:var(--nx-text);font-size:.82rem}
.ai-in button{border:none;border-radius:12px;width:40px;background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff}
.ai-dots i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a78bfa;margin:0 2px;animation:aiDot 1s infinite}
.ai-dots i:nth-child(2){animation-delay:.15s}.ai-dots i:nth-child(3){animation-delay:.3s}
@keyframes aiDot{0%,80%,100%{transform:translateY(0);opacity:.4}40%{transform:translateY(-5px);opacity:1}}
@media(max-width:991.98px){.ai-fab{bottom:96px;right:12px}.ai-panel{bottom:150px;right:12px}}
/* HR staff cards */
.hr2-bar{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:6px 0 14px}
.hr2-h{font-family:var(--font-head);font-weight:700;font-size:1.05rem;display:flex;align-items:center;gap:8px}
.hr2-h span.n{background:var(--nx-border);border-radius:20px;font-size:.7rem;padding:2px 9px}
.hr2-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:14px;margin-bottom:26px}
.hr2-card{background:var(--nx-card);border:1px solid var(--nx-border);border-radius:22px;padding:16px;display:flex;flex-direction:column;gap:12px;transition:transform .15s,border-color .15s,box-shadow .15s}
.hr2-card:hover{transform:translateY(-3px);border-color:rgba(30,158,82,.5);box-shadow:0 14px 34px rgba(0,0,0,.25)}
.hr2-top{display:flex;align-items:center;gap:12px}
.hr2-av{width:58px;height:58px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg,#1E9E52,#17C548) center/cover no-repeat;display:flex;align-items:center;justify-content:center;font-weight:700;color:#000;font-size:1.3rem;border:3px solid var(--nx-border)}
.hr2-top b{display:flex;align-items:center;font-size:.95rem}.hr2-top small{color:var(--nx-muted);font-size:.72rem}
.hr2-pay{background:var(--nx-surface);border-radius:14px;padding:10px 12px;display:flex;justify-content:space-between;align-items:center;gap:8px}
.hr2-pay .amt{font-family:var(--font-head);font-weight:700;font-size:1.15rem;background:linear-gradient(135deg,#1E9E52,#17C548);-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.hr2-pay small{display:block;font-size:.62rem;color:var(--nx-muted);text-transform:uppercase;letter-spacing:.6px}
.hr-chip2{font-size:.66rem;font-weight:700;padding:3px 9px;border-radius:20px;background:rgba(59,130,246,.15);color:#60a5fa;white-space:nowrap}
.hr-chip2.w{background:rgba(30,158,82,.15);color:#fbbf24}.hr-chip2.g{background:rgba(34,197,94,.15);color:#4ade80}
.hr2-ai{font-size:.74rem;color:var(--nx-muted);line-height:1.5;min-height:36px}
.hr2-ai b{color:var(--nx-text)}
.hr2-acts{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.hr2-acts button{border:1px solid var(--nx-border);background:var(--nx-surface);color:var(--nx-text);border-radius:12px;padding:8px 2px;font-size:.62rem;font-weight:600;display:flex;flex-direction:column;align-items:center;gap:4px;transition:all .15s}
.hr2-acts button i{font-size:.95rem}
.hr2-acts button:hover{border-color:var(--nx-accent);color:var(--nx-accent)}
.hr2-acts button.ai{background:linear-gradient(135deg,	rgba(30,158,82,.18),rgba(59,130,246,.18));border-color:	rgba(30,158,82,.4)}
.hr2-acts button.ai:hover{border-color:#a78bfa;color:#a78bfa}
/* NYMIX is reading loader */
.hrai-doc{width:110px;height:140px;margin:6px auto 18px;border-radius:12px;background:#fff;position:relative;overflow:hidden;box-shadow:0 14px 34px 	rgba(30,158,82,.35);background-image:repeating-linear-gradient(#fff 0 12px,#e2e8f0 12px 14px);background-size:100% 100%}
.hrai-doc::before{content:'';position:absolute;left:14px;top:14px;width:34px;height:34px;border-radius:50%;background:#c4b5fd}
.hrai-scan{position:absolute;left:0;right:0;height:3px;background:linear-gradient(90deg,transparent,#7c3aed,transparent);box-shadow:0 0 16px 4px 	rgba(30,158,82,.7);animation:hraiScan 1.5s ease-in-out infinite}
@keyframes hraiScan{0%{top:0}50%{top:calc(100% - 3px)}100%{top:0}}
.hrai-t{font-family:var(--font-head);font-weight:700;text-align:center;font-size:1.05rem}
.hrai-s{text-align:center;color:var(--nx-muted);font-size:.8rem;min-height:20px;margin-top:4px}
.hrai-tag{display:inline-block;margin:2px 4px 2px 0;padding:3px 10px;border-radius:20px;font-size:.7rem;background:	rgba(30,158,82,.15);color:#a78bfa;font-weight:600}
/* ══ NYMIX GREEN THEME (matches landing page) ══ */
@keyframes nxSpin{to{transform:rotate(360deg)}}
@keyframes nxPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}
:root,[data-theme="dark"]{
  --nx-bg:#0d2415;--nx-surface:#14351F;--nx-card:#1a4128;--nx-border:#2b5a3a;
  --nx-accent:#17C548;--nx-blue:#60a5fa;--nx-green:#17C548;--nx-red:#f87171;--nx-orange:#E87800;
  --nx-text:#eaf3ec;--nx-muted:#8fb09a;
  --font-body:'Outfit',sans-serif;--font-head:'Fraunces',serif;--font-mono:'DM Mono',monospace;
}
[data-theme="light"]{
  --nx-bg:#FBFAF4;--nx-surface:#FFFFFF;--nx-card:#FFFFFF;--nx-border:#E1E9DB;
  --nx-accent:#1E9E52;--nx-blue:#2563eb;--nx-green:#16a34a;--nx-red:#dc2626;--nx-orange:#E87800;
  --nx-text:#14251A;--nx-muted:#5f7466;
}
.card,.stat-card,.hr3-card,.pl-row,.hm-rew{border-radius:20px}
