.nx-page-title,.stat-value{font-family:var(--font-head);font-weight:600}
.stat-card:hover{box-shadow:0 24px 50px rgba(20,53,31,.12)}
.user-avatar,.pos-topbar-logo,.pos-cat-btn.active,.pos-cat-btn.active .pci,.pos-charge-btn,.pos-qbtn:hover,.cart-qty-btn:hover{color:#fff}

/* NT logo mark */
.nt-mark{width:38px;height:38px;border-radius:10px;display:inline-grid;place-items:center;flex-shrink:0;
  background:linear-gradient(135deg,#1E9E52,#17C548);box-shadow:0 4px 14px rgba(30,158,82,.35);
