.nt-lock{display:flex;align-items:center;gap:12px;font-family:var(--font-head);font-weight:600;font-size:1.35rem;letter-spacing:.5px;color:#fff}
.login-form-panel .nt-lock{color:var(--nx-text)}

/* Login panel */
#login-screen,[data-theme="light"] #login-screen{background:var(--nx-bg)}
.login-visual-overlay{background:linear-gradient(160deg,rgba(13,36,21,.92),rgba(20,53,31,.82) 55%,rgba(13,36,21,.95))}
.login-visual-content .login-feature-item strong{color:#fff}
.login-tagline,.login-feature-item span,.login-trust{color:rgba(255,255,255,.75)}

/* Loader (NT instead of bouncing photo) */
#nx-loader{background:radial-gradient(circle at 50% 40%,#1E4A2B 0%,#14351F 60%,#0d2415 100%)}
.nt-logo-wrap{background:linear-gradient(135deg,#1E9E52,#17C548);box-shadow:0 14px 40px rgba(23,197,72,.45)}
.nt-logo-fb{color:#fff;font-family:var(--font-head);font-size:2.2rem}
.nt-bar span{background:linear-gradient(90deg,#17C548,#E87800)}

/* NYMIX AI (same look as the landing page) */
.ai-fab{left:24px;right:auto;background:#14351F;border:1px solid rgba(255,255,255,.14);box-shadow:0 12px 30px rgba(20,53,31,.35)}
.ai-fab-dot{width:8px;height:8px;border-radius:50%;background:#17C548;box-shadow:0 0 10px #17C548;animation:aiBlink 2s ease-in-out infinite}
@keyframes aiBlink{0%,100%{opacity:1}50%{opacity:.25}}
.ai-panel{left:24px;right:auto}
.ai-ph{background:linear-gradient(135deg,#14351F,#1E4A2B)}
.ai-b.me{background:#d7f3e0;color:#14351F}
.ai-chips button:hover{border-color:#1E9E52;color:#1E9E52}
.ai-av{position:relative;width:44px;height:44px;display:grid;place-items:center;flex-shrink:0}
.ai-av i{position:absolute;inset:0;border-radius:50%;background:conic-gradient(#17C548,#E87800,#FBFAF4,#1E9E52,#17C548);
  -webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 2px));
  mask:radial-gradient(farthest-side,transparent calc(100% - 3px),#000 calc(100% - 2px));animation:nxSpin 1.6s linear infinite}
.ai-av b{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#1E9E52,#17C548);display:grid;place-items:center;font-size:15px;animation:nxPulse 2s ease-in-out infinite}
@media(max-width:991.98px){.ai-fab{left:12px;bottom:96px}.ai-panel{left:12px}}
</style>
