<!-- ══════════ ID VERIFICATION WIZARD ══════════ -->
<style>
.vf-steps{display:flex;align-items:center;justify-content:center;margin-bottom:20px}
.vf-dot{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:64px}
.vf-dot span{width:30px;height:30px;border-radius:50%;background:var(--nx-surface);border:2px solid var(--nx-border);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.8rem;color:var(--nx-muted);transition:all .2s}
.vf-dot label{font-size:.65rem;color:var(--nx-muted)}
.vf-dot.active span{background:#0095f6;border-color:#0095f6;color:#fff}
.vf-dot.active label{color:#0095f6;font-weight:600}
.vf-dot.done span{background:var(--nx-green);border-color:var(--nx-green);color:#fff;font-size:0}
.vf-dot.done span::after{content:"✓";font-size:.85rem}
.vf-line{flex:0 0 36px;height:2px;background:var(--nx-border);margin-bottom:16px}
.vf-preview{width:100%;max-height:190px;object-fit:contain;border-radius:12px;border:1px solid var(--nx-border);background:#000}
.vf-cam{position:relative;width:100%;max-width:320px;aspect-ratio:4/3;margin:0 auto 14px;border-radius:16px;overflow:hidden;background:#000}
.vf-cam video{width:100%;height:100%;object-fit:cover;transform:scaleX(-1)}
.vf-oval{position:absolute;inset:10% 27%;border:3px dashed rgba(255,255,255,.85);border-radius:50%;pointer-events:none}
.vf-pop{animation:vfPop .7s cubic-bezier(.2,1.4,.4,1)}
@keyframes vfPop{0%{transform:scale(0) rotate(-30deg);opacity:0}60%{transform:scale(1.2) rotate(6deg);opacity:1}100%{transform:scale(1) rotate(0)}}
.vf-blue{background:#0095f6;color:#fff;border:none}
.vf-blue:hover{background:#0081d6;color:#fff}
.vf-blue:disabled{opacity:.5}
</style>
<div class="modal fade" id="modal-idv" tabindex="-1" data-bs-backdrop="static" data-bs-keyboard="false">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title fw-head"><i class="fa fa-shield-halved me-2" style="color:#0095f6"></i>Verify My Identity</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div class="vf-steps">
          <div class="vf-dot active" data-n="1"><span>1</span><label>Scan ID</label></div>
          <div class="vf-line"></div>
          <div class="vf-dot" data-n="2"><span>2</span><label>Your face</label></div>
          <div class="vf-line"></div>
          <div class="vf-dot" data-n="3"><span>3</span><label>Match</label></div>
        </div>

        <div id="vf-err" class="alert alert-danger py-2 small d-none"></div>

        <!-- STEP 1: upload ID -->
        <div id="vf-id">
          <h6 class="fw-head mb-1">Take a photo of your ID</h6>
          <p class="text-nx-muted small mb-3">National ID, driver's licence or passport (front). Clear, well lit, no glare.</p>
          <div class="mb-3">
            <label class="form-label">ID issuing country</label>
            <select id="vf-country" class="form-select">
              <option value="KE">Kenya</option><option value="UG">Uganda</option><option value="TZ">Tanzania</option>
              <option value="RW">Rwanda</option><option value="ET">Ethiopia</option><option value="NG">Nigeria</option>
              <option value="GH">Ghana</option><option value="ZA">South Africa</option><option value="US">United States</option>
              <option value="GB">United Kingdom</option><option value="CA">Canada</option><option value="IN">India</option>
              <option value="XX">Other</option>
            </select>
          </div>
          <input type="file" id="vf-file" accept="image/*" capture="environment" class="form-control mb-3" onchange="vfFilePicked(this)">
          <img id="vf-preview" class="vf-preview d-none mb-3" alt="ID preview">
          <div class="form-check mb-3">
            <input class="form-check-input" type="checkbox" id="vf-consent">
            <label class="form-check-label small" for="vf-consent">I consent to my ID and face being checked on this device. The photos are never uploaded or saved.</label>
          </div>
          <button id="vf-go" class="btn vf-blue w-100 fw-bold" onclick="vfScanId()" disabled>Continue →</button>
        </div>

        <!-- validating ID -->
        <div id="vf-check" class="d-none text-center py-4">
          <div class="spinner-border mb-3" style="color:#0095f6;width:3rem;height:3rem"></div>
          <h6 class="fw-head mb-1">Please hold on while we validate your details</h6>
          <p class="text-nx-muted small mb-0" id="vf-check-msg">Getting things ready…</p>
        </div>

        <!-- STEP 2: face -->
        <div id="vf-face" class="d-none text-center">
          <h6 class="fw-head mb-1">Please capture your face</h6>
          <p class="text-nx-muted small mb-3">Look straight at the camera, keep your face inside the oval, and remove caps or glasses.</p>
          <div class="vf-cam">
            <video id="vf-video" autoplay playsinline muted></video>
            <div class="vf-oval"></div>
          </div>
          <button id="vf-cap" class="btn vf-blue w-100 fw-bold mb-2" onclick="vfCaptureFace()" disabled><i class="fa fa-camera me-2"></i>Capture</button>
          <button class="btn btn-outline-secondary btn-sm w-100" onclick="vfStartCamera()">Retry camera</button>
        </div>

        <!-- STEP 3: matching -->
        <div id="vf-match" class="d-none text-center py-4">
          <div class="spinner-border mb-3" style="color:#0095f6;width:3rem;height:3rem"></div>
          <h6 class="fw-head mb-1">Matching your face to your ID…</h6>
          <p class="text-nx-muted small mb-0">Almost done.</p>
        </div>

        <!-- failed -->
        <div id="vf-fail" class="d-none text-center py-3">
          <div style="font-size:2.5rem" class="mb-2">⚠️</div>
          <h6 class="fw-head mb-1">We couldn't verify you</h6>
          <p class="text-nx-muted small mb-3" id="vf-fail-msg"></p>
          <button class="btn vf-blue w-100 fw-bold mb-2" onclick="vfRetrySelfie()">Retake my face photo</button>
          <button class="btn btn-outline-secondary btn-sm w-100" onclick="vfRestart()">Use a different ID photo</button>
        </div>

        <!-- success -->
        <div id="vf-done" class="d-none text-center py-3">
          <div class="vf-pop d-inline-block mb-2" id="vf-done-badge"></div>
          <h5 class="fw-head mb-1">Verification successful</h5>
          <p class="text-nx-muted small mb-3">Thank you! Your blue badge is now active on your profile.</p>
          <div id="vf-photo-hint" class="alert py-2 small d-none" style="background:rgba(0,149,246,.1);color:var(--nx-text)">
            You don't have a profile picture yet. <a href="#" onclick="vfFinish();openProfile();return false" style="color:#0095f6;font-weight:600">Add one now →</a>
          </div>
          <button class="btn vf-blue w-100 fw-bold" onclick="vfFinish()">Done</button>
        </div>
      </div>
    </div>
  </div>
</div>

