<script>
// ════════════════════════════════════════════════════════════
//  NYMIX STAFF PORTAL — CLIENT JS  (Secured v2)
// ════════════════════════════════════════════════════════════
const SELF = window.location.pathname;
const CSRF = <?= json_encode($csrf_token) ?>;
const R = { OWNER:1, MANAGER:2, CASHIER:3, STOREKEEPER:4, SUPPLIER:5, SUPPORT:11 };
const CU = <?= $logged_in ? json_encode([
  'id'           => (int)$user['id'],
  'name'         => $user['full_name'] ?? '',
  'username'     => $user['username']  ?? '',
  'role_id'      => (int)($user['role_id'] ?? 0),
  'role_name'    => $user['role_name']   ?? '',
  'branch_id'    => (int)($user['branch_id'] ?? 0),
  'branch_name'  => $user['branch_name'] ?? '',
  'business_name'=> $user['business_name'] ?? 'NYMIX Hardware',
  'logo'         => $user['logo'] ?? '',
  'branch_address'=> $user['branch_address'] ?? '',
  'branch_phone' => $user['branch_phone'] ?? '',
  'id_verified'  => (int)($user['id_verified'] ?? 0),
  'card_required'=> (int)($user['card_required'] ?? 0),
  'card_issued'  => !empty($user['card_issued_at']) ? 1 : 0,
  'photo'        => $user['photo_path'] ?? '',
  'phone'        => $user['phone'] ?? '',
  'pwd_weak'     => !empty($user['pwd_weak']) ? 1 : 0,
]) : 'null' ?>;

// ── UTILS ────────────────────────────────────────────────────
const can = (...roles) => CU && roles.includes(CU.role_id);
const fmt = n => 'KSh ' + parseFloat(n||0).toLocaleString('en-KE',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtDate = d => d ? new Date(d).toLocaleDateString('en-KE') : '—';
const today = () => new Date().toISOString().slice(0,10);
const esc = s => { const d=document.createElement('div'); d.textContent=s||''; return d.innerHTML; };

// ── LIVE PRODUCT IMAGE SEARCH (self-healing, no API key needed) ─
const _imgCache = {};
async function searchProductImage(name) {
  if (!name) return null;
  if (_imgCache[name] !== undefined) return _imgCache[name];
  const d = await api('image_search', { q: name });
  const url = (d.ok && d.results && d.results[0]) ? d.results[0].thumb : null;
  _imgCache[name] = url;
  return url;
}
function fixProductImage(imgEl, name) {
  if (imgEl.dataset.fixing === '1') return;
  imgEl.dataset.fixing = '1';
  searchProductImage(name).then(url => {
    if (url) {
      imgEl.onerror = () => { imgEl.parentElement.innerHTML = `<div class="prod-img-fallback">${esc((name||'?').charAt(0).toUpperCase())}</div>`; };
      imgEl.src = url;
    } else {
      imgEl.parentElement.innerHTML = `<div class="prod-img-fallback">${esc((name||'?').charAt(0).toUpperCase())}</div>`;
    }
  });
}

// ── NOTIFICATION SOUNDS ──────────────────────────────────────
const _sfx = (() => {
  const ctx = new (window.AudioContext || window.webkitAudioContext)();
  function play(freq, type, duration, vol=0.3) {
    try {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.connect(g); g.connect(ctx.destination);
      o.type = type; o.frequency.setValueAtTime(freq, ctx.currentTime);
      g.gain.setValueAtTime(vol, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
      o.start(ctx.currentTime); o.stop(ctx.currentTime + duration);
    } catch(e) {}
  }
  return {
    success: () => { play(520, 'sine', 0.12); setTimeout(() => play(780, 'sine', 0.18), 100); },
    error:   () => { play(220, 'sawtooth', 0.15); setTimeout(() => play(180, 'sawtooth', 0.2), 120); },
    info:    () => { play(440, 'sine', 0.1, 0.15); },
    sale:    () => { play(520,'sine',0.1); setTimeout(()=>play(660,'sine',0.1),80); setTimeout(()=>play(880,'sine',0.18),160); },
    void:    () => { play(440,'sawtooth',0.12); setTimeout(()=>play(300,'sawtooth',0.15),100); setTimeout(()=>play(200,'sawtooth',0.2),200); },
  };
})();

function toast(msg, type='info') {
  const icons = { success:'✓', error:'✕', info:'ℹ' };
  const el = document.createElement('div');
  el.className = `nx-toast ${type}`;
  el.innerHTML = `<span>${icons[type]||'•'}</span><span>${msg}</span>`;
  document.getElementById('toast-wrap').appendChild(el);
  setTimeout(() => el.remove(), 3500);
  // Play sound
  try {
    if      (type === 'error')   _sfx.error();
    else if (type === 'success') _sfx.success();
    else                         _sfx.info();
  } catch(e) {}
}

function toastSale()  { _sfx.sale(); }
function toastVoid()  { _sfx.void(); }

// ── EMAIL EOD REPORT (dashboard button) ────────────────────────
async function sendEodReportNow() {
  let branch_id = CU.branch_id || 0;

  // Owner has no fixed branch — ask which branch to send the report for
  if (!branch_id) {
    const br = await api('branches_list');
    if (!br.ok || !br.branches.length) { toast('No branches found.', 'error'); return; }
    if (br.branches.length === 1) {
      branch_id = br.branches[0].id;
    } else {
      const names = br.branches.map((b, i) => `${i + 1}. ${b.name}`).join('\n');
      const pick = prompt(`Which branch?\n${names}\n\nEnter the number:`);
      const idx = parseInt(pick, 10) - 1;
      if (isNaN(idx) || !br.branches[idx]) { toast('Cancelled — no valid branch selected.', 'info'); return; }
      branch_id = br.branches[idx].id;
    }
  }

  toast('Sending End of Day report…', 'info');
  const res = await api('send_eod_report', { branch_id, date: today() }, 'POST');
  if (res.ok) {
    toast(res.msg || 'End of day report sent.', res.sent ? 'success' : 'info');
  } else {
    toast(res.msg || 'Failed to send report.', 'error');
  }
}

async function api(action, params={}, method='GET') {
  const url = SELF + '?action=' + encodeURIComponent(action);
  const opts = { method };
  if (method === 'POST') {
    const fd = new FormData();
    fd.append('csrf', CSRF); // CSRF on every POST
    for (const k in params) fd.append(k, params[k]);
    opts.body = fd;
  }
  try {
    const res = await fetch(
      method === 'GET' ? url + '&' + new URLSearchParams(params) : url,
      opts
    );
    const text = await res.text();
    let data;
    try {
      data = JSON.parse(text);
    } catch (parseErr) {
      console.error('Non-JSON response [' + action + ']:', text.substring(0, 800));
      toast('Server error on "' + action + '". Open browser console (F12) for details.', 'error');
      return { ok: false, msg: 'Server returned an unexpected response.' };
    }
    if (data.review_lock && !window._hlShowing) { healthGate().then(() => location.reload()); }
    if (data.review_lock && !window._hlShowing) { healthGate().then(() => location.reload()); }
    if (data.guideline_gate && !window._glShowing) { guidelineGate().then(() => location.reload()); }
    if (data.locked) {
      toast('System unavailable. Contact your administrator.', 'error');
      setTimeout(() => doLogout(), 2000);
    }
    return data;
  } catch (e) {
    console.error('Fetch failed [' + action + ']:', e);
    toast('Request failed: ' + e.message, 'error');
    return { ok: false, msg: 'Request failed: ' + e.message };
  }
}

// Bootstrap modal helpers
function openModal(id)  { bootstrap.Modal.getOrCreateInstance(document.getElementById(id)).show(); }
function closeModal(id) { bootstrap.Modal.getInstance(document.getElementById(id))?.hide(); }

function loading(el) {
  el.innerHTML = `<div class="d-flex align-items-center justify-content-center py-5">
    <div class="spinner-border text-warning me-3"></div>
    <span class="text-nx-muted">Loading...</span></div>`;
}

// ── SIDEBAR (mobile) ─────────────────────────────────────────
function toggleSidebar() {
  const sb = document.getElementById('nx-sidebar');
  const bd = document.getElementById('nx-backdrop');
  sb.classList.toggle('show');
  bd.classList.toggle('show');
  document.body.style.overflow = sb.classList.contains('show') ? 'hidden' : '';
}
function closeSidebar() {
  document.getElementById('nx-sidebar').classList.remove('show');
  document.getElementById('nx-backdrop').classList.remove('show');
  document.body.style.overflow = '';
}

// ── PASSWORD TOGGLE ──────────────────────────────────────────
function togglePassword() {
  const inp = document.getElementById('l-pass');
  const icon = document.getElementById('pw-eye-icon');
  const isHidden = inp.type === 'password';
  inp.type = isHidden ? 'text' : 'password';
  icon.className = isHidden ? 'fa fa-eye-slash' : 'fa fa-eye';
}

// ── LOGIN ────────────────────────────────────────────────────
async function doLogin() {
  const u   = document.getElementById('l-user').value.trim();
  const p   = document.getElementById('l-pass').value;
  const err = document.getElementById('login-err');
  const box = document.querySelector('#login-screen .login-box');
  err.classList.add('d-none');
  if (!u || !p) {
    err.textContent = 'Enter username and password.'; err.classList.remove('d-none');
    box?.classList.add('login-shake'); setTimeout(()=>box?.classList.remove('login-shake'),400);
    return;
  }
  const btn = document.querySelector('#login-screen .btn');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Signing in…';
  const res = await api('login', { username: u, password: p }, 'POST');
  btn.disabled = false; btn.innerHTML = '<i class="fa fa-sign-in-alt me-2"></i> Sign In';
  if (res.ok) { location.reload(); }
  else {
    err.textContent = res.msg || 'Login failed.'; err.classList.remove('d-none');
    box?.classList.add('login-shake'); setTimeout(()=>box?.classList.remove('login-shake'),400);
  }
}
document.getElementById('l-pass')?.addEventListener('keydown', e => { if (e.key === 'Enter') doLogin(); });
document.getElementById('l-user')?.addEventListener('keydown', e => { if (e.key === 'Enter') doLogin(); });

function doLogout() { window.location = SELF + '?action=logout'; }

// ── FORGOT PASSWORD (staff) ──────────────────────────────────
let _fgUsername = '';
function showForgotStep(step) {
  ['creds','username','email','reset'].forEach(s => {
    document.getElementById('login-step-' + s).classList.toggle('d-none', s !== step);
  });
  ['1','2','3'].forEach(n => document.getElementById('forgot-err-' + n)?.classList.add('d-none'));
}
function fgError(n, msg) {
  const el = document.getElementById('forgot-err-' + n);
  el.textContent = msg; el.classList.remove('d-none');
}
async function doForgotCheck() {
  const u = document.getElementById('fg-user').value.trim();
  if (!u) { fgError('1', 'Enter your username.'); return; }
  const res = await api('staff_forgot_check', { username: u }, 'POST');
  if (res.ok) {
    _fgUsername = u;
    showForgotStep('email');
  } else {
    fgError('1', res.msg || 'Username not found.');
  }
}
async function doForgotSend() {
  const email = document.getElementById('fg-email').value.trim();
  if (!email) { fgError('2', 'Enter an email address.'); return; }
  const res = await api('staff_forgot_send', { username: _fgUsername, email }, 'POST');
  if (res.ok) {
    showForgotStep('reset');
    toast('Reset code sent to your email', 'success');
  } else {
    fgError('2', res.msg || 'Could not send code.');
  }
}
async function doForgotReset() {
  const otp = document.getElementById('fg-otp').value.trim();
  const p1  = document.getElementById('fg-pass1').value;
  const p2  = document.getElementById('fg-pass2').value;
  if (!otp || !p1 || !p2) { fgError('3', 'All fields are required.'); return; }
  const res = await api('staff_forgot_reset', { username: _fgUsername, otp, password: p1, password2: p2 }, 'POST');
  if (res.ok) {
    toast('Password reset! Sign in with your new password.', 'success');
    showForgotStep('creds');
    document.getElementById('l-user').value = _fgUsername;
  } else {
    fgError('3', res.msg || 'Reset failed.');
  }
}

// ── STAFF SELF-REGISTRATION WIZARD (full screen) ─────────────
const REG_MAX_FILE_MB = 2;
