function rgErr(n, msg) { const e = $rg('rg-err-' + n); if (!e) return; e.textContent = msg || ''; e.classList.toggle('d-none', !msg); }
function rgIdvErr(msg) { const e = $rg('rg-idv-err'); if (!e) return; e.textContent = msg || ''; e.classList.toggle('d-none', !msg); }
function rgVMsg(m) { const e = $rg('rg-v-msg'); if (e) e.textContent = m; }

function rgShow(step) {
  ['card', 'check', 'exists', 'form', 'otp', 'idv', 'review', 'done'].forEach(s => $rg('rg-p-' + s)?.classList.toggle('d-none', s !== step));
  const n = RG_STEPS[step] || 1;
  document.querySelectorAll('#rg-overlay .reg-w-step-dot').forEach(d => { const i = +d.dataset.s; d.classList.toggle('active', i === n); d.classList.toggle('done', i < n); });
  const t = RG_TITLES[step] || RG_TITLES.card;
  $rg('rg-title').textContent = t[0]; $rg('rg-sub').textContent = t[1];
  if (step !== 'idv') rgCamStop();
  $rg('rg-overlay').scrollTop = 0;
}

function rgReset() {
  rgCamStop();
  Object.assign(RG, { card: { no: '', code: '' }, info: null, cv: null, busy: false, nonce: '', idDesc: null, idBlob: null, selfieBlob: null });
  ['rg-no', 'rg-code', 'rg-user', 'rg-email', 'rg-pass', 'rg-phone', 'rg-gender', 'rg-dob', 'rg-addr', 'rg-ecn', 'rg-ecp', 'rg-nok', 'rg-insp', 'rg-insn', 'rg-otp']
    .forEach(id => { const e = $rg(id); if (e) e.value = ''; });
  const cv = $rg('rg-cv'); if (cv) cv.value = '';
  rgCvPaint(); rgChips();
  const sm = $rg('rg-scan-msg'); if (sm) sm.textContent = '';
  [1, 2, 3].forEach(n => rgErr(n, ''));
  rgIdvReset();
}

function openRegWizard() {
  rgBuild(); rgReset();
  $rg('rg-overlay').classList.remove('d-none');
  document.body.style.overflow = 'hidden';
  rgShow('card');
}

// ── Step 1: read the card ──
function rgChips() {
  const a = $rg('rg-chip-no'), b = $rg('rg-chip-code'); if (!a || !b) return;
  a.className = 'hr-chip2 ' + (RG.card.no ? 'g' : 'w');
  a.textContent = RG.card.no ? 'Card number: ✓ ' + RG.card.no : 'Card number: not read yet';
  b.className = 'hr-chip2 ' + (RG.card.code ? 'g' : 'w');
  b.textContent = RG.card.code ? 'Security code: ✓ read' : 'Security code: not read yet';
  if (RG.card.no) $rg('rg-no').value = RG.card.no;
  if (RG.card.code) $rg('rg-code').value = RG.card.code;
}
async function rgCardScan(files) {
  if (RG.busy || !files || !files.length) return;
  rgErr(1, ''); RG.busy = true;
  const msg = $rg('rg-scan-msg');
  try {
    msg.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Loading reader…';
    await loadScriptOnce('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');
    let n = 0;
    for (const f of files) {
      n++; if (!f.type.startsWith('image/')) continue;
      msg.innerHTML = `<span class="spinner-border spinner-border-sm me-2"></span>Reading photo ${n} of ${files.length}…`;
      const r = cvParse(await cvOcrFile(f));
      if (r.no) RG.card.no = r.no;
      if (r.code) RG.card.code = r.code;
      rgChips();
    }
    RG.busy = false;
    if (RG.card.no && RG.card.code) { msg.innerHTML = '<i class="fa fa-wand-magic-sparkles me-1 text-accent"></i>Card read. Checking…'; await rgCardSubmit(); }
    else msg.textContent = !RG.card.no && !RG.card.code ? 'Could not read the card. Retake in better light, or type the details below.'
      : !RG.card.code ? 'Now upload the BACK of the card (security code).' : 'Now upload the FRONT of the card (card number).';
  } catch (e) { msg.textContent = e.message || 'Could not read the photo. Try again or type the details below.'; }
  $rg('rg-card-files').value = ''; RG.busy = false;
}
async function rgCardSubmit() {
  const no = $rg('rg-no').value.trim().toUpperCase(), code = $rg('rg-code').value.trim();
  rgErr(1, '');
  if (!no || !code) return rgErr(1, 'We still need both the card number and the security code.');
  rgShow('check'); $rg('rg-check-msg').textContent = 'Checking your card against our records…';
  await rgSleep(900);
  const r = await api('staff_register_card', { card_no: no, code }, 'POST');
  if (r.ok) {
    RG.info = r;
    $rg('rg-ok-msg').innerHTML = `<i class="fa fa-circle-check me-1"></i>Card verified. Welcome, <b>${esc((r.name || '').split(' ')[0])}</b>! We found your appointment.`;
    $rg('rg-chips').innerHTML = `<span class="hr-chip2 g">${esc(r.name)}</span><span class="hr-chip2">${esc(r.role)}</span><span class="hr-chip2">${esc(r.business)} · ${esc(r.branch)}</span><span class="hr-chip2">ID ${esc(r.id_hint)}</span>`;
    rgShow('form');
  } else if (r.msg === 'already_registered') rgShow('exists');
  else { RG.card = { no: '', code: '' }; rgChips(); rgShow('card'); rgErr(1, r.msg || 'Card not recognised.'); }
}

// ── Step 2: details + CV ──
function rgCvPaint() {
  const d = $rg('rg-cv-drop'); if (!d) return;
  d.classList.toggle('ok', !!RG.cv);
  d.innerHTML = RG.cv
    ? `<i class="fa fa-file-circle-check text-success" style="font-size:1.6rem"></i><div class="fw-bold small mt-1">${esc(RG.cv.name)}</div><div class="small text-nx-muted">${(RG.cv.size / 1048576).toFixed(2)} MB · tap to change</div>`
    : '<div style="font-size:1.8rem">📄</div><div class="fw-bold small">Tap to upload your CV</div><div class="small text-nx-muted">PDF, DOCX, DOC or TXT · max 4MB</div>';
}
function rgCvPicked(inp) {
  const f = inp.files[0]; rgErr(2, ''); if (!f) return;
  const ext = (f.name.split('.').pop() || '').toLowerCase();
  if (!['pdf', 'doc', 'docx', 'txt'].includes(ext)) { rgErr(2, 'Use a PDF, DOCX, DOC or TXT file.'); inp.value = ''; return; }
  if (f.size > 4 * 1048576) { rgErr(2, 'CV too large (max 4MB).'); inp.value = ''; return; }
  RG.cv = f; rgCvPaint();
}
async function rgSendOtp() {
  const g = id => $rg(id).value.trim();
  rgErr(2, '');
  if (!g('rg-user') || !g('rg-email') || !$rg('rg-pass').value || !g('rg-phone')) return rgErr(2, 'Please fill in username, email, password and phone.');
  if ($rg('rg-pass').value.length < 8) return rgErr(2, 'Password must be at least 8 characters.');
  if (!RG.cv) return rgErr(2, 'Please upload your CV to continue.');
  const fd = new FormData();
  fd.append('username', g('rg-user')); fd.append('email', g('rg-email')); fd.append('password', $rg('rg-pass').value); fd.append('phone', g('rg-phone'));
  fd.append('gender', g('rg-gender')); fd.append('date_of_birth', g('rg-dob')); fd.append('address', g('rg-addr'));
  fd.append('emergency_contact_name', g('rg-ecn')); fd.append('emergency_contact_phone', g('rg-ecp')); fd.append('next_of_kin_relationship', g('rg-nok'));
  fd.append('insurance_provider', g('rg-insp')); fd.append('insurance_number', g('rg-insn'));
  fd.append('cv', RG.cv);
  const btn = $rg('rg-send'); btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Sending…';
  let d;
  try { d = await (await fetch(SELF + '?action=staff_register_send_otp', { method: 'POST', body: fd })).json(); }
  catch (e) { btn.disabled = false; btn.innerHTML = 'Send verification code →'; return rgErr(2, 'Request failed: ' + e.message); }
  btn.disabled = false; btn.innerHTML = 'Send verification code →';
  if (d.ok) { $rg('rg-otp-note').textContent = 'We sent a 6-digit code to ' + g('rg-email') + '. Enter it below.'; rgShow('otp'); toast('Verification code sent to your email', 'success'); }
  else rgErr(2, d.msg || 'Could not proceed.');
}

// ── Step 3: email code ──
async function rgConfirmOtp() {
  const otp = $rg('rg-otp').value.trim(); rgErr(3, '');
  if (!otp) return rgErr(3, 'Enter the code.');
  const r = await api('staff_register_confirm_otp', { otp }, 'POST');
  if (r.ok) { toast('Email verified', 'success'); rgShow('idv'); rgIdvReset(); vfLoadLibs().catch(() => {}); }
  else rgErr(3, r.msg || 'Verification failed.');
}

// ── Step 4: identity (ID scan → live selfie → match) ──
async function rgPost(act, fields) {
  const fd = new FormData(); for (const k in fields) fd.append(k, fields[k]);
  const r = await fetch(IDV_URL + '?action=' + act, { method: 'POST', body: fd, credentials: 'same-origin' });
  try { return await r.json(); } catch (e) { throw new Error('The verification service did not respond. Check that identity_verify.php is uploaded next to staff_portal.php.'); }
}
function rgVShow(s) {
  ['id', 'check', 'face', 'match', 'fail'].forEach(x => $rg('rg-v-' + x)?.classList.toggle('d-none', x !== s));
  const n = { id: 1, check: 1, face: 2, match: 3, fail: 3 }[s];
  [1, 2, 3].forEach(i => { const d = $rg('rg-vd' + i); if (d) { d.classList.toggle('active', i === n); d.classList.toggle('done', i < n); } });
}
function rgIdvReset() {
  rgCamStop(); RG.busy = false; RG.idDesc = null; RG.nonce = '';
  const f = $rg('rg-id-file'); if (f) f.value = '';
  const img = $rg('rg-id-prev'); if (img) { img.classList.add('d-none'); img.removeAttribute('src'); }
  const go = $rg('rg-id-go'); if (go) go.disabled = true;
  const cb = $rg('rg-consent'); if (cb) cb.checked = false;
  const bar = $rg('rg-live-fill'); if (bar) bar.style.width = '0';
  rgIdvErr(''); rgVShow('id');
}
function rgIdPicked(inp) {
  const f = inp.files[0], img = $rg('rg-id-prev'), go = $rg('rg-id-go'); rgIdvErr('');
  if (img.dataset.url) { URL.revokeObjectURL(img.dataset.url); img.dataset.url = ''; }
  if (!f) { img.classList.add('d-none'); go.disabled = true; return; }
  if (!f.type.startsWith('image/')) { rgIdvErr('Please choose a photo (JPG or PNG).'); inp.value = ''; go.disabled = true; return; }
  img.dataset.url = URL.createObjectURL(f); img.src = img.dataset.url; img.classList.remove('d-none'); go.disabled = false;
}
function rgVFail(msg, res) {
  res = res || {}; RG.busy = false; rgCamStop();
  if (res.review) { rgReviewOpen(); return; }
  if (res.restart) { toast(msg, 'error'); rgReset(); rgShow('card'); return; }
  if (res.locked) { $rg('rg-fail-msg').textContent = msg; $rg('rg-fail-btns').classList.add('d-none'); rgVShow('fail'); return; }
  if (res.redo_id || res.where === 'id') { rgIdvReset(); rgIdvErr(msg); return; }
  $rg('rg-fail-msg').textContent = msg; $rg('rg-fail-btns').classList.remove('d-none'); rgVShow('fail');
}

async function rgIdScan() {
  if (RG.busy) return; rgIdvErr('');
  const file = $rg('rg-id-file').files[0];
  if (!file) return rgIdvErr('Take or choose a photo of your ID first.');
  if (!$rg('rg-consent').checked) return rgIdvErr('Please tick the consent box to continue.');
  RG.busy = true; rgVShow('check');
  try {
    rgVMsg('Loading verification tools (the first time may take a moment)…');
    await vfLoadLibs();
    const canvas = await vfFileToCanvas(file, 1800);
    rgVMsg('Reading the details on your ID…');
    const ocr = await Tesseract.recognize(canvas, 'eng');
    const text = (ocr && ocr.data && ocr.data.text) || '';
    rgVMsg('Checking the ID against your appointment record…');
    const res = await rgPost('id', { ocr_text: text.slice(0, 7000) });
    if (!res.ok) { RG.busy = false; return rgVFail(res.msg, res); }
    rgVMsg('Looking for the portrait on your ID…');
    const faces = await faceapi.detectAllFaces(canvas, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.3 })).withFaceLandmarks().withFaceDescriptors();
    if (!faces.length) throw new Error('We could not find the portrait on this ID. Photograph the front of the ID, flat and well lit.');
    faces.sort((a, b) => b.detection.box.area - a.detection.box.area);
    RG.nonce = res.nonce; RG.idDesc = Array.from(faces[0].descriptor);
    $rg('rg-id-file').value = '';
    RG.busy = false; rgVShow('face'); await rgCamStart();
  } catch (e) {
    RG.busy = false; rgVShow('id'); rgIdvErr(e.message || 'Something went wrong. Try again.');
    try { const fr = await rgPost('fail', { where: 'id' }); if (fr && fr.review) rgReviewOpen(); } catch (x) {}
  }
}

async function rgCamStart() {
  rgIdvErr(''); rgCamStop();
  const v = $rg('rg-video'), go = $rg('rg-live-go'); go.disabled = true;
  try {
    RG.stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false });
    v.srcObject = RG.stream; await v.play().catch(() => {}); go.disabled = false;
  } catch (e) { rgIdvErr('Could not open the camera. Allow camera access in your browser, then tap "Retry camera".'); }
}
function rgCamStop() {
  if (RG.stream) { RG.stream.getTracks().forEach(t => t.stop()); RG.stream = null; }
  const v = $rg('rg-video'); if (v) v.srcObject = null;
}
function rgYaw(lm) { const p = lm.positions, w = p[16].x - p[0].x; return w > 1 ? (p[30].x - p[0].x) / w : 0.5; }

async function rgLiveStart() {
  if (RG.busy) return;
  const v = $rg('rg-video'), btn = $rg('rg-live-go'), instr = $rg('rg-live-instr'), bar = $rg('rg-live-fill');
  if (!RG.stream || !v.videoWidth) return rgIdvErr('The camera is not ready yet. Give it a second, or tap Retry camera.');
  RG.busy = true; btn.disabled = true; rgIdvErr(''); bar.style.width = '0'; rgGrabSelfie(v);
  const sel = [];
  try {
    await vfLoadLibs();
    const t0 = performance.now(); let frames = 0, a = false, b = false;
    instr.innerHTML = 'Slowly turn your head to the <b>left</b>, then to the <b>right</b>';
    while (performance.now() - t0 < 30000 && !(a && b)) {
      const det = await faceapi.detectSingleFace(v, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.6 })).withFaceLandmarks();
      await rgSleep(30);
      if (!det) { instr.innerHTML = 'We lost your face. Move into the oval and keep going.'; continue; }
      frames++;
      const yaw = rgYaw(det.landmarks);
      if (yaw > 0.62) a = true;
      if (yaw < 0.38) b = true;
      bar.style.width = ((a ? 40 : 0) + (b ? 40 : 0)) + '%';
    }
    if (!(a && b)) throw new Error('We did not see you turn your head both ways. Please try again.');
    instr.innerHTML = 'Now look <b>straight</b> at the camera and hold still';
    let guard = 0;
    while (sel.length < 3 && guard++ < 80) {
      const det = await faceapi.detectSingleFace(v, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.7 })).withFaceLandmarks().withFaceDescriptor();
      if (!det) { await rgSleep(120); continue; }
      const yaw = rgYaw(det.landmarks);
      if (yaw < 0.42 || yaw > 0.58 || det.detection.box.width < v.videoWidth * 0.18) { await rgSleep(120); continue; }
      sel.push(Array.from(det.descriptor));
      bar.style.width = (80 + sel.length * 6.6) + '%';
      await rgSleep(350);
    }
    if (sel.length < 3) throw new Error('We could not get a clear straight-on photo of your face. Try again in better light.');
    const live = { a, b, frames, ms: Math.round(performance.now() - t0) };
    rgCamStop(); rgVShow('match');
    const res = await rgPost('face', { nonce: RG.nonce, d: JSON.stringify({ id: RG.idDesc, selfies: sel }), live: JSON.stringify(live) });
    RG.busy = false;
    if (res.ok) { RG.idDesc = null; sel.length = 0; toast('Identity verified', 'success'); rgFinish(); }
    else rgVFail(res.msg || 'Verification failed.', res);
  } catch (e) {
    let fr = null; try { fr = await rgPost('fail', { where: 'face' }); } catch (x) {}
    rgVFail(e.message || 'Something went wrong. Please try again.', fr && fr.review ? { review: true } : {});
  }
}

// ── Step 5: create the account + write the letter ──
async function rgFinish() {
  rgShow('check');
  $rg('rg-check-msg').textContent = 'Identity confirmed. Creating your account and writing your appointment letter…';
  const r = await api('staff_register_finish', {}, 'POST');
  if (r.ok) { $rg('rg-done-msg').textContent = r.msg || 'Your account is ready.'; rgShow('done'); }
  else if (r.need_idv) { rgShow('idv'); rgIdvReset(); rgIdvErr(r.msg || 'Please verify your identity again.'); }
  else { rgShow('form'); rgErr(2, r.msg || 'Registration failed. Please try again.'); }
}

function openRegWizard_old() {
  document.getElementById('reg-wizard-overlay').classList.remove('d-none');
  document.body.style.overflow = 'hidden';
  ['reg-fullname','reg-natid','reg-username','reg-email','reg-password','reg-phone','reg-age','reg-ins-provider','reg-ins-number','reg-gender','reg-dob','reg-address','reg-ec-name','reg-ec-phone','reg-nok-rel','reg-otp'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  _regFiles = { photo: null, cv: null, iddoc: null };
  ['photo','cv','iddoc'].forEach(f => {
    const inp = document.getElementById('reg-' + f); if (inp) inp.value = '';
    const st  = document.getElementById('reg-' + f + '-status'); if (st) { st.textContent = ''; st.className = 'reg-upload-status'; }
  });
  showRegStep('branch');
}
function closeRegWizard() {
  document.getElementById('reg-wizard-overlay').classList.add('d-none');
  document.body.style.overflow = '';
}

function showRegStep(step) {
  ['branch','checking','notfound','exists','form','otp','done'].forEach(s => document.getElementById('reg-w-' + s)?.classList.toggle('d-none', s !== step));
  const num = REG_STEP_NUMBER[step] || 1;
  document.querySelectorAll('.reg-w-step-dot').forEach(dot => {
    const dStep = parseInt(dot.dataset.step, 10);
    dot.classList.toggle('active', dStep === num);
    dot.classList.toggle('done', dStep < num);
  });
  const titles = {
    branch:   ['Welcome to the Registration Portal', "Let's get you set up — it only takes a couple of minutes."],
    checking: ['Checking Your Details', 'Just a moment while we verify your record.'],
    notfound: ["We Couldn't Find You", 'Please check your details and try again.'],
    exists:   ['Already Registered', "Looks like you've already signed up."],
    form:     ["You're Almost There, Staff!", "Just a few more details and you'll be ready to go."],
    otp:      ['One Last Step', 'Verify your email to activate your account.'],
    done:     ['Welcome Aboard!', 'Your account is ready.'],
  };
  const t = titles[step] || titles.branch;
  const titleEl = document.getElementById('reg-w-title');
  const subEl   = document.getElementById('reg-w-subtitle');
  if (titleEl) titleEl.textContent = t[0];
  if (subEl)   subEl.textContent   = t[1];
}
function regError(n, msg) { const el = document.getElementById('reg-err-' + n); if (el) { el.textContent = msg; el.classList.remove('d-none'); } }

function handleRegFileSelect(input, key) {
  const statusEl = document.getElementById('reg-' + key + '-status');
  const file = input.files[0];
  if (!file) { _regFiles[key] = null; if (statusEl) { statusEl.textContent = ''; statusEl.className = 'reg-upload-status'; } return; }
  const sizeMB = file.size / (1024 * 1024);
  if (sizeMB > REG_MAX_FILE_MB) {
    _regFiles[key] = null;
    input.value = '';
    if (statusEl) { statusEl.textContent = `File too large (${sizeMB.toFixed(1)}MB) — max ${REG_MAX_FILE_MB}MB.`; statusEl.className = 'reg-upload-status err'; }
    return;
  }
  _regFiles[key] = file;
  if (statusEl) { statusEl.innerHTML = `<i class="fa fa-check-circle me-1"></i>Uploaded successfully (${sizeMB.toFixed(2)}MB)`; statusEl.className = 'reg-upload-status ok'; }
}

async function doRegCheck() {
  const full_name  = document.getElementById('reg-fullname').value.trim();
  const national_id= document.getElementById('reg-natid').value.trim();
  if (!full_name || !national_id) { regError(1, 'Enter your full name and ID number.'); return; }
  showRegStep('checking');
  await new Promise(r => setTimeout(r, 1600)); // "checking our database, give us a moment"
  const res = await api('staff_register_check', { full_name, national_id }, 'POST');
  if (res.ok) {
    document.getElementById('reg-confirmed-msg').textContent = 'Confirmed — you are on ' + res.business_name + "'s (" + res.branch_name + ") appointed staff list. Please complete your details below.";
    showRegStep('form');
  } else if (res.msg === 'already_registered') {
    showRegStep('exists');
  } else {
    showRegStep('notfound');
  }
}

async function doRegSendOtp() {
  const username = document.getElementById('reg-username').value.trim();
  const email    = document.getElementById('reg-email').value.trim();
  const password = document.getElementById('reg-password').value;
  const phone    = document.getElementById('reg-phone').value.trim();
  if (!username || !email || !password || !phone) { regError(2, 'Please complete all required fields.'); return; }

  const fd = new FormData();
  fd.append('csrf', CSRF);
  fd.append('username', username);
  fd.append('email', email);
  fd.append('password', password);
  fd.append('phone', phone);
  fd.append('age', document.getElementById('reg-age').value || '');
  fd.append('insurance_provider', document.getElementById('reg-ins-provider').value.trim());
  fd.append('insurance_number', document.getElementById('reg-ins-number').value.trim());
  fd.append('gender', document.getElementById('reg-gender').value);
  fd.append('date_of_birth', document.getElementById('reg-dob').value);
  fd.append('address', document.getElementById('reg-address').value.trim());
  fd.append('emergency_contact_name', document.getElementById('reg-ec-name').value.trim());
  fd.append('emergency_contact_phone', document.getElementById('reg-ec-phone').value.trim());
  fd.append('next_of_kin_relationship', document.getElementById('reg-nok-rel').value.trim());
  if (_regFiles.photo) fd.append('photo', _regFiles.photo);
  if (_regFiles.cv)    fd.append('cv', _regFiles.cv);
  if (_regFiles.iddoc) fd.append('id_doc', _regFiles.iddoc);

  const btn = document.querySelector('#reg-w-form button.w-100');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Submitting…'; }

  let data;
  try {
    const res = await fetch(SELF + '?action=staff_register_send_otp', { method: 'POST', body: fd });
    data = await res.json();
  } catch (e) {
    if (btn) { btn.disabled = false; btn.innerHTML = 'Continue →'; }
    regError(2, 'Request failed: ' + e.message);
    return;
  }
  if (btn) { btn.disabled = false; btn.innerHTML = 'Continue →'; }

  if (data.ok) { showRegStep('otp'); toast('Verification code sent to your email', 'success'); }
  else regError(2, data.msg || 'Could not proceed.');
}

async function doRegConfirm() {
  const otp = document.getElementById('reg-otp').value.trim();
  if (!otp) { regError(3, 'Enter the code.'); return; }
  const res = await api('staff_register_confirm_otp', { otp }, 'POST');
  if (res.ok) {
    document.getElementById('reg-done-msg').textContent = res.msg;
    showRegStep('done');
  } else regError(3, res.msg || 'Verification failed.');
}

// ── THEME TOGGLE ─────────────────────────────────────────────
function toggleTheme() {
  const html = document.documentElement;
  const current = html.getAttribute('data-theme') || 'dark';
  const next = current === 'dark' ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  localStorage.setItem('nx-theme', next);
  updateThemeIcon(next);
}
function updateThemeIcon(theme) {
  const icon = document.getElementById('theme-icon');
  if (!icon) return;
  icon.className = theme === 'dark' ? 'fa fa-sun' : 'fa fa-moon';
}
// Set icon on load
document.addEventListener('DOMContentLoaded', () => {
  updateThemeIcon(localStorage.getItem('nx-theme') || 'light');
});

// ── NAVIGATION ───────────────────────────────────────────────
const PAGE_TITLES = {
  dashboard:'Dashboard', pos:'Point of Sale', sales:'Sales History',
  inventory:'Stock Levels', transfers:'Stock Transfers', customers:'Customers',
  purchases:'Purchase Orders', suppliers:'Suppliers', reports:'Reports',
  expenses:'Expenses', users:'Staff Users', products:'Products',
  categories:'Categories & Units', etims:'eTIMS / KRA Settings', salary:'HR & Payroll', finance:'My Finance', messages:'Messages', home:'Home'
};
const PAGE_ACCESS = {
  pos:       [R.OWNER, R.MANAGER, R.CASHIER],
  reports:   [R.OWNER, R.MANAGER],
  expenses:  [R.OWNER, R.MANAGER],
  users:     [R.OWNER],
  transfers: [R.OWNER, R.MANAGER, R.STOREKEEPER],
  purchases: [R.OWNER, R.MANAGER, R.STOREKEEPER, R.SUPPLIER],
  suppliers: [R.OWNER, R.MANAGER, R.STOREKEEPER, R.SUPPLIER],
  products:  [R.OWNER, R.MANAGER, R.STOREKEEPER],
  categories:[R.OWNER, R.MANAGER, R.STOREKEEPER],
  salary:    [R.OWNER, R.MANAGER],
};

const LOADER_HOME_MS = 4000; // how long the bouncing logo shows on Home (ms). Change to taste
let _navTok = 0, _ldTimers = [];
function showLoader() {
  const l = document.getElementById('nx-loader'); if (!l) return;
  _ldTimers.forEach(clearTimeout); _ldTimers = [];
  const st = document.getElementById('nt-status');
  const steps = ['Please wait while we perform security checks…', 'Redirecting you in a moment…', 'You are almost there…'];
  st.textContent = steps[0];
  steps.slice(1).forEach((s, i) => _ldTimers.push(setTimeout(() => { st.textContent = s; }, (i + 1) * 800)));
  l.classList.remove('d-none');
}
function hideLoader() {
  _ldTimers.forEach(clearTimeout); _ldTimers = [];
  document.getElementById('nx-loader')?.classList.add('d-none');
}
async function navigate(page) {
  if (!CU) return;
  const tok = ++_navTok, t0 = Date.now();
  showLoader();
  try { await navigateNow(page); } catch (e) { console.error(e); }
  setTimeout(() => { if (tok === _navTok) hideLoader(); }, Math.max(0, (page === 'home' ? LOADER_HOME_MS : 1700) - (Date.now() - t0)));
}
async function navigateNow(page) {
  if (!CU) return;
  if (PAGE_ACCESS[page] && !PAGE_ACCESS[page].includes(CU.role_id)) {
    toast('You do not have access to this section.', 'error'); return;
  }
  if (!['salary', 'home'].includes(page) && !(page === 'pos' && CU.role_id === R.CASHIER)) showChrome();
  if (page === 'home') hideChrome();
  document.querySelectorAll('.nx-nav-link').forEach(b => b.classList.toggle('active', b.dataset.page === page));
  document.getElementById('page-title').textContent = PAGE_TITLES[page] || page;
  closeSidebar();
  const el = document.getElementById('nx-content');
  loading(el);
  const renders = {
    dashboard, pos: renderPOS, sales: renderSales, inventory: renderInventory,
    transfers: renderTransfers, customers: renderCustomers, purchases: renderPurchases,
    suppliers: renderSuppliers, reports: renderReports, expenses: renderExpenses,
    users: renderUsers, products: renderProducts, categories: renderCategories,
    etims: renderEtims, salary: renderSalary, finance: renderFinance, messages: renderMessages, home: renderHome,
  };
  await (renders[page] || (() => el.innerHTML = '<p class="text-danger p-4">Page not found.</p>'))(el);
}

function buildNav() {
  if (!CU) return;
  const hide = (id, show) => { const el = document.getElementById(id); if (el) el.style.display = show ? '' : 'none'; };
  hide('nav-sales-sec',     can(R.OWNER, R.MANAGER, R.CASHIER));
  hide('nav-inventory-sec', true); // all roles see inventory
  hide('nav-products-sec',  can(R.OWNER, R.MANAGER, R.STOREKEEPER));
  hide('nav-purchase-sec',  can(R.OWNER, R.MANAGER, R.STOREKEEPER, R.SUPPLIER));
  hide('nav-crm-sec',       can(R.OWNER, R.MANAGER, R.CASHIER));
  hide('nav-reports-sec',   can(R.OWNER, R.MANAGER));
  hide('nav-admin-sec',     can(R.OWNER));
  hide('nav-salary-sec',    can(R.OWNER, R.MANAGER));
}

