function prodImgPreview() {
  const url = document.getElementById('prod-image-url').value.trim();
  const img = document.getElementById('prod-img-preview');
  if (url) { img.src = url; img.classList.remove('d-none'); }
  else img.classList.add('d-none');
}

async function handleProductImageUpload(e) {
  const file = e.target.files[0];
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) { toast('File too large (max 5MB)', 'error'); return; }
  toast('Uploading image…', 'info');
  const fd = new FormData();
  fd.append('csrf', CSRF);
  fd.append('image', file);
  try {
    const res = await fetch(SELF + '?action=product_image_upload', { method: 'POST', body: fd });
    const data = await res.json();
    if (data.ok) {
      document.getElementById('prod-image-url').value = data.url;
      prodImgPreview();
      toast('Image uploaded', 'success');
    } else {
      toast(data.msg || 'Upload failed.', 'error');
    }
  } catch (err) {
    toast('Upload failed: ' + err.message, 'error');
  }
  e.target.value = '';
}

async function suggestProductImage() {
  const name = document.getElementById('prod-name').value.trim();
  if (!name) { toast('Enter a product name first', 'error'); return; }
  toast('Searching the web for an image…', 'info');
  const d = await api('image_search', { q: name });
  if (d.ok && d.results && d.results.length) {
    document.getElementById('prod-image-url').value = d.results[0].full || d.results[0].thumb;
    prodImgPreview();
    toast('Image found — check it looks right before saving', 'success');
  } else {
    toast('No image found for that name. Try a simpler search term.', 'error');
  }
}

async function saveProduct() {
  const name = document.getElementById('prod-name').value.trim();
  const buy  = parseFloat(document.getElementById('prod-buy').value);
  const sell = parseFloat(document.getElementById('prod-sell').value);
  if (!name)      { toast('Product name required', 'error'); return; }
  if (!buy||!sell){ toast('Enter buying and selling prices', 'error'); return; }
  let imageUrl = document.getElementById('prod-image-url').value.trim();
  if (!imageUrl) {
    const found = await searchProductImage(name);
    if (found) imageUrl = found;
  }
  const res = await api('product_save', {
    id: document.getElementById('prod-id').value, name,
    sku: document.getElementById('prod-sku').value,
    barcode: document.getElementById('prod-barcode').value,
    category_id: document.getElementById('prod-category').value,
    unit: document.getElementById('prod-unit').value,
    buying_price: buy, selling_price: sell,
    reorder_level: document.getElementById('prod-reorder').value,
    is_active: document.getElementById('prod-active').value,
    image_url: imageUrl,
  }, 'POST');
  if (res.ok) { toast('Product saved', 'success'); closeModal('modal-product'); loadProducts(); }
  else toast(res.msg || 'Failed.', 'error');
}

