function salTab(tab, btn) {
  document.querySelectorAll('#nx-content .nav-tabs .nav-link').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('sal-req-pane').classList.toggle('d-none', tab!=='req');
  document.getElementById('sal-disb-pane').classList.toggle('d-none', tab!=='disb');
}

async function decideSalaryRequest(id, decision) {
  const res = await api('salary_decide_request', { request_id: id, decision }, 'POST');
  if (res.ok) { toast('Request '+decision, 'success'); navigate('salary'); }
  else toast(res.msg || 'Failed.', 'error');
}

function openStaffPayrollModal() {
  document.getElementById('sp-existing').value = '';
  spPickExisting('');
  openModal('modal-staff-payroll');
}
function spPickExisting(userId) {
  document.getElementById('sp-new-fields').style.display = userId ? 'none' : '';
  const sel = document.getElementById('sp-existing');
  const opt = sel.selectedOptions[0];
  if (userId && opt) {
    document.getElementById('sp-idnum').value   = opt.dataset.idnum || '';
    document.getElementById('sp-phone').value   = opt.dataset.phone || '';
    document.getElementById('sp-bank').value    = opt.dataset.bank || '';
    document.getElementById('sp-bankacc').value = opt.dataset.bankacc || '';
    document.getElementById('sp-fixed-salary').value = opt.dataset.fixed || '';
  } else {
    ['sp-idnum','sp-phone','sp-bank','sp-bankacc','sp-fixed-salary'].forEach(id => document.getElementById(id).value = '');
  }
}

// ── QUICK ADD/EDIT SALARY (per-staff, lightweight) ────────────
let _qsCurrentUserId = null;

function openQuickSalaryModal(s) {
  _qsCurrentUserId = s.user_id;
  document.getElementById('qs-modal-title').textContent = 'Add/Edit Salary — ' + s.full_name;
  document.getElementById('qs-modal-footer').classList.add('d-none');
  document.getElementById('qs-modal-body').innerHTML = `
    <div class="d-flex flex-column align-items-center justify-content-center py-5">
      <div class="spinner-border text-warning mb-3"></div>
      <span class="text-nx-muted small">Please wait, preparing the salary form…</span>
    </div>`;
  openModal('modal-quick-salary');

  setTimeout(() => {
    document.getElementById('qs-modal-body').innerHTML = `
      <div class="mb-3"><label class="form-label">Staff Member</label><input type="text" class="form-control" value="${esc(s.full_name)}" readonly></div>
      <div class="row g-3">
        <div class="col-6"><label class="form-label">ID Number *</label><input type="text" id="qs-idnum" class="form-control" value="${esc(s.id_number||'')}"></div>
        <div class="col-6"><label class="form-label">Phone *</label><input type="text" id="qs-phone" class="form-control" value="${esc(s.phone||'')}"></div>
        <div class="col-6"><label class="form-label">Bank Name</label><input type="text" id="qs-bank" class="form-control" value="${esc(s.bank_name||'')}"></div>
        <div class="col-6"><label class="form-label">Bank Account No.</label><input type="text" id="qs-bankacc" class="form-control" value="${esc(s.bank_account||'')}"></div>
        <div class="col-4"><label class="form-label">Pay Type</label>
          <select id="qs-paytype" class="form-select"><option value="fixed" ${s.pay_type==='hourly'?'':'selected'}>Fixed</option><option value="hourly" ${s.pay_type==='hourly'?'selected':''}>Hourly</option></select></div>
        <div class="col-4"><label class="form-label">Hourly Rate</label><input type="number" id="qs-hourly" class="form-control" min="0" step="0.01" value="${s.hourly_rate||''}"></div>
        <div class="col-4"><label class="form-label">Pay Via</label>
          <select id="qs-paymethod" class="form-select">${['mpesa:M-Pesa','bank:Bank','paypal:PayPal','cash:Cash'].map(o=>{const [v,l]=o.split(':');return `<option value="${v}" ${(s.pay_method||'bank')===v?'selected':''}>${l}</option>`}).join('')}</select></div>
        <div class="col-12"><label class="form-label">Fixed Monthly Salary (KSh)</label><input type="number" id="qs-fixed-salary" class="form-control" min="0" step="0.01" value="${s.fixed_salary||''}" placeholder="Leave blank if variable"></div>
      </div>`;
    document.getElementById('qs-modal-footer').classList.remove('d-none');
  }, 600);
}

async function saveQuickSalary() {
  const res = await api('staff_payroll_save', {
    user_id: _qsCurrentUserId,
    id_number: document.getElementById('qs-idnum').value,
    phone: document.getElementById('qs-phone').value,
    bank_name: document.getElementById('qs-bank').value,
    bank_account: document.getElementById('qs-bankacc').value,
    fixed_salary: document.getElementById('qs-fixed-salary').value,
    pay_type: document.getElementById('qs-paytype').value,
    hourly_rate: document.getElementById('qs-hourly').value,
    pay_method: document.getElementById('qs-paymethod').value,
  }, 'POST');
  if (res.ok) { toast('Salary details saved', 'success'); closeModal('modal-quick-salary'); navigate('salary'); }
  else toast(res.msg || 'Failed.', 'error');
}

function fillAllFixedSalaries() {
  const inputs = document.querySelectorAll('.sal-req-amt');
  let count = 0;
  inputs.forEach(inp => {
    if (inp.dataset.fixed) { inp.value = parseFloat(inp.dataset.fixed).toFixed(2); count++; }
  });
  toast(count ? `Filled ${count} fixed salary amount(s)` : 'No fixed salaries set yet — use Add/Edit Salary first', count ? 'success' : 'info');
}

// ── APPOINTED STAFF ────────────────────────────────────────────
async function openApointStaffModal() {
  openModal('modal-apoint-staff');
  // reset to the waiting state every time it's opened
  const el = document.getElementById('apoint-staff-body');
  el.innerHTML = `
    <div class="d-flex flex-column align-items-center justify-content-center py-5">
      <div class="spinner-border text-warning mb-3"></div>
      <span class="text-nx-muted small">Please wait, preparing the appointment page for you…</span>
    </div>`;
  await loadApointStaffList();
}

async function loadApointStaffList() {
  const el = document.getElementById('apoint-staff-body');
  if (!el) { toast('Could not find the appointment panel on this page.', 'error'); return; }

  // Safety timeout — if the server never replies, show an error instead of
  // leaving the "please wait" spinner up forever.
  let finished = false;
  const timeoutId = setTimeout(() => {
    if (!finished) {
      el.innerHTML = `<div class="p-4 text-center">
        <p class="text-danger mb-2"><i class="fa fa-triangle-exclamation me-1"></i>This is taking too long — the server did not respond.</p>
        <button class="btn btn-sm btn-outline-secondary" onclick="loadApointStaffList()">Try Again</button>
      </div>`;
    }
  }, 12000);

  let d;
  try {
    d = await api('appointed_staff_list');
  } catch (e) {
    finished = true; clearTimeout(timeoutId);
    el.innerHTML = `<p class="text-danger p-4">Request failed: ${esc(e.message || 'network error')}</p>`;
    return;
  }
  finished = true; clearTimeout(timeoutId);

  if (!d || !d.ok) {
    el.innerHTML = `<p class="text-danger p-4">${esc((d && d.msg) || 'Failed to load appointment list.')}</p>`;
    return;
  }

  const rows = (d.list || []).map(a => `
    <tr>
      <td class="small fw-bold">${esc(a.full_name)}</td>
      <td class="small text-nx-muted">${esc(a.national_id)}</td>
      <td class="small">${esc(a.role_name)}</td>
      <td class="small">${esc(a.branch_name)}</td>
      <td><span class="badge ${a.status === 'registered' ? 'bg-success bg-opacity-25 text-success' : 'bg-warning bg-opacity-25 text-warning'}">${esc(a.status)}</span></td>
      <td class="text-nowrap">
        <button class="btn btn-sm btn-outline-warning" title="Print / download card" onclick="showAppointedCard(${a.id})"><i class="fa fa-id-card"></i></button>
        ${a.status === 'pending' ? `<button class="btn btn-sm btn-danger" onclick="removeApointStaff(${a.id})"><i class="fa fa-trash"></i></button>` : ''}
      </td>
    </tr>`).join('');

  el.innerHTML = `
    <div class="p-3">
      <div class="row g-2 mb-3">
        <div class="col-md-4"><input type="text" id="apt-fullname" class="form-control form-control-sm" placeholder="Full Name (exact)"></div>
        <div class="col-md-3"><input type="text" id="apt-natid" class="form-control form-control-sm" placeholder="National ID"></div>
        <div class="col-md-3">
          <select id="apt-role" class="form-select form-select-sm">
            <option value="3">Cashier</option>
            <option value="4">Storekeeper</option>
            <option value="5">Supplier Clerk</option>
            <option value="2">Branch Manager</option>
            <option value="11">Support (Marketplace)</option>
          </select>
        </div>
        <div class="col-md-3">
          <select id="apt-paytype" class="form-select form-select-sm" onchange="document.getElementById('apt-amount').placeholder = this.value==='hourly' ? 'Rate (KSh per hour)' : 'Monthly salary (KSh)'">
            <option value="fixed">Fixed monthly salary</option>
            <option value="hourly">Hourly rate</option>
          </select>
        </div>
        <div class="col-md-3"><input type="number" id="apt-amount" class="form-control form-control-sm" min="0" step="0.01" placeholder="Monthly salary (KSh)"></div>
        <div class="col-md-3">
          <select id="apt-paymethod" class="form-select form-select-sm">
            <option value="mpesa">Pay via M-Pesa</option>
            <option value="bank">Pay via Bank</option>
            <option value="paypal">Pay via PayPal</option>
            <option value="cash">Pay via Cash</option>
          </select>
        </div>
        <div class="col-md-3"><button class="btn btn-sm w-100 fw-bold" style="background:var(--nx-accent);color:#fff" onclick="addApointStaff()"><i class="fa fa-plus"></i> Add</button></div>
        <div class="col-12 d-flex align-items-center gap-3 flex-wrap mt-1">
          <div id="apt-photo-preview" style="width:80px;height:100px;border-radius:10px;border:1px dashed var(--nx-border);background:var(--nx-surface) center/cover no-repeat;display:flex;align-items:center;justify-content:center;color:var(--nx-muted);font-size:.65rem;text-align:center">No photo</div>
          <video id="apt-video" class="d-none" autoplay playsinline muted style="width:160px;height:120px;border-radius:10px;background:#000;object-fit:cover;transform:scaleX(-1)"></video>
          <div class="d-flex flex-column gap-1">
            <input type="file" id="apt-photo" accept="image/*" class="d-none" onchange="aptPhotoPicked(this)">
            <button type="button" class="btn btn-sm btn-outline-secondary" onclick="document.getElementById('apt-photo').click()"><i class="fa fa-upload me-1"></i>Upload photo</button>
            <button type="button" class="btn btn-sm btn-outline-secondary" onclick="aptOpenCamera()"><i class="fa fa-camera me-1"></i>Take photo</button>
            <button type="button" id="apt-snap" class="btn btn-sm btn-warning d-none" onclick="aptSnap()"><i class="fa fa-circle-dot me-1"></i>Capture</button>
          </div>
          <span class="small text-nx-muted">Photo is auto-cropped to fit the card.</span>
        </div>
      </div>
      <div class="alert alert-info py-2 small mb-3"><i class="fa fa-info-circle me-1"></i>Name and ID must match <strong>exactly</strong> what the staff member enters on the Register screen.</div>
      <div class="table-responsive"><table class="table table-sm mb-0">
        <thead><tr><th>Name</th><th>ID No.</th><th>Role</th><th>Branch</th><th>Status</th><th></th></tr></thead>
        <tbody>${rows || '<tr><td colspan="6" class="text-center text-nx-muted py-3">No one appointed yet.</td></tr>'}</tbody>
      </table></div>
    </div>`;
}

async function addApointStaff() {
  const full_name   = document.getElementById('apt-fullname').value.trim();
  const national_id = document.getElementById('apt-natid').value.trim();
  const role_id     = document.getElementById('apt-role').value;
  if (!full_name || !national_id) { toast('Enter full name and ID number', 'error'); return; }
  if (!_aptPhotoBlob) { toast('Upload or take a staff photo first', 'error'); return; }
  const photo = new File([_aptPhotoBlob], 'staff.jpg', { type: 'image/jpeg' });
  const res = await api('appointed_staff_add', { full_name, national_id, role_id, photo }, 'POST');
  if (res.ok) {
    toast('Staff appointed — card ready', 'success');
    _aptPhotoBlob = null; aptStopCamera();
    await loadApointStaffList();
    showAppointedCard(res.id);
  }
  else toast(res.msg || 'Failed.', 'error');
}

async function removeApointStaff(id) {
  if (!confirm('Remove this appointment?')) return;
  const res = await api('appointed_staff_remove', { id }, 'POST');
  if (res.ok) { toast('Removed', 'success'); loadApointStaffList(); }
  else toast(res.msg || 'Failed.', 'error');
}
// ── APPOINT STAFF: photo capture + smart crop ─────────────────
let _aptPhotoBlob = null, _aptStream = null;

// Crops to 4:5 (matches the card frame), biased to the top so faces aren't cut off
function aptCropToBlob(src, sw, sh) {
  const TW = 600, TH = 750, ratio = TW / TH;
  let cw = sw, ch = sw / ratio;
  if (ch > sh) { ch = sh; cw = sh * ratio; }
  const sx = (sw - cw) / 2, sy = Math.max(0, (sh - ch) * 0.25);
  const c = document.createElement('canvas'); c.width = TW; c.height = TH;
  c.getContext('2d').drawImage(src, sx, sy, cw, ch, 0, 0, TW, TH);
  return new Promise(r => c.toBlob(r, 'image/jpeg', 0.9));
}
function aptShowPreview() {
  const el = document.getElementById('apt-photo-preview');
  if (!el || !_aptPhotoBlob) return;
  el.textContent = '';
  el.style.backgroundImage = 'url("' + URL.createObjectURL(_aptPhotoBlob) + '")';
}
async function aptPhotoPicked(inp) {
  const f = inp.files[0]; if (!f) return;
  if (!f.type.startsWith('image/')) { toast('Choose an image file', 'error'); inp.value = ''; return; }
  try {
    const bmp = await createImageBitmap(f);
    _aptPhotoBlob = await aptCropToBlob(bmp, bmp.width, bmp.height);
    aptShowPreview();
  } catch (e) { toast('Could not read that image', 'error'); }
  inp.value = '';
}
async function aptOpenCamera() {
  try {
    _aptStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false });
  } catch (e) { toast('Could not open the camera. Allow camera access.', 'error'); return; }
  const v = document.getElementById('apt-video');
  v.srcObject = _aptStream; v.classList.remove('d-none');
  document.getElementById('apt-snap').classList.remove('d-none');
}
async function aptSnap() {
  const v = document.getElementById('apt-video');
  if (!v.videoWidth) { toast('Camera not ready yet', 'error'); return; }
  _aptPhotoBlob = await aptCropToBlob(v, v.videoWidth, v.videoHeight);
  aptStopCamera(); aptShowPreview();
}
function aptStopCamera() {
  if (_aptStream) { _aptStream.getTracks().forEach(t => t.stop()); _aptStream = null; }
  document.getElementById('apt-video')?.classList.add('d-none');
  document.getElementById('apt-snap')?.classList.add('d-none');
}

// Show the card for an appointed staff member (download / print)
async function showAppointedCard(id) {
  const r = await api('appointed_card_data', { id });
  if (!r.ok) { toast(r.msg || 'Could not load card.', 'error'); return; }
  cvErr('');
  document.getElementById('cv-close').classList.remove('d-none');
  await cvRender(r.card);
  document.getElementById('cv-email-status').textContent = 'Print on card stock and hand it to the staff member. Keep the back (security code) private.';
  cvShowPanel('preview');
  closeModal('modal-apoint-staff');
  setTimeout(() => openModal('modal-cardv'), 350);
}

async function saveStaffPayroll() {
  const existingId = document.getElementById('sp-existing').value;
  const payload = {
    user_id: existingId || 0,
    full_name: document.getElementById('sp-full-name').value,
    username: document.getElementById('sp-username').value,
    role_id: document.getElementById('sp-role').value,
    password: document.getElementById('sp-password').value,
    id_number: document.getElementById('sp-idnum').value,
    phone: document.getElementById('sp-phone').value,
    bank_name: document.getElementById('sp-bank').value,
    bank_account: document.getElementById('sp-bankacc').value,
    fixed_salary: document.getElementById('sp-fixed-salary').value,
  };
  const res = await api('staff_payroll_save', payload, 'POST');
  if (res.ok) { toast('Staff record saved', 'success'); closeModal('modal-staff-payroll'); navigate('salary'); }
  else toast(res.msg || 'Failed.', 'error');
}

let _salaryPendingAction = null;
async function startSalaryAllocationRequest() {
  const month = document.getElementById('sal-req-month').value;
  const items = [...document.querySelectorAll('.sal-req-amt')].map(inp => ({
    user_id: inp.dataset.userId, name: inp.dataset.name, id_number: inp.dataset.idnum, phone: inp.dataset.phone,
    amount: parseFloat(inp.value || 0),
  })).filter(i => i.amount > 0);
  if (!items.length) { toast('Enter at least one staff amount', 'error'); return; }
  const res = await api('salary_request_otp', { month, items: JSON.stringify(items) }, 'POST');
  if (res.ok) { toast(res.msg, 'info'); _salaryPendingAction = 'allocation'; openModal('modal-salary-otp'); }
  else toast(res.msg || 'Failed.', 'error');
}

async function startSalaryDisbursement(month) {
  const sel = document.getElementById('sal-disb-staff');
  const staff_user_id = sel.value;
  if (!staff_user_id) { toast('Select a staff member', 'error'); return; }
  const amount = parseFloat(document.getElementById('sal-disb-amount').value || 0);
  const method = document.getElementById('sal-disb-method').value;
  const note   = document.getElementById('sal-disb-note').value;
  if (amount <= 0) { toast('Enter a valid amount', 'error'); return; }
  const res = await api('salary_disburse_otp', { month, staff_user_id, amount, method, note }, 'POST');
  if (res.ok) { toast(res.msg, 'info'); _salaryPendingAction = 'disbursement'; openModal('modal-salary-otp'); }
  else toast(res.msg || 'Failed.', 'error');
}

async function confirmSalaryOtp() {
  const otp = document.getElementById('sal-otp-input').value.trim();
  const errEl = document.getElementById('sal-otp-err');
  if (!otp) { errEl.textContent = 'Enter the code.'; errEl.classList.remove('d-none'); return; }
  const res = await api('salary_confirm_otp', { otp }, 'POST');
  if (res.ok) { closeModal('modal-salary-otp'); toast(res.msg || 'Confirmed', 'success'); navigate('salary'); }
  else { errEl.textContent = res.msg || 'Incorrect code.'; errEl.classList.remove('d-none'); }
}

// ── CHROME (sidebar/topbar) helpers ───────────────────────────
function hideChrome() {
  ['nx-sidebar','nx-topbar'].forEach(id => { const e = document.getElementById(id); if (e) e.style.display = 'none'; });
  const m = document.getElementById('nx-main'); if (m) { m.style.marginLeft = '0'; m.style.paddingTop = '0'; }
}
function showChrome() {
  ['nx-sidebar','nx-topbar'].forEach(id => { const e = document.getElementById(id); if (e) e.style.display = ''; });
  const m = document.getElementById('nx-main'); if (m) { m.style.marginLeft = ''; m.style.paddingTop = ''; }
}

