function hrTab(tab, btn) {
  document.querySelectorAll('#hr-pills .nav-link').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('hr-pane-payroll').classList.toggle('d-none', tab !== 'payroll');
  document.getElementById('hr-pane-hourly').classList.toggle('d-none', tab !== 'hourly');
  if (tab === 'hourly') loadHourlyPayroll();
}

async function loadHourlyPayroll() {
  const el = document.getElementById('hr-pane-hourly');
  el.innerHTML = '<div class="d-flex justify-content-center py-5"><div class="spinner-border text-warning"></div></div>';
  const [s, l] = await Promise.all([api('hourly_summary'), api('payout_list')]);
  if (!s.ok) { el.innerHTML = '<p class="text-danger p-4">' + esc(s.msg || 'Failed to load.') + '</p>'; return; }
  const rows = (s.staff || []).map(x => {
    const hrs = parseFloat(x.unpaid_hours || 0), rate = parseFloat(x.hourly_rate || 0);
    return `<tr>
      <td class="fw-bold small">${esc(x.full_name)}${parseInt(x.on_shift) ? ' <span class="badge bg-success bg-opacity-25 text-success">On shift</span>' : ''}</td>
      <td class="small">${esc(PAY_METHODS[x.pay_method] || x.pay_method)}</td>
      <td class="small">${fmt(rate)}/hr</td>
      <td class="small">${hrs.toFixed(2)} h</td>
      <td class="fw-bold text-accent">${fmt(hrs * rate)}</td>
      <td><input type="datetime-local" id="hp-dt-${x.user_id}" class="form-control form-control-sm" style="min-width:200px"></td>
      <td><button class="btn btn-sm fw-bold" style="background:var(--nx-accent);color:#fff" ${hrs > 0 ? '' : 'disabled'} onclick="schedulePayout(${x.user_id})">Schedule</button></td>
    </tr>`;
  }).join('');
  const prow = ((l.ok && l.payouts) || []).map(p => {
    const c = p.status === 'released' ? 'success' : p.status === 'cancelled' ? 'danger' : 'warning';
    return `<tr>
      <td class="small fw-bold">${esc(p.full_name)}</td>
      <td class="small">${parseFloat(p.hours).toFixed(2)} h</td>
      <td class="fw-bold">${fmt(p.amount)}</td>
      <td class="small">${esc(PAY_METHODS[p.pay_method] || p.pay_method)}</td>
      <td class="small">${new Date(p.disburse_at.replace(' ', 'T')).toLocaleString('en-KE')}</td>
      <td><span class="badge bg-${c} bg-opacity-25 text-${c}">${esc(p.status)}</span></td>
      <td>${p.status === 'scheduled' ? `<button class="btn btn-sm btn-outline-danger" onclick="cancelPayout(${p.id})">Cancel</button>` : ''}</td>
    </tr>`;
  }).join('');
  el.innerHTML = `
    <div class="card mb-4">
      <div class="card-header">Unpaid hours &amp; scheduling</div>
      <div class="card-body pb-2"><div class="alert alert-info py-2 small mb-3"><i class="fa fa-info-circle me-1"></i>Pick the date and time funds should be released. The staff member is emailed and gets a portal notification right away.</div></div>
      <div class="table-responsive"><table class="table table-sm mb-0">
        <thead><tr><th>Staff</th><th>Pay via</th><th>Rate</th><th>Unpaid hours</th><th>Amount due</th><th>Disburse on</th><th></th></tr></thead>
        <tbody>${rows || '<tr><td colspan="7" class="text-center text-nx-muted py-4">No hourly staff yet. Set Pay Type to Hourly when appointing.</td></tr>'}</tbody>
      </table></div>
    </div>
    <div class="card">
      <div class="card-header">Scheduled &amp; past payouts</div>
      <div class="table-responsive"><table class="table table-sm mb-0">
        <thead><tr><th>Staff</th><th>Hours</th><th>Amount</th><th>Method</th><th>Disburse on</th><th>Status</th><th></th></tr></thead>
        <tbody>${prow || '<tr><td colspan="7" class="text-center text-nx-muted py-4">Nothing scheduled yet</td></tr>'}</tbody>
      </table></div>
    </div>`;
}

async function schedulePayout(uid) {
  const dt = document.getElementById('hp-dt-' + uid)?.value;
  if (!dt) { toast('Pick the disbursement date and time', 'error'); return; }
  if (!confirm('Schedule this payout and notify the staff member?')) return;
  const res = await api('payout_schedule', { staff_user_id: uid, disburse_at: dt }, 'POST');
  if (res.ok) { toast(res.msg, 'success'); loadHourlyPayroll(); }
  else toast(res.msg || 'Failed.', 'error');
}
async function cancelPayout(id) {
  if (!confirm('Cancel this scheduled payout? The hours return to unpaid.')) return;
  const res = await api('payout_cancel', { id }, 'POST');
  if (res.ok) { toast('Payout cancelled', 'success'); loadHourlyPayroll(); }
  else toast(res.msg || 'Failed.', 'error');
}

