async function renderFinance(el) {
  const d = await api('finance_me');
  if (!d.ok) { el.innerHTML = '<p class="text-danger p-4">Failed to load your finances.</p>'; return; }
  const p = d.payroll || {}, f = d.profile || {};
  const hourly = p.pay_type === 'hourly';
  const rate = parseFloat(p.hourly_rate || 0);
  const est = (d.unpaid_hours || 0) * rate;
  const open = d.open_shift;
  const kpi = (l, v, c) => `<div class="col-6 col-lg-3"><div class="stat-card" style="--card-accent:${c}"><div class="stat-label">${l}</div><div class="stat-value" style="font-size:1.4rem">${v}</div></div></div>`;
  const logRows = (d.logs || []).map(x => `<tr>
      <td class="small">${new Date(x.clock_in.replace(' ','T')).toLocaleString('en-KE')}</td>
      <td class="small">${x.clock_out ? new Date(x.clock_out.replace(' ','T')).toLocaleString('en-KE') : '<span class="badge bg-success bg-opacity-25 text-success">In progress</span>'}</td>
      <td class="small">${x.clock_out ? (x.mins/60).toFixed(2) + ' h' : '—'}</td>
      <td class="small">${x.payout_id ? '<span class="text-success">Scheduled/Paid</span>' : (x.clock_out ? 'Unpaid' : '')}</td></tr>`).join('');
  const payRows = (d.payouts || []).map(x => {
    const c = x.status === 'released' ? 'success' : x.status === 'cancelled' ? 'danger' : 'warning';
    return `<tr><td class="small">${new Date(x.disburse_at.replace(' ','T')).toLocaleString('en-KE')}</td><td class="fw-bold">${fmt(x.amount)}</td><td class="small">${parseFloat(x.hours).toFixed(2)} h</td><td class="small">${esc(PAY_METHODS[x.pay_method]||x.pay_method)}</td><td><span class="badge bg-${c} bg-opacity-25 text-${c}">${esc(x.status)}</span></td></tr>`;
  }).join('');

  el.innerHTML = `
    <div style="max-width:1300px;margin:0 auto">
    <div class="card mb-4"><div class="card-body d-flex align-items-center gap-3 flex-wrap">
      <div style="width:64px;height:64px;border-radius:50%;background:${CU.photo ? `url('${esc(CU.photo)}') center/cover` : 'linear-gradient(135deg,var(--nx-accent),#17C548)'};display:flex;align-items:center;justify-content:center;font-weight:700;color:#000;font-size:1.5rem">${CU.photo ? '' : esc((CU.name||'U').charAt(0).toUpperCase())}</div>
      <div class="flex-grow-1">
        <div class="fw-head fw-bold" style="font-size:1.15rem">${esc(CU.name)}</div>
        <div class="small text-nx-muted">${esc(CU.role_name)} · ${esc(CU.branch_name||'')}</div>
      </div>
      <div class="text-end small">
        <div><span class="text-nx-muted">Pay type:</span> <strong>${hourly ? 'Hourly' : (p.pay_type ? 'Fixed salary' : 'Not set')}</strong></div>
        <div><span class="text-nx-muted">Paid via:</span> <strong>${esc(PAY_METHODS[p.pay_method] || '—')}</strong></div>
      </div>
    </div></div>

    ${hourly ? `
    <div class="row g-3 mb-4">
      ${kpi('Hours this month', (d.month_hours||0).toFixed(2) + ' h', 'var(--nx-blue)')}
      ${kpi('Unpaid hours', (d.unpaid_hours||0).toFixed(2) + ' h', 'var(--nx-orange)')}
      ${kpi('Hourly rate', fmt(rate), 'var(--nx-accent)')}
      ${kpi('Estimated earnings', fmt(est), 'var(--nx-green)')}
    </div>
    <div class="card mb-4"><div class="card-body d-flex align-items-center justify-content-between flex-wrap gap-3">
      <div>
        <div class="fw-bold">${open ? 'You are clocked in' : 'You are clocked out'}</div>
        <div class="small text-nx-muted">${open ? 'Shift time: <span id="fin-elapsed" class="fw-bold text-accent"></span>' : 'Clock in when you start work, clock out when you finish.'}</div>
      </div>
      <button class="btn fw-bold" style="background:${open ? 'var(--nx-red)' : 'var(--nx-green)'};color:#fff;min-width:160px" onclick="financeClock('${open ? 'out' : 'in'}')">
        <i class="fa fa-${open ? 'stop' : 'play'} me-2"></i>${open ? 'Clock Out' : 'Clock In'}
      </button>
    </div></div>
    <div class="row g-4 mb-4">
      <div class="col-lg-6"><div class="card h-100"><div class="card-header">Recent timesheet</div><div class="table-responsive"><table class="table table-sm mb-0">
        <thead><tr><th>In</th><th>Out</th><th>Hours</th><th>Status</th></tr></thead>
        <tbody>${logRows || '<tr><td colspan="4" class="text-center text-nx-muted py-3">No shifts yet</td></tr>'}</tbody></table></div></div></div>
      <div class="col-lg-6"><div class="card h-100"><div class="card-header">Payouts</div><div class="table-responsive"><table class="table table-sm mb-0">
        <thead><tr><th>Disburse on</th><th>Amount</th><th>Hours</th><th>Via</th><th>Status</th></tr></thead>
        <tbody>${payRows || '<tr><td colspan="5" class="text-center text-nx-muted py-3">No payouts yet</td></tr>'}</tbody></table></div></div></div>
    </div>` : `
    <div class="row g-3 mb-4">
      ${kpi('Monthly salary', p.fixed_salary ? fmt(p.fixed_salary) : '—', 'var(--nx-green)')}
      ${kpi('Pay method', esc(PAY_METHODS[p.pay_method] || '—'), 'var(--nx-blue)')}
    </div>`}

    <div class="card mb-4">
      <div class="card-header"><i class="fa fa-file-invoice-dollar me-2 text-accent"></i>Tax &amp; Financial Details</div>
      <div class="card-body">
        <div class="alert alert-info py-2 small"><i class="fa fa-info-circle me-1"></i>Keep these accurate. Your KRA PIN is required for payroll tax compliance.</div>
        <div class="row g-3">
          <div class="col-md-4"><label class="form-label">KRA PIN</label><input type="text" id="fin-kra" class="form-control" placeholder="A123456789B" maxlength="11" style="text-transform:uppercase" value="${esc(f.kra_pin||'')}"></div>
          <div class="col-md-4"><label class="form-label">NSSF Number</label><input type="text" id="fin-nssf" class="form-control" value="${esc(f.nssf_no||'')}"></div>
          <div class="col-md-4"><label class="form-label">SHIF Number</label><input type="text" id="fin-shif" class="form-control" value="${esc(f.shif_no||'')}"></div>
          <div class="col-md-4"><label class="form-label">Bank Name</label><input type="text" id="fin-bank" class="form-control" value="${esc(f.bank_name||'')}"></div>
          <div class="col-md-4"><label class="form-label">Bank Account No.</label><input type="text" id="fin-bankacc" class="form-control" value="${esc(f.bank_account||'')}"></div>
          <div class="col-md-4"><label class="form-label">M-Pesa Phone</label><input type="text" id="fin-mpesa" class="form-control" placeholder="07XX XXX XXX" value="${esc(f.mpesa_phone||'')}"></div>
          <div class="col-md-4"><label class="form-label">PayPal Email</label><input type="email" id="fin-paypal" class="form-control" value="${esc(f.paypal_email||'')}"></div>
          <div class="col-12"><button class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="saveFinance()"><i class="fa fa-save me-2"></i>Save Details</button></div>
        </div>
      </div>
    </div>

    <div class="card">
      <div class="card-header d-flex justify-content-between align-items-center flex-wrap gap-2"><span><i class="fa fa-money-bill-transfer me-2 text-accent"></i>Withdraw</span>
        <button class="btn btn-sm btn-outline-warning" onclick="openNewMsg('payout')"><i class="fa fa-comment-dollar me-1"></i>Request payout from manager</button></div>
      <div class="card-body">
        <p class="small text-nx-muted">Choose where you would like to withdraw to.</p>
        <div class="row g-3">
          ${WITHDRAW_OPTIONS.map((o, i) => `<div class="col-6 col-md-3 col-lg-2"><div class="bank-tile" onclick="withdrawSoon(${i})">
            <div class="bank-logo" style="background:${o.c}">${o.logo ? `<img src="${esc(o.logo)}" alt="${esc(o.n.split(' ').map(w => w[0]).join('').slice(0, 3).toUpperCase())}" onerror="this.parentElement.textContent=this.alt">` : esc(o.n.split(' ').map(w => w[0]).join('').slice(0, 3).toUpperCase())}</div>
            <div class="small fw-bold">${esc(o.n)}</div></div></div>`).join('')}
        </div>
      </div>
    </div></div>`;

  clearInterval(_finTimer);
  if (hourly && open) {
    let secs = parseInt(open.secs || 0);
    const tick = () => {
      const t = document.getElementById('fin-elapsed');
      if (!t) { clearInterval(_finTimer); return; }
      const h = Math.floor(secs / 3600), m = Math.floor((secs % 3600) / 60), s = secs % 60;
      t.textContent = [h, m, s].map(v => String(v).padStart(2, '0')).join(':'); secs++;
    };
    tick(); _finTimer = setInterval(tick, 1000);
  }
}

async function financeClock(dir) {
  const res = await api(dir === 'in' ? 'clock_in' : 'clock_out', {}, 'POST');
  if (res.ok) { toast(dir === 'in' ? 'Clocked in. Have a great shift!' : 'Clocked out. Hours saved.', 'success'); navigate('finance'); }
  else toast(res.msg || 'Failed.', 'error');
}
async function saveFinance() {
  const res = await api('finance_save', {
    kra_pin: document.getElementById('fin-kra').value, nssf_no: document.getElementById('fin-nssf').value,
    shif_no: document.getElementById('fin-shif').value, bank_name: document.getElementById('fin-bank').value,
    bank_account: document.getElementById('fin-bankacc').value, mpesa_phone: document.getElementById('fin-mpesa').value,
    paypal_email: document.getElementById('fin-paypal').value,
  }, 'POST');
  if (res.ok) toast('Financial details saved', 'success');
  else toast(res.msg || 'Failed.', 'error');
}
function withdrawSoon(i) {
  const o = WITHDRAW_OPTIONS[i]; if (!o) return;
  document.getElementById('wd-card')?.remove();
  const ini = esc(o.n.split(' ').map(w => w[0]).join('').slice(0, 3).toUpperCase());
  const el = document.createElement('div');
  el.id = 'wd-card'; el.className = 'wd-ov';
  el.onclick = e => { if (e.target === el) el.remove(); };
  el.innerHTML = `<div class="wd-box">
    <div class="wd-logo" style="background:${o.c}">${ini}${o.logo ? `<img src="${esc(o.logo)}" alt="" onerror="this.remove()">` : ''}</div>
    <div class="wd-ic">🚧</div>
    <h5>Sorry, ${esc(o.n)} is not available right now</h5>
    <p>This payment method is currently unavailable. Please check back later.</p>
    <button onclick="this.closest('.wd-ov').remove()">Got it</button>
  </div>`;
  document.body.appendChild(el);
}
function withdrawSoonOld(i) {
  toast('Hourly rates coming soon — our team is currently working on it.', 'info');
}

// ── NOTIFICATIONS ─────────────────────────────────────────────
let _notifLast = -1, _notifItems = [];
async function pollNotifs() {
  const d = await api('notif_list');
  if (!d.ok) return;
  _notifItems = d.items || [];
  const mb = document.getElementById('msg-badge');
  if (mb) { mb.textContent = d.msg_unread || 0; mb.classList.toggle('d-none', !d.msg_unread); }
  const hb = document.getElementById('home-msg-badge');
  if (hb) { hb.textContent = d.msg_unread || 0; hb.classList.toggle('d-none', !d.msg_unread); }
  const b = document.getElementById('notif-badge');
  if (b) { b.textContent = d.unread; b.classList.toggle('d-none', !d.unread); }
  if (_notifLast >= 0 && d.unread > _notifLast && _notifItems[0]) toast('🔔 ' + _notifItems[0].title, 'info');
  _notifLast = d.unread;
  try {
    const seen = JSON.parse(localStorage.getItem('nx_paid_seen') || '[]');
    const hit = _notifItems.find(n => n.title === 'Pay released' && n.is_read == 0 && !seen.includes(n.id));
    if (hit) {
      seen.push(hit.id);
      localStorage.setItem('nx_paid_seen', JSON.stringify(seen.slice(-50)));
      const m = (hit.body || '').match(/KSh\s*([\d,]+\.?\d*)/);
      showPayoutCelebration(m ? parseFloat(m[1].replace(/,/g, '')) : 0);
    }
  } catch (e) {}
}
async function showNotifs() {
  const box = document.getElementById('notif-list');
  if (!box) return;
  await pollNotifs();
  box.innerHTML = _notifItems.length ? _notifItems.map(n => `
    <div class="p-3 border-bottom" style="border-color:var(--nx-border)!important;${n.is_read == 0 ? 'background:rgba(30,158,82,.08)' : ''}">
      <div class="small fw-bold">${esc(n.title)}</div>
      <div class="small text-nx-muted">${esc(n.body || '')}</div>
      <div style="font-size:.65rem;color:var(--nx-muted)" class="mt-1">${new Date(n.created_at.replace(' ','T')).toLocaleString('en-KE')}</div>
    </div>`).join('') : '<div class="p-3 small text-nx-muted text-center">No notifications</div>';
  if (document.getElementById('notif-badge') && !document.getElementById('notif-badge').classList.contains('d-none')) {
    await api('notif_read', {}, 'POST');
    _notifLast = 0;
    const b = document.getElementById('notif-badge'); if (b) b.classList.add('d-none');
  }
}

// ── MESSAGES ──────────────────────────────────────────────────
const MSG_CATS = { general:'General', product:'Product request', payout:'Payout request', other:'Other' };
const NM_HINT  = { general:'Subject', product:'e.g. Request for 20 bags of cement', payout:"e.g. Request for this week's payout", other:'Subject' };
let _msgCur = 0, _msgPoll = null, _msgStatus = '';

async function renderMessages(el) {
  clearInterval(_msgPoll);
  el.innerHTML = `
    <div style="max-width:1300px;margin:0 auto">
      <div class="d-flex align-items-center justify-content-between mb-3 flex-wrap gap-2">
        <div><h5 class="fw-head mb-0"><i class="fa fa-comments text-accent me-2"></i>Messages</h5>
          <div class="small text-nx-muted">${can(R.OWNER, R.MANAGER) ? 'Requests and conversations from your team' : 'Send a request or question to your manager'}</div></div>
        <button class="btn btn-sm fw-bold" style="background:var(--nx-accent);color:#fff" onclick="openNewMsg()"><i class="fa fa-pen me-1"></i>New Message</button>
      </div>
      <div class="row g-3">
        <div class="col-lg-4"><div class="card"><div id="msg-list" style="max-height:72vh;overflow-y:auto"></div></div></div>
        <div class="col-lg-8"><div class="card" style="height:72vh;display:flex;flex-direction:column">
          <div id="msg-conv" style="flex:1;display:flex;flex-direction:column;min-height:0">
            <div class="d-flex flex-column align-items-center justify-content-center h-100 text-nx-muted"><i class="fa fa-comments mb-2" style="font-size:2.4rem;opacity:.3"></i><span class="small">Select a conversation</span></div>
          </div></div></div>
      </div>
    </div>`;
  await loadMsgThreads();
  if (_msgCur) openThread(_msgCur);
  _msgPoll = setInterval(() => {
    if (!document.getElementById('msg-list')) { clearInterval(_msgPoll); return; }
    loadMsgThreads(); if (_msgCur) refreshThread(false);
  }, 5000);
}

async function loadMsgThreads() {
  const d = await api('msg_threads');
  const box = document.getElementById('msg-list');
  if (!box) { clearInterval(_msgPoll); return; }
  if (!d.ok) { box.innerHTML = '<p class="text-danger p-3">Failed to load.</p>'; return; }
  box.innerHTML = d.threads.length ? d.threads.map(t => `
    <div class="p-3 border-bottom" style="cursor:pointer;border-color:var(--nx-border)!important;${t.id == _msgCur ? 'background:rgba(30,158,82,.10)' : ''}" onclick="openThread(${t.id})">
      <div class="d-flex justify-content-between align-items-start gap-2">
        <span class="small fw-bold text-truncate">${esc(t.subject)}</span>
        ${t.unread > 0 ? `<span class="badge bg-danger">${t.unread}</span>` : ''}
      </div>
      <div class="small text-nx-muted text-truncate">${esc(t.creator)} · ${esc(MSG_CATS[t.category] || t.category)}${t.status === 'closed' ? ' · closed' : ''}</div>
      <div class="small text-nx-muted text-truncate">${esc(t.last_body || '')}</div>
      <div style="font-size:.62rem;color:var(--nx-muted)">${new Date(t.last_message_at.replace(' ', 'T')).toLocaleString('en-KE')}</div>
    </div>`).join('') : '<div class="p-4 text-center small text-nx-muted">No conversations yet.<br>Tap <strong>New Message</strong> to start one.</div>';
}

function paintMsgs(d, force) {
  const body = document.getElementById('msg-body'); if (!body) return;
  const n = d.messages.length;
  if (!force && body.dataset.n == n) return;
  const nearBottom = body.scrollHeight - body.scrollTop - body.clientHeight < 80;
  body.dataset.n = n;
  body.innerHTML = d.messages.map(m => {
    const mine = m.sender_id == d.me;
    return `<div style="display:flex;flex-direction:column;align-items:${mine ? 'flex-end' : 'flex-start'}">
      <div class="msg-who">${mine ? 'You' : esc(m.full_name) + ' · ' + esc(m.role_name)} · ${new Date(m.created_at.replace(' ', 'T')).toLocaleString('en-KE', { hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' })}</div>
      <div class="msg-b ${mine ? 'me' : 'them'}">${esc(m.body)}</div></div>`;
  }).join('');
  if (force || nearBottom) body.scrollTop = body.scrollHeight;
}

async function openThread(id) {
  _msgCur = id;
  const d = await api('msg_thread', { id });
  const conv = document.getElementById('msg-conv'); if (!conv) return;
  if (!d.ok) { conv.innerHTML = `<div class="p-4 text-danger">${esc(d.msg || 'Failed')}</div>`; return; }
  const t = d.thread, closed = t.status === 'closed';
  _msgStatus = t.status;
  conv.innerHTML = `
    <div class="p-3 border-bottom d-flex justify-content-between align-items-center gap-2" style="border-color:var(--nx-border)!important">
      <div style="min-width:0"><div class="fw-bold text-truncate">${esc(t.subject)}</div>
        <div class="small text-nx-muted">${esc(t.creator)} · ${esc(MSG_CATS[t.category] || t.category)}${closed ? ' · <span class="text-danger">closed</span>' : ''}</div></div>
      ${can(R.OWNER, R.MANAGER) ? `<button class="btn btn-sm btn-outline-secondary" onclick="setThreadStatus(${t.id},'${closed ? 'open' : 'closed'}')">${closed ? 'Reopen' : 'Mark resolved'}</button>` : ''}
    </div>
    <div id="msg-body" style="flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:10px"></div>
    <div class="p-2 border-top d-flex gap-2 align-items-end" style="border-color:var(--nx-border)!important">
      ${closed ? '<div class="small text-nx-muted p-2">This conversation is closed.</div>'
        : `<textarea id="msg-input" class="form-control" rows="2" placeholder="Type your message… (Enter to send, Shift+Enter for a new line)"></textarea>
           <button class="btn fw-bold" style="background:var(--nx-accent);color:#fff;height:52px" onclick="sendMsgReply()"><i class="fa fa-paper-plane"></i></button>`}
    </div>`;
  paintMsgs(d, true);
  document.getElementById('msg-input')?.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMsgReply(); } });
  loadMsgThreads();
}

async function refreshThread(force) {
  if (!_msgCur) return;
  const d = await api('msg_thread', { id: _msgCur });
  if (!d.ok || !document.getElementById('msg-body')) return;
  if (d.thread.status !== _msgStatus) { openThread(_msgCur); return; }
  paintMsgs(d, !!force);
}

async function sendMsgReply() {
  const inp = document.getElementById('msg-input'); if (!inp) return;
  const body = inp.value.trim(); if (!body) return;
  inp.disabled = true;
  const r = await api('msg_send', { thread_id: _msgCur, body }, 'POST');
  inp.disabled = false;
  if (r.ok) { inp.value = ''; await refreshThread(true); loadMsgThreads(); inp.focus(); }
  else toast(r.msg || 'Could not send.', 'error');
}

async function setThreadStatus(id, status) {
  const r = await api('msg_status', { id, status }, 'POST');
  if (r.ok) { toast(status === 'closed' ? 'Marked as resolved' : 'Conversation reopened', 'success'); openThread(id); }
  else toast(r.msg || 'Failed.', 'error');
}

function openNewMsg(cat) {
  document.getElementById('nm-cat').value = cat || 'general';
  document.getElementById('nm-subject').value = '';
  document.getElementById('nm-body').value = '';
  nmCatChanged();
  openModal('modal-newmsg');
}
function nmCatChanged() {
  const c = document.getElementById('nm-cat').value, s = document.getElementById('nm-subject');
  s.placeholder = NM_HINT[c] || 'Subject';
  if (c === 'payout' && !s.value) s.value = "Request for this week's payout";
}
async function submitNewMsg() {
  const subject = document.getElementById('nm-subject').value.trim();
  const body = document.getElementById('nm-body').value.trim();
  const category = document.getElementById('nm-cat').value;
  if (!subject || !body) { toast('Enter a subject and a message', 'error'); return; }
  const r = await api('msg_send', { category, subject, body }, 'POST');
  if (!r.ok) { toast(r.msg || 'Could not send.', 'error'); return; }
  closeModal('modal-newmsg');
  toast('Message sent', 'success');
  _msgCur = r.thread_id;
  if (document.getElementById('msg-list')) { await loadMsgThreads(); openThread(r.thread_id); }
  else navigate('messages');
}

