  return [
    { n: 'Overview', items: [
      ['dashboard', 'Dashboard', 'fa-chart-pie', '#1E9E52', 'Sales, trends & alerts', null] ] },
    { n: 'Sales & Customers', items: [
      ['pos', 'Point of Sale', 'fa-cash-register', '#22c55e', 'Sell & take payments', [O, M, C]],
      ['sales', 'Sales History', 'fa-receipt', '#3b82f6', 'Receipts & records', [O, M, C]],
      ['customers', 'Customers', 'fa-users', '#a855f7', 'Loyalty & credit', [O, M, C]] ] },
    { n: 'Stock & Purchasing', items: [
      ['inventory', 'Stock Levels', 'fa-boxes-stacked', '#f97316', 'Levels & movements', null],
      ['transfers', 'Transfers', 'fa-arrows-left-right', '#06b6d4', 'Between branches', [O, M, S]],
      ['products', 'Products', 'fa-box', '#eab308', 'Catalogue & prices', [O, M, S]],
      ['categories', 'Categories & Units', 'fa-tags', '#84cc16', 'Organise products', [O, M, S]],
      ['purchases', 'Purchase Orders', 'fa-truck', '#ef4444', 'LPOs & receiving', [O, M, S, U]],
      ['suppliers', 'Suppliers', 'fa-industry', '#14b8a6', 'Supplier directory', [O, M, S, U]] ] },
    { n: 'Business', items: [
      ['reports', 'Reports', 'fa-chart-bar', '#6366f1', 'Sales & stock reports', [O, M]],
      ['expenses', 'Expenses', 'fa-wallet', '#f43f5e', 'Record spending', [O, M]],
      ['salary', 'HR & Payroll', 'fa-sack-dollar', '#1E9E52', 'Staff, pay & hours', [O, M]],
      ['users', 'Staff Users', 'fa-user-gear', '#0ea5e9', 'Accounts & roles', [O]],
      ['etims', 'eTIMS / KRA', 'fa-file-invoice', '#10b981', 'Tax compliance', [O]] ] },
    { n: 'My Space', items: [
      ['messages', 'Messages', 'fa-comments', '#3b82f6', 'Chat with your team', null],
      ['finance', 'My Finance', 'fa-wallet', '#22c55e', 'Pay, hours & tax details', null] ] },
  ];
}

// ══ REWARD LEVELS (edit names / xp thresholds here) ══
const LEVELS = [
  { n: 1, name: 'Rookie',      xp: 0,     c1: '#b87333', c2: '#e0a370' },
  { n: 2, name: 'Rising Star', xp: 500,   c1: '#64748b', c2: '#cbd5e1' },
  { n: 3, name: 'Pro',         xp: 1500,  c1: '#d97706', c2: '#fbbf24' },
  { n: 4, name: 'Elite',       xp: 4000,  c1: '#059669', c2: '#6ee7b7' },
  { n: 5, name: 'Legend',      xp: 10000, c1: '#7c3aed', c2: '#c4b5fd' },
];
function levelBadge(l, size = 56) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 64 64" role="img" aria-label="Level ${l.n}">
    <defs><linearGradient id="lg${l.n}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${l.c2}"/><stop offset="1" stop-color="${l.c1}"/></linearGradient></defs>
    <path d="M32 4 L56 12 V32 C56 46 46 56 32 60 C18 56 8 46 8 32 V12 Z" fill="url(#lg${l.n})" stroke="rgba(255,255,255,.55)" stroke-width="2"/>
    <path d="M32 9 L51 15 V32 C51 43 43 51 32 55 C21 51 13 43 13 32 V15 Z" fill="none" stroke="rgba(255,255,255,.35)" stroke-width="1.5"/>
    <text x="32" y="40" text-anchor="middle" font-family="Space Grotesk,Arial" font-weight="800" font-size="26" fill="#fff" style="paint-order:stroke;stroke:rgba(0,0,0,.25);stroke-width:2px">${l.n}</text>
  </svg>`;
}

const HOME_IMG = {
  hero: 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1600&q=70',
  'Overview': 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=70',
  'Sales & Customers': 'https://images.unsplash.com/photo-1556740738-b6a63e27c4df?auto=format&fit=crop&w=1200&q=70',
  'Stock & Purchasing': 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=70',
  'Business': 'https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1200&q=70',
  'My Space': 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=70',
};

async function loadRewards() {
  const d = await api('rewards_me');
  const box = document.getElementById('home-rewards');
  if (!box) return;
  if (!d.ok) { box.innerHTML = '<div class="small text-nx-muted">Rewards are unavailable right now.</div>'; return; }
  const xp = parseInt(d.xp || 0);
  let idx = 0;
  LEVELS.forEach((l, i) => { if (xp >= l.xp) idx = i; });
  const cur = LEVELS[idx], next = LEVELS[idx + 1] || null;
  const pct = next ? Math.min(100, Math.round(((xp - cur.xp) / (next.xp - cur.xp)) * 100)) : 100;
  const need = next ? next.xp - xp : 0;
  box.innerHTML = `
    <div class="hm-rew-top">
      ${levelBadge(cur, 68)}
      <div style="flex:1;min-width:0">
        <div class="hm-rew-l">LEVEL ${cur.n}</div>
        <div class="hm-rew-n">${esc(cur.name)}</div>
        <div class="hm-rew-xp">${xp.toLocaleString()} XP${next ? ' / ' + next.xp.toLocaleString() : ''}</div>
      </div>
    </div>
    <div class="hm-bar"><span style="width:0" data-w="${pct}"></span></div>
    ${next
      ? `<div class="hm-aim"><i class="fa fa-bullseye me-1 text-accent"></i>Next aim: reach <b>Level ${next.n} · ${esc(next.name)}</b>. Earn <b>${need.toLocaleString()} XP</b> more (about ${Math.ceil(need / 10)} sales or ${(need / 20).toFixed(1)} hours worked).</div>`
      : '<div class="hm-aim"><b>🏆 You reached the top level. Legend status!</b></div>'}
    <div class="hm-lv">${LEVELS.map(l => `<div class="hm-lv-i ${l.n <= cur.n ? '' : 'lock'}">${levelBadge(l, 46)}<span>${esc(l.name)}</span></div>`).join('')}</div>
    <div class="hm-stats">
      <div><b>${parseInt(d.sales || 0)}</b><span>Sales</span></div>
      <div><b>${parseFloat(d.hours || 0).toFixed(1)}</b><span>Hours</span></div>
      <div><b>${parseInt(d.ops || 0)}</b><span>Stock actions</span></div>
    </div>
    <div class="text-nx-muted mt-2" style="font-size:.66rem">10 XP per sale · 20 XP per hour worked · 3 XP per stock action</div>`;
  setTimeout(() => { const s = box.querySelector('.hm-bar span'); if (s) s.style.width = s.dataset.w + '%'; }, 120);
}

function showPayoutCelebration(amount) {
  document.getElementById('pay-cel')?.remove();
  const el = document.createElement('div');
  el.id = 'pay-cel'; el.className = 'pay-cel';
  el.innerHTML = `<div class="pc-conf"></div>
    <div class="pc-card">
      <div class="pc-ring"><svg viewBox="0 0 52 52"><circle cx="26" cy="26" r="24"/><path d="M14 27l8 8 16-17"/></svg></div>
      <div class="pc-h">Your hourly pay has been disbursed! 🎉</div>
      <div class="pc-amt" id="pc-amt">KSh 0.00</div>
      <div class="pc-sub">is now available for withdrawal</div>
      <button class="pc-btn" onclick="closePayoutCel(true)"><i class="fa fa-money-bill-transfer me-2"></i>Withdraw now</button>
      <button class="pc-later" onclick="closePayoutCel(false)">Later</button>
    </div>`;
  document.body.appendChild(el);
  const conf = el.querySelector('.pc-conf'), cols = ['#1E9E52', '#22c55e', '#3b82f6', '#ef4444', '#a78bfa', '#17C548'];
  for (let i = 0; i < 60; i++) {
    const c = document.createElement('i');
    c.style.cssText = `left:${Math.random() * 100}%;background:${cols[i % cols.length]};animation-duration:${2 + Math.random() * 2.5}s;animation-delay:${Math.random() * 1.2}s`;
    conf.appendChild(c);
  }
  const t0 = performance.now(), dur = 1400, target = parseFloat(amount || 0);
  const tick = now => {
    const a = document.getElementById('pc-amt'); if (!a) return;
    const p = Math.min(1, (now - t0) / dur);
    a.textContent = fmt(target * (1 - Math.pow(1 - p, 3)));
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
  try { _sfx.sale(); } catch (e) {}
}
function closePayoutCel(go) {
  document.getElementById('pay-cel')?.remove();
  if (go) navigate('finance');
}

async function renderHome(el) {
