  const h = new Date().getHours();
  const greet = h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
  const first = (CU.name || '').split(' ')[0];
  const groups = HOME_GROUPS().map(g => ({ n: g.n, items: g.items.filter(i => !i[5] || i[5].includes(CU.role_id)) })).filter(g => g.items.length);
  const logo = CU.logo
    ? `<img src="${esc(CU.logo)}" alt="" onerror="this.style.display='none'">`
    : `<div class="fb">${esc((CU.business_name || 'N').charAt(0).toUpperCase())}</div>`;
  const today = new Date().toLocaleDateString('en-KE', { weekday: 'long', day: 'numeric', month: 'long' });
  el.innerHTML = `
  <div class="hm">
    <div class="hm-hero" style="background-image:linear-gradient(160deg,rgba(20,53,31,.9),rgba(20,53,31,.6) 60%,rgba(30,158,82,.5)),url('${HOME_IMG.hero}')">
      <div class="hm-top">
        <div class="hm-brand">${logo}<div style="min-width:0"><div class="t">${esc(CU.business_name || '')}</div><div class="s">${esc(CU.branch_name || 'All branches')} · ${esc(CU.role_name || '')}</div></div></div>
        <div class="hm-acts">
          <button onclick="openProfile()" title="Profile"><i class="fa fa-user"></i></button>
          <button onclick="toggleTheme()" title="Theme"><i class="fa fa-circle-half-stroke"></i></button>
          <button onclick="lockScreen()" title="Lock"><i class="fa fa-lock"></i></button>
          <button onclick="doLogout()" title="Sign out"><i class="fa fa-right-from-bracket"></i></button>
        </div>
      </div>
      <div class="hm-greet"><h1>${greet}, ${esc(first)} 👋</h1><p>${today} · What would you like to do?</p></div>
      <div class="hm-search"><i class="fa fa-search"></i><input type="text" placeholder="Search modules…" oninput="homeFilter(this.value)"></div>
    </div>

    <div class="hm-rew" id="home-rewards"><div class="d-flex justify-content-center py-4"><div class="spinner-border spinner-border-sm text-warning"></div></div></div>

    ${groups.map(g => `
      <div class="home-group-wrap">
        <div class="hm-gh" style="background-image:linear-gradient(90deg,rgba(20,53,31,.88),rgba(20,53,31,.25)),url('${HOME_IMG[g.n] || ''}')">${g.n}</div>
        <div class="home-grid">${g.items.map(([p, t, i, c, d]) => `
          <button class="home-card" data-t="${esc(t.toLowerCase())}" onclick="navigate('${p}')">
            <div class="home-ico" style="background:${c}22;color:${c}"><i class="fa ${i}"></i></div>
            <b>${t}</b><small class="d">${d}</small>
            ${p === 'messages' ? '<span id="home-msg-badge" class="badge bg-danger position-absolute d-none" style="top:12px;right:12px">0</span>' : ''}
          </button>`).join('')}</div>
      </div>`).join('')}

    <div class="hm-nav">
      <button class="on" onclick="navigate('home')"><i class="fa fa-house"></i>Home</button>
      <button onclick="navigate('messages')"><i class="fa fa-comments"></i>Messages</button>
      <button onclick="navigate('finance')"><i class="fa fa-wallet"></i>Finance</button>
      <button onclick="openProfile()"><i class="fa fa-user"></i>Profile</button>
    </div>
  </div>`;
  pollNotifs();
  loadRewards();
}

