function homeFilter(q) {
  q = q.trim().toLowerCase();
  document.querySelectorAll('.home-group-wrap').forEach(g => {
    let any = false;
    g.querySelectorAll('.home-card').forEach(c => { const m = !q || c.dataset.t.includes(q); c.style.display = m ? '' : 'none'; if (m) any = true; });
    g.style.display = any ? '' : 'none';
  });
}

// ══ MESSAGING v2 ══════════════════════════════════════════════
let _msgTab = 'chats', _msgContacts = [], _msgThreadsCache = [], _msgPeople = {}, _newTo = 0, _msgUnreadPrev = -1;
let MSG_SET = { show_last_seen: 1, show_online: 1, read_receipts: 1, enter_to_send: 1, sound: 1 };

function msgAv(p, size) {
  p = p || {}; const name = p.name || '?';
  const bg = p.photo ? `url('${esc(p.photo)}') center/cover` : 'linear-gradient(135deg,var(--nx-accent),#17C548)';
  const dot = p.online === true ? '<span style="position:absolute;right:0;bottom:0;width:11px;height:11px;border-radius:50%;background:#22c55e;border:2px solid var(--nx-card)"></span>' : '';
  return `<div style="position:relative;flex-shrink:0;width:${size}px;height:${size}px"><div style="width:100%;height:100%;border-radius:50%;background:${bg};display:flex;align-items:center;justify-content:center;font-weight:700;color:#000;font-size:${Math.round(size * .42)}px">${p.photo ? '' : esc(name.charAt(0).toUpperCase())}</div>${dot}</div>`;
}
function msgName(p) { return `<span class="text-truncate">${esc(p.name)}</span>${parseInt(p.verified) ? verifiedBadge(14) : ''}`; }
function msgPresence(p) {
  if (!p) return '';
  if (p.online === true) return '<span style="color:#22c55e">online</span>';
  if (p.seen_ago == null) return '';
  const d = new Date(Date.now() - p.seen_ago * 1000), now = new Date();
  const t = d.toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit' });
  if (d.toDateString() === now.toDateString()) return 'last seen today at ' + t;
  if (d.toDateString() === new Date(Date.now() - 864e5).toDateString()) return 'last seen yesterday at ' + t;
  return 'last seen ' + d.toLocaleDateString('en-KE', { day: 'numeric', month: 'short' }) + ' at ' + t;
}
function msgTick(state) {
  if (state === 'sent') return '<i class="fa fa-check" style="color:#57534e;font-size:.65rem"></i>';
  return `<i class="fa fa-check-double" style="color:${state === 'read' ? '#2563eb' : '#57534e'};font-size:.65rem"></i>`;
}

async function renderMessages(el) {
  clearInterval(_msgPoll); _newTo = 0; _msgTab = 'chats';
  el.innerHTML = `
    <div style="max-width:1300px;margin:0 auto">
      <div class="d-flex align-items-center justify-content-between mb-3 flex-wrap gap-2">
        <div><h5 class="fw-head mb-0"><i class="fa fa-comments text-accent me-2"></i>Messages</h5>
          <div class="small text-nx-muted">Chat with your team, or send a request to your manager</div></div>
        <div class="d-flex gap-2">
          <button class="btn btn-sm btn-outline-secondary" onclick="openMsgSettings()" title="Message settings"><i class="fa fa-gear"></i></button>
          <button class="btn btn-sm fw-bold" style="background:var(--nx-accent);color:#fff" onclick="openNewMsg()"><i class="fa fa-pen me-1"></i>New Request</button>
        </div>
      </div>
      <div class="row g-3">
        <div class="col-lg-4"><div class="card">
          <ul class="nav nav-tabs px-2 pt-1 mb-0" id="msg-tabs">
            <li class="nav-item"><button class="nav-link active" data-t="chats" onclick="msgSetTab('chats')">Chats</button></li>
            <li class="nav-item"><button class="nav-link" data-t="people" onclick="msgSetTab('people')">People</button></li>
          </ul>
          <div id="msg-list" style="max-height:66vh;overflow-y:auto"></div>
          <div id="msg-people-wrap" class="d-none">
            <div class="p-2 border-bottom" style="border-color:var(--nx-border)!important">
              <input type="text" id="msg-search" class="form-control form-control-sm" placeholder="Search people you can message…" oninput="renderContacts()">
              <div class="small text-nx-muted mt-1 px-1">People you can message. Tap one to start a conversation.</div>
            </div>
            <div id="msg-people" style="max-height:58vh;overflow-y:auto"></div>
          </div>
        </div></div>
        <div class="col-lg-8"><div class="card" style="height:72vh;display:flex;flex-direction:column">
          <div id="msg-conv" style="flex:1;display:flex;flex-direction:column;min-height:0">
            <div class="d-flex flex-column align-items-center justify-content-center h-100 text-nx-muted"><i class="fa fa-comments mb-2" style="font-size:2.4rem;opacity:.3"></i><span class="small">Select a conversation or pick someone from People</span></div>
          </div></div></div>
      </div>
    </div>`;
  api('msg_settings').then(r => { if (r.ok) MSG_SET = r.settings; });
  await loadMsgThreads();
  if (_msgCur) openThread(_msgCur);
  _msgPoll = setInterval(() => {
    if (!document.getElementById('msg-list')) { clearInterval(_msgPoll); return; }
    loadMsgThreads();
    if (_msgTab === 'people') loadContacts();
    if (_msgCur && !_newTo) refreshThread(false);
  }, 5000);
}

function msgSetTab(t) {
  _msgTab = t;
  document.getElementById('msg-list').classList.toggle('d-none', t !== 'chats');
  document.getElementById('msg-people-wrap').classList.toggle('d-none', t !== 'people');
  document.querySelectorAll('#msg-tabs .nav-link').forEach(b => b.classList.toggle('active', b.dataset.t === t));
  if (t === 'people') loadContacts();
}

async function loadContacts() {
  const d = await api('msg_contacts');
  const box = document.getElementById('msg-people'); if (!box) return;
  if (!d.ok) { box.innerHTML = '<p class="text-danger p-3">Failed to load.</p>'; return; }
  _msgContacts = d.contacts || [];
  renderContacts();
}
function renderContacts() {
  const box = document.getElementById('msg-people'); if (!box) return;
  const q = (document.getElementById('msg-search')?.value || '').toLowerCase();
  const list = _msgContacts.filter(c => !q || c.name.toLowerCase().includes(q) || (c.role || '').toLowerCase().includes(q));
  list.sort((a, b) => (b.online === true) - (a.online === true));
  box.innerHTML = list.length ? list.map(c => `
    <div class="d-flex align-items-center gap-3 p-3 border-bottom" style="cursor:pointer;border-color:var(--nx-border)!important" onclick="startChat(${c.id})">
      ${msgAv(c, 42)}
      <div style="min-width:0;flex:1">
        <div class="small fw-bold d-flex align-items-center">${msgName(c)}</div>
        <div class="small text-nx-muted text-truncate">${esc(c.role)}${c.branch ? ' · ' + esc(c.branch) : ''}</div>
        <div style="font-size:.68rem" class="text-nx-muted">${msgPresence(c)}</div>
      </div>
      <i class="fa fa-comment-dots text-accent"></i>
    </div>`).join('') : '<div class="p-4 text-center small text-nx-muted">No one found.</div>';
}

async function loadMsgThreads() {
  const d = await api('msg_threads');
  const box = document.getElementById('msg-list');
  if (!box) { clearInterval(_msgPoll); return; }
  if (!d.ok) { box.innerHTML = '<p class="text-danger p-3">Failed to load.</p>'; return; }
  _msgPeople = d.people || {}; _msgThreadsCache = d.threads;
  const tot = d.threads.reduce((a, t) => a + parseInt(t.unread || 0), 0);
  if (_msgUnreadPrev >= 0 && tot > _msgUnreadPrev && +MSG_SET.sound === 1) { try { _sfx.info(); } catch (e) {} }
  _msgUnreadPrev = tot;
  box.innerHTML = d.threads.length ? d.threads.map(t => {
    const peer = _msgPeople[t.peer_id], direct = !!t.to_user_id;
    const title = direct && peer ? peer.name : t.subject;
    const sub = direct ? '' : esc(t.creator) + ' · ' + esc(MSG_CATS[t.category] || t.category) + (t.status === 'closed' ? ' · closed' : '');
    return `<div class="d-flex gap-3 p-3 border-bottom" style="cursor:pointer;border-color:var(--nx-border)!important;${t.id == _msgCur ? 'background:rgba(30,158,82,.10)' : ''}" onclick="openThread(${t.id})">
      ${msgAv(peer || { name: t.subject }, 42)}
      <div style="min-width:0;flex:1">
        <div class="d-flex justify-content-between align-items-start gap-2">
          <span class="small fw-bold text-truncate d-flex align-items-center">${esc(title)}${direct && peer && parseInt(peer.verified) ? verifiedBadge(13) : ''}</span>
          ${t.unread > 0 ? `<span class="badge bg-danger">${t.unread}</span>` : ''}
        </div>
        ${sub ? `<div class="small text-nx-muted text-truncate">${sub}</div>` : ''}
        <div class="small text-nx-muted text-truncate">${esc(t.last_body || '')}</div>
        <div style="font-size:.62rem;color:var(--nx-muted)">${new Date(t.last_message_at.replace(' ', 'T')).toLocaleString('en-KE')}</div>
      </div></div>`;
  }).join('') : '<div class="p-4 text-center small text-nx-muted">No conversations yet.<br>Open the <strong>People</strong> tab to start one.</div>';
}

function paintMsgs(d, force) {
  const body = document.getElementById('msg-body'); if (!body) return;
  const sig = d.messages.length + ':' + d.read_upto + ':' + d.deliv_upto;
  if (!force && body.dataset.n === sig) return;
  const nearBottom = body.scrollHeight - body.scrollTop - body.clientHeight < 80;
  body.dataset.n = sig;
  let lastDay = '';
  body.innerHTML = d.messages.map(m => {
    const mine = m.sender_id == d.me;
    const dt = new Date(m.created_at.replace(' ', 'T'));
    const day = dt.toLocaleDateString('en-KE', { weekday: 'short', day: 'numeric', month: 'short' });
    const sep = day !== lastDay ? `<div class="text-center small text-nx-muted my-1">${day}</div>` : ''; lastDay = day;
    const time = dt.toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit' });
    const state = m.id <= d.read_upto ? 'read' : (m.id <= d.deliv_upto ? 'delivered' : 'sent');
    const av = mine ? '' : msgAv({ name: m.full_name, photo: m.photo_path }, 30);
    return sep + `<div style="display:flex;gap:8px;align-items:flex-end;justify-content:${mine ? 'flex-end' : 'flex-start'}">${av}
      <div class="msg-wrap" style="max-width:78%">
        ${mine ? '' : `<div class="msg-who">${esc(m.full_name)}${parseInt(m.id_verified) ? verifiedBadge(12) : ''}&nbsp;· ${esc(m.role_name)}</div>`}
        <div class="msg-b ${mine ? 'me' : 'them'}">${esc(m.body)}
          <div style="text-align:right;font-size:.62rem;opacity:.8;margin-top:2px">${time}${mine ? ' ' + msgTick(state) : ''}</div></div>
      </div></div>`;
  }).join('');
  if (force || nearBottom) body.scrollTop = body.scrollHeight;
}

function msgComposer() {
  return `<div class="p-2 border-top d-flex gap-2 align-items-end" style="border-color:var(--nx-border)!important">
    <textarea id="msg-input" class="form-control" rows="2" placeholder="Type your message…"></textarea>
    <button class="btn fw-bold" style="background:var(--nx-accent);color:#fff;height:52px" onclick="sendMsgReply()"><i class="fa fa-paper-plane"></i></button></div>`;
}
function msgBindInput() {
  const i = document.getElementById('msg-input'); if (!i) return;
  i.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey && +MSG_SET.enter_to_send === 1) { e.preventDefault(); sendMsgReply(); } });
}

async function openThread(id) {
  _msgCur = id; _newTo = 0;
  const d = await api('msg_thread', { id });
  const conv = document.getElementById('msg-conv'); if (!conv) return;
  if (!d.ok) { conv.innerHTML = `<div class="p-4 text-danger">${esc(d.msg || 'Failed')}</div>`; return; }
  if (d.settings) MSG_SET = d.settings;
  const t = d.thread, closed = t.status === 'closed', direct = !!t.to_user_id;
  _msgStatus = t.status;
  const peers = Object.values(d.people || {});
  const one = peers.length === 1 ? peers[0] : null;
  const head = one
    ? `${msgAv(one, 42)}<div style="min-width:0"><div class="fw-bold d-flex align-items-center">${msgName(one)}</div>
        <div class="small text-nx-muted text-truncate">${direct ? '' : esc(t.subject) + ' · '}<span id="msg-presence">${msgPresence(one) || esc(one.role)}</span></div></div>`
    : `<div class="d-flex gap-1">${peers.slice(0, 3).map(p => msgAv(p, 36)).join('')}</div>
       <div style="min-width:0"><div class="fw-bold text-truncate">${esc(t.subject)}</div>
        <div class="small text-nx-muted text-truncate">${peers.map(p => esc(p.name)).join(', ') || esc(t.creator)}</div></div>`;
  conv.innerHTML = `
    <div class="p-3 border-bottom d-flex justify-content-between align-items-center gap-2" style="border-color:var(--nx-border)!important">
      <div class="d-flex align-items-center gap-3" style="min-width:0">${head}</div>
      ${can(R.OWNER, R.MANAGER) && !direct ? `<button class="btn btn-sm btn-outline-secondary" onclick="setThreadStatus(${t.id},'${closed ? 'open' : 'closed'}')">${closed ? 'Reopen' : 'Mark resolved'}</button>` : ''}
    </div>
    <div id="msg-body" style="flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:10px"></div>
    ${closed ? '<div class="small text-nx-muted p-3 border-top">This conversation is closed.</div>' : msgComposer()}`;
  paintMsgs(d, true);
  msgBindInput();
  loadMsgThreads();
}

async function refreshThread(force) {
  if (!_msgCur) return;
  const d = await api('msg_thread', { id: _msgCur });
  if (!d.ok || !document.getElementById('msg-body')) return;
  if (d.thread.status !== _msgStatus) { openThread(_msgCur); return; }
  const peers = Object.values(d.people || {});
  const pe = document.getElementById('msg-presence');
  if (pe && peers.length === 1) pe.innerHTML = msgPresence(peers[0]) || esc(peers[0].role);
  paintMsgs(d, !!force);
}

function startChat(uid) {
  const ex = _msgThreadsCache.find(t => t.to_user_id && t.peer_id == uid);
  if (ex) { openThread(ex.id); return; }
  const p = _msgContacts.find(c => c.id == uid); if (!p) return;
  _newTo = uid; _msgCur = 0;
  const conv = document.getElementById('msg-conv');
  conv.innerHTML = `
    <div class="p-3 border-bottom d-flex align-items-center gap-3" style="border-color:var(--nx-border)!important">
      ${msgAv(p, 42)}<div style="min-width:0"><div class="fw-bold d-flex align-items-center">${msgName(p)}</div>
      <div class="small text-nx-muted">${msgPresence(p) || esc(p.role)}</div></div></div>
    <div id="msg-body" style="flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center">
      <div class="text-center text-nx-muted small">Start a conversation with ${esc(p.name)} 👋<br>Say hello below.</div></div>
    ${msgComposer()}`;
  msgBindInput();
  document.getElementById('msg-input')?.focus();
}

async function sendMsgReply() {
  const inp = document.getElementById('msg-input'); if (!inp) return;
  const body = inp.value.trim(); if (!body) return;
  inp.disabled = true;
  const r = _newTo
    ? await api('msg_send', { to_user_id: _newTo, subject: 'Direct message', category: 'general', body }, 'POST')
    : await api('msg_send', { thread_id: _msgCur, body }, 'POST');
  inp.disabled = false;
  if (!r.ok) { toast(r.msg || 'Could not send.', 'error'); return; }
  inp.value = '';
  if (_newTo) { _newTo = 0; _msgCur = r.thread_id; await loadMsgThreads(); await openThread(r.thread_id); return; }
  await refreshThread(true); loadMsgThreads(); inp.focus();
}

async function openMsgSettings() {
  const r = await api('msg_settings'); if (r.ok) MSG_SET = r.settings;
  [['ms-online', 'show_online'], ['ms-seen', 'show_last_seen'], ['ms-read', 'read_receipts'], ['ms-enter', 'enter_to_send'], ['ms-sound', 'sound']]
    .forEach(([id, k]) => { document.getElementById(id).checked = +MSG_SET[k] === 1; });
  openModal('modal-msgset');
}
async function saveMsgSettings() {
  const v = id => document.getElementById(id).checked ? 1 : 0;
  const s = { show_online: v('ms-online'), show_last_seen: v('ms-seen'), read_receipts: v('ms-read'), enter_to_send: v('ms-enter'), sound: v('ms-sound') };
  const r = await api('msg_settings_save', s, 'POST');
  if (!r.ok) { toast(r.msg || 'Could not save.', 'error'); return; }
  MSG_SET = s; closeModal('modal-msgset'); toast('Message settings saved', 'success');
  loadMsgThreads(); if (_msgTab === 'people') loadContacts(); if (_msgCur) openThread(_msgCur);
}

// ── INTERNET MONITOR ──────────────────────────────────────────
const NET = { ms: null, mbps: null };
let _netState = null;
function netInit() {
  if (document.getElementById('nx-net')) return;
  const p = document.createElement('div'); p.id = 'nx-net'; p.title = 'Click to re-test your connection'; p.onclick = () => netCheck(true);
  document.body.appendChild(p);
  const b = document.createElement('div'); b.id = 'nx-offline'; b.className = 'd-none';
  b.innerHTML = '<i class="fa fa-wifi me-2"></i>No internet connection. Sales and changes will not save until you are back online.';
  document.body.appendChild(b);
  window.addEventListener('offline', () => netCheck(false));
  window.addEventListener('online',  () => netCheck(true));
  netCheck(true);
  setInterval(() => netCheck(false), 15000);
  setInterval(() => netCheck(true), 90000);
}
async function netCheck(speed) {
  if (!navigator.onLine) { netSet(false); return; }
  try {
    let t0 = performance.now();
    const r = await fetch(SELF + '?action=ping&t=' + Date.now(), { cache: 'no-store' });
    if (!r.ok) throw new Error('bad');
    await r.text();
    NET.ms = Math.round(performance.now() - t0);
    if (speed) {
      t0 = performance.now();
      const r2 = await fetch(SELF + '?action=ping&size=150000&t=' + Date.now(), { cache: 'no-store' });
      const buf = await r2.arrayBuffer();
      NET.mbps = (buf.byteLength * 8) / ((performance.now() - t0) / 1000) / 1e6;
    }
    netSet(true);
  } catch (e) { netSet(false); }
}
function netSet(ok) {
  const p = document.getElementById('nx-net'), b = document.getElementById('nx-offline'); if (!p) return;
  let state = 'good';
  if (!ok) state = 'off';
  else if (NET.ms > 1200 || (NET.mbps !== null && NET.mbps < 0.4)) state = 'slow';
  else if (NET.ms > 500 || (NET.mbps !== null && NET.mbps < 1.5)) state = 'fair';
  const col = { good:'#22c55e', fair:'#1E9E52', slow:'#f97316', off:'#ef4444' }[state];
  const label = { good:'Online', fair:'Fair', slow:'Slow connection', off:'Offline' }[state];
  p.innerHTML = `<span class="dot" style="background:${col}"></span><span>${label}${ok ? ` · ${NET.ms} ms${NET.mbps !== null ? ' · ' + NET.mbps.toFixed(1) + ' Mbps' : ''}` : ''}</span>`;
  b.classList.toggle('d-none', ok);
  if (_netState !== null && _netState !== state) {
    if (state === 'off') { toast('You are offline', 'error'); try { voiceSpeak('Warning. You are offline. Please check your internet connection.', 'Tahadhari. Huna mtandao. Tafadhali angalia muunganisho wako.'); } catch (e) {} }
    else if (_netState === 'off') { toast('Back online', 'success'); try { voiceSpeak('You are back online.', 'Mtandao umerudi.'); } catch (e) {} }
    else if (state === 'slow') toast('Your internet is slow', 'info');
  }
  _netState = state;
}

// ── WEAK PASSWORD NOTICE ──────────────────────────────────────
function weakPwdBanner() {
  if (!CU || !CU.pwd_weak || sessionStorage.getItem('nx_pwd_dismiss') || document.getElementById('pwd-banner')) return;
  const b = document.createElement('div'); b.id = 'pwd-banner'; b.className = 'pwd-banner';
  b.innerHTML = `<i class="fa fa-triangle-exclamation" style="font-size:1.2rem"></i>
    <span style="flex:1">Your password is weak. Change it now to prevent your account from being compromised.</span>
    <button class="go" onclick="openPwdChange()">Change now</button>
    <button class="x" onclick="dismissPwdBanner()" title="Dismiss">×</button>`;
  document.body.appendChild(b);
}
function dismissPwdBanner() { sessionStorage.setItem('nx_pwd_dismiss', '1'); document.getElementById('pwd-banner')?.remove(); }
function openPwdChange() {
  ['pw-cur', 'pw-new', 'pw-new2'].forEach(id => document.getElementById(id).value = '');
  document.getElementById('pw-err').classList.add('d-none');
  openModal('modal-pwd');
}
async function submitPwdChange() {
  const err = document.getElementById('pw-err'); err.classList.add('d-none');
  const r = await api('password_change', {
    current: document.getElementById('pw-cur').value,
    new: document.getElementById('pw-new').value,
    new2: document.getElementById('pw-new2').value,
  }, 'POST');
  if (r.ok) { CU.pwd_weak = 0; document.getElementById('pwd-banner')?.remove(); closeModal('modal-pwd'); toast('Password updated. Your account is safer now.', 'success'); }
  else { err.textContent = r.msg || 'Could not update password.'; err.classList.remove('d-none'); }
}

