async function saveEtimsSettings(branch_id) {
  const res = await api('branch_etims_save', {
    branch_id,
    etims_enabled:      document.getElementById('etims-enabled').checked ? 1 : 0,
    etims_pin:          document.getElementById('etims-pin').value,
    etims_branch_code:  document.getElementById('etims-branch-code').value,
    etims_device_serial:document.getElementById('etims-device-serial').value,
    etims_env:          document.getElementById('etims-env').value,
  }, 'POST');
  if (res.ok) toast('eTIMS settings saved', 'success');
  else toast(res.msg || 'Failed.', 'error');
}

async function retryQueue() {
  const res = await api('etims_retry_queue');
  if (res.ok) {
    const r = res.results;
    toast(`Retry complete: ${r.ok} submitted, ${r.failed} failed out of ${r.attempted}`, r.failed === 0 ? 'success' : 'info');
    renderEtims(document.getElementById('nx-content'));
  } else toast('Retry failed: ' + (res.msg || ''), 'error');
}

async function testEtims(branch_id) {
  toast('Testing connection...', 'info');
  // Test by hitting the eTIMS initialization endpoint
  const res = await api('branch_etims_get', { branch_id });
  if (res.ok && res.branch.etims_enabled) {
    toast('Credentials saved. Real test happens on next sale in sandbox mode.', 'info');
  } else {
    toast('Enable eTIMS first to test', 'error');
  }
}

// ── DEVICE CHECK (printer / scanner) ──────────────────────────
function checkDevices() {
  sessionStorage.setItem('nx_devices_checked', '1');
  const overlay = document.getElementById('device-check-overlay');
  if (!overlay) return;
  overlay.classList.remove('d-none');
  document.getElementById('dc-checking').classList.remove('d-none');
  document.getElementById('dc-results').classList.add('d-none');
  document.getElementById('dc-status-title').textContent = 'Checking devices…';
  document.getElementById('dc-status-sub').textContent = 'Looking for a connected receipt printer and barcode scanner';

  setTimeout(() => {
    document.getElementById('dc-checking').classList.add('d-none');
    document.getElementById('dc-results').classList.remove('d-none');
    document.getElementById('dc-status-title').textContent = 'Confirm your hardware';
    document.getElementById('dc-status-sub').textContent = "We can't auto-detect USB devices from the browser — please confirm what's plugged in";
    refreshDeviceStatusUI();
  }, 1400);
}

function refreshDeviceStatusUI() {
  const printerOk = localStorage.getItem('nx_printer_confirmed') === '1';
  const scannerOk = localStorage.getItem('nx_scanner_confirmed') === '1';
  const ps = document.getElementById('dc-printer-status');
  const ss = document.getElementById('dc-scanner-status');
  if (ps) { ps.textContent = printerOk ? '✓ Confirmed connected — auto-print on' : 'Not confirmed yet'; ps.style.color = printerOk ? 'var(--nx-green)' : 'var(--nx-muted)'; }
  if (ss) { ss.textContent = scannerOk ? '✓ Confirmed connected' : 'Not confirmed yet'; ss.style.color = scannerOk ? 'var(--nx-green)' : 'var(--nx-muted)'; }
}

function confirmDevice(type, connected) {
  localStorage.setItem('nx_' + type + '_confirmed', connected ? '1' : '0');
  refreshDeviceStatusUI();
  toast(type === 'printer'
    ? (connected ? 'Printer confirmed — receipts will auto-print' : 'Printer skipped — print manually')
    : (connected ? 'Scanner confirmed' : 'Scanner skipped'), 'info');
}

function closeDeviceCheck() {
  document.getElementById('device-check-overlay')?.classList.add('d-none');
}

// ── STK PUSH ─────────────────────────────────────────────────
let _stkTrackingId = null;
let _stkPollTimer  = null;
let _stkMpesaCode  = '';

async function triggerSTK() {
  const total = parseFloat(document.getElementById('cs-total').textContent.replace(/[^0-9.]/g, '') || 0);
  if (!total || total <= 0) { toast('Add items to the cart first', 'error'); return; }

  const phoneEl    = document.getElementById('stk-phone');
  const phone      = phoneEl?.value?.trim() || '';
  if (!phone) { toast('Enter customer phone number first', 'error'); phoneEl?.focus(); return; }

  const custName   = _posCustSelectedData?.name || 'Customer';

  const stkBtn = document.querySelector('#mpesa-row button[onclick="triggerSTK()"]');
  if (stkBtn) { stkBtn.disabled = true; stkBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>'; }

  const res = await api('pesapal_checkout', { phone, amount: total, customer_name: custName }, 'POST');

  if (stkBtn) { stkBtn.disabled = false; stkBtn.innerHTML = '<i class="fa fa-mobile-screen-button"></i> Pay'; }

  if (!res.ok) { toast('Pesapal error: ' + (res.msg || 'Unknown error'), 'error'); return; }

  // Save cart state to sessionStorage before redirect so we can resume after return
  sessionStorage.setItem('pesapal_cart', JSON.stringify({
    cart,
    customer_id:    document.getElementById('pos-customer').value,
    discount:       document.getElementById('cs-discount').value,
    disc_type:      document.getElementById('disc-type').value,
    note:           '',
    tracking_id:    res.order_tracking_id,
    merchant_ref:   res.merchant_reference,
  }));

  // Redirect customer to Pesapal hosted checkout page
  window.location.href = res.redirect_url;
}

let _darajaPollTimer = null;

async function triggerDarajaDemo() {
  const total = parseFloat(document.getElementById('cs-total')?.textContent?.replace(/[^0-9.]/g, '') || 0);
  if (!total || total <= 0) { toast('Add items to the cart first', 'error'); return; }

  const phone = document.getElementById('stk-phone')?.value?.trim() || '';
  if (!phone) { toast('Enter the customer\'s phone number first — the prompt has nowhere to go without it.', 'error'); document.getElementById('stk-phone')?.focus(); return; }
  const custName = _posCustSelectedData?.name || 'Customer';

  const btn = document.getElementById('daraja-demo-btn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Sending...'; }

  const res = await api('daraja_stk_push', { amount: total, phone }, 'POST');

  if (!res.ok) {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-satellite-dish me-1"></i>Try Daraja Sandbox Demo'; }
    toast('Daraja error: ' + (res.msg || 'Unknown error'), 'error');
    return;
  }

  showStkWaitingModal(phone, total, custName);

  let attempts = 0;
  clearInterval(_darajaPollTimer);
  // Give Safaricom's sandbox a few seconds to actually register the push
  // before checking status — querying instantly tends to return a stray
  // "still processing" body that looks like a cancel if you're not careful.
  setTimeout(() => {
    _darajaPollTimer = setInterval(async () => {
      attempts++;
      const q = await api('daraja_stk_query', { checkout_request_id: res.checkout_request_id });

      if (q.ok && q.paid) {
        clearInterval(_darajaPollTimer);
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-satellite-dish me-1"></i>Try Daraja Sandbox Demo'; }
        const mpesaInput = document.getElementById('pos-mpesa');
        if (mpesaInput) mpesaInput.value = 'DEMOSTK' + Date.now().toString().slice(-6);
        const paidInput = document.getElementById('pos-paid');
        if (paidInput) { paidInput.value = total.toFixed(2); updateCartTotals(); }
        showStkSuccess(custName, total, mpesaInput?.value);
        return;
      }
      if (q.ok && q.cancelled) {
        clearInterval(_darajaPollTimer);
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-satellite-dish me-1"></i>Try Daraja Sandbox Demo'; }
        closeStkModal();
        toast('Payment not completed: ' + (q.msg || 'cancelled on sandbox.'), 'error');
        return;
      }
      // Still processing — leave the waiting card exactly as it is and poll again.
      if (attempts >= 40) { // ~2 minutes of real polling after the initial delay
        clearInterval(_darajaPollTimer);
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fa fa-satellite-dish me-1"></i>Try Daraja Sandbox Demo'; }
        closeStkModal();
        toast('Demo timed out waiting for sandbox response.', 'error');
      }
    }, 3000);
  }, 4000);
}

function showStkWaitingModal(phone, amount, name) {
  document.getElementById('stk-modal-amount').textContent = fmt(amount);
  document.getElementById('stk-step-waiting').classList.remove('d-none');
  openModal('modal-stk');
}

function showStkSuccess(name, amount, code) {
  closeStkModal();
  _lastMpesaPayerName = name || '';
  document.getElementById('payment-success-name').textContent   = name ? name + ', thank you!' : 'Thank you!';
  document.getElementById('payment-success-amount').textContent = fmt(amount);
  document.getElementById('payment-success-code').textContent   = code ? 'M-Pesa Code: ' + code : '';
  document.getElementById('payment-success-overlay').classList.remove('d-none');
  spawnPaymentSuccessConfetti();
  _sfx.sale();
}

function closePaymentSuccessOverlay() {
  document.getElementById('payment-success-overlay').classList.add('d-none');
}

function spawnPaymentSuccessConfetti() {
  const wrap = document.getElementById('payment-success-confetti');
  if (!wrap) return;
  wrap.innerHTML = '';
  const colors = ['#1E9E52','#22c55e','#3b82f6','#ef4444','#a78bfa','#17C548'];
  for (let i = 0; i < 40; i++) {
    const d = document.createElement('div');
    d.style.cssText = `position:absolute;width:9px;height:9px;border-radius:50%;
      left:${Math.random()*100}%;top:${-10-Math.random()*20}%;
      background:${colors[i%colors.length]};
      animation:stkFall ${1.5+Math.random()*1.5}s ease forwards;
      animation-delay:${Math.random()*0.6}s`;
    wrap.appendChild(d);
  }
}

function closeStkModal() {
  clearInterval(_stkPollTimer);
  clearInterval(_darajaPollTimer);
  clearInterval(_darajaSplitPollTimer);
  closeModal('modal-stk');
}

function spawnStkConfetti() {
  const wrap = document.getElementById('stk-confetti');
  if (!wrap) return;
  wrap.innerHTML = '';
  const colors = ['#1E9E52','#22c55e','#3b82f6','#ef4444','#a78bfa','#17C548'];
  for (let i = 0; i < 22; i++) {
    const d = document.createElement('div');
    d.style.cssText = `position:absolute;width:7px;height:7px;border-radius:50%;
      left:${Math.random()*100}%;top:${Math.random()*30}%;
      background:${colors[i%colors.length]};
      animation:stkFall ${0.9+Math.random()*0.7}s ease forwards;
      animation-delay:${Math.random()*0.5}s`;
    wrap.appendChild(d);
  }
}

// ── INIT ──────────────────────────────────────────────────────
// ══ VERIFIED BADGE + PROFILE UI ══════════════════════════════
function verifiedBadge(size = 16) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" role="img" aria-label="Verified" style="flex-shrink:0;vertical-align:-3px;margin-left:4px;filter:drop-shadow(0 1px 2px rgba(0,149,246,.45))"><title>Verified</title>
    <rect x="4" y="4" width="16" height="16" rx="4.5" fill="#0095f6"/>
    <rect x="4" y="4" width="16" height="16" rx="4.5" fill="#0095f6" transform="rotate(45 12 12)"/>
    <path d="M7.9 12.4l2.9 2.8 5.5-6" fill="none" stroke="#fff" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

function applyProfileUI() {
  if (!CU) return;
  const setAvatar = el => {
    if (!el || !CU.photo) return;
    el.textContent = '';
    el.style.backgroundImage = 'url("' + CU.photo.replace(/"/g, '%22') + '")';
    el.style.backgroundSize = 'cover';
    el.style.backgroundPosition = 'center';
  };
  setAvatar(document.getElementById('sb-avatar'));
  setAvatar(document.getElementById('lock-avatar'));
setAvatar(document.getElementById('tb-avatar'));

  const badge = CU.id_verified ? verifiedBadge(15) : '';
  const nm = document.getElementById('sb-name');
  if (nm) { nm.style.display = 'flex'; nm.style.alignItems = 'center'; nm.innerHTML = '<span class="text-truncate" style="min-width:0">' + esc(CU.name) + '</span>' + badge; }
  const tb = document.getElementById('tb-username');
  if (tb) tb.innerHTML = esc(CU.name) + badge;
  const ln = document.getElementById('lock-name');
  if (ln) ln.innerHTML = esc(CU.name) + badge;

  if (CU.id_verified) {
    const v = document.getElementById('sb-verify');
    if (v) v.outerHTML = '<div id="sb-verify" style="font-size:.68rem;color:#0095f6;font-weight:600">Verified account</div>';
    document.getElementById('pos-verify-li')?.remove();
  }

  const chip = document.querySelector('.user-chip');
  if (chip && !chip.dataset.wired) {
    chip.dataset.wired = '1'; chip.style.cursor = 'pointer'; chip.title = 'Edit profile';
    chip.addEventListener('click', e => { if (e.target.closest('a')) return; openProfile(); });
  }
}

// ══ EDIT PROFILE ═════════════════════════════════════════════
let _pfFile = null, _pfPreviewUrl = null;

function pfRenderAvatar(src) {
  const el = document.getElementById('pf-avatar');
  if (src) { el.textContent = ''; el.style.backgroundImage = 'url("' + src.replace(/"/g, '%22') + '")'; }
  else { el.style.backgroundImage = ''; el.textContent = (CU.name || 'U').charAt(0).toUpperCase(); }
}
function openProfile() {
  if (!CU) return;
  _pfFile = null;
  document.getElementById('pf-file').value = '';
  document.getElementById('pf-name').innerHTML = esc(CU.name) + (CU.id_verified ? verifiedBadge(18) : '');
  document.getElementById('pf-role').textContent = CU.role_name || '';
  document.getElementById('pf-phone').value = CU.phone || '';
  document.getElementById('pf-note').textContent = CU.photo ? 'Tap the picture to change it.' : 'No profile picture yet — upload one so your team can recognise you.';
  document.getElementById('pf-verify-row').innerHTML = CU.id_verified
    ? '<div class="small" style="color:#0095f6;font-weight:600">' + verifiedBadge(16) + ' Identity verified</div>'
    : '<button class="btn btn-sm vf-blue w-100" onclick="closeModal(\'modal-profile\');setTimeout(openIdVerify,300)"><i class="fa fa-id-card me-1"></i>Verify my identity</button>';
  pfRenderAvatar(CU.photo);
  closeSidebar();
  openModal('modal-profile');
}
function pfPick(inp) {
  const f = inp.files[0];
  if (!f) return;
  if (!/^image\/(jpeg|png|webp)$/.test(f.type)) { toast('Use a JPG, PNG or WEBP photo', 'error'); inp.value = ''; return; }
  if (f.size > 3 * 1024 * 1024) { toast('Photo too large (max 3MB)', 'error'); inp.value = ''; return; }
  _pfFile = f;
  if (_pfPreviewUrl) URL.revokeObjectURL(_pfPreviewUrl);
  _pfPreviewUrl = URL.createObjectURL(f);
  pfRenderAvatar(_pfPreviewUrl);
}
async function saveProfile() {
  const params = { phone: document.getElementById('pf-phone').value.trim() };
  if (_pfFile) params.photo = _pfFile;
  const res = await api('profile_save', params, 'POST');
  if (res.ok) {
    CU.phone = res.phone || '';
    if (res.photo) CU.photo = res.photo;
    applyProfileUI();
    toast('Profile updated', 'success');
    closeModal('modal-profile');
  } else toast(res.msg || 'Could not save profile.', 'error');
}

// ══ ID VERIFICATION WIZARD (runs in the browser, photos never stored) ══
const VF = { stream: null, idDescriptor: null, selfieDescriptor: null, idText: '', country: 'KE', busy: false };
let _vfLibsPromise = null;

function loadScriptOnce(src) {
  return new Promise((resolve, reject) => {
    if (document.querySelector('script[data-idv="' + src + '"]')) return resolve();
    const s = document.createElement('script');
    s.src = src; s.dataset.idv = src;
    s.onload = resolve;
    s.onerror = () => { s.remove(); reject(new Error('Could not load verification tools. Check your internet and try again.')); };
    document.head.appendChild(s);
  });
}
function vfLoadLibs() {
  if (!_vfLibsPromise) {
    _vfLibsPromise = (async () => {
      await loadScriptOnce('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');
      await loadScriptOnce('https://cdn.jsdelivr.net/npm/@vladmandic/face-api/dist/face-api.js');
      const M = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api/model/';
      await Promise.all([
        faceapi.nets.ssdMobilenetv1.loadFromUri(M),
        faceapi.nets.faceLandmark68Net.loadFromUri(M),
        faceapi.nets.faceRecognitionNet.loadFromUri(M),
      ]);
    })().catch(e => { _vfLibsPromise = null; throw e; });
  }
  return _vfLibsPromise;
}
async function vfFileToCanvas(file, maxDim) {
  const bmp = await createImageBitmap(file);
  const scale = Math.min(1, maxDim / Math.max(bmp.width, bmp.height));
  const c = document.createElement('canvas');
  c.width = Math.round(bmp.width * scale); c.height = Math.round(bmp.height * scale);
  c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height);
  if (bmp.close) bmp.close();
  return c;
}
function vfLev(a, b) {
  const m = a.length, n = b.length;
  if (!m) return n; if (!n) return m;
  let p = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const c = [i];
    for (let j = 1; j <= n; j++) c[j] = Math.min(p[j] + 1, c[j - 1] + 1, p[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    p = c;
  }
  return p[n];
}

function vfShow(step) {
  ['id', 'check', 'face', 'match', 'fail', 'done'].forEach(s => document.getElementById('vf-' + s)?.classList.toggle('d-none', s !== step));
  const n = { id: 1, check: 1, face: 2, match: 3, fail: 3, done: 3 }[step];
  document.querySelectorAll('.vf-dot').forEach(d => {
    const i = +d.dataset.n;
    d.classList.toggle('active', i === n && step !== 'done');
    d.classList.toggle('done', i < n || step === 'done');
  });
}
function vfError(msg) {
  const el = document.getElementById('vf-err');
  el.textContent = msg || '';
  el.classList.toggle('d-none', !msg);
}
function vfCheckMsg(msg) { const el = document.getElementById('vf-check-msg'); if (el) el.textContent = msg; }

// ══ NYMIX STAFF CARD ═════════════════════════════════════════
let _cardData = null, _cardSheetUrl = null;

function cardSeed(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function cardRng(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function cardLoadImg(src){return new Promise(res=>{if(!src)return res(null);const i=new Image();i.onload=()=>res(i);i.onerror=()=>res(null);i.src=src;});}
function cardRR(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath();}
function cardFit(c,t,maxW,size,weight,fam){let s=size;do{c.font=weight+' '+s+'px '+fam;s-=2;}while(c.measureText(t).width>maxW&&s>14);}
function cardGuilloche(c,W,H,rnd,color,alpha){
  c.save();c.globalAlpha=alpha;c.strokeStyle=color;c.lineWidth=1;
  const n=34,f1=2+rnd()*4,f2=3+rnd()*5,p1=rnd()*6.28,p2=rnd()*6.28,a1=18+rnd()*22,a2=10+rnd()*16;
  for(let k=0;k<n;k++){c.beginPath();for(let x=0;x<=W;x+=4){const y=H*(k/n)+Math.sin(x/W*Math.PI*f1+p1+k*.18)*a1+Math.sin(x/W*Math.PI*f2+p2-k*.11)*a2;x?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();}
  c.restore();
}
function cardMicrotext(c,x,y,w,text,color){c.save();c.font='700 7px Arial';c.fillStyle=color;c.textBaseline='top';let s='';while(c.measureText(s).width<w)s+=text+' ';c.fillText(s,x,y);c.restore();}
function cardFoil(c,x,y,r,rnd){
  c.save();c.beginPath();c.arc(x,y,r,0,7);c.clip();
  const g=c.createLinearGradient(x-r,y-r,x+r,y+r);
  ['#ff5f6d','#ffc371','#f9f871','#7bffb2','#5ec8ff','#b58cff','#ff5f6d'].forEach((col,i,a)=>g.addColorStop(i/(a.length-1),col));
  c.fillStyle=g;c.fillRect(x-r,y-r,2*r,2*r);
  c.globalAlpha=.35;c.strokeStyle='#fff';c.lineWidth=1.5;
  for(let i=1;i<9;i++){c.beginPath();c.arc(x+(rnd()-.5)*10,y+(rnd()-.5)*10,i*r/9,0,7);c.stroke();}
  c.globalAlpha=.55;c.fillStyle='#0b1020';c.font='700 '+Math.round(r*.8)+'px Arial';c.textAlign='center';c.textBaseline='middle';c.fillText('NX',x,y+2);
  c.restore();
}

async function cardDrawFront(d){
  const W=1011,H=638,cv=document.createElement('canvas');cv.width=W;cv.height=H;
  const c=cv.getContext('2d'),rnd=cardRng(cardSeed(d.card_no)),F='"DM Sans",Arial,sans-serif',FH='"Space Grotesk",Arial,sans-serif';
  const [logo,photo]=await Promise.all([cardLoadImg('logo.png'),cardLoadImg(d.photo)]);
  cardRR(c,0,0,W,H,34);c.save();c.clip();
  let g=c.createLinearGradient(0,0,W,H);g.addColorStop(0,'#0a0f1e');g.addColorStop(.55,'#161d38');g.addColorStop(1,'#2a1c08');
  c.fillStyle=g;c.fillRect(0,0,W,H);
  cardGuilloche(c,W,H,rnd,'#1E9E52',.20);cardGuilloche(c,W,H,rnd,'#60a5fa',.12);
  g=c.createLinearGradient(0,0,W,0);g.addColorStop(0,'#1E9E52');g.addColorStop(1,'#17C548');c.fillStyle=g;c.fillRect(0,0,W,132);
  c.fillStyle='rgba(0,0,0,.18)';cardRR(c,40,26,80,80,18);c.fill();
  if(logo){c.drawImage(logo,46,32,68,68);}
  else{c.fillStyle='#000';c.font='700 38px '+FH;c.textAlign='center';c.textBaseline='middle';c.fillText('NX',80,66);c.textAlign='left';}
  c.textAlign='left';c.textBaseline='alphabetic';c.fillStyle='#000';
  c.font='700 46px '+FH;c.fillText('NYMIX TECH',144,72);
  c.font='600 19px '+F;c.fillText('STAFF AUTHORIZATION CARD',146,104);
  cardMicrotext(c,0,136,W,'NYMIX TECH AUTHORIZED PERSONNEL '+d.card_no,'rgba(255,255,255,.5)');
  // photo
  c.save();cardRR(c,50,180,250,310,20);c.clip();
  if(photo){const s=Math.max(250/photo.width,310/photo.height),w=photo.width*s,h=photo.height*s;c.drawImage(photo,50+(250-w)/2,180+(310-h)*0.25,w,h);}
  else{c.fillStyle='#1e2333';c.fillRect(50,180,250,310);c.fillStyle='#1E9E52';c.font='700 120px '+FH;c.textAlign='center';c.textBaseline='middle';c.fillText((d.name||'?').charAt(0).toUpperCase(),175,335);}
  c.restore();
  c.textAlign='left';c.textBaseline='alphabetic';
  c.strokeStyle='#1E9E52';c.lineWidth=4;cardRR(c,50,180,250,310,20);c.stroke();
  // details
  c.fillStyle='#fff';cardFit(c,d.name,560,46,'700',FH);c.fillText(d.name,340,225);
  c.fillStyle='#1E9E52';c.font='700 26px '+F;c.fillText(String(d.role).toUpperCase(),340,268);
  c.fillStyle='#cbd5e1';c.font='500 24px '+F;c.fillText(d.business,340,314);
  c.fillStyle='#94a3b8';c.font='500 21px '+F;c.fillText('Branch: '+d.branch,340,350);
  c.fillStyle='#64748b';c.font='600 15px '+F;c.fillText('CARD NO.',340,400);
  c.fillStyle='#fff';c.font='700 30px "Courier New",monospace';c.fillText(d.card_no,340,434);
  c.fillStyle='#64748b';c.font='600 15px '+F;c.fillText('ISSUED',340,472);
  c.fillStyle='#e2e8f0';c.font='600 22px '+F;c.fillText(d.issued,340,498);
  cardFoil(c,880,400,72,rnd);
  // authorization statement
  c.fillStyle='rgba(30,158,82,.14)';c.fillRect(0,530,W,108);
  c.fillStyle='#fff';c.font='700 22px '+F;c.fillText('THIS CARD IS AN AUTHORIZATION TO USE NYMIX TECH SYSTEMS.',50,572);
  c.fillStyle='#94a3b8';c.font='500 16px '+F;c.fillText('Property of NYMIX TECH. Valid only if the card number verifies online. Non-transferable.',50,602);
  cardMicrotext(c,0,622,W,'NYMIX TECH AUTHORIZED '+d.card_no.replace(/-/g,''),'rgba(255,255,255,.45)');
  c.restore();
  c.strokeStyle='rgba(30,158,82,.7)';c.lineWidth=5;cardRR(c,2.5,2.5,W-5,H-5,32);c.stroke();
  return cv;
}

async function cardDrawBack(d){
  const W=1011,H=638,cv=document.createElement('canvas');cv.width=W;cv.height=H;
  const c=cv.getContext('2d'),rnd=cardRng(cardSeed(d.card_no)),r2=cardRng(cardSeed(d.card_no+d.code)),F='"DM Sans",Arial,sans-serif';
  cardRR(c,0,0,W,H,34);c.save();c.clip();
  c.fillStyle='#f7f3ea';c.fillRect(0,0,W,H);
  cardGuilloche(c,W,H,rnd,'#0b1020',.10);
  c.fillStyle='#0b1020';c.fillRect(0,46,W,86);
  c.fillStyle='#1E9E52';c.font='700 30px '+F;c.textAlign='left';c.fillText('NYMIX TECH  |  AUTHORIZED USE ONLY',50,102);
  cardMicrotext(c,0,138,W,'NYMIX TECH AUTHORIZED PERSONNEL '+d.card_no,'rgba(11,16,32,.55)');
  c.fillStyle='#1e293b';c.font='500 21px '+F;
  ['This card is an authorization to use NYMIX TECH systems and remains',
   'the property of NYMIX TECH. It is non-transferable and must be shown on',
   'request. Copying, alteration or misuse is an offence and leads to',
   'immediate revocation. If found, please return to:'].forEach((t,i)=>c.fillText(t,50,186+i*30));
  c.font='700 21px '+F;c.fillText(d.business+' — '+d.branch+(d.phone?'  |  '+d.phone:''),50,318);
  // security code
  c.fillStyle='#0b1020';cardRR(c,50,346,470,110,14);c.fill();
  c.fillStyle='#1E9E52';c.font='700 15px '+F;c.fillText('SECURITY CODE — KEEP PRIVATE',72,376);
  c.fillStyle='#fff';c.font='700 40px "Courier New",monospace';c.fillText(d.code,72,428);
  // signature
  c.fillStyle='#fff';c.fillRect(560,346,400,110);c.strokeStyle='#94a3b8';c.lineWidth=2;c.strokeRect(560,346,400,110);
  c.fillStyle='#94a3b8';c.font='600 14px '+F;c.fillText('AUTHORIZED SIGNATURE',572,442);
  // barcode
  let x=50;c.fillStyle='#0b1020';while(x<560){const w=2+Math.floor(r2()*5);if(r2()>.35)c.fillRect(x,482,w,58);x+=w+2;}
  c.font='600 15px "Courier New",monospace';c.fillText(d.card_no,50,562);
  cardFoil(c,880,520,58,rnd);
  c.fillStyle='#475569';cardFit(c,'Verify: '+d.verify_url,W-100,15,'500',F);c.fillText('Verify: '+d.verify_url,50,596);
  cardMicrotext(c,0,618,W,'NYMIX TECH AUTHORIZED '+d.card_no.replace(/-/g,''),'rgba(11,16,32,.5)');
  c.restore();
  c.strokeStyle='rgba(11,16,32,.55)';c.lineWidth=5;cardRR(c,2.5,2.5,W-5,H-5,32);c.stroke();
  return cv;
}

async function cardDrawSheet(d){
  try{await document.fonts.load('700 20px "Space Grotesk"');await document.fonts.load('600 20px "DM Sans"');}catch(e){}
  const [f,b]=await Promise.all([cardDrawFront(d),cardDrawBack(d)]);
  const s=document.createElement('canvas');s.width=1131;s.height=1470;
  const c=s.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,1131,1470);
  c.fillStyle='#64748b';c.font='600 20px Arial';
  c.fillText('FRONT',60,48);c.drawImage(f,60,66);
  c.fillText('BACK',60,66+638+46);c.drawImage(b,60,66+638+66);
  return s;
}

function cvShowPanel(p){['verify','gen','preview','done'].forEach(x=>document.getElementById('cv-'+x).classList.toggle('d-none',x!==p));}
function cvErr(m){const e=document.getElementById('cv-err');e.textContent=m||'';e.classList.toggle('d-none',!m);}
async function cvRender(card){
  _cardData=card;
  const sheet=await cardDrawSheet(card);
  _cardSheetUrl=sheet.toDataURL('image/jpeg',0.92);
  document.getElementById('cv-preview-img').src=_cardSheetUrl;
}
function cvDownload(){
  if(!_cardSheetUrl)return;
  const a=document.createElement('a');a.href=_cardSheetUrl;a.download='NYMIX-Card-'+(_cardData?.card_no||'')+'.jpg';document.body.appendChild(a);a.click();a.remove();
}
function cvPrint(){
  if(!_cardSheetUrl)return;
  const w=window.open('','_blank','width=900,height=800');
  w.document.write('<!DOCTYPE html><html><head><title>NYMIX Card</title><style>@page{margin:8mm}body{margin:0;text-align:center}img{max-width:100%}</style></head><body><img src="'+_cardSheetUrl+'"></body></html>');
  w.document.close();w.focus();setTimeout(()=>w.print(),400);
}

// Entry point for every "verify / get my card" button
function openIdVerify() {
  cvErr('');
  const need = CU.card_required && !CU.id_verified;
  document.getElementById('cv-close').classList.toggle('d-none', !!need);
  if (CU.card_required && !CU.id_verified) cvShowPanel('verify');
  else if (!CU.card_issued && !CU.card_required) cvShowPanel('gen');
  else cvShowPanel('done');
  closeSidebar();
  openModal('modal-cardv');
}

// ── Card photo → OCR → auto-validate ──
const _cvS = { no: '', code: '', busy: false };
const cvHex = s => s.replace(/[OQ]/g, '0').replace(/[IL]/g, '1').replace(/S/g, '5');
const cvDig = s => cvHex(s).replace(/B/g, '8').replace(/Z/g, '2');

function cvParse(text) {
  let t = text.toUpperCase().replace(/\|/g, 'I'), no = '', code = '';
  const m = t.match(/NX\s*[-–—_.]?\s*([0-9A-Z]{8})\s*[-–—_.]?\s*([0-9OQILSBZ]{4})/);
  if (m) {
    const a = cvHex(m[1]);
    if (/^[0-9A-F]{8}$/.test(a)) { no = 'NX-' + a + '-' + cvDig(m[2]); t = t.replace(m[0], ' '); }
  }
  const si = t.indexOf('SECURITY');
  const re = /([0-9A-FOQILS]{4})\s*[-–—_.]?\s*([0-9A-FOQILS]{4})\s*[-–—_.]?\s*([0-9A-FOQILS]{4})/;
  const cm = (si >= 0 ? t.slice(si) : t).match(re);
  if (cm) {
    const c = cvHex(cm[1] + cm[2] + cm[3]);
    if (/^[0-9A-F]{12}$/.test(c)) code = c.match(/.{4}/g).join('-');
  }
  return { no, code };
}
async function cvOcrFile(file) {
  const cv = await vfFileToCanvas(file, 1800);
  const inv = document.createElement('canvas'); inv.width = cv.width; inv.height = cv.height;
  const ictx = inv.getContext('2d'); ictx.drawImage(cv, 0, 0);
  const im = ictx.getImageData(0, 0, inv.width, inv.height), p = im.data;
  for (let i = 0; i < p.length; i += 4) { p[i] = 255 - p[i]; p[i + 1] = 255 - p[i + 1]; p[i + 2] = 255 - p[i + 2]; }
  ictx.putImageData(im, 0, 0);
  const a = await Tesseract.recognize(cv, 'eng');
  const b = await Tesseract.recognize(inv, 'eng');
  return (a.data.text || '') + '\n' + (b.data.text || '');
}
function cvChips() {
  const set = (id, ok, label, val) => { const e = document.getElementById(id); if (!e) return; e.className = 'hr-chip2 ' + (ok ? 'g' : 'w'); e.textContent = ok ? label + ': ✓ ' + (id === 'cv-chip-no' ? val : 'read') : label + ': not read yet'; };
  set('cv-chip-no', !!_cvS.no, 'Card number', _cvS.no);
  set('cv-chip-code', !!_cvS.code, 'Security code', '');
  if (_cvS.no) document.getElementById('cv-no').value = _cvS.no;
  if (_cvS.code) document.getElementById('cv-code').value = _cvS.code;
}
async function cvScan(files) {
  if (_cvS.busy || !files || !files.length) return;
  cvErr(''); _cvS.busy = true;
  const msg = document.getElementById('cv-scan-msg');
  try {
    msg.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Loading reader…';
    await loadScriptOnce('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');
    let n = 0;
    for (const f of files) {
      n++;
      if (!f.type.startsWith('image/')) continue;
      msg.innerHTML = `<span class="spinner-border spinner-border-sm me-2"></span>Reading photo ${n} of ${files.length}…`;
      const r = cvParse(await cvOcrFile(f));
      if (r.no) _cvS.no = r.no;
      if (r.code) _cvS.code = r.code;
      cvChips();
    }
    if (_cvS.no && _cvS.code) {
      msg.innerHTML = '<i class="fa fa-wand-magic-sparkles me-1 text-accent"></i>Card read. Validating…';
      await cvSubmitVerify();
    } else {
      msg.textContent = !_cvS.no && !_cvS.code ? 'Could not read the card. Retake in better light, or type the details below.'
        : !_cvS.code ? 'Now upload the BACK of the card (security code).' : 'Now upload the FRONT of the card (card number).';
    }
  } catch (e) {
    msg.textContent = e.message || 'Could not read the photo. Try again or type the details below.';
  }
  document.getElementById('cv-files').value = '';
  _cvS.busy = false;
}
async function cvSubmitVerify() {
  cvErr('');
  const no = document.getElementById('cv-no').value.trim(), code = document.getElementById('cv-code').value.trim();
  if (!no || !code) return cvErr('We still need both the card number and the security code.');
  const r = await api('card_verify', { card_no: no, code }, 'POST');
  if (r.ok) {
    CU.id_verified = 1; applyProfileUI(); closeModal('modal-cardv');
    toast(r.msg || 'Card verified', 'success');
    setTimeout(() => location.reload(), 700); // reload so the terms & conditions screen appears next, cleanly
  } else {
    _cvS.no = ''; _cvS.code = ''; cvChips();
    cvErr((r.msg || 'Verification failed.') + ' If the photo was misread, correct the details under "Photo not reading?".');
    const d = document.querySelector('#cv-verify details'); if (d) d.open = true;
  }
}

async function cvGenerate() {
  const btn = document.getElementById('cv-gen-btn');
  cvErr('');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Generating…';
  const r = await api('card_generate', {}, 'POST');
  btn.disabled = false; btn.innerHTML = '<i class="fa fa-download me-2"></i>Generate &amp; Download My Card';
  if (!r.ok) return cvErr(r.msg || 'Could not generate your card.');
  CU.card_issued = 1; CU.id_verified = 1; applyProfileUI();
  await cvRender(r.card);
  cvShowPanel('preview');
  cvDownload();
  const st = document.getElementById('cv-email-status');
  st.textContent = 'Emailing a copy to you…';
  const m = await api('card_email', { sheet: _cardSheetUrl }, 'POST');
  st.innerHTML = m.ok ? '<i class="fa fa-envelope-circle-check me-1 text-success"></i>' + esc(m.msg) : '<span class="text-warning">' + esc(m.msg || 'Could not email the card.') + '</span>';
}

// Owner / manager: print a staff member's card (e.g. for new staff to verify with)
async function cardReprintFor(uid) {
  const r = await api('card_data', { user_id: uid });
