function vfCleanup() {
  vfStopCamera();
  VF.idDescriptor = null; VF.selfieDescriptor = null; VF.idText = ''; VF.busy = false;
}

function vfFilePicked(inp) {
  const f = inp.files[0], img = document.getElementById('vf-preview'), go = document.getElementById('vf-go');
  vfError('');
  if (!f) { img.classList.add('d-none'); go.disabled = true; return; }
  if (!f.type.startsWith('image/')) { vfError('Please choose a photo (JPG or PNG).'); inp.value = ''; go.disabled = true; return; }
  if (img.dataset.url) URL.revokeObjectURL(img.dataset.url);
  img.dataset.url = URL.createObjectURL(f);
  img.src = img.dataset.url;
  img.classList.remove('d-none');
  go.disabled = false;
}

// STEP 1 — validate the ID photo. Nothing moves on until it passes.
async function vfScanId() {
  if (VF.busy) return;
  vfError('');
  const file = document.getElementById('vf-file').files[0];
  if (!file) return vfError('Take or choose a photo of your ID first.');
  if (!document.getElementById('vf-consent').checked) return vfError('Please tick the consent box to continue.');
  VF.busy = true;
  VF.country = document.getElementById('vf-country').value;
  vfShow('check');
  try {
    vfCheckMsg('Loading verification tools (first time may take a moment)…');
    await vfLoadLibs();
    const canvas = await vfFileToCanvas(file, 1600);

    vfCheckMsg('Reading the details on your ID…');
    const ocr = await Tesseract.recognize(canvas, 'eng');
    const text = (ocr && ocr.data && ocr.data.text) || '';
    if (text.replace(/\s/g, '').length < 20) throw new Error('We could not read any text on this ID. Retake the photo closer, in good light, with no glare.');

    const norm = s => (s || '').toUpperCase().replace(/[^\p{L}\s]/gu, ' ').split(/\s+/).filter(Boolean);
    const nameTokens = norm(CU.name).filter(t => t.length >= 3);
    const ocrTokens = norm(text);
    let matched = 0;
    nameTokens.forEach(nt => { if (ocrTokens.some(ot => ot === nt || (nt.length >= 5 && vfLev(nt, ot) <= 1))) matched++; });
    const needed = Math.min(2, Math.max(1, nameTokens.length));
    if (matched < needed) throw new Error("We couldn't find your registered name (" + CU.name + ') on this ID. Make sure it is your own ID and the name is clearly visible.');

    vfCheckMsg('Looking for the photo on your ID…');
    const face = await faceapi.detectSingleFace(canvas, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.25 })).withFaceLandmarks().withFaceDescriptor();
    if (!face) throw new Error('We could not find a face on this ID. Photograph the front of the ID, flat and well lit.');

    VF.idDescriptor = face.descriptor;
    VF.idText = text;
    vfShow('face');
    await vfStartCamera();
  } catch (e) {
    vfShow('id');
    vfError(e.message || 'Something went wrong. Try again.');
  } finally {
    VF.busy = false;
  }
}

// STEP 2 — camera
async function vfStartCamera() {
  vfError('');
  vfStopCamera();
  const vid = document.getElementById('vf-video'), cap = document.getElementById('vf-cap');
  cap.disabled = true;
  try {
    VF.stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false });
    vid.srcObject = VF.stream;
    vid.onloadeddata = () => { cap.disabled = false; };
    await vid.play().catch(() => {});
    if (vid.videoWidth) cap.disabled = false;
  } catch (e) {
    vfError('Could not open the camera. Allow camera access in your browser, then tap "Retry camera".');
  }
}
function vfStopCamera() {
  if (VF.stream) { VF.stream.getTracks().forEach(t => t.stop()); VF.stream = null; }
}

// STEP 2 → 3 — only moves on once a real face is captured
async function vfCaptureFace() {
  if (VF.busy) return;
  const vid = document.getElementById('vf-video'), btn = document.getElementById('vf-cap');
  if (!VF.stream || !vid.videoWidth) return vfError('The camera is not ready yet. Give it a second.');
  VF.busy = true; vfError('');
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Checking your face…';
  let ok = false;
  try {
    await vfLoadLibs();
    const c = document.createElement('canvas');
    c.width = vid.videoWidth; c.height = vid.videoHeight;
    c.getContext('2d').drawImage(vid, 0, 0);
    const face = await faceapi.detectSingleFace(c, new faceapi.SsdMobilenetv1Options({ minConfidence: 0.5 })).withFaceLandmarks().withFaceDescriptor();
    if (!face) throw new Error('We could not see your face clearly. Face the camera in good light and try again.');
    VF.selfieDescriptor = face.descriptor;
    ok = true;
  } catch (e) {
    vfError(e.message || 'Capture failed. Try again.');
  }
  btn.disabled = false;
  btn.innerHTML = '<i class="fa fa-camera me-2"></i>Capture';
  VF.busy = false;
  if (ok) { vfStopCamera(); vfShow('match'); await vfMatch(); }
}

// STEP 3 — match against the ID + records
async function vfMatch() {
  try {
    const distance = faceapi.euclideanDistance(VF.idDescriptor, VF.selfieDescriptor);
    await new Promise(r => setTimeout(r, 900));
    const res = await api('verify_id', { country: VF.country, ocr_text: VF.idText, face_distance: distance.toFixed(4) }, 'POST');
    if (res.ok) {
      CU.id_verified = 1;
      applyProfileUI();
      document.getElementById('vf-done-badge').innerHTML = verifiedBadge(96);
      document.getElementById('vf-photo-hint').classList.toggle('d-none', !!CU.photo);
      vfShow('done');
      toast(res.msg || 'ID verified', 'success');
      VF.idDescriptor = null; VF.selfieDescriptor = null; VF.idText = '';
      return;
    }
    document.getElementById('vf-fail-msg').textContent = res.msg || 'Verification failed. Please try again.';
    vfShow('fail');
  } catch (e) {
    document.getElementById('vf-fail-msg').textContent = e.message || 'Something went wrong. Please try again.';
    vfShow('fail');
  }
}
document.getElementById('modal-idv')?.addEventListener('hidden.bs.modal', vfCleanup);

