  n.innerHTML = [['home','fa-house','Home'],['messages','fa-comments','Chats'],['finance','fa-wallet','Wallet'],['profile','fa-user','Profile']]
    .map(([p,i,l]) => `<button data-p="${p}" onclick="nxBn('${p}')"><i class="fa ${i}"></i><span>${l}</span></button>`).join('');
