function nxLabelTables() {
  document.querySelectorAll('#nx-content table.table').forEach(t => {
    const heads = [...t.querySelectorAll('thead th')].map(h => h.textContent.trim());
    if (!heads.length) return;
    t.querySelectorAll('tbody tr').forEach(tr => {
      [...tr.children].forEach((td, i) => td.setAttribute('data-label', td.colSpan > 1 ? '' : (heads[i] || '')));
    });
    t.classList.add('nx-stack');
  });
}
let _nxObs = null, _nxT = null;
function nxObserve() {
  if (_nxObs) return;
  const c = document.getElementById('nx-content'); if (!c) return;
  _nxObs = new MutationObserver(() => { clearTimeout(_nxT); _nxT = setTimeout(nxLabelTables, 80); });
  _nxObs.observe(c, { childList: true, subtree: true });
}
function nxAfterNav(page) {
  nxEnsureBnav(); nxSetBnav(page); nxObserve();
  const c = document.getElementById('nx-content');
  if (c) { c.classList.remove('pg-in'); void c.offsetWidth; c.classList.add('pg-in'); }
}
