// ── WALLET CARD (Finance) ──
function nxTween(el, target, fmtFn) {
  const t0 = performance.now();
  const step = now => {
    const p = Math.min(1, (now - t0) / 1200);
    el.textContent = fmtFn(target * (1 - Math.pow(1 - p, 3)));
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
function walletFlip(e) {
  if (e) e.stopPropagation();
  const w = document.getElementById('wc'); if (!w) return;
  const on = w.classList.toggle('flip');
  try { _sfx.info(); } catch (x) {}
  if (!on) setTimeout(() => {
    document.getElementById('wc-q')?.classList.remove('d-none');
    document.getElementById('wc-bal')?.classList.add('d-none');
  }, 800);
}
function walletReveal(e) {
  if (e) e.stopPropagation();
  document.getElementById('wc-q')?.classList.add('d-none');
  document.getElementById('wc-bal')?.classList.remove('d-none');
  const w = window._wallet || {};
  const amt = document.getElementById('wc-amt');
  if (amt) nxTween(amt, parseFloat(w.balance || 0), fmt);
  try { _sfx.success(); } catch (x) {}
}
function walletWithdraw(e) {
  walletFlip(e);
  setTimeout(() => document.querySelector('.bank-tile')?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 500);
}
