// ── DASHBOARD: animated counters + highlight strip ──
function nxCountUp(el) {
  const txt = el.textContent, m = txt.match(/[\d,]+(\.\d+)?/); if (!m) return;
  const target = parseFloat(m[0].replace(/,/g, '')); if (!isFinite(target) || !target) return;
  const dec = m[1] ? m[1].length - 1 : 0, t0 = performance.now();
  const step = now => {
    const p = Math.min(1, (now - t0) / 900), v = target * (1 - Math.pow(1 - p, 3));
    el.textContent = txt.replace(m[0], v.toLocaleString('en-KE', { minimumFractionDigits: dec, maximumFractionDigits: dec }));
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
const _nxDash = dashboard;
dashboard = async function (el) {
  await _nxDash(el);
  try {
    el.querySelectorAll('#dash-kpis .stat-value').forEach(nxCountUp);     loadAiInsights();
    const ch = _dashCharts.hourly; let best = '—';
    if (ch) {
      const data = ch.data.datasets[0].data, mx = Math.max(...data);
      if (mx > 0) best = String(ch.data.labels[data.indexOf(mx)]).replace('h', ':00');
    }
    const topEl = document.querySelector('#dash-top-products .fw-bold');
    const top = topEl ? topEl.textContent.trim().replace(/^\S+\s+/, '') : '—';
    document.getElementById('dash-kpis')?.insertAdjacentHTML('beforebegin',
      `<div class="dash-strip"><div><i>⏰</i><span>Best hour today</span><b>${esc(best)}</b></div><div><i>🏆</i><span>Top product today</span><b>${esc(top)}</b></div></div>`);
  } catch (e) {}
};

