const _nxSal = renderSalary;
renderSalary = async function (el) {
  await _nxSal(el);
  try {
    const r = await api('staff_payroll_list');
    const box = document.getElementById('hr-pane-payroll');
    if (!r.ok || !r.staff.length || !box || !document.getElementById('modal-quick-salary')) return;
    window._hrStaff = r.staff;
    box.insertAdjacentHTML('afterbegin', `<div class="hr-team"><div class="hr-team-h">Your team <span>${r.staff.length}</span></div>
      <div class="hr-grid">${r.staff.map((s, i) => {
        const hourly = s.pay_type === 'hourly';
        const av = s.photo_path ? `background-image:url('${esc(s.photo_path)}')` : '';
        return `<button class="hr-card" onclick="openQuickSalaryModal(_hrStaff[${i}])">
          <div class="hr-av" style="${av}">${s.photo_path ? '' : esc((s.full_name || '?').charAt(0).toUpperCase())}</div>
          <div style="min-width:0"><b class="text-truncate">${esc(s.full_name)}</b>
            <span class="hr-chip ${hourly ? 'h' : 'f'}">${hourly ? 'Hourly · ' + fmt(s.hourly_rate) + '/hr' : 'Fixed · ' + (s.fixed_salary ? fmt(s.fixed_salary) : 'not set')}</span>
            <span class="hr-chip m">${esc(PAY_METHODS[s.pay_method] || 'Bank Transfer')}</span></div></button>`;
      }).join('')}</div></div>`);
  } catch (e) {}
};

