const _nxRcp = viewSaleReceipt;
viewSaleReceipt = async function (id) {
  await _nxRcp(id);
  const r = document.querySelector('#receipt-body .receipt');
  if (!r || r.dataset.dec) return;
  r.dataset.dec = '1';
  const no = (r.querySelector('.text-muted')?.firstChild?.textContent || '').trim();
  r.insertAdjacentHTML('afterbegin', `<div class="rc-brand">${CU.logo ? `<img src="${esc(CU.logo)}" alt="" onerror="this.remove()">` : ''}<b>${esc(CU.business_name || 'NYMIX')}</b></div>`);
  if (no) r.insertAdjacentHTML('beforeend', `<div class="rc-qr"><img src="https://api.qrserver.com/v1/create-qr-code/?size=110x110&data=${encodeURIComponent('NYMIX|' + no)}" alt="QR"><div>${esc(no)}</div></div>`);
};
