  g.push({ n: 'Marketplace', items: [
    ['mp_store', 'My Store', 'fa-store', '#22c55e', 'Profile, listings & fleet', [O, M, S]],
    ['mp_orders', 'Orders & Support', 'fa-truck-fast', '#3b82f6', 'Track, deliver & chat', [O, M, P]] ] });
  return g;
};
const _mpBN = buildNav;
buildNav = function () {
  _mpBN();
  const h = (id, s) => { const e = document.getElementById(id); if (e) e.style.display = s ? '' : 'none'; };
  h('nav-mp-store', can(R.OWNER, R.MANAGER, R.STOREKEEPER));
  h('nav-mp-orders', can(R.OWNER, R.MANAGER, R.SUPPORT));
  h('nav-mp-sec', can(R.OWNER, R.MANAGER, R.STOREKEEPER, R.SUPPORT));
  h('nav-inventory-sec', !can(R.SUPPORT));
};
const _mpNavNow = navigateNow;
navigateNow = async function (page) {
  const M = { mp_store: [[R.OWNER, R.MANAGER, R.STOREKEEPER], renderMpStore], mp_orders: [[R.OWNER, R.MANAGER, R.SUPPORT], renderMpOrders] }[page];
  if (!M) return _mpNavNow(page);
  if (!M[0].includes(CU.role_id)) { toast('You do not have access to this section.', 'error'); return; }
  showChrome();
  document.querySelectorAll('.nx-nav-link').forEach(b => b.classList.toggle('active', b.dataset.page === page));
  document.getElementById('page-title').textContent = PAGE_TITLES[page];
  closeSidebar();
  const el = document.getElementById('nx-content'); loading(el);
  await M[1](el); nxAfterNav(page);
};

let MPB = 0, MPT = 'store', _mpCh = 0;
const $mp = id => document.getElementById(id);
const mpa = (a, p = {}, m = 'GET') => { if (CU.role_id === R.OWNER && MPB) p.branch_id = MPB; return api(a, p, m); };
const MP_LBL = { placed: 'Placed', confirmed: 'Confirmed', packed: 'Packed', dispatched: 'Dispatched', out_for_delivery: 'Out for delivery', delivered: 'Delivered', cancelled: 'Cancelled' };
const mpBadge = s => `<span class="badge bg-${{ delivered: 'success', cancelled: 'danger', placed: 'warning', pending: 'warning', approved: 'success', rejected: 'danger', paid: 'success', unpaid: 'secondary' }[s] || 'primary'} bg-opacity-25 text-${{ delivered: 'success', cancelled: 'danger', placed: 'warning', pending: 'warning', approved: 'success', rejected: 'danger', paid: 'success', unpaid: 'secondary' }[s] || 'primary'}">${esc(MP_LBL[s] || s)}</span>`;
function mpModal(t, h) {
  let m = $mp('modal-mp');
  if (!m) { m = document.createElement('div'); m.className = 'modal fade'; m.id = 'modal-mp'; m.tabIndex = -1;
    m.innerHTML = '<div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title fw-head" id="mpm-t"></h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="mpm-b"></div></div></div>';
    document.body.appendChild(m); }
  $mp('mpm-t').textContent = t; $mp('mpm-b').innerHTML = h; openModal('modal-mp');
}
async function mpShell(el, title, sub, tabs) {
  let sel = '';
  if (CU.role_id === R.OWNER) {
    const b = await api('mp_branches');
    if (!MPB && b.branches && b.branches.length) MPB = b.branches[0].id;
    sel = `<select class="form-select form-select-sm" style="width:auto" onchange="MPB=+this.value;mpTab(MPT)">${(b.branches || []).map(x => `<option value="${x.id}" ${x.id == MPB ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select>`;
  }
  el.innerHTML = `<div style="max-width:1200px;margin:0 auto"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2 mb-3"><div><h5 class="fw-head mb-0">${title}</h5><div class="small text-nx-muted">${sub}</div></div>${sel}</div>
    <ul class="nav nav-tabs" id="mp-tabs">${tabs.map(([k, l], i) => `<li class="nav-item"><button class="nav-link ${i ? '' : 'active'}" data-k="${k}" onclick="mpTab('${k}')">${l}</button></li>`).join('')}</ul><div id="mp-pane"></div></div>`;
  mpTab(tabs[0][0]);
}
function mpTab(k) {
  MPT = k; clearInterval(window._mpPoll);
  document.querySelectorAll('#mp-tabs .nav-link').forEach(b => b.classList.toggle('active', b.dataset.k === k));
  ({ store: mpLoadStore, preview: mpLoadPreview, listings: mpLoadListings, fleet: mpLoadFleet, orders: mpLoadOrders, chats: mpLoadChats, ratings: mpLoadRatings })[k]();
}
const renderMpStore = el => mpShell(el, '<i class="fa fa-store text-accent me-2"></i>My Marketplace Store', 'Your public shop on NYMIX Market',
  can(R.OWNER, R.MANAGER) ? [['store', 'Store profile'], ['preview', 'Preview & score'], ['listings', 'Products'], ['fleet', 'Fleet']] : [['listings', 'Products'], ['preview', 'Preview & score']]);
const renderMpOrders = el => mpShell(el, '<i class="fa fa-truck-fast text-accent me-2"></i>Marketplace Orders', 'Update tracking, talk to customers, build your rating',
  [['orders', 'Orders'], ['chats', 'Customer chats'], ['ratings', 'Ratings']]);

// ── Store profile ──
