  const box = $mp('mp-pane'); loading(box);
  const d = await mpa('mp_store_get'); if (!d.ok) { box.innerHTML = `<p class="text-danger p-3">${esc(d.msg)}</p>`; return; }
  const p = d.p || {}, v = (k, def = '') => esc(p[k] ?? def);
  box.innerHTML = `<div class="row g-3 mt-1"><div class="col-lg-7"><div class="card"><div class="card-body"><div class="row g-3">
    <div class="col-md-7"><label class="form-label">Store name *</label><input id="mps-name" class="form-control" value="${esc(p.display_name || p.branch_name || '')}"></div>
    <div class="col-md-5"><label class="form-label">Brand colour</label><input id="mps-accent" type="color" class="form-control form-control-color w-100" value="${v('accent', '#1E9E52')}"></div>
    <div class="col-12"><label class="form-label">Tagline</label><input id="mps-tag" class="form-control" maxlength="160" value="${v('tagline')}"></div>
    <div class="col-12"><label class="form-label">About the store</label><textarea id="mps-desc" class="form-control" rows="3">${v('description')}</textarea></div>
    <div class="col-12"><label class="form-label">Categories (comma separated)</label><input id="mps-cats" class="form-control" value="${v('categories')}" placeholder="Cement, Paint, Tools"></div>
    <div class="col-4"><label class="form-label">Avg delivery (min)</label><input id="mps-mins" type="number" class="form-control" value="${v('avg_delivery_mins', 60)}"></div>
    <div class="col-4"><label class="form-label">Delivery fee</label><input id="mps-fee" type="number" class="form-control" value="${v('delivery_fee', 200)}"></div>
    <div class="col-4"><label class="form-label">Min order</label><input id="mps-min" type="number" class="form-control" value="${v('min_order', 0)}"></div>
    <div class="col-12 d-flex gap-4 flex-wrap">
      <div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="mps-del" ${p.delivery_enabled == 0 ? '' : 'checked'}><label class="form-check-label" for="mps-del">Delivery</label></div>
      <div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="mps-pick" ${p.pickup_enabled == 0 ? '' : 'checked'}><label class="form-check-label" for="mps-pick">Pickup</label></div>
      <div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="mps-pub" ${p.is_published == 1 ? 'checked' : ''}><label class="form-check-label fw-bold" for="mps-pub">Published on marketplace</label></div>
    </div>
    <div class="col-12"><span class="small">NYMIX Verified badge: </span>${p.nymix_verified == 1 ? '<span class="badge bg-primary">✔ Verified</span>' : '<span class="badge bg-secondary">Not verified</span> <span class="small text-nx-muted">(granted by NYMIX TECH)</span>'}</div>
    <div class="col-12 d-flex gap-2 flex-wrap"><button class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="mpSaveStore()"><i class="fa fa-save me-2"></i>Save store</button>       <button class="btn btn-outline-warning" onclick="mpTab('preview')"><i class="fa fa-eye me-2"></i>Preview how customers see it</button> <button class="btn btn-outline-info" onclick="mpAiStore(this)"><i class="fa fa-wand-magic-sparkles me-2"></i>Write with AI</button></div>
  </div></div></div></div>
  <div class="col-lg-5"><div class="card mb-3"><div class="card-header">Store location (map pin)</div><div class="card-body">
    <div class="row g-2 mb-2"><div class="col"><input id="mps-lat" class="form-control form-control-sm" placeholder="Latitude" value="${v('latitude')}" oninput="mpMapPrev()"></div><div class="col"><input id="mps-lng" class="form-control form-control-sm" placeholder="Longitude" value="${v('longitude')}" oninput="mpMapPrev()"></div></div>
    <button class="btn btn-sm btn-outline-warning mb-2" onclick="mpLocate()"><i class="fa fa-location-crosshairs me-1"></i>Use my current location</button>
    <div id="mps-map" style="border-radius:10px;overflow:hidden;height:220px;background:var(--nx-surface)"></div>
    <div class="small text-nx-muted mt-1">Stand inside the shop and tap the button, or paste coordinates from Google Maps.</div></div></div>
  <div class="card mb-3"><div class="card-header">Branding & photos</div><div class="card-body">
    <div class="d-flex gap-2 flex-wrap mb-2">
      <button class="btn btn-sm btn-outline-secondary" onclick="mpUp('logo')">Upload logo</button><button class="btn btn-sm btn-outline-secondary" onclick="mpUp('banner')">Upload banner</button>
      <button class="btn btn-sm btn-outline-secondary" onclick="mpUp('store')">+ Store photo</button><button class="btn btn-sm btn-outline-secondary" onclick="mpUp('staff')">+ Staff photo</button><button class="btn btn-sm btn-outline-secondary" onclick="mpUp('delivery')">+ Delivery photo</button></div>
    <div class="d-flex gap-2 flex-wrap">${(d.photos || []).map(x => `<div style="position:relative"><img src="${esc(x.path)}" style="width:72px;height:72px;object-fit:cover;border-radius:10px"><button class="btn btn-sm btn-danger p-0" style="position:absolute;top:-6px;right:-6px;width:20px;height:20px;line-height:1" onclick="mpDelPhoto(${x.id})">×</button></div>`).join('') || '<span class="small text-nx-muted">No photos yet.</span>'}</div>
  </div></div></div></div>`;
  mpMapPrev();
}
function mpMapPrev() {
  const la = parseFloat($mp('mps-lat')?.value), ln = parseFloat($mp('mps-lng')?.value), m = $mp('mps-map'); if (!m) return;
  m.innerHTML = (isFinite(la) && isFinite(ln)) ? `<iframe width="100%" height="220" style="border:0" src="https://www.openstreetmap.org/export/embed.html?bbox=${ln - .008},${la - .005},${ln + .008},${la + .005}&layer=mapnik&marker=${la},${ln}"></iframe>` : '<div class="h-100 d-flex align-items-center justify-content-center small text-nx-muted">No location set</div>';
}
function mpLocate() {
  if (!navigator.geolocation) { toast('Location is not supported here', 'error'); return; }
  navigator.geolocation.getCurrentPosition(p => { $mp('mps-lat').value = p.coords.latitude.toFixed(7); $mp('mps-lng').value = p.coords.longitude.toFixed(7); mpMapPrev(); toast('Location captured', 'success'); }, () => toast('Allow location access and try again', 'error'), { enableHighAccuracy: true, timeout: 15000 });
}
async function mpSaveStore() {
  const r = await mpa('mp_store_save', { display_name: $mp('mps-name').value, tagline: $mp('mps-tag').value, description: $mp('mps-desc').value, categories: $mp('mps-cats').value, accent: $mp('mps-accent').value,
    avg_delivery_mins: $mp('mps-mins').value, delivery_fee: $mp('mps-fee').value, min_order: $mp('mps-min').value, delivery_enabled: $mp('mps-del').checked ? 1 : 0, pickup_enabled: $mp('mps-pick').checked ? 1 : 0,
    is_published: $mp('mps-pub').checked ? 1 : 0, latitude: $mp('mps-lat').value, longitude: $mp('mps-lng').value }, 'POST');
  r.ok ? toast('Store saved', 'success') : toast(r.msg || 'Failed', 'error');
}
function mpUp(kind) {
  const i = document.createElement('input'); i.type = 'file'; i.accept = 'image/jpeg,image/png,image/webp';
  i.onchange = async () => { if (!i.files[0]) return; const r = await mpa('mp_store_upload', { kind, image: i.files[0] }, 'POST'); r.ok ? (toast('Uploaded', 'success'), mpLoadStore()) : toast(r.msg || 'Failed', 'error'); };
  i.click();
}
async function mpDelPhoto(id) { const r = await mpa('mp_photo_delete', { id }, 'POST'); if (r.ok) mpLoadStore(); }

// ── Store preview + health score ──
let MPV = 'desktop';
async function mpLoadPreview() {   const box = $mp('mp-pane'); loading(box);   const d = await mpa('mp_preview'); if (!d.ok) { box.innerHTML = `<p class="text-danger p-3">${esc(d.msg)}</p>`; return; }   window._mpv = d; mpRenderPreview(); } function mpSetView(v) { MPV = v; mpRenderPreview(); } function mpRenderPreview() {   const box = $mp('mp-pane'), d = window._mpv; if (!box || !d) return;   const p = d.p || {}, team = d.team || [], items = d.items || [], canEdit = can(R.OWNER, R.MANAGER);   const mins = +(p.avg_delivery_mins || 60), rate = d.store || {}, nRev = +(rate.n || 0), avg = +(rate.avg || 0);   const hasLoc = p.latitude != null && p.latitude !== '' && p.longitude != null && p.longitude !== '';   const checks = [     [5,  !!(p.display_name || '').trim(), 'Store name', 'store'],     [10, !!p.logo_path, 'Upload a logo', 'store'],     [10, !!p.banner_path, 'Upload a banner image', 'store'],     [5,  (p.tagline || '').trim().length >= 8, 'Add a catchy tagline', 'store'],     [10, (p.description || '').trim().length >= 60, 'Write an About section (60+ characters)', 'store'],     [5,  (p.categories || '').trim() !== '', 'Add categories so shoppers can find you', 'store'],     [10, hasLoc, 'Pin your store on the map', 'store'],     [15, d.item_count >= 5, 'List at least 5 in-stock products (you have ' + d.item_count + ')' + (d.pending ? ' · ' + d.pending + ' waiting approval' : ''), 'listings'],     [5,  d.item_count > 0 && d.img_count / d.item_count >= 0.8, 'Give 80%+ of listed products a photo', 'listings'],     [5,  d.photo_count >= 3, 'Add 3+ store photos (' + d.photo_count + ' now)', 'store'],     [5,  team.some(t => t.photo), 'A support agent with a profile photo', null],     [5,  team.some(t => +t.verified), 'A verified support agent (blue badge)', null],     [5,  !+p.delivery_enabled || d.vehicle_count > 0, 'Add a delivery vehicle', 'fleet'],     [5,  +p.is_published === 1, 'Publish your store', 'store'],   ];   const score = checks.reduce((a, c) => a + (c[1] ? c[0] : 0), 0);   const col = score >= 80 ? '#22c55e' : score >= 50 ? '#1E9E52' : '#ef4444';   const fixBtn = c => (!c[1] && c[3] && (c[3] === 'listings' || canEdit)) ? `<button class="btn btn-sm btn-outline-warning py-0" style="font-size:.68rem" onclick="mpTab('${c[3]}')">Fix</button>` : '';   const earn = [     ['✔ NYMIX Verified', +p.nymix_verified === 1, 'Granted by NYMIX TECH after review'],     ['⚡ Fast delivery', mins <= 45, 'Set average delivery to 45 min or less'],     ['★ Top rated', nRev >= 5 && avg >= 4.5, '5+ reviews averaging 4.5★ (now ' + nRev + ' reviews' + (nRev ? ', ' + avg + '★' : '') + ')'],     ['🛍 Pickup', +p.pickup_enabled === 1, 'Turn on pickup in Store profile'],   ];   const noProfile = !p.display_name;   const bg = p.banner_path ? `background-image:url('${esc(p.banner_path)}')` : `background:linear-gradient(135deg,${esc(p.accent || '#1E9E52')},#14351F)`;   const bd = [];   if (+p.nymix_verified) bd.push('<span class="pv-bd v">✔ NYMIX Verified</span>');   if (nRev >= 5 && avg >= 4.5) bd.push('<span class="pv-bd t">★ Top rated</span>');   if (mins <= 45) bd.push('<span class="pv-bd f">⚡ Fast delivery</span>');   if (+p.pickup_enabled === 1) bd.push('<span class="pv-bd">🛍 Pickup</span>');   const stars = nRev ? `<span style="color:#f5a623">★</span> ${avg} (${nRev})` : '✨ New';   const av = (u, sz) => `<div class="pv-avw" style="width:${sz}px;height:${sz}px"><div class="pv-av" style="font-size:${Math.round(sz * .36)}px">${u.photo ? `<img src="${esc(u.photo)}" alt="">` : esc((u.name || '?').charAt(0))}</div>${+u.verified ? `<span class="pv-avb">${verifiedBadge(Math.round(sz * .32))}</span>` : ''}</div>`;   const phone = MPV === 'phone';    box.innerHTML = `   <style>     .pv{background:#FBFAF4;color:#14251A;border-radius:18px;overflow:hidden;margin:0 auto;border:1px solid var(--nx-border);width:100%;max-width:${phone ? '390px' : '100%'};font-family:var(--font-body)}     .pv-ribbon{background:#b91c1c;color:#fff;text-align:center;font-size:.75rem;padding:6px}     .pv-ban{height:${phone ? 120 : 170}px;background-size:cover;background-position:center}     .pv-head{display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;margin-top:-34px;padding:0 18px;position:relative}     .pv-logo{width:76px;height:76px;border-radius:18px;background:#fff;border:3px solid #fff;display:grid;place-items:center;font-weight:700;font-size:28px;color:#1E9E52;overflow:hidden;box-shadow:0 8px 22px rgba(0,0,0,.14)}     .pv-logo img{width:100%;height:100%;object-fit:cover}     .pv-bd{font-size:.62rem;padding:3px 8px;border-radius:10px;background:#F1F5EC;color:#4B5D50;margin-right:6px;display:inline-block;margin-top:6px}     .pv-bd.v{background:rgba(30,158,82,.1);color:#1E9E52}.pv-bd.t{background:#fff4e0;color:#E87800}.pv-bd.f{background:#eaf1ff;color:#2a5bd7}     .pv-body{padding:14px 18px 22px}     .pv-info{display:flex;gap:14px;flex-wrap:wrap;font-size:.78rem;color:#4B5D50;margin:10px 0}     .pv-h{font-weight:700;font-size:1.05rem;margin:20px 0 10px;color:#14351F}     .pv-photos{display:flex;gap:8px;overflow-x:auto;margin:10px 0}.pv-photos img{height:90px;border-radius:10px}     .pv-team{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px}     .pv-tm{background:#fff;border:1px solid rgba(20,50,25,.08);border-radius:14px;padding:14px 8px;text-align:center}     .pv-avw{position:relative;margin:0 auto 8px}.pv-av{width:100%;height:100%;border-radius:50%;background:rgba(30,158,82,.09);display:grid;place-items:center;font-weight:700;color:#1E9E52;overflow:hidden;border:3px solid #fff;box-shadow:0 4px 12px rgba(20,53,31,.12)}     .pv-av img{width:100%;height:100%;object-fit:cover}.pv-avb{position:absolute;right:-4px;bottom:-2px;background:#fff;border-radius:50%;line-height:0;padding:1px;box-shadow:0 2px 6px rgba(0,0,0,.2)}     .pv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(${phone ? 150 : 170}px,1fr));gap:10px}     .pv-pc{background:#fff;border:1px solid rgba(20,50,25,.08);border-radius:14px;overflow:hidden}     .pv-pi{aspect-ratio:1;background:#F1F5EC center/cover;display:grid;place-items:center;font-size:1.6rem;color:#93A697}     .pv-pt{padding:10px;font-size:.78rem}.pv-pt b{display:block;line-height:1.25}.pv-pt strong{color:#1E9E52}     .pv-sub{font-size:.68rem;color:#93A697}   </style>   <div class="row g-3 mt-1">     <div class="col-lg-4">       <div class="card mb-3"><div class="card-body">         <div class="d-flex align-items-center gap-3 mb-2">           <div style="width:74px;height:74px;border-radius:50%;background:conic-gradient(${col} ${score * 3.6}deg,var(--nx-border) 0);display:flex;align-items:center;justify-content:center"><div style="width:58px;height:58px;border-radius:50%;background:var(--nx-card);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1.15rem">${score}</div></div>           <div><div class="fw-bold">Store health score</div><div class="small text-nx-muted">${score >= 80 ? 'Great! Customers will love it.' : score >= 50 ? 'Getting there. Fix the items below.' : 'Needs work before you promote it.'}</div></div>         </div>         ${checks.map(c => `<div class="d-flex align-items-center gap-2 py-1 border-top" style="border-color:var(--nx-border)!important;font-size:.8rem">           <i class="fa ${c[1] ? 'fa-circle-check' : 'fa-circle-xmark'}" style="color:${c[1] ? '#22c55e' : '#ef4444'}"></i>           <span class="flex-grow-1 ${c[1] ? 'text-nx-muted' : ''}">${esc(c[2])}</span><span class="text-nx-muted" style="font-size:.68rem">+${c[0]}</span>${fixBtn(c)}</div>`).join('')}       </div></div>       <div class="card"><div class="card-header py-2 small fw-bold">Badges customers see</div><div class="card-body py-2">         ${earn.map(e => `<div class="d-flex justify-content-between align-items-start py-1" style="font-size:.8rem"><span>${e[0]}</span><span class="text-end ${e[1] ? '' : 'text-nx-muted'}" style="max-width:60%;font-size:.7rem">${e[1] ? '<b style="color:#22c55e">Earned</b>' : esc(e[2])}</span></div>`).join('')}       </div></div>     </div>     <div class="col-lg-8">       <div class="d-flex justify-content-between align-items-center mb-2 flex-wrap gap-2">         <div class="small text-nx-muted"><i class="fa fa-eye me-1"></i>This is how your store appears on NYMIX Market</div>         <div class="btn-group btn-group-sm"><button class="btn ${phone ? 'btn-outline-secondary' : 'btn-warning'}" onclick="mpSetView('desktop')"><i class="fa fa-desktop me-1"></i>Desktop</button><button class="btn ${phone ? 'btn-warning' : 'btn-outline-secondary'}" onclick="mpSetView('phone')"><i class="fa fa-mobile-screen me-1"></i>Phone</button></div>       </div>       ${noProfile ? '<div class="card p-4 text-center text-nx-muted">Save your store details first (Store profile tab), then come back to preview it.</div>' : `       <div class="pv">         ${+p.is_published === 1 ? '' : '<div class="pv-ribbon">Not published yet: customers cannot see this store</div>'}         <div class="pv-ban" style="${bg}"></div>         <div class="pv-head"><div class="pv-logo">${p.logo_path ? `<img src="${esc(p.logo_path)}" alt="">` : esc((p.display_name || '?').charAt(0))}</div>           <div style="flex:1;min-width:150px;padding-bottom:4px"><div style="font-weight:700;font-size:${phone ? 1.15 : 1.4}rem">${esc(p.display_name)}</div><div class="pv-sub">${stars}${p.tagline ? ' · ' + esc(p.tagline) : ''}</div></div>           <div style="padding-bottom:4px"><span class="pv-bd" style="background:#1E9E52;color:#fff;padding:7px 12px;font-size:.7rem">💬 Message store</span></div></div>         <div class="pv-body">           <div>${bd.join('')}</div>           <div class="pv-info"><span>🚚 Delivery ${+p.delivery_enabled ? 'KES ' + Number(p.delivery_fee || 0).toLocaleString() : 'not offered'}</span><span>⏱ ~${mins} min</span><span>🧾 Min order KES ${Number(p.min_order || 0).toLocaleString()}</span>${p.address ? '<span>📍 ' + esc(p.address) + '</span>' : ''}${p.phone ? '<span>📞 ' + esc(p.phone) + '</span>' : ''}</div>           ${p.description ? `<p style="font-size:.82rem;line-height:1.7;color:#4B5D50">${esc(p.description)}</p>` : '<p class="pv-sub">No description yet.</p>'}           <div class="pv-h">Meet the support team</div>           ${team.length ? `<div class="pv-team">${team.map(u => `<div class="pv-tm">${av(u, 64)}<div style="font-weight:700;font-size:.85rem">${esc(u.name)}${+u.verified ? verifiedBadge(13) : ''}</div><div class="pv-sub">${+u.reviews > 0 ? '<span style="color:#f5a623">★</span> ' + u.rating + ' (' + u.reviews + ')' : '✨ New'}</div>${+u.verified ? '<div class="pv-sub" style="color:#0095f6;font-weight:600">Verified NYMIX staff</div>' : ''}${u.photo ? '' : '<div class="pv-sub" style="color:#ef4444">No photo yet</div>'}</div>`).join('')}</div>` : '<div class="pv-sub">No support agents yet. Appoint someone with the Support role so customers can see who serves them.</div>'}           <div class="pv-h">In stock (${d.item_count})</div>           ${items.length ? `<div class="pv-grid">${items.map(i => `<div class="pv-pc"><div class="pv-pi" style="${i.img ? `background-image:url('${esc(i.img)}')` : ''}">${i.img ? '' : esc(i.name.charAt(0))}</div><div class="pv-pt"><b>${esc(i.name)}</b><strong>KES ${Number(i.price).toLocaleString()}</strong>${i.img ? '' : '<div class="pv-sub" style="color:#ef4444">no photo</div>'}</div></div>`).join('')}</div>${d.item_count > items.length ? `<div class="pv-sub mt-2">+ ${d.item_count - items.length} more</div>` : ''}` : '<div class="pv-sub">Nothing listed yet. Approve products in the Products tab.</div>'}           <div class="pv-h">Reviews</div><div class="pv-sub">${nRev ? stars + ' from ' + nRev + ' customer' + (nRev > 1 ? 's' : '') : 'No reviews yet. Delivered orders prompt customers to review you and your agent.'}</div>         </div></div>`}     </div>   </div>`; }  // ── Listings ──
async function mpLoadListings() {
  const box = $mp('mp-pane'); loading(box);
  const d = await mpa('mp_listings'); if (!d.ok) { box.innerHTML = `<p class="text-danger p-3">${esc(d.msg)}</p>`; return; }
  const mgr = can(R.OWNER, R.MANAGER);
  box.innerHTML = `<div class="alert alert-info py-2 small my-3">Only products the manager <b>approves</b> appear on NYMIX Market, and only while they are in stock at this branch.</div>
  <div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Marketplace</th><th></th></tr></thead><tbody>
  ${d.rows.map(r => `<tr><td class="fw-bold">${esc(r.name)}</td><td class="small">${esc(r.category || '—')}</td><td>${fmt(r.selling_price)}</td><td>${parseFloat(r.qty).toFixed(0)}</td>
   <td>${r.status ? mpBadge(r.status) : '<span class="small text-nx-muted">Not listed</span>'}</td>
   <td class="text-nowrap">${mgr ? (r.status === 'approved' ? `<button class="btn btn-sm btn-outline-danger" onclick="mpList(${r.id},'remove')">Remove</button>` :
     `<button class="btn btn-sm btn-success" onclick="mpList(${r.id},'approved')">Approve</button> ${r.status === 'pending' ? `<button class="btn btn-sm btn-outline-secondary" onclick="mpList(${r.id},'rejected')">Reject</button>` : ''}`)
     : (!r.status || r.status === 'rejected' ? `<button class="btn btn-sm btn-outline-warning" onclick="mpList(${r.id},'request')">Request listing</button>` : '')}</td></tr>`).join('') || '<tr><td colspan="6" class="text-center text-nx-muted py-4">No products</td></tr>'}
  </tbody></table></div></div>`;
}
async function mpList(pid, decision) { const r = await mpa('mp_listing_set', { product_id: pid, decision }, 'POST'); r.ok ? mpLoadListings() : toast(r.msg || 'Failed', 'error'); }

// ── Fleet ──
async function mpLoadFleet() {
  const box = $mp('mp-pane'); loading(box);
  const d = await mpa('mp_vehicles');
  box.innerHTML = `<div class="card mt-3"><div class="card-body"><div class="row g-2">
    <div class="col-md-3"><input id="mpv-l" class="form-control form-control-sm" placeholder="Label (e.g. Van 1)"></div><div class="col-md-2"><input id="mpv-p" class="form-control form-control-sm" placeholder="Plate"></div>
    <div class="col-md-2"><input id="mpv-t" class="form-control form-control-sm" placeholder="Type"></div><div class="col-md-3"><input id="mpv-d" class="form-control form-control-sm" placeholder="Driver name"></div>
    <div class="col-md-2"><button class="btn btn-sm w-100 fw-bold" style="background:var(--nx-accent);color:#fff" onclick="mpAddVeh()">Add</button></div></div></div>
   <div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Vehicle</th><th>Plate</th><th>Type</th><th>Driver</th><th></th></tr></thead><tbody>
   ${(d.rows || []).map(v => `<tr><td class="fw-bold">${esc(v.label)}</td><td>${esc(v.plate || '—')}</td><td>${esc(v.vtype || '—')}</td><td>${esc(v.driver_name || '—')}</td><td><button class="btn btn-sm btn-outline-secondary" onclick="mpToggleVeh(${v.id})">${v.is_active == 1 ? 'Disable' : 'Enable'}</button></td></tr>`).join('') || '<tr><td colspan="5" class="text-center text-nx-muted py-3">No vehicles yet</td></tr>'}
   </tbody></table></div></div>`;
}
async function mpAddVeh() { const r = await mpa('mp_vehicle_save', { label: $mp('mpv-l').value, plate: $mp('mpv-p').value, vtype: $mp('mpv-t').value, driver_name: $mp('mpv-d').value }, 'POST'); r.ok ? mpLoadFleet() : toast(r.msg || 'Failed', 'error'); }
async function mpToggleVeh(id) { await mpa('mp_vehicle_toggle', { id }, 'POST'); mpLoadFleet(); }

// ── Orders ──
async function mpLoadOrders() {
  const box = $mp('mp-pane'); loading(box);
  const d = await mpa('mp_orders'); if (!d.ok) { box.innerHTML = `<p class="text-danger p-3">${esc(d.msg)}</p>`; return; }
  box.innerHTML = `<div class="card mt-3"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Pay</th><th>Status</th><th>ETA</th><th>Agent</th><th></th></tr></thead><tbody>
  ${d.rows.map(o => `<tr><td class="fw-bold text-accent small">${esc(o.order_no)}<div class="text-nx-muted" style="font-size:.65rem">${new Date(o.created_at.replace(' ', 'T')).toLocaleString('en-KE')}</div></td>
   <td class="small">${esc(o.customer)}<div class="text-nx-muted">${esc(o.phone)}</div></td><td class="fw-bold">${fmt(o.total)}</td>
   <td class="small">${esc(o.payment_method)} ${mpBadge(o.payment_status)}</td><td>${mpBadge(o.status)}<div class="small text-nx-muted">${o.fulfil}</div></td>
   <td class="small">${o.eta_at ? new Date(o.eta_at.replace(' ', 'T')).toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit' }) : '—'}</td>
   <td class="small">${esc(o.support_name || '—')}</td><td><button class="btn btn-sm btn-outline-warning" onclick="mpOpenOrder(${o.id})">Open</button></td></tr>`).join('') || '<tr><td colspan="8" class="text-center text-nx-muted py-4">No marketplace orders yet</td></tr>'}
  </tbody></table></div></div>`;
}
async function mpOpenOrder(id) {
  const d = await mpa('mp_order', { order_id: id }); if (!d.ok) { toast(d.msg || 'Failed', 'error'); return; }
  const o = d.o, mgr = can(R.OWNER, R.MANAGER), closed = ['delivered', 'cancelled'].includes(o.status);
  const eta = o.eta_at ? o.eta_at.replace(' ', 'T').slice(0, 16) : '';
  mpModal('Order ' + o.order_no, `
   <div class="row g-3"><div class="col-md-6"><div class="small text-nx-muted">CUSTOMER</div><div class="fw-bold">${esc(o.customer)}</div><a href="tel:${esc(o.contact_phone)}">${esc(o.contact_phone)}</a>
     <div class="small mt-1">${o.fulfil === 'delivery' ? '🚚 ' + esc(o.delivery_address || '—') : '🛍 Customer pickup'}</div>${o.note ? `<div class="small text-nx-muted">Note: ${esc(o.note)}</div>` : ''}</div>
    <div class="col-md-6 text-md-end"><div class="small text-nx-muted">PAYMENT</div><div>${esc(o.payment_method.toUpperCase())} ${mpBadge(o.payment_status)}</div>
     ${o.payment_status !== 'paid' && !closed ? `<button class="btn btn-sm btn-success mt-1" onclick="mpPay(${o.id})">Mark as paid</button>` : ''}<div class="fw-bold fs-5 mt-1">${fmt(o.total)}</div></div></div>
   <table class="table table-sm my-3"><tbody>${d.items.map(i => `<tr><td>${esc(i.name)}</td><td>×${parseFloat(i.quantity)}</td><td class="text-end">${fmt(i.line_total)}</td></tr>`).join('')}
     <tr><td colspan="2" class="text-nx-muted">Delivery fee</td><td class="text-end">${fmt(o.delivery_fee)}</td></tr></tbody></table>
   ${closed ? `<div class="alert alert-secondary py-2 small">This order is ${o.status}.</div>` : `
   <div class="card p-3 mb-3"><div class="row g-2">
    <div class="col-md-4"><label class="form-label">Status</label><select id="mpo-st" class="form-select form-select-sm">${['confirmed', 'packed', 'dispatched', 'out_for_delivery', 'delivered'].concat(mgr ? ['cancelled'] : []).map(s => `<option value="${s}" ${s === o.status ? 'selected' : ''}>${MP_LBL[s]}</option>`).join('')}</select></div>
    <div class="col-md-4"><label class="form-label">Where is it now?</label><input id="mpo-loc" class="form-control form-control-sm" placeholder="e.g. Left warehouse, Thika Rd"></div>
    <div class="col-md-4"><label class="form-label">Expected arrival</label><input id="mpo-eta" type="datetime-local" class="form-control form-control-sm" value="${eta}"></div>
    ${mgr ? `<div class="col-md-4"><label class="form-label">Support agent</label><select id="mpo-sup" class="form-select form-select-sm"><option value="0">— Unassigned —</option>${d.supports.map(s => `<option value="${s.id}" ${s.id == o.assigned_support_id ? 'selected' : ''}>${esc(s.full_name)}</option>`).join('')}</select></div>
    <div class="col-md-4"><label class="form-label">Vehicle</label><select id="mpo-veh" class="form-select form-select-sm"><option value="0">— None —</option>${d.vehicles.map(v => `<option value="${v.id}" ${v.id == o.vehicle_id ? 'selected' : ''}>${esc(v.label)} ${esc(v.plate || '')}</option>`).join('')}</select></div>` : ''}
    <div class="col-md-4"><label class="form-label">Note to customer</label><input id="mpo-note" class="form-control form-control-sm"></div>
    <div class="col-12"><button class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="mpSaveOrder(${o.id})">Update order</button>
     <span class="small text-nx-muted ms-2">Confirming an order reserves stock and records the sale.</span></div></div></div>`}
   <div class="small text-nx-muted mb-1">TRACKING HISTORY</div>
   ${d.track.map(t => `<div class="small border-bottom py-1">${mpBadge(t.status)} ${esc(t.location_text ? '📍 ' + t.location_text : '')} ${esc(t.note || '')} <span class="text-nx-muted">· ${new Date(t.created_at.replace(' ', 'T')).toLocaleString('en-KE')} ${t.by_name ? '· ' + esc(t.by_name) : ''}</span></div>`).join('')}`);
}
async function mpSaveOrder(id) {
  const p = { order_id: id, status: $mp('mpo-st').value, location_text: $mp('mpo-loc').value, note: $mp('mpo-note').value, eta: $mp('mpo-eta').value };
  if ($mp('mpo-sup')) { p.support_id = $mp('mpo-sup').value; p.vehicle_id = $mp('mpo-veh').value; }
  const r = await mpa('mp_order_update', p, 'POST');
  if (r.ok) { toast('Order updated. Customer sees it live.', 'success'); closeModal('modal-mp'); mpLoadOrders(); } else toast(r.msg || 'Failed', 'error');
}
async function mpPay(id) { const r = await mpa('mp_order_pay', { order_id: id }, 'POST'); if (r.ok) { toast('Marked as paid', 'success'); mpOpenOrder(id); mpLoadOrders(); } else toast(r.msg || 'Failed', 'error'); }

// ── Chats ──
async function mpLoadChats() {
  const box = $mp('mp-pane'); loading(box);
  box.innerHTML = `<div class="row g-3 mt-1"><div class="col-lg-4"><div class="card"><div id="mpc-list" style="max-height:62vh;overflow-y:auto"></div></div></div>
   <div class="col-lg-8"><div class="card" style="height:62vh;display:flex;flex-direction:column"><div id="mpc-conv" class="d-flex align-items-center justify-content-center h-100 text-nx-muted small">Select a conversation</div></div></div></div>`;
  await mpThreads(); if (_mpCh) mpThread(_mpCh);
  window._mpPoll = setInterval(() => { if (!$mp('mpc-list')) { clearInterval(window._mpPoll); return; } mpThreads(); if (_mpCh) mpThread(_mpCh, true); }, 5000);
}
async function mpThreads() {
  const d = await mpa('mp_threads'); const b = $mp('mpc-list'); if (!b || !d.ok) return;
  b.innerHTML = d.rows.map(t => `<div class="p-3 border-bottom" style="cursor:pointer;border-color:var(--nx-border)!important;${t.id == _mpCh ? 'background:rgba(30,158,82,.1)' : ''}" onclick="mpThread(${t.id})">
   <div class="d-flex justify-content-between"><b class="small">${esc(t.customer)}</b>${t.unread > 0 ? `<span class="badge bg-danger">${t.unread}</span>` : ''}</div><div class="small text-nx-muted text-truncate">${esc(t.last_body || '')}</div></div>`).join('') || '<div class="p-4 text-center small text-nx-muted">No customer chats yet</div>';
}
async function mpThread(id, quiet) {
  _mpCh = id; const d = await mpa('mp_thread', { id }); const c = $mp('mpc-conv'); if (!c || !d.ok) return;
  const keep = $mp('mpc-in')?.value || '';
  c.className = ''; c.style.cssText = 'flex:1;display:flex;flex-direction:column;min-height:0';
  c.innerHTML = `<div class="p-3 border-bottom fw-bold" style="border-color:var(--nx-border)!important">${esc(d.t.customer)}</div>
   <div id="mpc-body" style="flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:8px">${d.msgs.map(m => `<div style="align-self:${m.sender_type === 'staff' ? 'flex-end' : 'flex-start'};max-width:78%"><div class="msg-b ${m.sender_type === 'staff' ? 'me' : 'them'}">${esc(m.body)}</div></div>`).join('')}</div>
   <div class="p-2 border-top d-flex gap-2" style="border-color:var(--nx-border)!important"><input id="mpc-in" class="form-control" placeholder="Reply to customer…" value="${esc(keep)}" onkeydown="if(event.key==='Enter')mpSend()"><button class="btn btn-outline-info" title="Draft reply with AI" onclick="mpAiReply(this)"><i class="fa fa-wand-magic-sparkles"></i></button><button class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="mpSend()"><i class="fa fa-paper-plane"></i></button></div>`;
  const bd = $mp('mpc-body'); bd.scrollTop = bd.scrollHeight; if (!quiet) $mp('mpc-in').focus();
}
async function mpSend() { const i = $mp('mpc-in'); const b = i.value.trim(); if (!b) return; i.value = ''; const r = await mpa('mp_reply', { thread_id: _mpCh, body: b }, 'POST'); r.ok ? mpThread(_mpCh) : toast(r.msg || 'Failed', 'error'); }

// ── Ratings ──
async function mpLoadRatings() {
  const box = $mp('mp-pane'); loading(box);
  const d = await mpa('mp_reviews'); if (!d.ok) { box.innerHTML = `<p class="text-danger p-3">${esc(d.msg)}</p>`; return; }
  const star = n => '★'.repeat(Math.round(n)) + '☆'.repeat(5 - Math.round(n));
  box.innerHTML = `<div class="row g-3 my-1">
    <div class="col-md-4"><div class="stat-card" style="--card-accent:var(--nx-accent)"><div class="stat-label">Store rating</div><div class="stat-value">${d.store.n > 0 ? d.store.avg : '—'}</div><div class="stat-sub">${d.store.n} review(s)</div></div></div>
    ${d.stats.map(s => `<div class="col-md-4"><div class="stat-card" style="--card-accent:var(--nx-green)"><div class="stat-label">${esc(s.full_name)}</div><div class="stat-value">${s.avg}</div><div class="stat-sub" style="color:#1E9E52">${star(s.avg)} · ${s.n} review(s)</div></div></div>`).join('')}</div>
   <div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Rating</th><th>Comment</th><th>Agent</th></tr></thead><tbody>
   ${d.rows.map(r => `<tr><td class="small">${esc(r.order_no)}</td><td class="small">${esc(r.customer)}</td><td style="color:#1E9E52">${star(r.rating)}</td><td class="small">${esc(r.comment || '')}</td><td class="small">${esc(r.support || '—')}</td></tr>`).join('') || '<tr><td colspan="5" class="text-center text-nx-muted py-4">No reviews yet</td></tr>'}</tbody></table></div></div>`;
}

