async function loadAiInsights(refresh) {
  const box = document.getElementById('ai-insights-body'); if (!box) return;
  if (!can(R.OWNER, R.MANAGER)) { document.getElementById('ai-card')?.remove(); return; }
  box.innerHTML = '<div class="d-flex justify-content-center py-4"><div class="spinner-border spinner-border-sm text-warning"></div></div>';
  const d = await api('ai_insights', refresh ? { refresh: 1 } : {});
  if (!document.getElementById('ai-insights-body')) return;
  if (!d.ok) { box.innerHTML = `<div class="small text-nx-muted p-3">${esc(d.msg || 'AI insights unavailable.')}</div>`; return; }
  box.innerHTML = `<div class="p-3">
    ${d.summary ? `<div class="small" style="line-height:1.65">${esc(d.summary)}</div>` : ''}
    ${d.ai_error ? `<div class="small text-warning mt-2">${esc(d.ai_error)}</div>` : ''}
    ${(d.flags || []).length ? `<ul class="small text-nx-muted mt-2 mb-0 ps-3">${d.flags.map(f => `<li>${esc(f)}</li>`).join('')}</ul>` : ''}
    <div class="text-nx-muted mt-2" style="font-size:.65rem">AI-written from rule-based flags. Treat as a lead to check, not proof.</div></div>`;
}

async function mpAiStore(btn) {
  const name = $mp('mps-name').value.trim();
  if (!name) { toast('Enter the store name first', 'error'); return; }
  const old = btn.innerHTML; btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Writing…';
  const r = await mpa('ai_mp_draft', { kind: 'store', name, categories: $mp('mps-cats').value }, 'POST');
  btn.disabled = false; btn.innerHTML = old;
  if (!r.ok) { toast(r.msg || 'AI failed', 'error'); return; }
  $mp('mps-tag').value = r.tagline || '';
  $mp('mps-desc').value = r.description || '';
  toast('Draft added. Edit it, then press Save store.', 'success');
}

async function mpAiReply(btn) {
  if (!_mpCh) return;
  const old = btn.innerHTML; btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  const r = await mpa('ai_mp_draft', { kind: 'reply', thread_id: _mpCh }, 'POST');
  btn.disabled = false; btn.innerHTML = old;
  if (!r.ok) { toast(r.msg || 'AI failed', 'error'); return; }
  const i = $mp('mpc-in'); if (i) { i.value = r.text; i.focus(); }
  toast('Draft ready. Read it, edit if needed, then send.', 'info');
}

