const AI_CHIPS = {
  dashboard: ['How do I read my sales trend?', 'What should I check every day?'],
  inventory: ['How do I set a good reorder level?', 'What causes stock shrinkage?'],
  salary: ['How is PAYE calculated?', 'What is SHIF?', 'What is the housing levy?'],
