}
function nxAiMount() {
  if (document.getElementById('ai-fab')) return;
  document.body.insertAdjacentHTML('beforeend', `
    <button id="ai-fab" class="ai-fab" onclick="nxAiToggle()" title="Ask NYMIX AI"><span class="ai-fab-dot"></span>✨<span>Ask NYMIX AI</span></button>
    <div id="ai-panel" class="ai-panel d-none">
      <div class="ai-ph"><div class="d-flex align-items-center gap-2"><div class="ai-av"><i></i><b>✨</b></div><div><b>NYMIX AI</b><div class="ai-ps">Your assistant inside the portal</div></div></div><button onclick="nxAiToggle()">×</button></div>
      <div id="ai-msgs" class="ai-msgs"><div class="ai-b bot">Hi ${esc((CU.name || '').split(' ')[0])} 👋 Ask me how to use the portal, or about payroll, stock and sales basics. I can't see your business numbers here yet.</div></div>
      <div id="ai-chips" class="ai-chips"></div>
      <div class="ai-in"><input id="ai-q" placeholder="Ask NYMIX AI…" onkeydown="if(event.key==='Enter')nxAiAsk()"><button onclick="nxAiAsk()"><i class="fa fa-paper-plane"></i></button></div>
    </div>`);
  nxAiChips();
}
function nxAiToggle() { document.getElementById('ai-panel')?.classList.toggle('d-none'); document.getElementById('ai-q')?.focus(); }
async function nxAiAsk(q) {
  const inp = document.getElementById('ai-q'); q = (q || inp.value).trim(); if (!q) return; inp.value = '';
  const box = document.getElementById('ai-msgs');
  box.insertAdjacentHTML('beforeend', `<div class="ai-b me">${esc(q)}</div><div class="ai-b bot" id="ai-wait"><span class="ai-dots"><i></i><i></i><i></i></span></div>`);
  box.scrollTop = box.scrollHeight;
  const r = await api('ai_assist', { q, page: _aiPage }, 'POST');
  const w = document.getElementById('ai-wait');
  if (w) { w.removeAttribute('id'); w.textContent = r.ok ? r.text : (r.msg || 'NYMIX AI is unavailable right now.'); }
  box.scrollTop = box.scrollHeight;
}
const _nxNavAi = navigateNow;
navigateNow = async function (page) {
  await _nxNavAi(page);
  _aiPage = page; nxAiChips();
  const f = document.getElementById('ai-fab'); if (f) f.style.display = page === 'pos' ? 'none' : '';
  if (page === 'pos') document.getElementById('ai-panel')?.classList.add('d-none');
};

// ── Read a CV in the browser (PDF/TXT), then send only the text to NYMIX AI ──
async function hrReadCvFile(url) {
  const ext = (url.split('?')[0].split('.').pop() || '').toLowerCase();
  if (ext === 'pdf') {
    await loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');
    pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    const pdf = await pdfjsLib.getDocument(url).promise; let out = '';
    for (let i = 1; i <= Math.min(pdf.numPages, 6); i++) {
      const tc = await (await pdf.getPage(i)).getTextContent();
      out += tc.items.map(x => x.str).join(' ') + '\n';
    }
    return out.trim();
  }
  if (['txt', 'md'].includes(ext)) return (await (await fetch(url)).text()).trim();
  throw new Error('Only PDF or TXT CVs can be read automatically.');
}

let _hraiT = null;
function hrAiOpen(name) {
  let m = document.getElementById('modal-hrai');
  if (!m) {
    m = document.createElement('div'); m.className = 'modal fade'; m.id = 'modal-hrai'; m.tabIndex = -1;
    m.innerHTML = '<div class="modal-dialog modal-dialog-centered modal-lg modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title fw-head"><span class="nx-ai-tag me-2"><i class="fa fa-wand-magic-sparkles"></i> NYMIX AI</span><span id="hrai-name"></span></h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="hrai-b"></div></div></div>';
    document.body.appendChild(m);
    m.addEventListener('hidden.bs.modal', () => clearInterval(_hraiT));
  }
  document.getElementById('hrai-name').textContent = name;
  openModal('modal-hrai');
}
function hrAiLoader(name, cv) {
  clearInterval(_hraiT);
  const steps = cv
    ? [`NYMIX is reading ${name}'s CV…`, 'Scanning work experience…', 'Spotting skills and strengths…', 'Drafting the staff profile…']
    : [`NYMIX is studying the role…`, `Drafting ${name}'s role description…`, 'Almost there…'];
  document.getElementById('hrai-b').innerHTML = `<div class="py-4"><div class="hrai-doc"><div class="hrai-scan"></div></div><div class="hrai-t" id="hrai-t">${esc(steps[0])}</div><div class="hrai-s">This takes a few seconds</div></div>`;
  let i = 0;
  _hraiT = setInterval(() => { i = (i + 1) % steps.length; const t = document.getElementById('hrai-t'); if (t) t.textContent = steps[i]; }, 1700);
}
function hrAiPaste(name, why) {
  clearInterval(_hraiT);
  document.getElementById('hrai-b').innerHTML = `
    <div class="alert alert-warning py-2 small">${esc(why)}</div>
    <label class="form-label">Paste the CV text (optional)</label>
    <textarea id="hrai-paste" class="form-control" rows="8" placeholder="Paste the CV content here…"></textarea>
    <div class="d-flex gap-2 mt-3 flex-wrap">
      <button class="btn fw-bold" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="hrAiSend(document.getElementById('hrai-paste').value)"><i class="fa fa-wand-magic-sparkles me-2"></i>Read this CV</button>
      <button class="btn btn-outline-secondary" onclick="hrAiSend('')">Use role only</button></div>`;
}
async function hrAiStart(kind, idx) {
  const o = kind === 'user' ? _hrS[idx] : _hrA[idx];
  window._hrAiCtx = { kind, id: kind === 'user' ? o.user_id : o.id, name: o.full_name };
  hrAiOpen(o.full_name);
  if (kind === 'user') {
    if (!o.cv_path) { hrAiPaste(o.full_name, 'No CV on file for this person.'); return; }
    hrAiLoader(o.full_name, true);
    let text = '';
    try { text = await hrReadCvFile(o.cv_path); } catch (e) { console.warn(e); }
    if (text.length < 80) { hrAiPaste(o.full_name, "We couldn't pull readable text out of this CV (it may be scanned or a Word file)."); return; }
    await hrAiSend(text);
  } else {
    await hrAiSend('');
  }
}
async function hrAiSend(text) {
  const c = window._hrAiCtx; if (!c) return;
  text = (text || '').trim();
  hrAiLoader(c.name, !!text);
  const p = { cv_text: text }; p[c.kind === 'user' ? 'user_id' : 'appointed_id'] = c.id;
  const r = await api('ai_staff_profile', p, 'POST');
  if (!r.ok) {
    clearInterval(_hraiT);
    document.getElementById('hrai-b').innerHTML = `<div class="text-center py-4"><div style="font-size:2rem">⚠️</div><p class="text-nx-muted">${esc(r.msg || 'NYMIX AI could not finish.')}</p><button class="btn btn-outline-secondary" onclick="hrAiSend(${JSON.stringify(text).replace(/"/g, '&quot;')})">Try again</button></div>`;
    return;
  }
  clearInterval(_hraiT);
  hrAiResult(c.name, r.p);
  hrRenderTeam();
}
const jarr = s => { try { return JSON.parse(s || '[]'); } catch (e) { return []; } };
function hrAiResult(name, p) {
  document.getElementById('hrai-b').innerHTML = `
    <div class="mb-3"><div class="small text-nx-muted">${p.source === 'cv' ? 'Generated from the CV' : 'Generated from the role (no CV)'}</div>
      <h5 class="fw-head mb-1">${esc(p.headline || name)}</h5><p class="mb-0" style="line-height:1.6">${esc(p.summary)}</p></div>
    ${jarr(p.skills).length ? `<div class="mb-3"><div class="small text-nx-muted mb-1">SKILLS</div>${jarr(p.skills).map(s => `<span class="hrai-tag">${esc(s)}</span>`).join('')}</div>` : ''}
    ${jarr(p.duties).length ? `<div class="mb-3"><div class="small text-nx-muted mb-1">SUGGESTED DUTIES</div><ul class="small mb-0 ps-3">${jarr(p.duties).map(s => `<li>${esc(s)}</li>`).join('')}</ul></div>` : ''}
    ${jarr(p.strengths).length ? `<div class="mb-3"><div class="small text-nx-muted mb-1">STRENGTHS</div><ul class="small mb-0 ps-3">${jarr(p.strengths).map(s => `<li>${esc(s)}</li>`).join('')}</ul></div>` : ''}
    ${p.gaps ? `<div class="mb-3"><div class="small text-nx-muted mb-1">WORTH CHECKING OR TRAINING</div><div class="small">${esc(p.gaps)}</div></div>` : ''}
    <div class="alert alert-info py-2 small mb-0"><i class="fa fa-circle-info me-1"></i>AI-written from the CV text only. Review it before relying on it, and never use it alone for hiring or firing decisions.</div>`;
}

// ── HR: structured staff cards ──
let _hrS = [], _hrA = [], _hrP = {};
async function hrRenderTeam() {
  if (!document.getElementById('hr-team2')) return;
  const [s, a, p] = await Promise.all([api('staff_payroll_list'), api('appointed_staff_list'), api('ai_profiles_list')]);
  _hrS = s.ok ? s.staff : [];
  _hrA = (a.ok ? a.list : []).filter(x => x.status !== 'registered');
  _hrP = {}; (p.ok ? p.rows : []).forEach(x => { _hrP[(x.user_id ? 'u' : 'a') + (x.user_id || x.appointed_id)] = x; });
  hrPaintTeam();
}
function hrAiLine(p) {
  return p ? `<b>${esc(p.headline || 'AI profile ready')}</b><br>${esc((p.summary || '').slice(0, 110))}${(p.summary || '').length > 110 ? '…' : ''}`
           : '<i class="fa fa-wand-magic-sparkles me-1"></i>No AI profile yet. Tap NYMIX AI to generate one.';
}
function hrPaintTeam() {
  const host = document.getElementById('hr-team2'); if (!host) return;
  const q = (document.getElementById('hr2-q')?.value || '').toLowerCase();
  const staff = _hrS.map((s, i) => [s, i]).filter(([s]) => !q || (s.full_name || '').toLowerCase().includes(q));
  const appt  = _hrA.map((a, i) => [a, i]).filter(([a]) => !q || (a.full_name || '').toLowerCase().includes(q));
  const pay = o => {
    const hourly = o.pay_type === 'hourly';
    const amt = hourly ? (o.hourly_rate ? fmt(o.hourly_rate) : 'Not set') : (o.fixed_salary ? fmt(o.fixed_salary) : 'Not set');
    return `<div class="hr2-pay"><div><small>${hourly ? 'Hourly rate' : 'Monthly salary'}</small><span class="amt">${amt}${hourly && o.hourly_rate ? '<span style="font-size:.7rem"> /hr</span>' : ''}</span></div><span class="hr-chip2 ${o.pay_method === 'mpesa' ? 'g' : ''}">${esc(PAY_METHODS[o.pay_method] || 'Bank Transfer')}</span></div>`;
  };
  const av = (o, ini) => `<div class="hr2-av" style="${o.photo_path ? `background-image:url('${esc(o.photo_path)}')` : ''}">${o.photo_path ? '' : esc((ini || '?').charAt(0).toUpperCase())}</div>`;
  host.innerHTML = `
    <div class="hr2-bar"><div class="hr2-h"><span class="ico-tile" style="width:32px;height:32px"><i class="fa fa-users"></i></span>Your team <span class="n">${staff.length}</span></div>
      <div class="d-flex gap-2 flex-wrap"><input id="hr2-q" class="form-control form-control-sm" style="width:200px" placeholder="Search staff…" value="${esc(q)}" oninput="hrPaintTeam()">
      <button class="btn btn-sm fw-bold" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="openApointStaffModal()"><i class="fa fa-user-plus me-1"></i>Appoint staff</button></div></div>
    <div class="hr2-grid">${staff.map(([s, i]) => `
      <div class="hr2-card">
        <div class="hr2-top">${av(s, s.full_name)}<div style="min-width:0"><b class="text-truncate">${esc(s.full_name)}${s.id_verified ? verifiedBadge(15) : ''}</b><small>${esc(s.role_name || '')}${s.branch_name ? ' · ' + esc(s.branch_name) : ''}</small></div></div>
        ${pay(s)}
        <div class="hr2-ai">${hrAiLine(_hrP['u' + s.user_id])}</div>
        <div class="hr2-acts">
          <button onclick="hrMessage(${s.user_id})" ${s.user_id == CU.id ? 'disabled style="opacity:.4"' : ''}><i class="fa fa-comment-dots"></i>Message</button>
          <button onclick="psOpenFor(${s.user_id})"><i class="fa fa-file-invoice-dollar"></i>Payslip</button>
          <button class="ai" onclick="hrAiStart('user',${i})"><i class="fa fa-wand-magic-sparkles"></i>NYMIX AI</button>
          <button onclick="openQuickSalaryModal(_hrS[${i}])"><i class="fa fa-money-check-dollar"></i>Salary</button>
        </div></div>`).join('') || '<div class="text-nx-muted small p-3">No staff match.</div>'}</div>
    ${_hrA.length ? `<div class="hr2-bar"><div class="hr2-h"><span class="ico-tile" style="width:32px;height:32px"><i class="fa fa-clipboard-user"></i></span>Appointed, waiting to register <span class="n">${appt.length}</span></div></div>
    <div class="hr2-grid">${appt.map(([a, i]) => `
      <div class="hr2-card">
        <div class="hr2-top">${av(a, a.full_name)}<div style="min-width:0"><b class="text-truncate">${esc(a.full_name)}</b><small>${esc(a.role_name || '')} · ${esc(a.branch_name || '')}</small></div><span class="hr-chip2 w ms-auto">Pending</span></div>
        ${pay(a)}
        <div class="hr2-ai">${hrAiLine(_hrP['a' + a.id])}</div>
        <div class="hr2-acts" style="grid-template-columns:repeat(3,1fr)">
          <button class="ai" onclick="hrAiStart('appt',${i})"><i class="fa fa-wand-magic-sparkles"></i>Role brief</button>
          <button onclick="showAppointedCard(${a.id})"><i class="fa fa-id-card"></i>ID card</button>
          <button onclick="removeApointStaff(${a.id})"><i class="fa fa-trash"></i>Remove</button>
        </div></div>`).join('')}</div>` : ''}`;
  if (q) { const i = document.getElementById('hr2-q'); i.focus(); i.setSelectionRange(q.length, q.length); }
}
async function hrMessage(uid) {
  await navigate('messages');
  await loadContacts();
  if (!_msgContacts.find(c => c.id == uid)) { toast('You can only message people in your own branch.', 'info'); return; }
  startChat(uid);
}

