const _nxSal2 = renderSalary;
renderSalary = async function (el) {
  await _nxSal2(el);
  try {
    document.querySelector('.hr-team')?.remove();
    const pills = document.getElementById('hr-pills'); if (!pills) return;
    if (!document.getElementById('hr-pill-ps')) pills.insertAdjacentHTML('beforeend', '<li class="nav-item"><button id="hr-pill-ps" class="nav-link" onclick="hrTab(\'payslips\',this)"><i class="fa fa-file-invoice-dollar me-1"></i>Payslips</button></li>');
    if (!document.getElementById('hr-pane-payslips')) pills.parentElement.insertAdjacentHTML('beforeend', '<div id="hr-pane-payslips" class="d-none"></div>');
    const pane = document.getElementById('hr-pane-payroll');
    if (pane && !document.getElementById('hr-team2')) pane.insertAdjacentHTML('afterbegin', '<div id="hr-team2"></div>');
    await hrRenderTeam();
  } catch (e) { console.error(e); }
};
function psOpenFor(uid) {
  const pill = document.getElementById('hr-pill-ps'); if (pill) hrTab('payslips', pill);
  setTimeout(() => { const s = document.getElementById('ps-user'); if (s) { s.value = uid; psPick(); } }, 600);
}
async function loadPayslips() {
