  window._psStaff = s.staff;
  const num = (id, label, ph) => `<div class="col-6"><label class="form-label">${label}</label><input type="number" id="${id}" class="form-control form-control-sm" min="0" step="0.01" placeholder="${ph || '0.00'}"></div>`;
  el.innerHTML = `
    <div class="row g-3">
      <div class="col-lg-5"><div class="card"><div class="card-header d-flex align-items-center"><span class="ico-tile" style="width:30px;height:30px"><i class="fa fa-file-invoice-dollar"></i></span>Payslip studio</div><div class="card-body">
        <div class="row g-2">
          <div class="col-12"><label class="form-label">Staff</label><select id="ps-user" class="form-select form-select-sm" onchange="psPick()"><option value="">Select staff…</option>${s.staff.map(x => `<option value="${x.user_id}">${esc(x.full_name)}</option>`).join('')}</select></div>
          <div class="col-12"><label class="form-label">Month</label><input type="month" id="ps-month" class="form-control form-control-sm" value="${new Date().toISOString().slice(0, 7)}" onchange="psPreview()"></div>
          ${num('ps-allow', 'Allowances (KSh)')}${num('ps-ot', 'Overtime (KSh)')}
          ${num('ps-ins', 'Insurance premium paid by staff')}${num('ps-adv', 'Salary advance')}
          ${num('ps-oth', 'Other deductions')}
          <div class="col-6 d-flex align-items-end"><div class="form-check"><input class="form-check-input" type="checkbox" id="ps-def"><label class="form-check-label small" for="ps-def">Save allowances and insurance as defaults</label></div></div>
        </div>
        <div class="d-flex gap-2 mt-3 flex-wrap">
          <button class="btn btn-outline-secondary" onclick="psPreview()"><i class="fa fa-calculator me-1"></i>Calculate</button>
          <button class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="psGenerate()"><i class="fa fa-paper-plane me-1"></i>Generate &amp; send</button></div>
        <div class="small text-nx-muted mt-2">A payslip is a statement. It does not move money; use Disburse or Hourly Payroll for that.</div>
      </div></div></div>
      <div class="col-lg-7"><div class="card"><div class="card-header">Live breakdown</div><div class="card-body" id="ps-out"><div class="text-nx-muted small">Pick a staff member and tap Calculate.</div></div></div></div>
    </div>
    <div class="card mt-3"><div class="card-header">Generated payslips</div><div class="table-responsive"><table class="table table-sm mb-0">
      <thead><tr><th>Staff</th><th>Period</th><th class="text-end">Gross</th><th class="text-end">Deductions</th><th class="text-end">Net</th><th></th></tr></thead>
      <tbody>${(l.rows || []).map(r => `<tr><td class="fw-bold small">${esc(r.full_name)}</td><td class="small">${esc(r.period)}</td><td class="text-end small">${fmt(r.gross)}</td><td class="text-end small text-danger">${fmt(r.total_deductions)}</td><td class="text-end fw-bold text-accent">${fmt(r.net)}</td>
        <td><a class="btn btn-sm btn-outline-warning" href="${SELF}?action=payslip_view&id=${r.id}" target="_blank"><i class="fa fa-eye me-1"></i>View</a></td></tr>`).join('') || '<tr><td colspan="6" class="text-center text-nx-muted py-3">No payslips yet</td></tr>'}</tbody></table></div></div>`;
}
function psPick() {
  const u = (window._psStaff || []).find(x => x.user_id == document.getElementById('ps-user').value);
  document.getElementById('ps-allow').value = u && parseFloat(u.allowances) ? u.allowances : '';
  document.getElementById('ps-ins').value = u && parseFloat(u.insurance_premium) ? u.insurance_premium : '';
  ['ps-ot', 'ps-adv', 'ps-oth'].forEach(i => document.getElementById(i).value = '');
  if (u) psPreview();
}
function psParams() {
  const g = id => document.getElementById(id)?.value || '';
  return { user_id: g('ps-user'), month: g('ps-month'), allowances: g('ps-allow'), overtime: g('ps-ot'), insurance_premium: g('ps-ins'), advance: g('ps-adv'), other_deduct: g('ps-oth') };
}
async function psPreview() {
  const p = psParams(); if (!p.user_id) { toast('Pick a staff member', 'error'); return; }
  const r = await api('payslip_preview', p);
  const out = document.getElementById('ps-out');
  if (!r.ok) { out.innerHTML = `<div class="alert alert-warning small mb-0">${esc(r.msg || 'Could not calculate.')}</div>`; return; }
  const d = r.p, row = (l, v, neg) => `<tr><td>${l}</td><td class="r ${neg ? 'text-danger' : ''}">${neg ? '− ' : ''}${fmt(v)}</td></tr>`;
  out.innerHTML = `
    <div class="d-flex justify-content-between align-items-center mb-2"><div class="fw-bold">${esc(d.name)} <span class="small text-nx-muted">· ${esc(d.role)}</span></div><span class="hr-chip2">${d.pay_type === 'hourly' ? d.hours + ' h × ' + fmt(d.rate) : 'Fixed salary'}</span></div>
    <table class="w-100 ps-pre"><tbody>
      ${row(d.pay_type === 'hourly' ? 'Hourly pay' : 'Basic salary', d.basic)}${d.allowances ? row('Allowances', d.allowances) : ''}${d.overtime ? row('Overtime', d.overtime) : ''}
      <tr class="t"><td>Gross pay</td><td class="r">${fmt(d.gross)}</td></tr>
      ${row('PAYE', d.paye, 1)}${row('NSSF', d.nssf, 1)}${row('SHIF', d.shif, 1)}${row('Housing levy', d.ahl, 1)}
      ${d.insurance_premium ? row('Insurance premium', d.insurance_premium, 1) : ''}${d.advance ? row('Salary advance', d.advance, 1) : ''}${d.other_deduct ? row('Other deductions', d.other_deduct, 1) : ''}
      <tr class="t"><td>Total deductions</td><td class="r text-danger">${fmt(d.total_deductions)}</td></tr></tbody></table>
    <div class="d-flex justify-content-between align-items-center mt-3 p-3 rounded" style="background:#0b1020;color:#fff"><span class="small" style="letter-spacing:1px;opacity:.7">NET PAY</span><b style="font-size:1.6rem;color:#4ade80">${fmt(d.net)}</b></div>
    <div class="small text-nx-muted mt-2">Taxable pay ${fmt(d.taxable)} · tax ${fmt(d.tax_before)} − personal relief ${fmt(d.personal_relief)}${d.insurance_relief ? ' − insurance relief ' + fmt(d.insurance_relief) : ''}. Employer pays NSSF ${fmt(d.employer_nssf)} + levy ${fmt(d.employer_ahl)} on top.</div>`;
}
async function psGenerate() {
  const p = psParams(); if (!p.user_id) { toast('Pick a staff member', 'error'); return; }
  if (document.getElementById('ps-def').checked) p.save_defaults = 1;
  if (!confirm('Generate this payslip and notify the staff member? An existing payslip for the same month will be replaced.')) return;
  const r = await api('payslip_generate', p, 'POST');
  if (!r.ok) { toast(r.msg || 'Failed.', 'error'); return; }
  toast(r.msg, 'success');
  window.open(SELF + '?action=payslip_view&id=' + r.id, '_blank');
  loadPayslips();
}

// ── Staff: their own payslips on My Finance ──
const _nxFin2 = renderFinance;
