// ══════════════ HR v4: profile cards, CV upload, hero, read-only staff view ══════════════
const hrMask = a => a ? '••••' + String(a).slice(-4) : '—';
const hrExt  = p => ((p || '').split('?')[0].split('.').pop() || '').toLowerCase();
const hrCvUrl = uid => SELF + '?action=staff_cv_view&uid=' + uid;

// CVs are now read through the gated endpoint (PDF, DOCX, TXT)
hrReadCvFile = async function (uid, ext) {
  const url = hrCvUrl(uid);
  if (ext === 'pdf') {
    await loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');
    pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    const pdf = await pdfjsLib.getDocument({ url, withCredentials: true }).promise; let out = '';
    for (let i = 1; i <= Math.min(pdf.numPages, 6); i++) {
      const tc = await (await pdf.getPage(i)).getTextContent();
      out += tc.items.map(x => x.str).join(' ') + '\n';
    }
    return out.trim();
  }
  if (ext === 'docx') {
    await loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js');
    const buf = await (await fetch(url, { credentials: 'same-origin' })).arrayBuffer();
    return ((await mammoth.extractRawText({ arrayBuffer: buf })).value || '').trim();
  }
  if (ext === 'txt') return (await (await fetch(url, { credentials: 'same-origin' })).text()).trim();
  throw new Error('Old .doc files cannot be read automatically.');
};
hrAiStart = async function (kind, idx) {
  const o = kind === 'user' ? _hrS[idx] : _hrA[idx];
  window._hrAiCtx = { kind, id: kind === 'user' ? o.user_id : o.id, name: o.full_name };
  hrAiOpen(o.full_name);
  if (kind === 'user') {
    if (!o.cv_path) { hrAiPaste(o.full_name, 'No CV on file yet. Upload one from the card, or paste the text below.'); return; }
    hrAiLoader(o.full_name, true);
    let text = '';
    try { text = await hrReadCvFile(o.user_id, hrExt(o.cv_path)); } catch (e) { console.warn(e); }
    if (text.length < 80) { hrAiPaste(o.full_name, "We couldn't pull readable text out of this CV (scanned image or old .doc)."); return; }
    await hrAiSend(text);
  } else {
    await hrAiSend('');
  }
};

function hrCvUpload(uid) {
  const i = document.createElement('input'); i.type = 'file'; i.accept = '.pdf,.docx,.doc,.txt';
  i.onchange = async () => {
    const f = i.files[0]; if (!f) return;
    if (f.size > 4 * 1024 * 1024) { toast('CV too large (max 4MB)', 'error'); return; }
    toast('Uploading CV…', 'info');
    const r = await api('staff_cv_upload', { user_id: uid, cv: f }, 'POST');
    if (r.ok) { toast('CV uploaded. Tap NYMIX AI to read it.', 'success'); hrRenderTeam(); }
    else toast(r.msg || 'Upload failed.', 'error');
  };
  i.click();
}

// ── hero stats ──
function hrPaintStats() {
  const el = document.getElementById('hr-hero-stats'); if (!el) return;
  const fixed = _hrS.filter(s => s.pay_type !== 'hourly').reduce((a, s) => a + parseFloat(s.fixed_salary || 0), 0);
  const hourly = _hrS.filter(s => s.pay_type === 'hourly').length;
  const noCv = _hrS.filter(s => !s.cv_path).length;
  el.innerHTML = `
    <div class="hr-stat"><b>${_hrS.length}</b><span>Staff</span></div>
    <div class="hr-stat"><b>${_hrA.length}</b><span>Awaiting sign-up</span></div>
    <div class="hr-stat"><b>${fmt(fixed)}</b><span>Fixed payroll / month</span></div>
    <div class="hr-stat"><b>${hourly}</b><span>Hourly staff</span></div>
    <div class="hr-stat"><b>${noCv}</b><span>Missing a CV</span></div>`;
}

// ── centered profile cards (replaces the earlier card painter) ──
hrPaintTeam = function () {
  const host = document.getElementById('hr-team2'); if (!host) return;
  hrPaintStats();
  const q = (document.getElementById('hr2-q')?.value || '').toLowerCase();
  const staff = _hrS.map((s, i) => [s, i]).filter(([s]) => !q || (s.full_name || '').toLowerCase().includes(q));
  const appt  = _hrA.map((a, i) => [a, i]).filter(([a]) => !q || (a.full_name || '').toLowerCase().includes(q));
  const av = (o, kind, i) => `<div class="hr3-av" onclick="hrProfile('${kind}',${i})" style="${o.photo_path ? `background-image:url('${esc(o.photo_path)}')` : ''}">${o.photo_path ? '' : esc((o.full_name || '?').charAt(0).toUpperCase())}</div>`;
  const pay = o => {
    const hourly = o.pay_type === 'hourly', val = hourly ? o.hourly_rate : o.fixed_salary;
    const allow = parseFloat(o.allowances || 0) > 0 ? `<small style="text-transform:none;letter-spacing:0;margin-top:2px">+ ${fmt(o.allowances)} allowances</small>` : '';
    return `<div class="hr3-pay"><small>${hourly ? 'Hourly rate' : 'Monthly salary'}</small><span class="amt">${val ? fmt(val) : 'Not set'}</span>${hourly && val ? ' <small style="display:inline">/ hour</small>' : ''}${allow}
      <div class="mt-2"><span class="hr-chip2 ${o.pay_method === 'mpesa' ? 'g' : ''}"><i class="fa fa-wallet me-1"></i>${esc(PAY_METHODS[o.pay_method] || 'Bank Transfer')}</span></div></div>`;
  };
  const B = (ic, label, fn, cls, dis) => `<button class="${cls || ''}" ${dis ? 'disabled' : `onclick="${fn}"`}><i class="fa ${ic}"></i>${label}</button>`;

  const staffCard = ([s, i]) => `
    <article class="hr3-card"><div class="hr3-cover"></div>${av(s, 'u', i)}
      <div class="hr3-name">${esc(s.full_name)}${s.id_verified ? verifiedBadge(16) : ''}</div>
      <div class="hr3-role">${esc(s.role_name || '')}${s.branch_name ? ' · ' + esc(s.branch_name) : ''}</div>
      <div class="hr3-chips">
        <span class="hr-chip2 ${s.id_verified ? 'g' : 'w'}">${s.id_verified ? 'ID verified' : 'Not verified'}</span>
        <span class="hr-chip2">${s.pay_type === 'hourly' ? 'Hourly' : 'Fixed salary'}</span>
        <span class="hr-chip2 ${s.cv_path ? 'g' : 'r'}">${s.cv_path ? 'CV on file' : 'No CV'}</span></div>
      ${pay(s)}
      <div class="hr3-info">
        <div><span>Phone</span><b>${esc(s.phone || '—')}</b></div>
        <div><span>ID number</span><b>${esc(s.id_number || '—')}</b></div>
        <div><span>Bank</span><b>${s.bank_name ? esc(s.bank_name) + ' ' + hrMask(s.bank_account) : '—'}</b></div>
        <div><span>Joined</span><b>${s.joined_at ? fmtDate(s.joined_at) : '—'}</b></div></div>
      <div class="hr3-ai">${hrAiLine(_hrP['u' + s.user_id])}</div>
      <div class="hr3-acts">
        ${B('fa-comment-dots', 'Message', `hrMessage(${s.user_id})`, '', s.user_id == CU.id)}
        ${B('fa-file-invoice-dollar', 'Payslip', `psOpenFor(${s.user_id})`)}
        ${B('fa-wand-magic-sparkles', 'NYMIX AI', `hrAiStart('user',${i})`, 'ai')}
        ${B('fa-money-check-dollar', 'Salary', `openQuickSalaryModal(_hrS[${i}])`)}
        ${B('fa-upload', s.cv_path ? 'New CV' : 'Upload CV', `hrCvUpload(${s.user_id})`)}
        ${B('fa-file-lines', 'View CV', `window.open(hrCvUrl(${s.user_id}),'_blank')`, '', !s.cv_path)}
        ${B('fa-id-card', 'ID card', `cardReprintFor(${s.user_id})`)}
        ${B('fa-user', 'Profile', `hrProfile('u',${i})`)}
      </div></article>`;

  const apptCard = ([a, i]) => `
    <article class="hr3-card"><div class="hr3-cover" style="background:linear-gradient(135deg,#1E9E52,#17C548)"></div>${av(a, 'a', i)}
      <div class="hr3-name">${esc(a.full_name)}</div>
      <div class="hr3-role">${esc(a.role_name || '')} · ${esc(a.branch_name || '')}</div>
      <div class="hr3-chips"><span class="hr-chip2 w">Waiting to register</span><span class="hr-chip2">${a.pay_type === 'hourly' ? 'Hourly' : 'Fixed salary'}</span></div>
      ${pay(a)}
      <div class="hr3-info">
        <div><span>ID number</span><b>${esc(a.national_id || '—')}</b></div>
        <div><span>Card no.</span><b>${esc(a.card_no || '—')}</b></div></div>
      <div class="hr3-ai">${hrAiLine(_hrP['a' + a.id])}</div>
      <div class="hr3-acts three">
        ${B('fa-wand-magic-sparkles', 'Role brief', `hrAiStart('appt',${i})`, 'ai')}
        ${B('fa-id-card', 'ID card', `showAppointedCard(${a.id})`)}
        ${B('fa-trash', 'Remove', `removeApointStaff(${a.id})`)}
      </div></article>`;

  host.innerHTML = `<div class="hr3-wrap">
    <div class="hr3-bar"><div class="t"><span class="ico-tile" style="width:32px;height:32px;margin:0"><i class="fa fa-users"></i></span>Your team <span class="n">${staff.length}</span></div>
      <input id="hr2-q" class="form-control form-control-sm" style="width:min(240px,100%)" placeholder="Search staff…" value="${esc(q)}" oninput="hrPaintTeam()">
      <button class="btn btn-sm fw-bold" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="openApointStaffModal()"><i class="fa fa-user-plus me-1"></i>Appoint staff</button></div>
    <div class="hr3-grid">${staff.map(staffCard).join('') || '<div class="text-nx-muted small p-3">No staff match.</div>'}</div>
    ${_hrA.length ? `<div class="hr3-bar"><div class="t"><span class="ico-tile" style="width:32px;height:32px;margin:0"><i class="fa fa-clipboard-user"></i></span>Appointed, waiting to register <span class="n">${appt.length}</span></div></div>
    <div class="hr3-grid">${appt.map(apptCard).join('')}</div>` : ''}</div>`;
  if (q) { const i = document.getElementById('hr2-q'); i.focus(); i.setSelectionRange(q.length, q.length); }
};

// ── full staff profile (opens from the avatar or Profile button) ──
function hrProfAct(act, i) {
