  setTimeout(() => ({
    msg: () => hrMessage(_hrS[i].user_id), ps: () => psOpenFor(_hrS[i].user_id), ai: () => hrAiStart('user', i),
    sal: () => openQuickSalaryModal(_hrS[i]), cv: () => hrCvUpload(_hrS[i].user_id), card: () => cardReprintFor(_hrS[i].user_id),
    aai: () => hrAiStart('appt', i), acard: () => showAppointedCard(_hrA[i].id),
  })[act](), 320);
}
