      <div class="hr3-name" style="font-size:1.25rem">${esc(o.full_name)}${isU && o.id_verified ? verifiedBadge(18) : ''}</div>
      <div class="hr3-role">${esc(o.role_name || '')} · ${esc(o.branch_name || '')}</div>
      <div class="hr3-chips">${isU ? `<span class="hr-chip2 ${o.id_verified ? 'g' : 'w'}">${o.id_verified ? 'ID verified' : 'Not verified'}</span><span class="hr-chip2 ${o.cv_path ? 'g' : 'r'}">${o.cv_path ? 'CV on file' : 'No CV'}</span>` : '<span class="hr-chip2 w">Waiting to register</span>'}</div>
    </div>
    <div class="hr3-sec">Employment</div>
    <div class="hr3-pm-grid">
      ${T('Role', esc(o.role_name || '—'))}${T('Branch', esc(o.branch_name || '—'))}
      ${isU ? T('Joined', o.joined_at ? fmtDate(o.joined_at) : '—') + T('Last login', o.last_login ? fmtDate(o.last_login) : 'Never') + T('Email', esc(o.email || '—')) + T('Card no.', esc(o.card_no || '—')) : T('Appointed', fmtDate(o.created_at)) + T('Card no.', esc(o.card_no || '—'))}
      ${T('ID number', esc((isU ? o.id_number : o.national_id) || '—'))}${isU ? T('Phone', esc(o.phone || '—')) : ''}
    </div>
    <div class="hr3-sec">Pay</div>
    <div class="hr3-pm-grid">
      ${T('Pay type', hourly ? 'Hourly' : 'Fixed salary')}${T(hourly ? 'Hourly rate' : 'Monthly salary', fmt(hourly ? o.hourly_rate : o.fixed_salary))}
      ${T('Paid via', esc(PAY_METHODS[o.pay_method] || 'Bank Transfer'))}
      ${isU ? T('Allowances', fmt(o.allowances || 0)) + T('Insurance premium', fmt(o.insurance_premium || 0)) + T('Bank', o.bank_name ? esc(o.bank_name) + ' ' + hrMask(o.bank_account) : '—') : ''}
    </div>
    <div class="hr3-sec">NYMIX AI profile</div>
    ${ai ? `<div class="hr3-ai" style="margin:0;text-align:left"><b>${esc(ai.headline || '')}</b><br>${esc(ai.summary || '')}
      ${jarr(ai.skills).length ? `<div class="mt-2">${jarr(ai.skills).map(s => `<span class="hrai-tag">${esc(s)}</span>`).join('')}</div>` : ''}
      ${jarr(ai.duties).length ? `<div class="mt-2"><b>Duties</b><ul class="mb-0 ps-3">${jarr(ai.duties).map(s => `<li>${esc(s)}</li>`).join('')}</ul></div>` : ''}
      ${ai.gaps ? `<div class="mt-2"><b>Worth checking or training:</b> ${esc(ai.gaps)}</div>` : ''}</div>`
      : '<div class="hr3-ai" style="margin:0">No AI profile yet.</div>'}
    ${isU ? '<div class="hr3-sec">Payslips</div><div id="hrp-ps" class="small text-nx-muted">Loading…</div>' : ''}
    <div class="d-flex gap-2 flex-wrap justify-content-center mt-4">
      ${isU ? AB('fa-comment-dots', 'Message', 'msg') + AB('fa-file-invoice-dollar', 'Payslip', 'ps') + AB('fa-wand-magic-sparkles', 'NYMIX AI', 'ai', 'btn-primary') + AB('fa-money-check-dollar', 'Edit salary', 'sal') + AB('fa-upload', 'Upload CV', 'cv') + (o.cv_path ? `<a class="btn btn-sm btn-outline-secondary" href="${hrCvUrl(o.user_id)}" target="_blank"><i class="fa fa-file-lines me-1"></i>View CV</a>` : '') + AB('fa-id-card', 'ID card', 'card')
           : AB('fa-wand-magic-sparkles', 'Role brief', 'aai', 'btn-primary') + AB('fa-id-card', 'ID card', 'acard')}
    </div>`;
  openModal('modal-hrprof');
  if (isU) {
    const r = await api('payslip_list');
    const box = document.getElementById('hrp-ps'); if (!box) return;
    const rows = (r.rows || []).filter(x => x.user_id == o.user_id).slice(0, 6);
    box.innerHTML = rows.length ? rows.map(x => `<div class="d-flex justify-content-between align-items-center py-2 border-bottom" style="border-color:var(--nx-border)!important"><span class="fw-bold">${esc(x.period)}</span><span>Net ${fmt(x.net)}</span><a class="btn btn-sm btn-outline-warning" href="${SELF}?action=payslip_view&id=${x.id}" target="_blank">View</a></div>`).join('') : 'No payslips yet.';
  }
}

