        ${T('CV on file', u.has_cv ? `<a href="${hrCvUrl(r.uid)}" target="_blank">View my CV</a>` : 'None')}
      </div>
      ${ai ? `<div class="hr3-ai mt-3" style="margin-left:0;margin-right:0;text-align:left"><b>${esc(ai.headline || '')}</b><br>${esc(ai.summary || '')}
        ${jarr(ai.skills).length ? `<div class="mt-2">${jarr(ai.skills).map(s => `<span class="hrai-tag">${esc(s)}</span>`).join('')}</div>` : ''}</div>` : ''}
      <div class="small text-nx-muted mt-3">Something wrong here? Tell your manager. Only they can change role, pay and employment details.</div></div></div>`;
    const wc = host.querySelector('.wc-wrap');
    wc ? wc.insertAdjacentHTML('afterend', html) : host.insertAdjacentHTML('afterbegin', html);
