document.head.insertAdjacentHTML('beforeend', `<style>
.hl-ov{position:fixed;inset:0;z-index:100060;display:flex;align-items:center;justify-content:center;padding:20px;overflow:auto;color:#fff;background:radial-gradient(circle at 50% 30%,#1a2140,#0a0d16 70%)}
