.hl-box{text-align:left;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:12px 14px;margin:14px 0 0;font-size:.84rem;line-height:1.55}
.hl-box.need{border-color:rgba(30,158,82,.5);background:rgba(30,158,82,.1)}
.hl-box.warn{border-color:rgba(249,115,22,.5);background:rgba(249,115,22,.1)}
