</style>`);

// ── Staff: "Checking account health…" then either through, or locked with "Account under review" ──
let _hlTimer = null, _hlSig = '';
const HL_CHECK = `<div class="hl-card"><div class="hl-ring"><i class="fa fa-shield-halved"></i></div><h4>Checking account health…</h4><p>Please wait while we run a quick security and compliance check on your account.</p><div class="hl-bar"><span></span></div></div>`;
const HL_OK = `<div class="hl-card"><div class="hl-ring ok"><i class="fa fa-check"></i></div><h4>Your account is healthy</h4><p>Taking you in…</p></div>`;
function hlSet(html) {
  let o = document.getElementById('hl-ov');
  if (!o) { o = document.createElement('div'); o.id = 'hl-ov'; o.className = 'hl-ov'; document.body.appendChild(o); }
  o.innerHTML = html;
}
function hlClose() { document.getElementById('hl-ov')?.remove(); }
function hlPaint(r, force) {
  const sig = JSON.stringify([r.status, r.manager_note, r.meeting_at, r.meeting_location, r.staff_response]);
  if (!force && sig === _hlSig) return;
  _hlSig = sig;
  const keep = document.getElementById('hl-resp')?.value || '';
  const fd = s => new Date(s.replace(' ', 'T')).toLocaleString('en-KE', { weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
  let status;
  if (r.status === 'meeting' && r.meeting_at) status = `<div class="hl-box"><b><i class="fa fa-calendar-check me-2"></i>Meeting scheduled</b><br>${esc(fd(r.meeting_at))}${r.meeting_location ? ' · ' + esc(r.meeting_location) : ''}<br><small style="color:#94a3b8">Please attend on time. Your manager will go over the review with you.</small></div>`;
  else if (r.status === 'upheld') status = `<div class="hl-box warn"><b><i class="fa fa-circle-exclamation me-2"></i>Review concluded</b><br>Your account remains restricted for now. Please speak to your manager.</div>`;
  else status = `<div class="hl-box"><b><i class="fa fa-hourglass-half me-2"></i>Review in progress</b><br>Your manager is reviewing this and we will notify you once the review is done.</div>`;
  const need = r.manager_note ? `<div class="hl-box need"><b><i class="fa fa-clipboard-list me-2"></i>From your manager</b><br>${esc(r.manager_note)}</div>` : '';
  hlSet(`<div class="hl-card"><div class="hl-ring warn"><i class="fa fa-user-shield"></i></div><h4>Account under review</h4>
    <p>For now you can't proceed with anything until the review is complete. We will notify you as soon as it is done.</p>
    ${status}${need}
    ${r.staff_response ? '<p style="margin-top:12px"><i class="fa fa-check me-1"></i>Your reply was sent to your manager. You can send an update below.</p>' : ''}
    <textarea id="hl-resp" rows="3" maxlength="1000" placeholder="Need to explain something or provide what your manager asked for? Write it here…">${esc(keep)}</textarea>
    <button class="hl-btn" onclick="hlSendReply()"><i class="fa fa-paper-plane me-2"></i>Send to my manager</button>
    <button class="hl-btn hl-out" onclick="doLogout()"><i class="fa fa-right-from-bracket me-2"></i>Sign out</button></div>`);
  const t = document.getElementById('hl-resp'); if (t) t.value = keep;
}
async function hlSendReply() {
  const v = document.getElementById('hl-resp')?.value.trim();
  if (!v) { toast('Write your reply first', 'error'); return; }
  const r = await api('health_respond', { text: v }, 'POST');
  if (r.ok) { toast('Sent to your manager', 'success'); document.getElementById('hl-resp').value = ''; _hlSig = ''; } else toast(r.msg || 'Failed', 'error');
}
async function healthGate() {
  window._hlShowing = true;
  hlSet(HL_CHECK);
  const t0 = Date.now();
  const d = await api('health_check');
  await new Promise(r => setTimeout(r, Math.max(0, 1500 - (Date.now() - t0))));
  if (!d.ok || !d.blocked) {
    if (d.ok) { hlSet(HL_OK); await new Promise(r => setTimeout(r, 600)); }
    hlClose(); window._hlShowing = false; return true;
  }
  return new Promise(resolve => {
    hlPaint(d.review, true);
    clearInterval(_hlTimer);
    _hlTimer = setInterval(async () => {
      const x = await api('health_check');
      if (!x.ok) return;
      if (!x.blocked) {
        clearInterval(_hlTimer); hlClose(); window._hlShowing = false;
        toast('Your account review is complete. Welcome back!', 'success'); resolve(true);
      } else hlPaint(x.review, false);
    }, 20000);
  });
}
const _hlInit = init;
init = function () {
  if (!CU) return;
  if (window._hlPassed) return _hlInit();
  healthGate().then(ok => { if (ok) { window._hlPassed = true; _hlInit(); } });
};

// ── Nav / home tweaks ──
const _hlBN = buildNav;
buildNav = function () {
  _hlBN();
  const h = (sel, s) => { const e = document.querySelector(sel); if (e) e.style.display = s ? '' : 'none'; };
  h('#nav-health-sec', can(R.OWNER, R.MANAGER));
  h('.nx-nav-link[data-page="pos"]', can(R.OWNER, R.CASHIER));
};
const _hlHG = HOME_GROUPS;
HOME_GROUPS = function () {
  const g = _hlHG();
  g.forEach(x => x.items.forEach(i => { if (i[0] === 'pos') i[5] = [R.OWNER, R.CASHIER]; }));
  const b = g.find(x => x.n === 'Business');
  if (b) b.items.push(['reviews', 'Accounts Under Review', 'fa-user-shield', '#ef4444', 'AI flags & decisions', [R.OWNER, R.MANAGER]]);
  return g;
};
const _hlNavNow = navigateNow;
navigateNow = async function (page) {
  if (page !== 'reviews') return _hlNavNow(page);
  if (!can(R.OWNER, R.MANAGER)) { toast('You do not have access to this section.', 'error'); return; }
  showChrome();
  document.querySelectorAll('.nx-nav-link').forEach(b => b.classList.toggle('active', b.dataset.page === page));
  document.getElementById('page-title').textContent = PAGE_TITLES.reviews;
  closeSidebar();
  const el = document.getElementById('nx-content'); loading(el);
  await renderReviews(el); nxAfterNav(page);
};

// ── Manager / owner: Accounts Under Review ──
let _hlView = 'todo', _hlRows = [];
const HL_ST = { open: ['Needs your decision', 'warning'], meeting: ['Meeting scheduled', 'primary'], upheld: ['Restricted', 'danger'], cleared: ['Reinstated', 'success'] };
const HL_CODE = { EXCESS_VOIDS: 'Excess voids', HIGH_DISCOUNTS: 'High discounts', STOCK_WRITEOFFS: 'Stock write-offs' };
const hlJ = s => { try { return JSON.parse(s || '[]'); } catch (e) { return []; } };
const hlWhen = s => s ? new Date(String(s).replace(' ', 'T')).toLocaleString('en-KE', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';

async function hlBadge() {
  const d = await api('health_count'); const b = document.getElementById('hl-badge');
  if (b && d.ok) { b.textContent = d.n; b.classList.toggle('d-none', !d.n); }
}
async function renderReviews(el) {
  el.innerHTML = `<div style="max-width:1200px;margin:0 auto">
    <div class="mb-3"><h5 class="fw-head mb-0"><i class="fa fa-user-shield text-accent me-2"></i>Accounts Under Review</h5>
      <div class="small text-nx-muted">Accounts our health checks flagged. These staff are locked out until you decide.</div></div>
    <ul class="nav nav-tabs" id="hl-tabs">
      <li class="nav-item"><button class="nav-link ${_hlView === 'todo' ? 'active' : ''}" onclick="_hlView='todo';renderReviews(document.getElementById('nx-content'))">Under review</button></li>
      <li class="nav-item"><button class="nav-link ${_hlView === 'done' ? 'active' : ''}" onclick="_hlView='done';renderReviews(document.getElementById('nx-content'))">Reinstated</button></li></ul>
    <div id="hl-list" class="mt-3"></div></div>`;
  await hlLoad();
}
async function hlLoad() {
  const box = document.getElementById('hl-list'); if (!box) return; loading(box);
  const d = await api('health_reviews_list', { view: _hlView });
  if (!d.ok) { box.innerHTML = `<p class="text-danger">${esc(d.msg || 'Failed')}</p>`; return; }
  _hlRows = d.rows;
  if (!d.rows.length) { box.innerHTML = `<div class="card p-5 text-center text-nx-muted"><div style="font-size:2.2rem">✅</div><div class="mt-2">${_hlView === 'todo' ? 'No accounts under review. All clear.' : 'Nothing here yet.'}</div></div>`; return; }
  box.innerHTML = `<div class="row g-3">${d.rows.map((r, i) => {
    const [lbl, c] = HL_ST[r.status] || ['', 'secondary'], fl = hlJ(r.flags);
    const txt = (r.ai_summary || (fl[0] && fl[0].text) || '');
    return `<div class="col-md-6 col-xl-4"><div class="card h-100"><div class="card-body d-flex flex-column gap-2">
      <div class="d-flex align-items-center gap-3">
        <div class="hr2-av" style="width:46px;height:46px;font-size:1rem;${r.photo_path ? `background-image:url('${esc(r.photo_path)}')` : ''}">${r.photo_path ? '' : esc((r.full_name || '?').charAt(0).toUpperCase())}</div>
        <div style="min-width:0"><b class="d-block text-truncate">${esc(r.full_name)}</b><small class="text-nx-muted">${esc(r.role_name)} · ${esc(r.branch_name)}</small></div>
        <span class="badge bg-${c} bg-opacity-25 text-${c} ms-auto">${lbl}</span></div>
      <div class="small text-nx-muted">Flagged ${hlWhen(r.created_at)}${r.staff_response ? ' · <span class="text-accent">staff replied</span>' : ''}</div>
      <div>${fl.map(f => `<span class="hr-chip2 r me-1 mb-1">${esc(HL_CODE[f.code] || f.code)}</span>`).join('')}</div>
      <div class="small" style="line-height:1.5">${esc(txt.slice(0, 170))}${txt.length > 170 ? '…' : ''}</div>
      <button class="btn btn-sm fw-bold mt-auto" style="background:var(--nx-accent);color:#fff" onclick="hlOpen(${i})">${r.status === 'cleared' ? 'View' : 'Review &amp; decide'}</button>
    </div></div></div>`;
  }).join('')}</div>`;
}
function hlModal(title, html) {
  let m = document.getElementById('modal-hl');
  if (!m) {
    m = document.createElement('div'); m.className = 'modal fade'; m.id = 'modal-hl'; m.tabIndex = -1;
    m.innerHTML = '<div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title fw-head" id="hlm-t"></h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="hlm-b"></div></div></div>';
    document.body.appendChild(m);
  }
  document.getElementById('hlm-t').textContent = title; document.getElementById('hlm-b').innerHTML = html; openModal('modal-hl');
}
function hlOpen(i) {
  const r = _hlRows[i], fl = hlJ(r.flags), ev = hlJ(r.evidence), open = r.status !== 'cleared';
  const [lbl, c] = HL_ST[r.status] || ['', 'secondary'];
  const ico = { void: 'fa-ban', discount: 'fa-tag', stock: 'fa-boxes-stacked' };
  const dt = new Date(Date.now() + 864e5); dt.setHours(10, 0, 0, 0);
  const dtv = new Date(dt - dt.getTimezoneOffset() * 6e4).toISOString().slice(0, 16);
  hlModal(r.full_name, `
    <div class="d-flex align-items-center gap-3 flex-wrap mb-3">
      <div class="hr2-av" style="width:56px;height:56px;${r.photo_path ? `background-image:url('${esc(r.photo_path)}')` : ''}">${r.photo_path ? '' : esc((r.full_name || '?').charAt(0).toUpperCase())}</div>
      <div><b>${esc(r.full_name)}</b>${parseInt(r.id_verified) ? verifiedBadge(15) : ''}<div class="small text-nx-muted">${esc(r.role_name)} · ${esc(r.branch_name)}</div></div>
      <span class="badge bg-${c} bg-opacity-25 text-${c} ms-auto">${lbl}</span></div>
    ${r.meeting_at ? `<div class="alert alert-info py-2 small"><i class="fa fa-calendar-check me-1"></i>Meeting: <b>${hlWhen(r.meeting_at)}</b> · ${esc(r.meeting_location || '')}</div>` : ''}
    <div class="hr3-sec" style="margin-top:6px">What the system flagged</div>
    ${fl.map(f => `<div class="small mb-1"><span class="hr-chip2 r me-2">${esc(HL_CODE[f.code] || f.code)}</span>${esc(f.text)}</div>`).join('')}
    <div class="hr3-sec">NYMIX AI summary</div>
    ${r.ai_summary ? `<div class="hr3-ai" style="margin:0;text-align:left">${esc(r.ai_summary)}</div>` : '<div class="small text-nx-muted">AI summary unavailable. The rule-based flags above still apply.</div>'}
    <div class="small text-nx-muted mt-1">Flags come from fixed rules and the AI only explains them. Treat this as a lead to check, not proof of wrongdoing.</div>
    <div class="hr3-sec">Evidence (since ${hlWhen(r.scan_from)})</div>
    <div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Type</th><th>Reference</th><th>Detail</th><th class="text-end">Amount</th><th>When</th></tr></thead><tbody>
      ${ev.map(e => `<tr><td><i class="fa ${ico[e.kind] || 'fa-circle'} me-1 text-accent"></i>${esc(e.kind)}</td><td class="small fw-bold">${esc(e.ref)}</td><td class="small">${esc(e.detail)}</td><td class="text-end small">${fmt(e.amount)}</td><td class="small text-nx-muted">${hlWhen(e.at)}</td></tr>`).join('') || '<tr><td colspan="5" class="text-center text-nx-muted py-3">No line items.</td></tr>'}
    </tbody></table></div>
    ${r.staff_response ? `<div class="hr3-sec">Staff reply · ${hlWhen(r.staff_response_at)}</div><div class="hr3-ai" style="margin:0;text-align:left">${esc(r.staff_response)}</div>` : ''}
    ${(r.log || []).length ? `<div class="hr3-sec">Timeline</div>${r.log.map(l => `<div class="small border-bottom py-1" style="border-color:var(--nx-border)!important"><b>${esc(l.action.replace('_', ' '))}</b> ${esc(l.full_name ? '· ' + l.full_name : '')} <span class="text-nx-muted">· ${hlWhen(l.created_at)}</span>${l.note ? `<div class="text-nx-muted">${esc(l.note)}</div>` : ''}</div>`).join('')}` : ''}
    ${open ? `<div class="hr3-sec">Your decision</div>
    <div class="card p-3 mb-3" style="border-color:	rgba(30,158,82,.45)">
      <div class="d-flex align-items-center justify-content-between flex-wrap gap-2">
        <b class="small"><span class="nx-ai-tag me-2"><i class="fa fa-wand-magic-sparkles"></i> NYMIX AI</span>Analyse this review and write the emails</b>
        <button id="hl-ai-btn" class="btn btn-sm fw-bold" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="hlAiAssist(${i})"><i class="fa fa-wand-magic-sparkles me-1"></i>Analyse &amp; autofill</button></div>
      <div id="hl-ai-out" class="small text-nx-muted mt-2">AI recommends a decision and fills in a well-written email for each option below. You can edit anything before it is sent.</div>
    </div>
    <div class="row g-3">
      <div class="col-md-6"><div class="card p-3 h-100"><b class="small"><i class="fa fa-calendar-plus me-1 text-accent"></i>Schedule an office meeting</b>
        <input type="datetime-local" id="hl-mt" class="form-control form-control-sm mt-2" value="${dtv}">
        <input id="hl-ml" class="form-control form-control-sm mt-2" placeholder="Where (default: Branch office)">
        <textarea id="hl-mn" class="form-control form-control-sm mt-2" rows="4" placeholder="Message to staff (optional)"></textarea>
        <button class="btn btn-sm btn-primary mt-2" onclick="hlDecide(${i},'meeting')">Schedule &amp; notify</button></div></div>
      <div class="col-md-6"><div class="card p-3 h-100"><b class="small"><i class="fa fa-clipboard-question me-1 text-accent"></i>Ask the staff for something</b>
        <textarea id="hl-in" class="form-control form-control-sm mt-2" rows="3" placeholder="What do you need from them before reinstating?"></textarea>
        <button class="btn btn-sm btn-outline-warning mt-2" onclick="hlDecide(${i},'info')">Send request</button></div></div>
      <div class="col-md-6"><div class="card p-3 h-100"><b class="small"><i class="fa fa-circle-check me-1 text-success"></i>Reinstate account</b>
        <textarea id="hl-cn" class="form-control form-control-sm mt-2" rows="4" placeholder="Note (optional)"></textarea>
        <button class="btn btn-sm btn-success mt-2" onclick="hlDecide(${i},'clear')">Reinstate &amp; send email</button></div></div>
      <div class="col-md-6"><div class="card p-3 h-100"><b class="small"><i class="fa fa-ban me-1 text-danger"></i>Keep restricted</b>
        <textarea id="hl-un" class="form-control form-control-sm mt-2" rows="4" placeholder="Reason (required)"></textarea>
        <button class="btn btn-sm btn-outline-danger mt-2" onclick="hlDecide(${i},'uphold')">Keep restricted &amp; notify</button></div></div>
      ${can(R.OWNER) ? `<div class="col-12"><div class="card p-3" style="border-color:rgba(239,68,68,.6)"><b class="small text-danger"><i class="fa fa-file-circle-xmark me-1"></i>Terminate employment (owner only)</b>
        <textarea id="hl-tn" class="form-control form-control-sm mt-2" rows="3" placeholder="Reason for termination (goes into the letter)"></textarea>
        <button class="btn btn-sm btn-danger mt-2" onclick="hlDecide(${i},'terminate')">Terminate &amp; send letter</button>
        <div class="small text-nx-muted mt-1">Deactivates the account and emails a termination letter to the staff member, manager and owner. Make sure they were heard first.</div></div></div>` : ''}
    </div>` : `<div class="small text-nx-muted mt-3">Reinstated ${hlWhen(r.decided_at)}${r.decided_by_name ? ' by ' + esc(r.decided_by_name) : ''}.</div>`}`);
}
const HL_AI = {};
const HL_AI_LBL = { meeting: 'Schedule an office meeting', info: 'Request more information', clear: 'Reinstate the account', uphold: 'Keep the account restricted' };
async function hlAiAssist(i) {
  const r = _hlRows[i], btn = document.getElementById('hl-ai-btn'), out = document.getElementById('hl-ai-out');
  if (!btn || !out) return;
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Analysing…';
  out.innerHTML = '<span class="text-nx-muted">NYMIX AI is reading the flags, evidence and the staff reply…</span>';
  const d = await api('health_ai_assist', { id: r.id }, 'POST');
  btn.disabled = false; btn.innerHTML = '<i class="fa fa-rotate me-1"></i>Re-analyse';
  if (!d.ok) { out.innerHTML = `<span class="text-warning">${esc(d.msg || 'AI is unavailable right now.')}</span>`; return; }
  HL_AI[r.id] = d;
  const set = (id, v) => { const e = document.getElementById(id); if (e) e.value = v || ''; };
  set('hl-mn', d.drafts.meeting); set('hl-in', d.drafts.info); set('hl-cn', d.drafts.clear); set('hl-un', d.drafts.uphold);
  out.innerHTML = `
    <div class="p-3 rounded" style="background:	rgba(30,158,82,.08);border:1px dashed 	rgba(30,158,82,.45)">
      <div class="small text-nx-muted">AI RECOMMENDS · confidence ${esc(d.confidence)}</div>
      <div class="fw-bold" style="font-size:1.05rem">${esc(HL_AI_LBL[d.recommended])}</div>
      <div class="small mt-1" style="line-height:1.55;color:var(--nx-text)">${esc(d.reasoning)}</div>
      <div class="small text-nx-muted mt-2">All four email drafts are filled in below. Edit them if you like, then approve.</div>
      <button class="btn btn-sm fw-bold mt-2" style="background:#22c55e;color:#fff" onclick="hlAiApprove(${i})"><i class="fa fa-circle-check me-1"></i>Approve AI decision</button>
    </div>
    <div class="text-nx-muted mt-1" style="font-size:.65rem">AI suggests, you decide. This is a lead to check, not proof of wrongdoing.</div>`;
}
function hlAiApprove(i) {
  const a = HL_AI[_hlRows[i].id]; if (!a) return;
  if (['meeting', 'info'].includes(a.recommended) && !confirm('Approve the AI decision: ' + HL_AI_LBL[a.recommended] + '? The staff member will be emailed the message shown in the form.')) return;
  hlDecide(i, a.recommended);
}

async function hlDecide(i, dec) {
  const r = _hlRows[i], g = id => document.getElementById(id)?.value || '';
  const p = { id: r.id, decision: dec };
  if (dec === 'meeting') { p.meeting_at = g('hl-mt'); p.meeting_location = g('hl-ml'); p.note = g('hl-mn'); if (!p.meeting_at) { toast('Pick the meeting date and time', 'error'); return; } }
  if (dec === 'info') { p.note = g('hl-in'); if (!p.note.trim()) { toast('Say what you need from the staff member', 'error'); return; } }
  if (dec === 'clear') { p.note = g('hl-cn'); if (!confirm('Reinstate ' + r.full_name + '? They will be emailed and can sign in again.')) return; }
  if (dec === 'uphold') { p.note = g('hl-un'); if (!p.note.trim()) { toast('Add the reason for this decision', 'error'); return; } if (!confirm('Keep ' + r.full_name + "'s account restricted?")) return; }
  if (dec === 'terminate') { p.note = g('hl-tn'); if (!p.note.trim()) { toast('Add the reason for termination', 'error'); return; } if (!confirm('TERMINATE ' + r.full_name + '? Their account is deactivated and a termination letter is emailed. This cannot be undone here.')) return; }
  const res = await api('health_review_decide', p, 'POST');
  if (res.ok) { toast(res.msg || 'Done', 'success'); closeModal('modal-hl'); hlLoad(); hlBadge(); } else toast(res.msg || 'Failed', 'error');
}
if (CU && can(R.OWNER, R.MANAGER)) { hlBadge(); setInterval(hlBadge, 60000); }

// ── Stock-only dashboard (storekeeper and other non-finance roles) ──
async function dashboardStock(el) {
  el.innerHTML = `<div class="d-flex justify-content-center py-5"><div class="spinner-border text-warning"></div></div>`;
  const d = await api('dashboard_data');
  if (!d.ok) { el.innerHTML = '<p class="text-danger p-4">Failed to load dashboard.</p>'; return; }
  const kpi = (l, v, sub, c, ic) => `<div class="col-6 col-md-3"><div class="stat-card" style="--card-accent:${c}"><div class="stat-label">${l}</div><div class="stat-value">${v}</div><div class="stat-sub">${sub}</div><i class="fa ${ic} stat-icon"></i></div></div>`;
  const healthy = Math.max(0, d.tracked - d.low_stock);
  const low = (d.low_items || []).map(it => {
    const pct = it.reorder_level > 0 ? Math.min(100, Math.round(it.quantity / it.reorder_level * 100)) : 0;
    const col = it.quantity <= 0 ? 'var(--nx-red)' : pct < 50 ? 'var(--nx-orange)' : 'var(--nx-accent)';
    return `<div class="px-3 py-2 border-bottom" style="border-color:var(--nx-border)!important"><div class="d-flex justify-content-between mb-1"><span class="small fw-bold text-truncate" style="max-width:240px">${esc(it.name)}</span><span style="color:${col};font-size:.78rem;font-weight:700">${parseFloat(it.quantity).toFixed(0)} left</span></div>
      <div style="height:4px;background:var(--nx-border);border-radius:2px"><div style="height:4px;width:${pct}%;background:${col};border-radius:2px"></div></div>
      <div style="font-size:.65rem;color:var(--nx-muted);margin-top:2px">Reorder at ${it.reorder_level} · ${esc(it.branch_name)}</div></div>`;
  }).join('') || '<div class="text-center py-4 small" style="color:var(--nx-green)">✓ All stock levels OK</div>';
  const mv = (d.moves || []).map(m => { const q = parseFloat(m.quantity); return `<tr><td class="small text-nx-muted">${new Date(m.created_at.replace(' ', 'T')).toLocaleString('en-KE', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</td><td class="small fw-bold">${esc(m.product_name)}</td><td><span class="mov-type mov-${m.type}">${esc(m.type.replace('_', ' '))}</span></td><td class="${q >= 0 ? 'text-success' : 'text-danger'} fw-bold small">${q >= 0 ? '+' : ''}${q.toFixed(2)}</td></tr>`; }).join('');
  el.innerHTML = `
    <div class="d-flex align-items-center justify-content-between mb-4 flex-wrap gap-2">
      <div><h5 class="fw-head mb-0">Stock Dashboard</h5><div class="text-nx-muted small">${esc(CU.branch_name || '')}</div></div>
      <div class="d-flex gap-2"><button class="btn btn-sm btn-outline-secondary" onclick="navigate('inventory')"><i class="fa fa-boxes-stacked me-1"></i>Stock levels</button>
        ${can(R.STOREKEEPER) ? '<button class="btn btn-sm btn-outline-secondary" onclick="navigate(\'transfers\')"><i class="fa fa-arrows-left-right me-1"></i>Transfers</button>' : ''}</div></div>
    <div class="row g-3 mb-4">
      ${kpi('Items tracked', d.tracked, 'in this branch', 'var(--nx-blue)', 'fa-boxes-stacked')}
      ${kpi('Healthy', healthy, 'above reorder level', 'var(--nx-green)', 'fa-circle-check')}
      ${kpi('Low stock', d.low_stock, 'need reorder', 'var(--nx-orange)', 'fa-triangle-exclamation')}
      ${kpi('Out of stock', d.out_of_stock, 'zero on hand', 'var(--nx-red)', 'fa-ban')}</div>
    <div class="row g-4"><div class="col-lg-6"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">⚠️ Low Stock Alerts</div><div class="card-body p-0" style="max-height:380px;overflow-y:auto">${low}</div></div></div>
      <div class="col-lg-6"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Recent stock activity</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>When</th><th>Product</th><th>Type</th><th>Qty</th></tr></thead><tbody>${mv || '<tr><td colspan="4" class="text-center text-nx-muted py-4 small">No activity yet</td></tr>'}</tbody></table></div></div></div></div>`;
}

// ══════════════ HR ROLE + LEANER MANAGER + BRANCH INSIGHTS ══════════════
R.HR = 12;
PAGE_TITLES.insights = 'Branch Insights';
PAGE_ACCESS.insights  = [R.OWNER, R.MANAGER];
PAGE_ACCESS.salary    = [R.OWNER, R.MANAGER, R.HR];
// Manager no longer manages the catalogue. That belongs to Owner and Storekeeper.
PAGE_ACCESS.products   = [R.OWNER, R.STOREKEEPER];
PAGE_ACCESS.categories = [R.OWNER, R.STOREKEEPER];
PAGE_ACCESS.suppliers  = [R.OWNER, R.STOREKEEPER, R.SUPPLIER];

// ── Sidebar ──
const _hrBN = buildNav;
buildNav = function () {
  _hrBN();
  const h = (sel, s) => { const e = document.querySelector(sel); if (e) e.style.display = s ? '' : 'none'; };
  h('#nav-products-sec', can(R.OWNER, R.STOREKEEPER));
  h('.nx-nav-link[data-page="suppliers"]', can(R.OWNER, R.STOREKEEPER, R.SUPPLIER));
  h('#nav-salary-sec', can(R.OWNER, R.MANAGER, R.HR));
  if (can(R.HR)) ['#nav-sales-sec', '#nav-inventory-sec', '#nav-purchase-sec', '#nav-crm-sec', '#nav-reports-sec', '#nav-admin-sec',
    '#nav-mp-sec', '#nav-health-sec', '.nx-nav-link[data-page="dashboard"]'].forEach(s => h(s, false));
  const rep = document.getElementById('nav-reports-sec');
  if (rep && can(R.OWNER, R.MANAGER) && !document.querySelector('.nx-nav-link[data-page="insights"]'))
    rep.insertAdjacentHTML('beforeend', '<button class="nx-nav-link" data-page="insights"><i class="fa fa-wand-magic-sparkles"></i> Branch Insights</button>');
};

// ── Home grid ──
const _hrHG = HOME_GROUPS;
HOME_GROUPS = function () {
  const g = _hrHG(), O = R.OWNER, M = R.MANAGER, S = R.STOREKEEPER, U = R.SUPPLIER, H = R.HR;
  g.forEach(grp => grp.items.forEach(i => {
    if (i[0] === 'products' || i[0] === 'categories') i[5] = [O, S];
    if (i[0] === 'suppliers') i[5] = [O, S, U];
    if (i[0] === 'salary') {
      i[5] = [O, M, H];
      if (CU.role_id === M) { i[1] = 'Payroll & Payouts'; i[4] = 'Allocations & disbursements'; }
    }
  }));
  const biz = g.find(x => x.n === 'Business');
  if (biz) biz.items.unshift(['insights', 'Branch Insights', 'fa-wand-magic-sparkles', '#7c3aed', 'AI profit & growth advice', [O, M]]);
  if (CU.role_id === H) g.forEach(x => { x.items = x.items.filter(i => ['salary', 'messages', 'finance'].includes(i[0])); });
  return g;
};

// ── Appoint dropdown: HR and Manager are Owner-only appointments ──
const _hrLA = loadApointStaffList;
loadApointStaffList = async function () {
  await _hrLA();
  const s = document.getElementById('apt-role'); if (!s) return;
  if (!can(R.OWNER)) [...s.options].forEach(o => { if (['2', '12'].includes(o.value)) o.remove(); });
  else if (![...s.options].some(o => o.value === '12')) s.insertAdjacentHTML('beforeend', '<option value="12">HR Officer</option>');
};

// ── HR sees people tools only, never the money cards ──
const _hrRS = renderSalary;
renderSalary = async function (el) {
  await _hrRS(el);
  if (!can(R.HR)) return;
  const pane = document.getElementById('hr-pane-payroll'); if (!pane) return;
  pane.querySelectorAll('.card-header').forEach(hd => {
    if (['Request Salary Allocation', 'Disburse Salary', 'History'].includes(hd.textContent.trim())) hd.closest('.card')?.remove();
  });
  pane.querySelectorAll('.stat-card').forEach(c => c.closest('.row')?.remove());
};

// ── Navigation for Branch Insights ──
const _biNav = navigateNow;
navigateNow = async function (page) {
  if (page !== 'insights') return _biNav(page);
  if (!can(R.OWNER, R.MANAGER)) { toast('You do not have access to this section.', 'error'); return; }
  showChrome();
  document.querySelectorAll('.nx-nav-link').forEach(b => b.classList.toggle('active', b.dataset.page === page));
  document.getElementById('page-title').textContent = PAGE_TITLES.insights;
  closeSidebar();
  const el = document.getElementById('nx-content'); loading(el);
  await renderInsights(el); nxAfterNav(page);
};

// ══ Branch Insights page ══
let _biDays = 30, _biBranch = 0;
const biN = v => parseFloat(v || 0);
const biDelta = (v, goodUp = true) => v == null ? '<span class="text-nx-muted">no prior data</span>'
  : `<span style="color:${(v >= 0) === goodUp ? 'var(--nx-green)' : 'var(--nx-red)'};font-weight:600">${v >= 0 ? '▲' : '▼'} ${Math.abs(v)}%</span> <span class="text-nx-muted">vs previous</span>`;

async function renderInsights(el) {
  let sel = '';
  if (can(R.OWNER)) {
    const b = await api('mp_branches');
    sel = `<select class="form-select form-select-sm" style="width:auto" onchange="_biBranch=+this.value;biLoad(false)">
      <option value="0">All branches</option>${(b.branches || []).map(x => `<option value="${x.id}" ${x.id == _biBranch ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select>`;
  }
  el.innerHTML = `<div style="max-width:1250px;margin:0 auto">
    <div class="d-flex align-items-center justify-content-between flex-wrap gap-2 mb-3">
      <div><h5 class="fw-head mb-0 d-flex align-items-center"><span class="ico-tile" style="width:32px;height:32px"><i class="fa fa-chart-line"></i></span>Branch Insights<span class="nx-ai-tag ms-2"><i class="fa fa-wand-magic-sparkles"></i> NYMIX AI</span></h5>
        <div class="small text-nx-muted">Profit, revenue, costs and advice, worked out from your real numbers</div></div>
      <div class="d-flex gap-2 flex-wrap">${sel}
        <div class="btn-group btn-group-sm" id="bi-days">${[7, 30, 90].map(n => `<button class="btn btn-outline-secondary" data-n="${n}" onclick="_biDays=${n};biLoad(false)">${n} days</button>`).join('')}</div>
        <button class="btn btn-sm btn-outline-secondary" onclick="biLoad(true)"><i class="fa fa-rotate me-1"></i>Re-analyse</button></div></div>
    <div id="bi-body"></div></div>`;
  biLoad(false);
}

async function biLoad(refresh) {
  const box = document.getElementById('bi-body'); if (!box) return;
  document.querySelectorAll('#bi-days button').forEach(b => { b.className = 'btn ' + (+b.dataset.n === _biDays ? 'btn-warning' : 'btn-outline-secondary'); });
  _destroyCharts();
  box.innerHTML = `<div class="card p-5 text-center"><div class="hrai-doc" style="width:90px;height:115px"><div class="hrai-scan"></div></div>
    <div class="hrai-t">NYMIX AI is analysing your branch…</div><div class="hrai-s">Working through revenue, margins, costs and stock. This takes a few seconds.</div></div>`;
  const p = { days: _biDays }; if (_biBranch) p.branch_id = _biBranch; if (refresh) p.refresh = 1;
  const d = await api('ai_branch_advisor', p);
  if (!document.getElementById('bi-body')) return;
  if (!d.ok) { box.innerHTML = `<div class="alert alert-warning">${esc(d.msg || 'Could not load insights.')}</div>`; return; }
  biPaint(d);
}

function biPaint(d) {
  const box = document.getElementById('bi-body'); if (!box) return;
  const k = d.kpi, dl = d.delta || {}, a = d.ai, dark = (localStorage.getItem('nx-theme') || 'light') === 'dark';
  const kc = (l, v, sub, c) => `<div class="col-6 col-lg"><div class="stat-card" style="--card-accent:${c}"><div class="stat-label">${l}</div><div class="stat-value" style="font-size:1.25rem">${v}</div><div class="stat-sub">${sub}</div></div></div>`;
  const tbl = (heads, rows, empty) => `<div class="table-responsive"><table class="table table-sm mb-0"><thead><tr>${heads.map(h => `<th${h[1] ? ' class="text-end"' : ''}>${h[0]}</th>`).join('')}</tr></thead>
    <tbody>${rows.join('') || `<tr><td colspan="${heads.length}" class="text-center text-nx-muted py-3 small">${empty}</td></tr>`}</tbody></table></div>`;
  const basket = k.txns > 0 ? biN(k.revenue) / k.txns : 0;

  let ai;
  if (a) {
    const vc = { strong: ['#22c55e', 'Strong'], steady: ['#1E9E52', 'Steady'], at_risk: ['#ef4444', 'At risk'] }[a.verdict] || ['#1E9E52', 'Steady'];
    const li = (arr, ic, c) => (arr || []).map(x => `<div class="d-flex gap-2 py-1 small"><i class="fa ${ic}" style="color:${c};margin-top:3px"></i><span>${esc(x)}</span></div>`).join('') || '<div class="small text-nx-muted">Nothing notable.</div>';
    ai = `<div class="card mb-4" style="border-color:	rgba(30,158,82,.45)"><div class="card-body">
      <div class="d-flex align-items-center gap-3 flex-wrap">
        <div style="width:78px;height:78px;border-radius:50%;background:conic-gradient(${vc[0]} ${a.score * 3.6}deg,var(--nx-border) 0);display:flex;align-items:center;justify-content:center;flex-shrink:0">
          <div style="width:62px;height:62px;border-radius:50%;background:var(--nx-card);display:flex;flex-direction:column;align-items:center;justify-content:center"><b style="font-size:1.2rem;line-height:1">${a.score}</b><span style="font-size:.55rem;color:${vc[0]};font-weight:700">${vc[1].toUpperCase()}</span></div></div>
        <div style="flex:1;min-width:220px"><div class="small text-nx-muted">NYMIX AI VERDICT</div><div class="fw-head fw-bold" style="font-size:1.15rem">${esc(a.headline)}</div></div></div>
      <p class="mt-3 mb-3" style="line-height:1.65">${esc(a.summary)}</p>
      <div class="row g-3 mb-3">
        <div class="col-md-6"><div class="hr3-sec" style="margin-top:0">What is working</div>${li(a.wins, 'fa-circle-check', '#22c55e')}</div>
        <div class="col-md-6"><div class="hr3-sec" style="margin-top:0">Watch out for</div>${li(a.risks, 'fa-triangle-exclamation', '#f97316')}</div></div>
      <div class="hr3-sec" style="margin-top:0">Recommended actions, biggest impact first</div>
      <div class="row g-3">${(a.actions || []).map((x, i) => `<div class="col-md-6"><div class="p-3 h-100 rounded" style="background:var(--nx-surface);border:1px solid var(--nx-border)">
        <div class="d-flex justify-content-between align-items-start gap-2"><b class="small">${i + 1}. ${esc(x.title)}</b>
          <span class="hr-chip2 ${x.impact === 'high' ? 'g' : x.impact === 'medium' ? 'w' : ''}">${esc(x.impact)} impact</span></div>
        <div class="small text-nx-muted mt-1" style="line-height:1.5">${esc(x.why)}</div>
        <div style="font-size:.65rem" class="text-nx-muted mt-1">Effort: ${esc(x.effort)}</div></div></div>`).join('')}</div>
      ${a.watch ? `<div class="alert alert-info py-2 small mt-3 mb-0"><i class="fa fa-bullseye me-1"></i><b>Next period target:</b> ${esc(a.watch)}</div>` : ''}
      <div class="text-nx-muted mt-2" style="font-size:.65rem">AI-written from your figures. Treat it as guidance to check, not a guarantee. Generated ${esc(d.generated_at)}${d.cached ? ' (cached today, press Re-analyse for a fresh run)' : ''}.</div></div></div>`;
  } else {
    ai = `<div class="alert alert-warning small mb-4">${esc(d.ai_error || 'AI analysis is unavailable right now.')} The figures below are still accurate.</div>`;
  }

  const bk = (d.branches || []).length ? `<div class="card mb-4"><div class="card-header py-2 px-3 small fw-bold">Branch comparison</div>${tbl([['Branch'], ['Revenue', 1], ['Gross profit', 1], ['Margin', 1]],
    d.branches.map(x => `<tr><td class="fw-bold small">${esc(x.branch)}</td><td class="text-end small">${fmt(x.rev)}</td><td class="text-end small">${fmt(x.gp)}</td><td class="text-end small">${x.margin}%</td></tr>`), '')}</div>` : '';

  box.innerHTML = `
    <div class="small text-nx-muted mb-2">${esc(d.scope)} · ${esc(d.from)} to ${esc(d.to)}</div>
    <div class="row g-3 mb-4">
      ${kc('Revenue', fmt(k.revenue), biDelta(dl.revenue), 'var(--nx-accent)')}
      ${kc('Gross profit', fmt(k.gp), k.margin + '% margin · ' + biDelta(dl.gp), 'var(--nx-green)')}
      ${kc('Expenses', fmt(k.expenses), 'Payroll ' + fmt(k.payroll) + ' · ' + biDelta(dl.expenses, false), 'var(--nx-orange)')}
      ${kc('Est. net profit', fmt(k.net), biDelta(dl.net), biN(k.net) >= 0 ? 'var(--nx-green)' : 'var(--nx-red)')}
      ${kc('Avg basket', fmt(basket), k.txns + ' sales', 'var(--nx-blue)')}</div>
    ${ai}
    <div class="row g-4 mb-4">
      <div class="col-lg-8"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Revenue and gross profit by day</div><div class="card-body" style="position:relative;height:250px"><canvas id="bi-trend"></canvas></div></div></div>
      <div class="col-lg-4"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Where the money goes (expenses)</div><div class="card-body d-flex align-items-center justify-content-center" style="position:relative;height:250px">
        ${(d.exp_cats || []).length ? '<canvas id="bi-exp"></canvas>' : '<span class="small text-nx-muted">No expenses recorded in this period</span>'}</div></div></div></div>
    ${bk}
    <div class="row g-4 mb-4">
      <div class="col-lg-6"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Top earners (by profit)</div>${tbl([['Product'], ['Sold', 1], ['Revenue', 1], ['Profit', 1]],
        (d.top || []).map(x => `<tr><td class="small fw-bold">${esc(x.name)}</td><td class="text-end small">${biN(x.qty).toFixed(0)}</td><td class="text-end small">${fmt(x.rev)}</td><td class="text-end small text-success fw-bold">${fmt(x.profit)}</td></tr>`), 'No sales in this period')}</div></div>
      <div class="col-lg-6"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Thin margins (under 10%)</div>${tbl([['Product'], ['Revenue', 1], ['Margin', 1]],
        (d.low_margin || []).map(x => `<tr><td class="small fw-bold">${esc(x.name)}</td><td class="text-end small">${fmt(x.rev)}</td><td class="text-end small text-danger fw-bold">${(biN(x.profit) / biN(x.rev) * 100).toFixed(1)}%</td></tr>`), 'No thin-margin sellers 👍')}</div></div></div>
    <div class="row g-4 mb-4">
      <div class="col-lg-6"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Dead stock · ${fmt(d.dead.total)} tied up (${d.dead.count} products)</div>${tbl([['Product'], ['On hand', 1], ['Cost value', 1]],
        (d.dead.items || []).map(x => `<tr><td class="small fw-bold">${esc(x.name)}</td><td class="text-end small">${biN(x.qty).toFixed(0)}</td><td class="text-end small">${fmt(x.val)}</td></tr>`), 'No dead stock 👍')}</div></div>
      <div class="col-lg-6"><div class="card h-100"><div class="card-header py-2 px-3 small fw-bold">Fast sellers running low</div>${tbl([['Product'], ['Sold', 1], ['On hand', 1]],
        (d.stockouts || []).map(x => `<tr><td class="small fw-bold">${esc(x.name)}</td><td class="text-end small">${biN(x.sold).toFixed(0)}</td><td class="text-end small text-danger fw-bold">${biN(x.onhand).toFixed(0)}</td></tr>`), 'Nothing at risk 👍')}</div></div></div>
    <div class="dash-strip">
      <div><i>📅</i><span>Best weekday</span><b>${esc(d.best_day || '—')}</b></div>
      <div><i>⏰</i><span>Busiest hour</span><b>${esc(d.best_hour || '—')}</b></div>
      <div><i>🚫</i><span>Voided sales</span><b>${d.voids.n} · ${fmt(d.voids.amt)}</b></div>
      <div><i>💳</i><span>Customers over limit</span><b>${d.credit.over} · owed ${fmt(d.credit.outstanding)}</b></div></div>
    <div class="text-nx-muted" style="font-size:.68rem">Profit is an estimate: cost of goods uses current buying prices, payroll counts only payouts recorded in NYMIX, and VAT is not separated.</div>`;

  const grid = dark ? 'rgba(255,255,255,.06)' : 'rgba(0,0,0,.06)', txt = dark ? '#6b7280' : '#94a3b8';
  const tc = document.getElementById('bi-trend');
  if (tc && (d.daily || []).length) {
    _dashCharts.bi1 = new Chart(tc.getContext('2d'), {
      data: { labels: d.daily.map(x => new Date(x.d).toLocaleDateString('en-KE', { day: 'numeric', month: 'short' })),
        datasets: [
          { type: 'bar', label: 'Revenue', data: d.daily.map(x => x.rev), backgroundColor: 'rgba(30,158,82,.28)', borderColor: 'rgba(30,158,82,.9)', borderWidth: 1, borderRadius: 4 },
          { type: 'line', label: 'Gross profit', data: d.daily.map(x => x.gp), borderColor: 'rgba(34,197,94,.95)', backgroundColor: 'rgba(34,197,94,.08)', borderWidth: 2, pointRadius: 2, tension: .35, fill: true }] },
      options: { responsive: true, maintainAspectRatio: false, interaction: { mode: 'index', intersect: false },
        plugins: { legend: { labels: { color: txt, boxWidth: 12, font: { size: 10 } } } },
        scales: { x: { grid: { color: grid }, ticks: { color: txt, font: { size: 9 }, maxTicksLimit: 12 } },
                  y: { grid: { color: grid }, ticks: { color: txt, font: { size: 9 }, callback: v => v >= 1000 ? (v / 1000).toFixed(0) + 'k' : v } } } } });
  } else if (tc) tc.parentElement.innerHTML = '<span class="small text-nx-muted">No sales in this period</span>';
  const ec = document.getElementById('bi-exp');
  if (ec) {
    _dashCharts.bi2 = new Chart(ec.getContext('2d'), { type: 'doughnut',
      data: { labels: d.exp_cats.map(x => x.name), datasets: [{ data: d.exp_cats.map(x => biN(x.amt)), borderColor: dark ? '#1e2333' : '#fff', borderWidth: 3,
        backgroundColor: ['#1E9E52', '#3b82f6', '#22c55e', '#ef4444', '#a78bfa', '#17C548'] }] },
      options: { responsive: true, maintainAspectRatio: false, cutout: '62%', plugins: { legend: { position: 'bottom', labels: { color: txt, boxWidth: 10, font: { size: 10 } } } } } });
  }
}

