.gl-scroll{max-height:42vh;overflow-y:auto;text-align:left;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.15);border-radius:14px;padding:14px;font-size:.85rem;line-height:1.65;white-space:pre-wrap;color:#e2e8f0}
.gl-sig{width:100%;background:#fff;border-radius:12px;touch-action:none;cursor:crosshair}
.pl-row{background:var(--nx-card);border:1px solid var(--nx-border);border-radius:16px;padding:14px;margin-bottom:10px}
