// ── Staff: read, understand, sign ──
async function guidelineGate() {
  const s = await api('guideline_status');
  if (!s.ok || !s.pending) return true;
  window._glShowing = true;
  return new Promise(resolve => glPaint(s.g, resolve));
}
function glPaint(g, resolve) {
  let o = document.getElementById('gl-ov');
  if (!o) { o = document.createElement('div'); o.id = 'gl-ov'; o.className = 'hl-ov'; o.style.zIndex = 100070; document.body.appendChild(o); }
  o.innerHTML = `<div class="hl-card gl-card"><div class="hl-ring warn"><i class="fa fa-file-signature"></i></div>
    <h4>${esc(g.title)} <small style="opacity:.6">v${g.version}</small></h4>
    <p>To continue you must read and understand these guidelines, then sign electronically.</p>
    <div id="gl-scroll" class="gl-scroll">${esc(g.body)}</div>
    <div id="gl-hint" class="small mt-2" style="color:#1E9E52">Scroll to the bottom to continue ↓</div>
    <label id="gl-agree-l" class="d-flex gap-2 mt-3 text-start small" style="opacity:.4"><input type="checkbox" id="gl-agree" disabled><span>I have read and understood these guidelines and agree to follow them.</span></label>
    <input id="gl-name" class="form-control mt-3" placeholder="Type your full name (${esc(CU.name)})" disabled>
    <div class="text-start small mt-3 mb-1" style="color:#94a3b8">Draw your signature</div>
    <canvas id="gl-sig" class="gl-sig" width="600" height="180"></canvas>
    <div class="d-flex gap-2 mt-2"><button class="hl-btn hl-out" style="margin:0" id="gl-clear">Clear</button><button class="hl-btn" style="margin:0" id="gl-go" disabled>Sign &amp; continue</button></div>
    <button class="hl-btn hl-out" onclick="doLogout()"><i class="fa fa-right-from-bracket me-2"></i>Sign out</button></div>`;
  const sc = document.getElementById('gl-scroll'), cv = document.getElementById('gl-sig'), ctx = cv.getContext('2d');
  const agree = document.getElementById('gl-agree'), nm = document.getElementById('gl-name'), go = document.getElementById('gl-go');
  let ink = 0, down = false, read = false;
  const blank = () => { ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, cv.width, cv.height); ctx.strokeStyle = '#111'; ctx.lineWidth = 2.6; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ink = 0; };
  const check = () => { go.disabled = !(read && agree.checked && nm.value.trim().length > 2 && ink > 8); };
  const unlock = () => { if (read) return; read = true; agree.disabled = false; nm.disabled = false; document.getElementById('gl-agree-l').style.opacity = 1; document.getElementById('gl-hint').textContent = '✓ You have reached the end.'; document.getElementById('gl-hint').style.color = '#22c55e'; };
  const atEnd = () => { if (sc.scrollTop + sc.clientHeight >= sc.scrollHeight - 8) unlock(); };
  sc.addEventListener('scroll', atEnd); setTimeout(atEnd, 150);
  blank();
  const pos = e => { const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) * cv.width / r.width, (e.clientY - r.top) * cv.height / r.height]; };
  cv.addEventListener('pointerdown', e => { down = true; cv.setPointerCapture(e.pointerId); const [x, y] = pos(e); ctx.beginPath(); ctx.moveTo(x, y); });
  cv.addEventListener('pointermove', e => { if (!down) return; const [x, y] = pos(e); ctx.lineTo(x, y); ctx.stroke(); ink++; check(); });
  ['pointerup', 'pointercancel'].forEach(ev => cv.addEventListener(ev, () => { down = false; }));
  document.getElementById('gl-clear').onclick = () => { blank(); check(); };
  agree.onchange = check; nm.oninput = check;
  go.onclick = async () => {
    go.disabled = true; go.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Saving…';
    const r = await api('guideline_sign', { guideline_id: g.id, typed_name: nm.value.trim(), signature: cv.toDataURL('image/png') }, 'POST');
    if (r.ok) { o.remove(); window._glShowing = false; toast('Thank you. Your signature was recorded.', 'success'); resolve(true); }
    else { toast(r.msg || 'Could not save signature.', 'error'); go.innerHTML = 'Sign &amp; continue'; check(); }
  };
}
const _glInit = init;
init = function () {
  if (!CU) return;
  if (window._glPassed) return _glInit();
  guidelineGate().then(() => { window._glPassed = true; _glInit(); });
};

