  const s = document.getElementById('nav-health-sec');
  if (s && can(R.OWNER, R.MANAGER) && !s.querySelector('[data-page="policies"]'))
    s.insertAdjacentHTML('beforeend', '<button class="nx-nav-link" data-page="policies"><i class="fa fa-scale-balanced"></i> Policies &amp; Attendance</button>');
};
const _plHG = HOME_GROUPS;
