  if (b) b.items.push(['policies', 'Policies & Attendance', 'fa-scale-balanced', '#8b5cf6', 'AI rules, leave, guidelines', [R.OWNER, R.MANAGER]]);
  return g;
};
const _plNav = navigateNow;
navigateNow = async function (page) {
  if (page !== 'policies') return _plNav(page);
  if (!can(R.OWNER, R.MANAGER)) { toast('You do not have access to this section.', 'error'); return; }
  showChrome();
