  document.getElementById('page-title').textContent = PAGE_TITLES.policies;
  closeSidebar();
  const el = document.getElementById('nx-content'); loading(el);
  await renderPolicies(el); nxAfterNav(page);
};

// ── Manager / owner page ──
async function renderPolicies(el) {
  el.innerHTML = `<div style="max-width:1200px;margin:0 auto">
    <div class="mb-3"><h5 class="fw-head mb-0"><i class="fa fa-scale-balanced text-accent me-2"></i>Policies &amp; Attendance</h5>
      <div class="small text-nx-muted">Write company rules in plain English. NYMIX AI turns them into checks that run automatically.</div></div>
    <ul class="nav nav-tabs" id="pl-tabs">${[['policies', 'Policies'], ['guidelines', 'Guidelines & signatures'], ['leave', 'Leave'], ['attendance', 'Attendance']]
      .map(([k, l], i) => `<li class="nav-item"><button class="nav-link ${i ? '' : 'active'}" data-k="${k}" onclick="plTab('${k}')">${l}</button></li>`).join('')}</ul>
    <div id="pl-pane" class="mt-3"></div></div>`;
  plTab('policies');
}
function plTab(k) {
  document.querySelectorAll('#pl-tabs .nav-link').forEach(b => b.classList.toggle('active', b.dataset.k === k));
  ({ policies: plPolicies, guidelines: plGuidelines, leave: plLeave, attendance: plAttendance })[k]();
}
const PL_M = { absent_days: 'Absent days in window', consecutive_absent_days: 'Consecutive absent days', void_count: 'Voided sales', discount_pct: 'Discounts % of sales', writeoff_value: 'Stock write-offs (KSh)', none: 'Not measurable' };
const PL_A = { review: 'Send to manual review', suspend: 'Suspend account immediately', terminate: 'Terminate + send letter' };

async function plPolicies() {
  const box = document.getElementById('pl-pane'); loading(box);
  const d = await api('policy_list');
  if (!d.ok) { box.innerHTML = `<div class="alert alert-warning">${esc(d.msg)}</div>`; return; }
  box.innerHTML = `
    <div class="card mb-3"><div class="card-body">
      <b><i class="fa fa-wand-magic-sparkles text-accent me-1"></i>Add a policy</b>
      <textarea id="pl-text" class="form-control mt-2" rows="3" placeholder="e.g. A cashier absent 3 working days in a row without approved leave must be reviewed. Anyone who voids more than 10 sales in a week is suspended."></textarea>
      <button id="pl-go" class="btn fw-bold mt-2" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="plAdd()"><i class="fa fa-wand-magic-sparkles me-1"></i>Analyse with AI</button>
      <div class="small text-nx-muted mt-2">AI maps your rule to checks the system can measure (absence, voids, discounts, stock write-offs). Anything else is saved as advisory and not enforced. Nothing runs until you activate it.</div>
    </div></div>
    <div class="alert alert-info py-2 small">Built-in default: 3 working days absent in a row, with no sign-in and no approved leave, sends the account to review. Add an absence policy to override it.</div>
    ${(d.rows || []).map(p => `<div class="pl-row">
      <div class="d-flex justify-content-between align-items-start gap-2 flex-wrap">
        <div style="min-width:0;flex:1"><b>${esc(p.title)}</b>
          <div class="small text-nx-muted" style="font-style:italic">“${esc(p.original_text)}”</div></div>
        <span class="badge bg-${+p.is_active ? 'success' : 'secondary'} bg-opacity-25 text-${+p.is_active ? 'success' : 'secondary'}">${+p.is_active ? 'Active' : 'Draft'}</span></div>
      <div class="small mt-2"><i class="fa fa-wand-magic-sparkles text-accent me-1"></i>${esc(p.ai_note || '')}</div>
      <div class="mt-2">${+p.supported
        ? `<span class="hr-chip2">${esc(PL_M[p.metric])} ≥ ${parseFloat(p.threshold)}</span> <span class="hr-chip2">window ${p.window_days} days</span> <span class="hr-chip2 ${p.severity === 'critical' ? 'r' : 'w'}">${esc(p.severity)}</span> <span class="hr-chip2 ${p.action === 'review' ? '' : 'r'}">${esc(PL_A[p.action])}</span>`
        : '<span class="hr-chip2 w">Advisory only (not enforced)</span>'}</div>
      <div class="d-flex gap-2 mt-3">
        ${+p.supported ? `<button class="btn btn-sm ${+p.is_active ? 'btn-outline-secondary' : 'btn-success'}" onclick="plToggle(${p.id},${+p.is_active ? 0 : 1})">${+p.is_active ? 'Deactivate' : 'Activate'}</button>` : ''}
        <button class="btn btn-sm btn-outline-danger" onclick="plDel(${p.id})"><i class="fa fa-trash"></i></button></div>
    </div>`).join('') || '<div class="text-center text-nx-muted py-4 small">No policies yet.</div>'}`;
}
async function plAdd() {
  const t = document.getElementById('pl-text').value.trim(); if (t.length < 10) { toast('Describe the rule first', 'error'); return; }
  const b = document.getElementById('pl-go'); b.disabled = true; b.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>NYMIX AI is analysing…';
  const r = await api('policy_add', { text: t }, 'POST');
  if (r.ok) { toast(r.msg, 'success'); plPolicies(); } else { toast(r.msg || 'Failed', 'error'); b.disabled = false; b.innerHTML = 'Analyse with AI'; }
}
async function plToggle(id, on) {
  if (on && !confirm('Activate this policy? It starts applying to staff on their next health check and in the daily scan.')) return;
  const r = await api('policy_toggle', { id, on }, 'POST'); r.ok ? (toast(r.msg, 'success'), plPolicies()) : toast(r.msg || 'Failed', 'error');
}
async function plDel(id) { if (!confirm('Delete this policy?')) return; const r = await api('policy_delete', { id }, 'POST'); if (r.ok) plPolicies(); }

async function plGuidelines() {
  const box = document.getElementById('pl-pane'); loading(box);
  const d = await api('guideline_list');
  if (!d.ok) { box.innerHTML = `<div class="alert alert-warning">${esc(d.msg)}</div>`; return; }
  const act = (d.rows || []).find(x => +x.is_active);
  box.innerHTML = `<div class="row g-3">
    <div class="col-lg-6"><div class="card"><div class="card-body">
      <div class="p-3 mb-3 rounded" style="border:1px dashed 	rgba(30,158,82,.45);background:	rgba(30,158,82,.06)">
        <b class="small"><span class="nx-ai-tag me-2"><i class="fa fa-wand-magic-sparkles"></i> NYMIX AI</span>Draft it from your business</b>
        <div class="small text-nx-muted mt-1">AI looks at your branches, staff roles, pay types, payment methods, credit, stock losses and online store, then writes terms that fit. Nothing is published until you press Publish.</div>
        <textarea id="gl-focus" class="form-control form-control-sm mt-2" rows="2" placeholder="Anything specific to include? (optional) e.g. uniforms, no phones at the till, overtime approval"></textarea>
        <button id="gl-ai-btn" class="btn btn-sm fw-bold mt-2" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="plAiDraft()"><i class="fa fa-wand-magic-sparkles me-1"></i>Analyse business &amp; draft terms</button>
        <div id="gl-ai-basis" class="small text-nx-muted mt-2"></div>
      </div>
      <b>Publish terms &amp; guidelines</b>
      <input id="gl-t" class="form-control mt-2" placeholder="Title, e.g. Staff Terms & Conditions" value="${esc(act ? act.title : '')}">
      <textarea id="gl-b" class="form-control mt-2" rows="12" placeholder="Write the full guidelines here: conduct, cash handling, attendance, confidentiality, discipline…"></textarea>
      <button class="btn fw-bold mt-2" style="background:var(--nx-accent);color:#fff" onclick="plSaveGl()"><i class="fa fa-file-signature me-1"></i>Publish new version</button>
      <div class="small text-nx-muted mt-2">Publishing creates a new version. Everyone, including you, must read it and sign again before using the portal.</div></div></div></div>
    <div class="col-lg-6"><div class="card mb-3"><div class="card-header small fw-bold">${act ? `Current: v${act.version} · ${act.signed} signed` : 'No guidelines published yet'}</div>
      <div class="card-body small">
        ${(d.unsigned || []).length ? `<b class="text-warning">Not signed yet (${d.unsigned.length})</b><div class="mb-3">${d.unsigned.map(u => `<div>${esc(u.full_name)} <span class="text-nx-muted">· ${esc(u.role_name)}</span></div>`).join('')}</div>` : (act ? '<div class="text-success mb-2">✓ Everyone has signed.</div>' : '')}
        ${(d.signed || []).length ? `<b>Signed</b>${d.signed.map(s => `<div class="d-flex justify-content-between border-bottom py-1" style="border-color:var(--nx-border)!important"><span>${esc(s.full_name)}</span><span class="text-nx-muted">${hlWhen(s.signed_at)} · <a href="${esc(s.signature_path)}" target="_blank">signature</a></span></div>`).join('')}` : ''}
      </div></div>
      <div class="card"><div class="card-header small fw-bold">Versions</div><div class="card-body small">${(d.rows || []).map(r => `<div class="d-flex justify-content-between py-1"><span>v${r.version} · ${esc(r.title)}</span><span class="text-nx-muted">${+r.is_active ? 'current · ' : ''}${r.signed} signed</span></div>`).join('') || 'None yet.'}</div></div></div></div>`;
}
async function plAiDraft() {
  const b = document.getElementById('gl-ai-btn'), basis = document.getElementById('gl-ai-basis');
  if (!b) return;
  if (document.getElementById('gl-b').value.trim().length > 80 && !confirm('Replace the text in the box with a new AI draft?')) return;
  b.disabled = true; b.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>NYMIX AI is analysing your business…';
  basis.innerHTML = '';
  const r = await api('guideline_ai_draft', { focus: document.getElementById('gl-focus').value }, 'POST');
  b.disabled = false; b.innerHTML = '<i class="fa fa-rotate me-1"></i>Re-draft';
  if (!r.ok) { toast(r.msg || 'AI could not draft the terms.', 'error'); return; }
  document.getElementById('gl-t').value = r.title;
  document.getElementById('gl-b').value = r.body;
  document.getElementById('gl-b').rows = 18;
  basis.innerHTML = '<b>What the AI looked at:</b><ul class="mb-1 ps-3">' + (r.basis || []).map(x => `<li>${esc(x)}</li>`).join('') + '</ul>' +
    '<span style="font-size:.68rem">AI-written draft, not legal advice. Read and edit it, and have a lawyer check it before you rely on it for discipline or dismissal.</span>';
  toast('Draft ready. Edit it if needed, then press Publish.', 'success');
}
async function plSaveGl() {
  if (!confirm('Publish a new version? Everyone must read and sign again.')) return;
  const r = await api('guideline_save', { title: document.getElementById('gl-t').value, body: document.getElementById('gl-b').value }, 'POST');
  r.ok ? (toast(r.msg, 'success'), plGuidelines()) : toast(r.msg || 'Failed', 'error');
}

async function plLeave() {
  const box = document.getElementById('pl-pane'); loading(box);
  const [a, l] = await Promise.all([api('attendance_overview'), api('leave_list')]);
  if (!l.ok) { box.innerHTML = `<div class="alert alert-warning">${esc(l.msg)}</div>`; return; }
  box.innerHTML = `<div class="card mb-3"><div class="card-body"><b>Record approved leave</b>
    <div class="row g-2 mt-1">
      <div class="col-md-3"><select id="lv-u" class="form-select form-select-sm"><option value="">Staff…</option>${(a.staff || []).map(s => `<option value="${s.id}">${esc(s.full_name)}</option>`).join('')}</select></div>
      <div class="col-md-2"><input type="date" id="lv-s" class="form-control form-control-sm"></div>
      <div class="col-md-2"><input type="date" id="lv-e" class="form-control form-control-sm"></div>
      <div class="col-md-2"><select id="lv-t" class="form-select form-select-sm">${['annual', 'sick', 'compassionate', 'maternity', 'paternity', 'unpaid', 'other'].map(x => `<option>${x}</option>`).join('')}</select></div>
      <div class="col-md-3"><input id="lv-r" class="form-control form-control-sm" placeholder="Reason (optional)"></div>
      <div class="col-12"><button class="btn btn-sm fw-bold" style="background:var(--nx-accent);color:#fff" onclick="plAddLeave()">Save leave</button>
        <span class="small text-nx-muted ms-2">Days covered by leave never count as absent.</span></div></div></div></div>
    <div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Staff</th><th>From</th><th>To</th><th>Type</th><th>Reason</th><th></th></tr></thead><tbody>
    ${(l.rows || []).map(x => `<tr><td class="fw-bold small">${esc(x.full_name)}</td><td class="small">${esc(x.start_date)}</td><td class="small">${esc(x.end_date)}</td><td class="small">${esc(x.leave_type)}</td><td class="small">${esc(x.reason || '')}</td><td><button class="btn btn-sm btn-outline-danger" onclick="plDelLeave(${x.id})"><i class="fa fa-trash"></i></button></td></tr>`).join('') || '<tr><td colspan="6" class="text-center text-nx-muted py-3">No leave recorded</td></tr>'}</tbody></table></div></div>`;
}
async function plAddLeave() {
  const r = await api('leave_add', { user_id: document.getElementById('lv-u').value, start_date: document.getElementById('lv-s').value, end_date: document.getElementById('lv-e').value, leave_type: document.getElementById('lv-t').value, reason: document.getElementById('lv-r').value }, 'POST');
  r.ok ? (toast('Leave recorded', 'success'), plLeave()) : toast(r.msg || 'Failed', 'error');
}
async function plDelLeave(id) { if (!confirm('Remove this leave?')) return; const r = await api('leave_delete', { id }, 'POST'); if (r.ok) plLeave(); }

async function plAttendance() {
  const box = document.getElementById('pl-pane'); loading(box);
  const d = await api('attendance_overview');
  if (!d.ok) { box.innerHTML = `<div class="alert alert-warning">${esc(d.msg)}</div>`; return; }
  box.innerHTML = `<div class="small text-nx-muted mb-2">Last 14 days, Mon to Sat. “Present” means signed into the portal that day. Leave days are excluded.</div>
    <div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Staff</th><th>Role</th><th>Branch</th><th>Last seen</th><th class="text-end">Absent</th><th class="text-end">In a row</th><th class="text-end">On leave</th></tr></thead><tbody>
    ${(d.staff || []).map(s => `<tr><td class="fw-bold small">${esc(s.full_name)}</td><td class="small">${esc(s.role_name)}</td><td class="small">${esc(s.branch_name)}</td><td class="small">${s.last_day ? esc(s.last_day) : '—'}</td>
      <td class="text-end ${s.absent >= 3 ? 'text-danger fw-bold' : ''}">${s.absent}</td><td class="text-end ${s.streak >= 3 ? 'text-danger fw-bold' : ''}">${s.streak}</td><td class="text-end">${s.leave_days}</td></tr>`).join('') || '<tr><td colspan="7" class="text-center text-nx-muted py-3">No staff</td></tr>'}</tbody></table></div></div>`;
}

// ══════════════ RECRUITMENT MODULE ══════════════
PAGE_ACCESS.jobs = [R.OWNER, R.MANAGER, R.HR];
PAGE_TITLES.jobs = 'Recruitment';

const _jbBN = buildNav;
buildNav = function () {
  _jbBN();
  const e = document.getElementById('nav-jobs-sec');
  if (e) e.style.display = can(R.OWNER, R.MANAGER, R.HR) ? '' : 'none';
};
const _jbHG = HOME_GROUPS;
HOME_GROUPS = function () {
  const g = _jbHG();
  const item = ['jobs', 'Jobs & Applicants', 'fa-briefcase', '#06b6d4', 'Post jobs, screen with AI', [R.OWNER, R.MANAGER, R.HR]];
  const b = g.find(x => x.n === 'Business');
  b ? b.items.push(item) : g.push({ n: 'Business', items: [item] });
  return g;
};
const _jbNav = navigateNow;
navigateNow = async function (page) {
  if (page !== 'jobs') return _jbNav(page);
  if (!can(R.OWNER, R.MANAGER, R.HR)) { toast('You do not have access to this section.', 'error'); return; }
  showChrome();
  document.querySelectorAll('.nx-nav-link').forEach(b => b.classList.toggle('active', b.dataset.page === page));
  document.getElementById('page-title').textContent = PAGE_TITLES.jobs;
  closeSidebar();
  const el = document.getElementById('nx-content'); loading(el);
  await renderJobs(el); nxAfterNav(page);
};

let _jbRows = [], _jbBranches = [];
const JB_TYPES_UI = { full_time: 'Full time', part_time: 'Part time', contract: 'Contract', internship: 'Internship', casual: 'Casual' };
const JB_ST = { submitted: 'warning', screening: 'info', shortlisted: 'primary', interview: 'primary', offered: 'success', hired: 'success', rejected: 'danger', withdrawn: 'secondary' };

async function renderJobs(el) {
  el.innerHTML = `<div style="max-width:1200px;margin:0 auto">
    <div class="d-flex align-items-center justify-content-between flex-wrap gap-2 mb-3">
      <div><h5 class="fw-head mb-0"><i class="fa fa-briefcase text-accent me-2"></i>Recruitment</h5>
        <div class="small text-nx-muted">Post jobs, let NYMIX AI screen applicants, then you decide</div></div>
      <button class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="jbNew()"><i class="fa fa-plus me-1"></i>Post a job</button></div>
    <div id="jb-list"></div></div>`;
  await jbLoad();
}

async function jbLoad() {
  const box = document.getElementById('jb-list'); if (!box) return; loading(box);
  const d = await api('jb_jobs');
  if (!d.ok) { box.innerHTML = `<div class="alert alert-warning">${esc(d.msg || 'Failed to load.')}</div>`; return; }
  _jbRows = d.rows; _jbBranches = d.branches || [];
  box.innerHTML = `<div class="card"><div class="table-responsive"><table class="table table-sm mb-0">
    <thead><tr><th>Job</th><th>Branch</th><th>Type</th><th class="text-end">Applicants</th><th class="text-end">New</th><th>Status</th><th></th></tr></thead><tbody>
    ${d.rows.map((j, i) => `<tr>
      <td class="fw-bold small">${esc(j.title)}<div class="text-nx-muted" style="font-size:.65rem">${j.deadline ? 'Closes ' + esc(j.deadline) : 'No deadline'}</div></td>
      <td class="small">${esc(j.branch_name)}</td><td class="small">${esc(JB_TYPES_UI[j.job_type] || j.job_type)}</td>
      <td class="text-end">${j.apps}</td><td class="text-end ${+j.fresh ? 'text-warning fw-bold' : ''}">${j.fresh}</td>
      <td><span class="badge bg-${j.status === 'open' ? 'success' : 'secondary'} bg-opacity-25 text-${j.status === 'open' ? 'success' : 'secondary'}">${esc(j.status)}</span></td>
      <td class="text-nowrap">
        <button class="btn btn-sm btn-outline-warning" onclick="jbApps(${j.id})"><i class="fa fa-users me-1"></i>Applicants</button>
        <button class="btn btn-sm btn-outline-secondary" onclick="jbNew(${i})"><i class="fa fa-pen"></i></button>
        <button class="btn btn-sm btn-outline-secondary" onclick="jbStatus(${j.id},'${j.status === 'open' ? 'closed' : 'open'}')">${j.status === 'open' ? 'Close' : 'Reopen'}</button>
      </td></tr>`).join('') || '<tr><td colspan="7" class="text-center text-nx-muted py-4">No jobs yet. Tap Post a job.</td></tr>'}
    </tbody></table></div></div>`;
}

async function jbStatus(id, status) {
  const r = await api('jb_job_status', { id, status }, 'POST');
  r.ok ? jbLoad() : toast(r.msg || 'Failed', 'error');
}

function jbNew(i) {
  const j = (i !== undefined && _jbRows[i]) ? _jbRows[i] : {};
  const v = (k, d = '') => esc(j[k] ?? d);
  let skills = j.skills || '';
  try { const a = JSON.parse(skills); if (Array.isArray(a)) skills = a.join(', '); } catch (e) {}
  hlModal(j.id ? 'Edit job' : 'Post a job', `
    <input type="hidden" id="jb-id" value="${j.id || ''}">
    <div class="p-3 mb-3 rounded" style="border:1px dashed 	rgba(30,158,82,.45);background:	rgba(30,158,82,.06)">
      <b class="small"><span class="nx-ai-tag me-2"><i class="fa fa-wand-magic-sparkles"></i> NYMIX AI</span>Describe the role, AI writes the advert</b>
      <textarea id="jb-brief" class="form-control form-control-sm mt-2" rows="2" placeholder="e.g. We need a cashier for the Thika branch, must handle M-Pesa and cash, weekends included"></textarea>
      <button id="jb-ai-btn" class="btn btn-sm fw-bold mt-2" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="jbDraft()"><i class="fa fa-wand-magic-sparkles me-1"></i>Draft with AI</button></div>
    <div class="row g-2">
      <div class="col-md-8"><label class="form-label">Job title *</label><input id="jb-title" class="form-control form-control-sm" value="${v('title')}"></div>
      <div class="col-md-4"><label class="form-label">Type</label><select id="jb-type" class="form-select form-select-sm">${Object.entries(JB_TYPES_UI).map(([k, l]) => `<option value="${k}" ${j.job_type === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
      <div class="col-12"><label class="form-label">Description *</label><textarea id="jb-desc" class="form-control form-control-sm" rows="5">${v('description')}</textarea></div>
      <div class="col-12"><label class="form-label">Requirements</label><textarea id="jb-req" class="form-control form-control-sm" rows="3">${v('requirements')}</textarea></div>
      <div class="col-md-8"><label class="form-label">Skills (comma separated)</label><input id="jb-skills" class="form-control form-control-sm" value="${esc(skills)}"></div>
      <div class="col-md-4"><label class="form-label">Min experience (yrs)</label><input id="jb-exp" type="number" min="0" class="form-control form-control-sm" value="${v('min_exp', 0)}"></div>
      <div class="col-md-4"><label class="form-label">Location</label><input id="jb-loc" class="form-control form-control-sm" value="${v('location')}"></div>
      <div class="col-md-4"><label class="form-label">Openings</label><input id="jb-open" type="number" min="1" class="form-control form-control-sm" value="${v('openings', 1)}"></div>
      <div class="col-md-4"><label class="form-label">Deadline</label><input id="jb-dl" type="date" class="form-control form-control-sm" value="${v('deadline')}"></div>
      <div class="col-md-4"><label class="form-label">Salary min</label><input id="jb-smin" type="number" class="form-control form-control-sm" value="${v('salary_min')}"></div>
      <div class="col-md-4"><label class="form-label">Salary max</label><input id="jb-smax" type="number" class="form-control form-control-sm" value="${v('salary_max')}"></div>
      <div class="col-md-4 d-flex align-items-end"><div class="form-check"><input class="form-check-input" type="checkbox" id="jb-show" ${+j.show_salary ? 'checked' : ''}><label class="form-check-label small" for="jb-show">Show salary publicly</label></div></div>
      ${can(R.OWNER) ? `<div class="col-md-6"><label class="form-label">Branch</label><select id="jb-branch" class="form-select form-select-sm">${_jbBranches.map(b => `<option value="${b.id}" ${b.id == j.branch_id ? 'selected' : ''}>${esc(b.branch_name)}</option>`).join('')}</select></div>` : ''}
    </div>
    <div class="small text-nx-muted mt-2">Requirements about age, gender, religion, tribe or marital status are blocked.</div>
    <button class="btn fw-bold mt-3" style="background:var(--nx-accent);color:#fff" onclick="jbSave()"><i class="fa fa-save me-1"></i>Save job</button>`);
}

async function jbDraft() {
  const brief = document.getElementById('jb-brief').value.trim();
  if (brief.length < 8) { toast('Describe the role first', 'error'); return; }
  const b = document.getElementById('jb-ai-btn'); b.disabled = true; b.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Writing…';
  const r = await api('jb_ai_draft', { brief }, 'POST');
  b.disabled = false; b.innerHTML = '<i class="fa fa-rotate me-1"></i>Re-draft';
  if (!r.ok) { toast(r.msg || 'AI failed', 'error'); return; }
  const j = r.job, set = (id, x) => { const e = document.getElementById(id); if (e) e.value = x ?? ''; };
  set('jb-title', j.title); set('jb-desc', j.description); set('jb-req', j.requirements);
  set('jb-skills', (j.skills || []).join(', ')); set('jb-type', j.job_type); set('jb-exp', j.min_exp);
  toast('Draft added. Edit it, then Save.' + (j.salary_hint ? ' Salary hint: ' + j.salary_hint : ''), 'success');
}

async function jbSave() {
  const g = id => document.getElementById(id)?.value || '';
  const p = { id: g('jb-id'), title: g('jb-title'), description: g('jb-desc'), requirements: g('jb-req'), skills: g('jb-skills'),
    job_type: g('jb-type'), min_exp: g('jb-exp'), location: g('jb-loc'), openings: g('jb-open'), deadline: g('jb-dl'),
    salary_min: g('jb-smin'), salary_max: g('jb-smax'), show_salary: document.getElementById('jb-show').checked ? 1 : 0,
    ai: g('jb-brief').trim() ? 1 : 0 };
  if (document.getElementById('jb-branch')) p.branch_id = g('jb-branch');
  const r = await api('jb_job_save', p, 'POST');
  if (r.ok) { toast('Job saved', 'success'); closeModal('modal-hl'); jbLoad(); } else toast(r.msg || 'Failed', 'error');
}

async function jbApps(jobId) {
  hlModal('Applicants', '<div class="d-flex justify-content-center py-5"><div class="spinner-border text-warning"></div></div>');
  const d = await api('jb_apps', { job_id: jobId });
  const body = document.getElementById('hlm-b'); if (!body) return;
  if (!d.ok) { body.innerHTML = `<div class="alert alert-warning">${esc(d.msg || 'Failed')}</div>`; return; }
  document.getElementById('hlm-t').textContent = 'Applicants: ' + d.job.title;
  const sugg = { shortlist: 'success', review: 'warning', decline: 'danger' };
  body.innerHTML = `
    <div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3">
      <div class="small text-nx-muted">${d.rows.length} applicant(s), best match first</div>
      <button id="jb-scr" class="btn btn-sm fw-bold" style="background:linear-gradient(135deg,#1E9E52,#17C548);color:#fff" onclick="jbScreen(${jobId})"><i class="fa fa-wand-magic-sparkles me-1"></i>Screen with NYMIX AI</button></div>
    ${d.rows.map(a => `<div class="pl-row">
      <div class="d-flex align-items-center gap-3 flex-wrap">
        <div class="hr2-av" style="width:46px;height:46px;font-size:1rem;${a.photo_path ? `background-image:url('${esc(a.photo_path)}')` : ''}">${a.photo_path ? '' : esc((a.full_name || '?').charAt(0).toUpperCase())}</div>
        <div style="min-width:0;flex:1"><b>${esc(a.full_name)}</b><div class="small text-nx-muted">${esc(a.headline || '')}${a.location ? ' · ' + esc(a.location) : ''} · ${a.experience_years || 0} yrs</div></div>
        <div class="text-center"><div class="fw-bold" style="font-size:1.2rem;color:${a.match_score >= 70 ? '#22c55e' : a.match_score >= 45 ? '#1E9E52' : '#ef4444'}">${a.match_score || 0}%</div><div style="font-size:.6rem" class="text-nx-muted">MATCH</div></div>
        <span class="badge bg-${JB_ST[a.status] || 'secondary'} bg-opacity-25 text-${JB_ST[a.status] || 'secondary'}">${esc(a.status)}</span></div>
      <div class="mt-2">${(a.matched || []).map(s => `<span class="hrai-tag" style="background:rgba(34,197,94,.15);color:#4ade80">${esc(s)}</span>`).join('')}${(a.missing || []).map(s => `<span class="hrai-tag" style="background:rgba(239,68,68,.15);color:#f87171">missing: ${esc(s)}</span>`).join('')}</div>
      ${(a.flags || []).length ? `<div class="small mt-1">${a.flags.map(f => `<span class="hr-chip2 ${f.sev === 'hard' ? 'r' : 'w'} me-1">${esc(f.text)}</span>`).join('')}</div>` : ''}
      ${a.ai ? `<div class="hr3-ai mt-2" style="margin:0;text-align:left"><span class="hr-chip2 ${sugg[a.ai.suggestion] === 'success' ? 'g' : sugg[a.ai.suggestion] === 'danger' ? 'r' : 'w'} me-1">AI: ${esc(a.ai.suggestion)}</span>${esc(a.ai.summary || '')}
        ${(a.ai.concerns || []).length ? `<div class="mt-1"><b>Concerns:</b> ${a.ai.concerns.map(esc).join('; ')}</div>` : ''}</div>` : ''}
      ${a.auto_rejected ? `<div class="small text-danger mt-1">Auto-rejected: ${esc(a.reject_reason || '')}</div>` : ''}
      <div class="d-flex gap-1 flex-wrap mt-2">
        ${+a.has_cv ? `<a class="btn btn-sm btn-outline-secondary" target="_blank" href="${SELF}?action=jb_cv_view&id=${a.candidate_id}"><i class="fa fa-file-lines me-1"></i>CV</a>` : ''}
        ${['shortlisted', 'interview', 'offered', 'hired'].map(s => `<button class="btn btn-sm btn-outline-${s === 'hired' ? 'success' : 'primary'}" onclick="jbDecide(${a.id},'${s}',${jobId})">${s}</button>`).join('')}
        <button class="btn btn-sm btn-outline-danger" onclick="jbDecide(${a.id},'rejected',${jobId})">reject</button></div>
    </div>`).join('') || '<div class="text-center text-nx-muted py-4">No applicants yet.</div>'}`;
}

async function jbScreen(jobId) {
  const b = document.getElementById('jb-scr'); b.disabled = true; b.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Screening…';
  const r = await api('jb_screen', { job_id: jobId }, 'POST');
  if (r.ok) { toast(`Screened ${r.screened}: ${r.auto_rejected} auto-rejected, ${r.analysed} analysed by AI`, 'success'); jbApps(jobId); }
  else { toast(r.msg || 'Failed', 'error'); b.disabled = false; b.innerHTML = 'Screen with NYMIX AI'; }
}

async function jbDecide(appId, status, jobId) {
  let note = '';
  if (status === 'rejected') { note = prompt('Reason (the candidate will see this):', 'Not selected for this role.'); if (note === null) return; }
  else if (!confirm('Move this applicant to "' + status + '"? They will be emailed.')) return;
  const r = await api('jb_decide', { app_id: appId, status, note }, 'POST');
  r.ok ? (toast('Updated', 'success'), jbApps(jobId)) : toast(r.msg || 'Failed', 'error');
}

/* ══════════════ NYMIX POS STUDIO ══════════════
   A normal POS (no AI stage) with: dark-glass look + animated background,
   a "paying" scene (money floating, pulse rings), an M-Pesa phone-ringing wait card,
   a "thank you" scene (animated tick + confetti) and a ticket receipt that prints out of a slot.
   Everything WRAPS your existing functions, so sale / stock / STK / eTIMS logic stays untouched. */

const PX_TK_CSS = `
.tk-wrap{position:relative;padding:4px 4px 12px;display:flex;flex-direction:column;align-items:center}
.tk-slot{position:relative;z-index:3;width:min(350px,96%);height:18px;border-radius:12px;background:linear-gradient(#2b3548,#0b1020);box-shadow:0 8px 22px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.18)}
.tk-slot::after{content:'';position:absolute;left:12px;right:12px;bottom:4px;height:4px;border-radius:4px;background:#000}
.tk-led{position:absolute;right:14px;top:5px;width:6px;height:6px;border-radius:50%;background:#17C548;box-shadow:0 0 8px #17C548;animation:tkLed .45s steps(2) 5}
@keyframes tkLed{50%{opacity:.15}}
.tk-feed{overflow:hidden;width:min(320px,90%);margin-top:-6px;padding-bottom:14px;position:relative;z-index:2}
.tk{position:relative;background:#fffef9;color:#14171c;font-family:'Courier New',ui-monospace,monospace;font-size:12px;line-height:1.35;padding:18px 18px 34px;
  transform:translateY(-101%);animation:tkOut 1.15s cubic-bezier(.22,.9,.3,1.04) .25s forwards;
  -webkit-mask:linear-gradient(#000 0 0) top/100% calc(100% - 9px) no-repeat,conic-gradient(from -45deg at bottom,#0000,#000 1deg 89deg,#0000 90deg) bottom/18px 9px repeat-x;
  mask:linear-gradient(#000 0 0) top/100% calc(100% - 9px) no-repeat,conic-gradient(from -45deg at bottom,#0000,#000 1deg 89deg,#0000 90deg) bottom/18px 9px repeat-x}
@keyframes tkOut{0%{transform:translateY(-101%)}80%{transform:translateY(1.5%)}100%{transform:none}}
.tk-a{opacity:0;animation:tkFade .4s ease forwards;animation-delay:calc(.95s + var(--i,0) * .07s)}
@keyframes tkFade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.tk-brand{display:flex;flex-direction:column;align-items:center;gap:3px;text-align:center}
.tk-logo{width:46px;height:46px;border-radius:13px;background:linear-gradient(135deg,#17C548,#E87800);display:grid;place-items:center;font:800 21px/1 'Space Grotesk',sans-serif;color:#04170b;overflow:hidden}
.tk-logo img{width:100%;height:100%;object-fit:cover}
.tk-biz{font:800 15px/1.2 'Space Grotesk',sans-serif;letter-spacing:.08em;text-transform:uppercase;margin-top:4px}
.tk-br{font-size:10px;color:#6b7280}
.tk-no{display:inline-block;margin-top:9px;padding:3px 11px;border:1.5px solid #14171c;border-radius:999px;font-weight:700;letter-spacing:.06em;font-size:11px}
.tk-meta{display:grid;grid-template-columns:1fr 1fr;gap:5px 10px;margin:11px 0 0;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em}
.tk-meta b{display:block;color:#14171c;font-size:11.5px;letter-spacing:0;text-transform:none}
.tk-dash{border-top:2px dashed #c9ccd2;margin:11px 0;height:0}
.tk-head,.tk-it .n,.tk-r,.tk-tot{display:flex;justify-content:space-between;gap:10px}
.tk-head{font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.08em}
.tk-it{margin:6px 0}.tk-it .n{font-weight:700}.tk-it .q{font-size:10px;color:#6b7280}
.tk-r{margin:3px 0}.tk-r.red{color:#b91c1c;font-weight:700}
.tk-it .n span:last-child,.tk-r>span:last-child,.tk-tot span:last-child{white-space:nowrap}
.tk-totwrap{position:relative}
.tk-tot{align-items:baseline;font:800 23px/1.1 'Space Grotesk',sans-serif;border-top:2px solid #14171c;padding-top:8px;margin:8px 0 6px}
.tk-pill{display:inline-block;padding:1px 8px;border-radius:999px;background:#e8f8ee;color:#15803d;font-weight:700;font-size:10px;text-transform:uppercase;letter-spacing:.05em}
.tk-code{display:block;margin:8px auto 0;width:fit-content;padding:3px 10px;border-radius:8px;background:#f1f5f9;font-weight:700;letter-spacing:.08em}
.tk-stamp{position:absolute;right:10px;top:14px;border:3px solid #16a34a;color:#16a34a;font:900 18px/1 'Space Grotesk',sans-serif;letter-spacing:.16em;padding:4px 9px;border-radius:8px;
  transform:rotate(-13deg) scale(3);opacity:0;animation:tkStamp .4s cubic-bezier(.2,1.6,.4,1) 2s forwards;mix-blend-mode:multiply}
.tk-stamp.due{border-color:#dc2626;color:#dc2626;font-size:12px}
.tk-stamp.void{border-color:#6b7280;color:#6b7280}
@keyframes tkStamp{0%{transform:rotate(-13deg) scale(3);opacity:0}60%{opacity:1}100%{transform:rotate(-13deg) scale(1);opacity:.92}}
.tk-qr{text-align:center}.tk-qr img{width:82px;height:82px;border-radius:6px}
.tk-bars{display:block;margin:8px auto 0;height:30px;width:80%}
.tk-etims{text-align:center;font-size:10px}.tk-etims b{letter-spacing:.1em}
.tk-thx{text-align:center;font:800 14px/1.25 'Space Grotesk',sans-serif;margin-top:4px}
.tk-sm{text-align:center;font-size:9.5px;color:#6b7280;margin-top:3px}
`;

