/* ───────── particles: coins + notes + sparks (money) and confetti (burst) ───────── */
function pxFx(cv) {
  const ctx = cv.getContext('2d');
  const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  let W = 1, H = 1, raf = 0, dead = false, last = performance.now(), parts = [];
  const fx = { max: 34 };
  const R = (a, b) => a + Math.random() * (b - a);
  function size() {
    const r = cv.getBoundingClientRect();
    W = Math.max(1, r.width); H = Math.max(1, r.height);
    cv.width = W * dpr; cv.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  size(); window.addEventListener('resize', size);
  function money(init) {
    const k = Math.random(), z = R(.55, 1.35);
    return { m: 1, k: k < .42 ? 'coin' : k < .8 ? 'note' : 'spark', x: R(0, W), y: init ? R(0, H) : H + R(20, 140), z,
      vy: -R(26, 68) * z, sw: R(10, 34), ph: R(0, 6.28), sp: R(.6, 1.6), rot: R(0, 6.28), vr: R(-2.2, 2.2), a: Math.min(1, .3 + z * .4) };
  }
  const COLS = ['#17C548', '#7bf0a0', '#fcd34d', '#E87800', '#38bdf8', '#f472b6', '#ffffff'];
  function conf(x, y) {
    const ang = R(-Math.PI * .97, -Math.PI * .03), sp = R(280, 820);
    return { m: 0, k: Math.random() < .25 ? 'dot' : 'rect', x, y, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, g: R(900, 1350),
      rot: R(0, 6.28), vr: R(-9, 9), w: R(6, 12), h: R(4, 8), c: COLS[(Math.random() * COLS.length) | 0], a: 1, fl: R(0, 6.28), fs: R(4, 11) };
  }
  fx.burst = (n, x, y) => { for (let i = 0; i < n; i++) parts.push(conf(x == null ? W / 2 : x, y == null ? H * .42 : y)); };
  function draw(p) {
    ctx.save(); ctx.globalAlpha = Math.max(0, p.a); ctx.translate(p.x, p.y);
    if (p.k === 'coin') {
      const s = 11 * p.z, f = Math.max(.14, Math.abs(Math.cos(p.rot)));
      ctx.scale(f, 1); ctx.fillStyle = '#fbbf24'; ctx.beginPath(); ctx.arc(0, 0, s, 0, 6.283); ctx.fill();
      ctx.strokeStyle = '#b45309'; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.arc(0, 0, s * .68, 0, 6.283); ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,.55)'; ctx.beginPath(); ctx.arc(-s * .3, -s * .3, s * .22, 0, 6.283); ctx.fill();
    } else if (p.k === 'note') {
      const w = 34 * p.z, h = 18 * p.z;
      ctx.rotate(p.rot * .35); ctx.scale(1, .5 + .5 * Math.abs(Math.cos(p.rot * 1.3)));
      ctx.fillStyle = '#16a34a'; ctx.fillRect(-w / 2, -h / 2, w, h);
      ctx.strokeStyle = 'rgba(255,255,255,.6)'; ctx.lineWidth = 1; ctx.strokeRect(-w / 2 + 3, -h / 2 + 3, w - 6, h - 6);
      ctx.beginPath(); ctx.arc(0, 0, h * .28, 0, 6.283); ctx.stroke();
    } else if (p.k === 'spark') {
      const s = 7 * p.z; ctx.rotate(p.rot); ctx.fillStyle = '#d9ffe6';
      ctx.beginPath(); ctx.moveTo(0, -s); ctx.quadraticCurveTo(0, 0, s, 0); ctx.quadraticCurveTo(0, 0, 0, s); ctx.quadraticCurveTo(0, 0, -s, 0); ctx.quadraticCurveTo(0, 0, 0, -s); ctx.fill();
    } else if (p.k === 'dot') {
      ctx.fillStyle = p.c; ctx.beginPath(); ctx.arc(0, 0, p.w * .45, 0, 6.283); ctx.fill();
    } else {
      ctx.rotate(p.rot); ctx.scale(1, Math.cos(p.fl)); ctx.fillStyle = p.c; ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
    }
    ctx.restore();
  }
  function step(dt) {
    let nm = 0;
    for (let i = parts.length - 1; i >= 0; i--) {
      const p = parts[i];
      if (p.m) {
        p.y += p.vy * dt; p.ph += p.sp * dt; p.x += Math.sin(p.ph) * p.sw * dt; p.rot += p.vr * dt;
        if (p.y < -40) { if (parts.length > fx.max || nm > fx.max) parts.splice(i, 1); else Object.assign(p, money(false)); }
        nm++;
      } else {
        p.vx *= Math.pow(.2, dt); p.vy += p.g * dt; p.x += p.vx * dt; p.y += p.vy * dt; p.rot += p.vr * dt; p.fl += p.fs * dt;
        if (p.y > H + 30) parts.splice(i, 1);
      }
    }
    let have = 0; for (const p of parts) if (p.m) have++;
    for (; have < fx.max; have++) parts.push(money(false));
  }
  function frame(t) {
    if (dead || !cv.isConnected) { fx.stop(); return; }
    const dt = Math.min(.05, (t - last) / 1000); last = t;
    ctx.clearRect(0, 0, W, H); step(dt); parts.forEach(draw);
    raf = requestAnimationFrame(frame);
  }
  fx.stop = () => { dead = true; cancelAnimationFrame(raf); window.removeEventListener('resize', size); };
  for (let i = 0; i < fx.max; i++) parts.push(money(true));
  if (reduce) { parts.forEach(draw); fx.burst = () => {}; return fx; }
  raf = requestAnimationFrame(frame);
  return fx;
}

/* ───────── scene helpers ───────── */
const PX_ICON  = { cash: 'fa-money-bill-wave', mpesa: 'fa-mobile-screen-button', credit: 'fa-credit-card', mixed: 'fa-code-branch', tokens: 'fa-coins' };
const PX_LABEL = { cash: 'Counting cash', mpesa: 'Finalising M-Pesa sale', credit: 'Recording on credit', mixed: 'Splitting payment', tokens: 'Redeeming tokens' };
let _pxScene = null, _pxFx = null;

function pxKill() {
  if (_pxFx) { _pxFx.stop(); _pxFx = null; }
  if (_pxScene) { _pxScene.remove(); _pxScene = null; }
  window._pxSkip = null;
}
function pxOpen(html) {
  if (_pxScene && !_pxScene.classList.contains('out')) {          // reuse the open scene: swap the card, keep the money floating
    const c = _pxScene.querySelector('.px-center');
    const n = c.cloneNode(false); n.innerHTML = html; c.replaceWith(n);
    return _pxScene;
  }
  pxKill();
  const o = document.createElement('div');
  o.className = 'px-scene'; o.id = 'px-scene';
  o.innerHTML = '<canvas class="px-cv"></canvas><div class="px-center">' + html + '</div>';
  document.body.appendChild(o);
  _pxScene = o; _pxFx = pxFx(o.querySelector('.px-cv'));
  return o;
}
function pxLeave(cb) {
  const o = _pxScene;
  if (!o) { if (cb) cb(); return; }
  o.classList.add('out');
  setTimeout(() => { if (_pxScene === o) pxKill(); if (cb) cb(); }, 330);
}
function pxFirst(n) {
  n = String(n || '').trim().replace(/^[^A-Za-z]+/, '').replace(/[^A-Za-z' -].*$/, '').trim().split(/\s+/)[0] || '';
  return n ? n.charAt(0).toUpperCase() + n.slice(1).toLowerCase() : '';
}
function pxSnap() {
  const num = id => parseFloat((document.getElementById(id)?.textContent || '0').replace(/[^0-9.]/g, '')) || 0;
  const total = num('cs-total');
  const method = document.getElementById('pay-method')?.value || 'cash';
  const cash = parseFloat(document.getElementById('pos-paid')?.value || 0) || 0;
  const mp = parseFloat(document.getElementById('pos-mpesa-amt')?.value || 0) || 0;
  const paid = method === 'cash' ? cash : method === 'mixed' ? cash + mp : total;
  const change = (method === 'cash' || method === 'mixed') ? Math.max(0, paid - total) : 0;
  const name = pxFirst((document.getElementById('pos-cust-selected-name')?.textContent || '') || _lastMpesaPayerName);
  return { total, method, change, name };
}
const pxTickSVG = '<svg class="px-tick" viewBox="0 0 120 120"><circle class="c" cx="60" cy="60" r="52"/><path class="p" d="M36 62 L52 78 L84 42"/></svg>';
function pxLetters(txt, name) {
  let i = 0;
  const L = s => [...s].map(ch => '<span style="--i:' + (i++) + '">' + (ch === ' ' ? '&nbsp;' : esc(ch)) + '</span>').join('');
  return L(txt) + (name ? '<em>' + L(' ' + name) + '</em>' : '') + L('!');
}
function pxPayingHTML(s) {
  return `<div class="px-orb"><span class="r"></span><span class="r"></span><span class="r"></span>
      <div class="px-core"><i class="fa ${PX_ICON[s.method] || 'fa-coins'}"></i></div></div>
    <div class="px-lbl">${PX_LABEL[s.method] || 'Processing payment'}</div>
    <div class="px-amt">${fmt(s.total)}</div>
    <div class="px-sub">Hang tight<span class="px-dots"><b></b><b></b><b></b></span></div>
    <div class="px-bar"><span></span></div>`;
}
function pxThanks(s, sale) {
  pxOpen(`${pxTickSVG}
    <div class="px-lbl">Payment complete</div>
    <div class="px-ty">${pxLetters('Thank you', s.name)}</div>
    <div class="px-sub">Sale <b>${esc(sale.no || '')}</b> recorded</div>
    <div class="px-box"><div><span>Total</span><b>${fmt(sale.amount != null ? sale.amount : s.total)}</b></div>${s.change > 0 ? `<div class="chg"><span>Change due</span><b>${fmt(s.change)}</b></div>` : ''}</div>
    <div class="px-print"><i class="fa fa-print me-1"></i>Printing your receipt<span class="px-dots"><b></b><b></b><b></b></span></div>
    <button class="px-btn ghost" id="px-skip">Show receipt now</button>`);
  if (_pxFx) { _pxFx.burst(170); _pxFx.max = 14; setTimeout(() => { if (_pxFx) _pxFx.burst(90); }, 650); }
  let done = false;
  const finish = () => {
    if (done) return; done = true; window._pxSkip = null;
    pxLeave(() => { window._pxHold = false; const f = window._pxPending; window._pxPending = null; if (f) f(); });
  };
  window._pxSkip = finish;
  document.getElementById('px-skip')?.addEventListener('click', finish);
  setTimeout(finish, 3600);
}
function pxReceived(i) {
  const nm = pxFirst(i.name);
  const o = pxOpen(`${pxTickSVG}
    <div class="px-lbl">M-Pesa payment received</div>
    <div class="px-ty">${pxLetters('Thank you', nm)}</div>
    <div class="px-box"><div><span>Amount paid</span><b>${fmt(i.amount)}</b></div></div>
    ${i.code ? `<div class="px-print" style="animation-delay:1.5s">Code <b style="color:#fff">${esc(i.code)}</b></div>` : ''}
    <button class="px-btn" id="px-go" style="animation:tkFade .5s ease 1.7s both"><i class="fa fa-receipt me-2"></i>Complete sale &amp; print receipt</button>`);
  if (_pxFx) { _pxFx.burst(170); _pxFx.max = 14; }
  try { _sfx.sale(); } catch (e) {}
  o.querySelector('#px-go').addEventListener('click', () => processSale());
}

/* ───────── hook: the sale itself ───────── */
toastSale = function (amount, no) { window._pxSale = { amount, no }; try { _sfx.sale(); } catch (e) {} };

const _pxPS = processSale;
processSale = async function () {
  if (window._pxBusy) return;
  if (!cart.length) return _pxPS();                                // original shows "Cart is empty"
  const s = pxSnap(), t0 = Date.now();
  window._pxBusy = true; window._pxHold = true; window._pxSale = null; window._pxPending = null;
  pxOpen(pxPayingHTML(s));
  try { await _pxPS(); } catch (e) { console.error(e); }
  window._pxBusy = false;
  const sale = window._pxSale;
  if (!sale) { window._pxHold = false; pxLeave(); return; }       // failed / validation message: back to the till
  setTimeout(() => pxThanks(s, sale), Math.max(0, 1600 - (Date.now() - t0)));
};

/* ───────── hook: M-Pesa STK wait card + "payment received" ───────── */
const _pxSW = showStkWaitingModal;
showStkWaitingModal = function (phone, amount, name) {
  const w = document.getElementById('stk-step-waiting');
  if (w && !w.dataset.px) {
    w.dataset.px = '1'; w.className = 'px-stkw'; w.removeAttribute('style');
    w.innerHTML = `<div class="px-pw"><span class="r"></span><span class="r"></span><span class="r"></span>
        <div class="px-phone"><div class="s"><b>M-PESA</b><small>Enter PIN</small><div class="px-pin"><i></i><i></i><i></i><i></i></div></div></div></div>
      <h6>Payment prompt sent</h6>
      <p>Ask the customer to check their phone and enter their M-Pesa PIN</p>
      <div class="px-stkamt"><span>Amount to pay</span><b id="stk-modal-amount"></b></div>
      <div class="wait">Waiting for customer<span class="px-dots"><b></b><b></b><b></b></span></div>
      <button class="px-btn ghost w-100" onclick="closeStkModal()">Cancel</button>`;
  }
  _pxSW(phone, amount, name);
  const body = document.querySelector('#modal-stk .modal-body');
  if (body && !body.querySelector('.px-stkcv')) body.insertAdjacentHTML('afterbegin', '<canvas class="px-stkcv"></canvas>');
  setTimeout(() => {
    const cv = document.querySelector('#modal-stk .px-stkcv');
    if (cv && cv.offsetWidth) { if (window._pxStkFx) window._pxStkFx.stop(); window._pxStkFx = pxFx(cv); window._pxStkFx.max = 16; }
  }, 350);
};
document.getElementById('modal-stk')?.addEventListener('hidden.bs.modal', () => { if (window._pxStkFx) { window._pxStkFx.stop(); window._pxStkFx = null; } });

showStkSuccess = function (name, amount, code) {
  closeStkModal();
  _lastMpesaPayerName = name || '';
  pxReceived({ name, amount, code });
};

/* ───────── the receipt: a ticket that prints out of a slot ───────── */
function pxBars(no) {
  let x = 4, out = '';
  const seq = [2, 1];
  out += '<rect x="0" y="0" width="2" height="30"/><rect x="4" y="0" width="1" height="30"/>';
  x = 8;
  for (const ch of String(no || 'NYMIX')) {
    const c = ch.charCodeAt(0);
    for (let b = 0; b < 4; b++) {
      const w = 1 + ((c >> (b * 2)) & 3) % 3;
      if (b % 2 === 0) out += '<rect x="' + x + '" y="0" width="' + w + '" height="30"/>';
      x += w + 1;
    }
    x += 1;
  }
  out += '<rect x="' + x + '" y="0" width="1" height="30"/><rect x="' + (x + 3) + '" y="0" width="2" height="30"/>';
  return '<svg class="tk-bars" viewBox="0 0 ' + (x + 6) + ' 30" preserveAspectRatio="none" fill="#14171c">' + out + '</svg>';
}
function pxCount(el, to, delay) {
  if (!el) return;
  el.textContent = fmt(0);
  setTimeout(() => {
    const t0 = performance.now(), D = 800;
    (function f(t) {
      if (!el.isConnected) return;
      const k = Math.min(1, (t - t0) / D), e = 1 - Math.pow(1 - k, 3);
      el.textContent = fmt(to * e);
      if (k < 1) requestAnimationFrame(f);
    })(t0);
  }, delay);
}
function pxTicketHTML(s, items) {
  const biz = (typeof CU !== 'undefined' && CU && CU.business_name) || 'NYMIX';
  const logo = (typeof CU !== 'undefined' && CU && CU.logo) ? `<img src="${esc(CU.logo)}" alt="" onerror="this.remove()">` : esc(String(biz).charAt(0).toUpperCase());
  const d = new Date(s.sale_date);
  const grand = parseFloat(s.grand_total) || 0, paid = parseFloat(s.amount_paid) || 0, bal = parseFloat(s.balance_due) || 0;
  const change = (s.payment_method === 'cash' || s.payment_method === 'mixed') ? Math.max(0, paid - grand) : 0;
  let i = 3;
  const rows = items.map(it => {
    const q = parseFloat(it.quantity) || 0, sub = parseFloat(it.subtotal) || 0, up = parseFloat(it.unit_price) || (q ? sub / q : 0);
    return `<div class="tk-it tk-a" style="--i:${Math.min(i++, 14)}"><div class="n"><span>${esc(it.product_name)}</span><span>${fmt(sub)}</span></div><div class="q">${q} × ${fmt(up)}</div></div>`;
  }).join('');
  const stamp = s.voided ? '<div class="tk-stamp void">VOID</div>' : bal > 0 ? '<div class="tk-stamp due">ON CREDIT</div>' : '<div class="tk-stamp">PAID</div>';
  const qr = s.receipt_no ? `<div class="tk-qr tk-a" style="--i:${i++}"><img src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=${encodeURIComponent('NYMIX|' + s.receipt_no)}" alt="QR">${pxBars(s.receipt_no)}</div>` : '';
  const etims = s.etims_status === 'submitted' ? `
      <div class="tk-dash"></div>
      <div class="tk-etims tk-a" style="--i:${i++}"><b>KRA eTIMS VERIFIED</b><div>CU Invoice: <strong>${esc(s.etims_invoice_no || '—')}</strong></div>
      ${s.etims_qr_code ? `<img src="https://api.qrserver.com/v1/create-qr-code/?size=100x100&data=${encodeURIComponent(s.etims_qr_code)}" style="width:76px;margin-top:5px;border-radius:4px" alt="">` : ''}
      <div style="color:#6b7280">${s.etims_submitted_at ? new Date(s.etims_submitted_at).toLocaleString('en-KE') : ''}</div></div>`
    : s.etims_status === 'failed' ? `<div class="tk-dash"></div><div class="tk-etims" style="color:#b91c1c">⚠ eTIMS submission failed<div style="color:#6b7280">${esc(s.etims_error || '')}</div></div>` : '';
  return `<div class="tk-wrap">
    <div class="tk-slot"><span class="tk-led"></span></div>
    <div class="tk-feed"><div class="tk" id="tk">
      ${stamp}
      <div class="tk-brand tk-a" style="--i:0"><div class="tk-logo">${logo}</div><div class="tk-biz">${esc(biz)}</div><div class="tk-br">${esc(s.branch_name || '')}</div><div class="tk-no">${esc(s.receipt_no || '')}</div></div>
      <div class="tk-meta tk-a" style="--i:1">
        <div>Date<b>${isNaN(d) ? '—' : d.toLocaleDateString('en-KE', { day: '2-digit', month: 'short', year: 'numeric' })}</b></div>
        <div>Time<b>${isNaN(d) ? '—' : d.toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit' })}</b></div>
        <div>Cashier<b>${esc(s.cashier || '—')}</b></div>
        <div>Customer<b>${esc(s.customer_name || 'Walk-in')}</b></div>
      </div>
      <div class="tk-dash"></div>
      <div class="tk-head tk-a" style="--i:2"><span>Item</span><span>Amount</span></div>
      ${rows}
      <div class="tk-dash"></div>
      <div class="tk-r tk-a" style="--i:${Math.min(i++, 15)}"><span>Subtotal</span><span>${fmt(s.subtotal)}</span></div>
      ${parseFloat(s.discount) > 0 ? `<div class="tk-r tk-a" style="--i:${Math.min(i++, 15)}"><span>Discount</span><span>-${fmt(s.discount)}</span></div>` : ''}
      <div class="tk-tot tk-a" style="--i:${Math.min(i++, 15)}"><span>TOTAL</span><span id="tk-total">${fmt(grand)}</span></div>
      <div class="tk-r tk-a" style="--i:${Math.min(i++, 15)}"><span>Paid <span class="tk-pill">${esc(s.payment_method || '')}</span></span><span>${fmt(paid)}</span></div>
      ${change > 0 ? `<div class="tk-r tk-a" style="--i:${Math.min(i++, 15)}"><span>Change</span><span>${fmt(change)}</span></div>` : ''}
      ${bal > 0 ? `<div class="tk-r red tk-a" style="--i:${Math.min(i++, 15)}"><span>Balance due</span><span>${fmt(bal)}</span></div>` : ''}
      ${s.mpesa_code ? `<span class="tk-code tk-a" style="--i:${Math.min(i++, 15)}">M-PESA ${esc(s.mpesa_code)}</span>` : ''}
      ${etims}
      <div class="tk-dash"></div>
      ${qr}
      <div class="tk-thx tk-a" style="--i:${Math.min(i++, 16)}">Thank you for shopping with us!</div>
      <div class="tk-sm tk-a" style="--i:${Math.min(i++, 16)}">Karibu tena · Powered by NYMIX TECH</div>
    </div></div></div>`;
}
async function pxViewReceipt(id) {
  currentSaleId = id;
  const d = await api('sale_detail', { id });
  if (!d.ok) return;
  document.getElementById('receipt-body').innerHTML = pxTicketHTML(d.sale, d.items);
  const grand = parseFloat(d.sale.grand_total) || 0;
  const tot = document.getElementById('tk-total');
  if (tot) pxCount(tot, grand, 1100);
  document.querySelector('#modal-receipt .modal-footer .btn-secondary')?.classList.add('px-print-btn');
  const voidBtn = document.getElementById('btn-void-sale');
  if (voidBtn) voidBtn.classList.toggle('d-none', !can(R.OWNER, R.MANAGER) || !!d.sale.voided);
  const show = () => { openModal('modal-receipt'); try { _sfx.info(); } catch (e) {} };
  if (window._pxHold) window._pxPending = show; else show();
}
viewSaleReceipt = function (id) { const p = pxViewReceipt(id); window._pxRcptP = p; return p; };

const _pxPR = printReceipt;
printReceipt = async function () {
  try { if (window._pxRcptP) await window._pxRcptP; } catch (e) {}
  const t = document.querySelector('#receipt-body .tk');
  if (!t) return _pxPR();
  const win = window.open('', '_blank', 'width=380,height=720');
  if (!win) { toast('Allow pop-ups to print the receipt', 'error'); return; }
  win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Receipt</title><style>' + PX_TK_CSS + PX_TK_PRINT + '</style></head><body>' + t.outerHTML + '</body></html>');
  win.document.close(); win.focus();
  const imgs = [...win.document.images].map(im => im.complete ? 1 : new Promise(r => { im.onload = im.onerror = r; }));
  await Promise.race([Promise.all(imgs), new Promise(r => setTimeout(r, 1800))]);
  setTimeout(() => { win.print(); win.close(); }, 150);
};

/* ───────── hook: apply the look to the POS page only ───────── */
const _pxRP = renderPOS;
renderPOS = async function (el) {
  await _pxRP(el);
  const _top = el.querySelector('.pos-topbar'), _lay = el.querySelector('.pos-layout');
  if (!_top || !_lay || _top.parentElement.classList.contains('posx')) return;
  const _w = document.createElement('div'); _w.className = 'posx'; el.insertBefore(_w, _top); _w.appendChild(_top); _w.appendChild(_lay);
  {
    let em = '';
    for (let i = 0; i < 14; i++) em += `<em style="--x:${(4 + Math.random() * 92).toFixed(1)}%;--s:${(8 + Math.random() * 12).toFixed(0)}px;--d:${(14 + Math.random() * 14).toFixed(1)}s;--w:-${(Math.random() * 20).toFixed(1)}s;--dx:${(Math.random() * 120 - 60).toFixed(0)}px"></em>`;
    _w.insertAdjacentHTML('afterbegin', '<div class="posx-bg"><i></i><i></i><i></i><b></b>' + em + '</div>');
  }
};
const _pxNav = navigateNow;
navigateNow = async function (page) {
  const c = document.getElementById('nx-content');
  if (c) c.classList.remove('posx');
  return _pxNav(page);
};
document.addEventListener('keydown', e => { if (e.key === 'Escape' && window._pxSkip) window._pxSkip(); });

// ══════════════ MANUAL REGISTRATION REVIEW ══════════════
function rgGrabSelfie(v) {
  try {
    if (!v || !v.videoWidth) return;
    const c = document.createElement('canvas'); c.width = v.videoWidth; c.height = v.videoHeight;
    c.getContext('2d').drawImage(v, 0, 0);
    c.toBlob(b => { if (b) RG.selfieBlob = b; }, 'image/jpeg', 0.85);
  } catch (e) {}
}
function rgReviewOpen() {
  RG.busy = false; rgCamStop();
  rgShow('review');
  $rg('rg-title').textContent = 'Manual review';
  $rg('rg-sub').textContent = 'Your manager will confirm your identity.';
  $rg('rg-rv-id-s').textContent = RG.idBlob ? '✓ We already have your ID photo. Choose a file only to replace it.' : 'Required';
  $rg('rg-rv-self-s').textContent = RG.selfieBlob ? '✓ We already have your selfie. Choose a file only to replace it.' : 'Required';
}
async function rgReviewSubmit() {
  rgErr(4, '');
  const idF = $rg('rg-rv-id').files[0] || RG.idBlob, sF = $rg('rg-rv-self').files[0] || RG.selfieBlob;
  if (!idF) return rgErr(4, 'Please add a photo of your ID.');
  if (!sF) return rgErr(4, 'Please add a selfie.');
  const fd = new FormData(); fd.append('id_photo', idF, 'id.jpg'); fd.append('selfie', sF, 'selfie.jpg');
  const btn = $rg('rg-rv-go'); btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Sending…';
  let d;
  try { d = await (await fetch(SELF + '?action=staff_register_review_submit', { method: 'POST', body: fd })).json(); }
  catch (e) { btn.disabled = false; btn.innerHTML = 'Submit for manager review'; return rgErr(4, 'Request failed. Check your internet and try again.'); }
  if (!d.ok) { btn.disabled = false; btn.innerHTML = 'Submit for manager review'; return rgErr(4, d.msg || 'Could not submit.'); }
  RG.idBlob = null; RG.selfieBlob = null;
  $rg('rg-title').textContent = 'Submitted';
  $rg('rg-p-review').innerHTML = `<div class="text-center py-3"><div style="font-size:3rem" class="mb-2">📨</div>
    <h5 class="fw-head mb-2">Sorry, we could not verify your identity for now</h5>
    <p class="text-nx-muted small">Your registration has been submitted to your manager for final review. No action is needed from you. We will email you as soon as it is decided.</p>
    <button class="btn w-100 fw-bold mt-2" style="background:var(--nx-accent);color:#fff" onclick="closeRegWizard()">Back to Sign In</button></div>`;
}

// ── Manager / owner: registrations awaiting approval (shown on Accounts Under Review) ──
let _rgRows = [];
const RG_AI = { approve: ['Looks genuine', '#22c55e'], reject: ['Looks wrong', '#ef4444'], manual_check: ['Unclear, check it yourself', '#f59e0b'] };
function regAiHtml(r) {
  let a = null; try { a = JSON.parse(r.ai_result || 'null'); } catch (e) {}
  if (!a) return '<div class="small text-nx-muted">No AI opinion yet.</div>';
  const v = RG_AI[a.recommendation] || RG_AI.manual_check;
  return `<div class="p-3 rounded" style="background:rgba(30,158,82,.08);border:1px dashed rgba(30,158,82,.45)">
    <div class="small text-nx-muted">AI PRE-CHECK (advisory only)</div>
    <div class="fw-bold" style="color:${v[1]}">${v[0]}</div>
    <div class="small mt-1" style="line-height:1.55">${esc(a.reasoning || '')}</div>
    <div class="mt-2 small">
      <span class="hr-chip2 me-1">Name: ${esc(a.name_matches || '?')}</span><span class="hr-chip2 me-1">ID no.: ${esc(a.id_number_last3_matches || '?')}</span>
      <span class="hr-chip2 me-1">Face: ${esc((a.face_comparison || '?').replace('_', ' '))}</span><span class="hr-chip2 me-1">Tampering: ${esc(a.tamper_signs || '?')}</span>
      <span class="hr-chip2">Photo quality: ${esc(a.image_quality || '?')}</span></div>
    <div class="small text-nx-muted mt-2">Face comparison by AI is only a rough impression. Compare the photos yourself.</div></div>`;
}
const _rrOld = renderReviews;
renderReviews = async function (el) {
  await _rrOld(el);
  try {
    const d = await api('reg_review_list');
    if (!d.ok || !d.rows.length) return;
    _rgRows = d.rows;
    const html = `<div class="card mb-4" style="border-color:rgba(30,158,82,.55)">
      <div class="card-header py-2 px-3 small fw-bold"><i class="fa fa-user-check text-accent me-2"></i>Registrations awaiting your approval <span class="badge bg-danger ms-1">${d.rows.length}</span></div>
      <div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Name</th><th>Role</th><th>Branch</th><th>AI</th><th>Submitted</th><th></th></tr></thead><tbody>
      ${d.rows.map((r, i) => { let a = null; try { a = JSON.parse(r.ai_result || 'null'); } catch (e) {} const v = a ? (RG_AI[a.recommendation] || RG_AI.manual_check) : null;
        return `<tr><td class="fw-bold small">${esc(r.full_name)}</td><td class="small">${esc(r.role_name)}</td><td class="small">${esc(r.branch_name)}</td>
          <td class="small">${v ? `<span style="color:${v[1]};font-weight:700">${v[0]}</span>` : '<span class="text-nx-muted">—</span>'}</td>
          <td class="small text-nx-muted">${hlWhen(r.created_at)}</td>
          <td><button class="btn btn-sm fw-bold" style="background:var(--nx-accent);color:#fff" onclick="regOpen(${i})">Review</button></td></tr>`; }).join('')}
      </tbody></table></div></div>`;
    const anchor = el.querySelector('#hl-tabs');
    anchor ? anchor.insertAdjacentHTML('beforebegin', html) : el.firstElementChild.insertAdjacentHTML('beforeend', html);
  } catch (e) { console.error(e); }
};
function regOpen(i) {
  const r = _rgRows[i]; if (!r) return;
  const img = k => `${SELF}?action=reg_review_file&id=${r.id}&kind=${k}`;
  hlModal('Registration: ' + r.full_name, `
    <div class="small mb-3">${esc(r.role_name)} · ${esc(r.branch_name)} · ID no. <b>${esc(r.national_id)}</b> · ${esc(r.email)} · ${esc(r.phone)}</div>
    <div class="row g-3 mb-3">
      <div class="col-md-6"><div class="small text-nx-muted mb-1">ID PHOTO</div><a href="${img('id')}" target="_blank"><img src="${img('id')}" style="width:100%;border-radius:12px;border:1px solid var(--nx-border)"></a></div>
      <div class="col-md-6"><div class="small text-nx-muted mb-1">SELFIE</div><a href="${img('selfie')}" target="_blank"><img src="${img('selfie')}" style="width:100%;border-radius:12px;border:1px solid var(--nx-border)"></a></div>
    </div>
    ${+r.has_cv ? `<a class="btn btn-sm btn-outline-secondary mb-3" target="_blank" href="${img('cv')}"><i class="fa fa-file-lines me-1"></i>View CV</a>` : ''}
    <div id="rgv-ai">${regAiHtml(r)}</div>
    <button class="btn btn-sm btn-outline-secondary mt-2" onclick="regAi(${i})"><i class="fa fa-wand-magic-sparkles me-1"></i>${r.ai_result ? 'Re-run AI' : 'Run AI check'}</button>
    <div class="hr3-sec">Your decision</div>
    <textarea id="rgv-note" class="form-control form-control-sm mb-2" rows="2" placeholder="Reason (required if you reject; the staff member will see it)"></textarea>
    <div class="d-flex gap-2 flex-wrap">
      <button class="btn btn-success fw-bold" onclick="regDecide(${i},'approve')"><i class="fa fa-circle-check me-1"></i>Approve &amp; send welcome email + appointment letter</button>
      <button class="btn btn-outline-danger" onclick="regDecide(${i},'reject')">Reject</button></div>`);
}
async function regAi(i) {
  const r = _rgRows[i], box = document.getElementById('rgv-ai'); if (!box) return;
  box.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span><span class="small text-nx-muted">NYMIX AI is looking at the photos…</span>';
  const d = await api('reg_review_ai', { id: r.id }, 'POST');
  if (d.ok) { r.ai_result = JSON.stringify(d.ai); box.innerHTML = regAiHtml(r); } else box.innerHTML = `<div class="small text-warning">${esc(d.msg || 'AI unavailable.')}</div>`;
}
async function regDecide(i, dec) {
  const r = _rgRows[i], note = document.getElementById('rgv-note')?.value || '';
  if (dec === 'reject' && !note.trim()) { toast('Add a reason so the staff member knows what to fix', 'error'); return; }
  if (!confirm(dec === 'approve' ? 'Approve ' + r.full_name + '? The account is created and the welcome email with the appointment letter is sent.' : 'Reject this registration?')) return;
  const res = await api('reg_review_decide', { id: r.id, decision: dec, note }, 'POST');
  if (res.ok) { toast(res.msg, 'success'); closeModal('modal-hl'); renderReviews(document.getElementById('nx-content')); }
  else toast(res.msg || 'Failed', 'error');
}

// ══════════════ AI QUICK ADD PRODUCTS (ledger + free web images) ══════════════
let _ps = { rows: [], tok: 0 };
const psA = s => esc(s).replace(/"/g, '&quot;');
const psCan = () => can(R.OWNER, R.STOREKEEPER, R.SUPPLIER);
const PS_BTN = '<button class="btn btn-sm btn-outline-info ms-2" onclick="psOpen()"><i class="fa fa-wand-magic-sparkles me-1"></i>AI Quick Add</button>';

function psEnsure() {
  if (document.getElementById('modal-ps')) return;
  const m = document.createElement('div'); m.className = 'modal fade'; m.id = 'modal-ps'; m.tabIndex = -1;
  m.innerHTML = '<div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title fw-head"><span class="nx-ai-tag me-2"><i class="fa fa-wand-magic-sparkles"></i> NYMIX AI</span>Quick add products</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="ps-body"></div></div></div>';
  document.body.appendChild(m);
  m.addEventListener('hidden.bs.modal', () => { _ps.tok++; });
}

async function psOpen() {
  if (!psCan()) return;
  psEnsure();
  const tok = ++_ps.tok;
  document.getElementById('ps-body').innerHTML = `<div class="py-4"><div class="hrai-doc"><div class="hrai-scan"></div></div>
    <div class="hrai-t">NYMIX AI is checking what kind of business you run…</div><div class="hrai-s">Picking products that fit ${esc(CU.business_name || 'your business')}</div></div>`;
  openModal('modal-ps');
  const d = await api('ai_product_suggest', {}, 'POST');
  if (tok !== _ps.tok) return;
  if (!d.ok) {
    document.getElementById('ps-body').innerHTML = `<div class="text-center py-4"><div style="font-size:2rem">⚠️</div><p class="text-nx-muted">${esc(d.msg || 'AI could not suggest products.')}</p>
      <button class="btn btn-outline-secondary" onclick="psOpen()">Try again</button></div>`;
    return;
  }
  _ps.rows = d.items.map(x => ({ ...x, on: true, imgs: [], ii: 0 }));
  psPaint(d.business_type);
  psLoadImgs(tok);
}

function psPaint(type) {
  const body = document.getElementById('ps-body'); if (!body) return;
  const inp = (i, k, w, t) => `<input type="${t || 'text'}" class="form-control form-control-sm" style="min-width:${w}px" value="${psA(_ps.rows[i][k])}" ${t === 'number' ? 'min="0" step="0.01"' : ''} oninput="psSet(${i},'${k}',this.value)">`;
  body.innerHTML = `
    <div class="alert alert-info py-2 small mb-3"><i class="fa fa-lightbulb me-1"></i>Looks like <b>${esc(type || 'a retail business')}</b>. Tick what you sell, fix names or prices, and set your opening quantity. Prices are estimates, so adjust them.</div>
    <div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-2">
      <div class="small text-nx-muted" id="ps-sum"></div>
      <div class="d-flex gap-2"><button class="btn btn-sm btn-outline-secondary" onclick="psAll(true)">Select all</button><button class="btn btn-sm btn-outline-secondary" onclick="psAll(false)">Clear</button></div></div>
    <div class="table-responsive"><table class="table table-sm align-middle mb-0">
      <thead><tr><th></th><th>#</th><th>Photo</th><th>Product</th><th>Category</th><th>Unit</th><th>Buy (KSh)</th><th>Sell (KSh)</th><th>Qty</th></tr></thead>
      <tbody>${_ps.rows.map((r, i) => `<tr id="ps-row-${i}">
        <td><input type="checkbox" class="form-check-input" ${r.on ? 'checked' : ''} onchange="psSet(${i},'on',this.checked)"></td>
        <td class="small text-nx-muted">${i + 1}</td>
        <td><div id="ps-img-${i}" onclick="psCycle(${i})" title="Click for another photo" style="width:44px;height:44px;border-radius:10px;background:var(--nx-surface);display:flex;align-items:center;justify-content:center;overflow:hidden;cursor:pointer"><span class="spinner-border spinner-border-sm text-warning"></span></div></td>
        <td>${inp(i, 'name', 170)}</td><td>${inp(i, 'category', 110)}</td><td>${inp(i, 'unit', 70)}</td>
        <td>${inp(i, 'buying_price', 80, 'number')}</td><td>${inp(i, 'selling_price', 80, 'number')}</td><td>${inp(i, 'qty', 70, 'number')}</td></tr>`).join('')}</tbody></table></div>
    <div class="d-flex gap-2 mt-3 flex-wrap">
      <button id="ps-save" class="btn fw-bold" style="background:var(--nx-accent);color:#fff" onclick="psSave()"><i class="fa fa-check me-1"></i>Add selected products</button>
      <button class="btn btn-outline-secondary" onclick="sessionStorage.setItem('nx_ps_skip','1');closeModal('modal-ps')">Skip for now</button></div>
    <div class="small text-nx-muted mt-2">Photos are free web images found automatically. Click a photo to try another, and check they look right.</div>`;
  psSum();
}

function psSet(i, k, v) {
  const r = _ps.rows[i]; if (!r) return;
  r[k] = v;
  if (k === 'on') psSum();
  if (k === 'name') { clearTimeout(r._t); r._t = setTimeout(() => psFetchImg(i, _ps.tok), 900); }
}
function psAll(on) { _ps.rows.forEach((r, i) => { r.on = on; const c = document.querySelector('#ps-row-' + i + ' input[type=checkbox]'); if (c) c.checked = on; }); psSum(); }
function psSum() {
  const el = document.getElementById('ps-sum'); if (!el) return;
  const s = _ps.rows.filter(r => r.on);
  const val = s.reduce((a, r) => a + (parseFloat(r.buying_price) || 0) * (parseFloat(r.qty) || 0), 0);
  el.innerHTML = `<b>${s.length}</b> of ${_ps.rows.length} selected · opening stock worth <b>${fmt(val)}</b> at cost`;
}

function psImg(i) {
  const r = _ps.rows[i], box = document.getElementById('ps-img-' + i); if (!r || !box) return;
  const u = r.imgs[r.ii] && r.imgs[r.ii].thumb;
  box.innerHTML = u ? `<img src="${psA(u)}" style="width:100%;height:100%;object-fit:cover" onerror="this.parentElement.textContent='${esc((r.name || '?').charAt(0).toUpperCase())}'">`
                    : `<span class="text-nx-muted">${esc((r.name || '?').charAt(0).toUpperCase())}</span>`;
}
function psCycle(i) { const r = _ps.rows[i]; if (!r || !r.imgs.length) return; r.ii = (r.ii + 1) % r.imgs.length; psImg(i); }
async function psFetchImg(i, tok) {
  const r = _ps.rows[i]; if (!r || !r.name.trim()) return;
  const d = await api('image_search', { q: r.name });
  if (tok !== _ps.tok || !document.getElementById('ps-img-' + i)) return;
  r.imgs = (d.ok && d.results) || []; r.ii = 0; psImg(i);
}
async function psLoadImgs(tok) {
  const q = _ps.rows.map((_, i) => i);
  const worker = async () => { while (q.length && tok === _ps.tok) await psFetchImg(q.shift(), tok); };
  await Promise.all([worker(), worker(), worker()]);
}

async function psSave() {
  const items = _ps.rows.filter(r => r.on && (r.name || '').trim()).map(r => ({
    name: r.name.trim(), category: (r.category || '').trim(), unit: (r.unit || 'pcs').trim(),
    buying_price: parseFloat(r.buying_price) || 0, selling_price: parseFloat(r.selling_price) || 0,
    reorder_level: parseFloat(r.reorder_level) || 0, qty: parseFloat(r.qty) || 0,
    image_url: (r.imgs[r.ii] && r.imgs[r.ii].thumb) || '' }));
  if (!items.length) { toast('Tick at least one product', 'error'); return; }
  if (items.some(x => x.selling_price <= 0) && !confirm('Some products have no selling price. Add them anyway?')) return;
  const b = document.getElementById('ps-save'); b.disabled = true; b.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Saving…';
  const res = await api('product_bulk_add', { items: JSON.stringify(items) }, 'POST');
  if (res.ok) {
    toast(`${res.added} product(s) added${res.skipped ? ', ' + res.skipped + ' skipped (already exist)' : ''}`, 'success');
    closeModal('modal-ps');
    if (document.getElementById('prod-table')) loadProducts();
    if (document.getElementById('po-table')) loadPurchases();
  } else { toast(res.msg || 'Failed.', 'error'); b.disabled = false; b.innerHTML = '<i class="fa fa-check me-1"></i>Add selected products'; }
}

// auto-open the first time, when the business has no products yet
async function psAuto() {
  if (!psCan() || sessionStorage.getItem('nx_ps_skip')) return;
  const d = await api('products_all');
  if (d.ok && !d.products.length) psOpen();
}
const _psRP = renderProducts;
renderProducts = async function (el) {
  await _psRP(el);
  if (psCan()) { el.querySelector('h5')?.insertAdjacentHTML('afterend', PS_BTN); psAuto(); }
};
const _psRPO = renderPurchases;
renderPurchases = async function (el) {
  await _psRPO(el);
  if (psCan()) el.querySelector('h5')?.insertAdjacentHTML('afterend', PS_BTN);
};

function init() {
  if (!CU) return;
  // Cashier: hide sidebar and topbar, POS gets full screen
  if (CU.role_id === R.CASHIER) {
    const sb = document.getElementById('nx-sidebar');
    const tb = document.getElementById('nx-topbar');
    const mx = document.getElementById('nx-main');
    if (sb) sb.style.display = 'none';
    if (tb) tb.style.display = 'none';
    if (mx) { mx.style.marginLeft = '0'; mx.style.paddingTop = '0'; }
  }
  buildNav();
  applyProfileUI();
  document.getElementById('topbar-date').textContent =
    new Date().toLocaleDateString('en-KE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  document.querySelectorAll('.nx-nav-link[data-page]').forEach(btn => {
    btn.addEventListener('click', () => navigate(btn.dataset.page));
  });
  const defaults = {
    [R.OWNER]: 'dashboard', [R.MANAGER]: 'dashboard',
    [R.CASHIER]: 'pos', [R.STOREKEEPER]: 'inventory', [R.SUPPLIER]: 'purchases'
  };
  // Check if we're returning from Pesapal
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('pesapal_result') === '1') {
    const saved = sessionStorage.getItem('pesapal_cart');
    if (saved) {
      const state = JSON.parse(saved);
      sessionStorage.removeItem('pesapal_cart');
      // Restore cart and navigate to POS
      navigate('pos');
      // Wait for POS to render then inject result
      setTimeout(async () => {
        cart = state.cart || [];
        renderCart();
        // Fetch result from PHP session via a quick ping
        const r = await fetch(SELF + '?action=pesapal_result_session');
        const data = await r.json();
        if (data.paid) {
          const mpesaInput = document.getElementById('pos-mpesa');
          if (mpesaInput && data.mpesa_code) mpesaInput.value = data.mpesa_code;
          const paidInput = document.getElementById('pos-paid');
          if (paidInput) { paidInput.value = parseFloat(data.amount || 0).toFixed(2); updateCartTotals(); }
          showStkSuccess('Customer', data.amount, data.mpesa_code);
        } else {
          toast('Payment not confirmed. Check with customer before processing.', 'error');
        }
      }, 800);
      return;
    }
  }

  navigate('home');
  if (CU.card_required && !CU.id_verified) openIdVerify(); // mandatory for newly onboarded staff
  pollNotifs(); setInterval(pollNotifs, 60000);
  weakPwdBanner(); netInit();
  resetIdle();
}
init();
</script>
</body>
</html>